"use strict";(globalThis.webpackChunkmy_tech_blog=globalThis.webpackChunkmy_tech_blog||[]).push([[7133],{27953:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"crypto-exchange-security-structure","metadata":{"permalink":"/blog/en/finance/crypto-exchange-security-structure","source":"@site/finance/2026-10-31-crypto-exchange-security-structure/index.mdx","title":"\uac00\uc0c1\uc790\uc0b0 \uac70\ub798\uc18c \ubcf4\uc548 \uad6c\uc870, \ud56b\uc6d4\ub81b\uacfc \ucf5c\ub4dc\uc6d4\ub81b\uc744 \ub098\ub204\ub294 \uc774\uc720","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-31T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac00\uc0c1\uc790\uc0b0","permalink":"/blog/en/finance/tags/\uac00\uc0c1\uc790\uc0b0"},{"inline":true,"label":"\uac70\ub798\uc18c\ubcf4\uc548","permalink":"/blog/en/finance/tags/\uac70\ub798\uc18c\ubcf4\uc548"},{"inline":true,"label":"\ud56b\uc6d4\ub81b","permalink":"/blog/en/finance/tags/\ud56b\uc6d4\ub81b"},{"inline":true,"label":"\ucf5c\ub4dc\uc6d4\ub81b","permalink":"/blog/en/finance/tags/\ucf5c\ub4dc\uc6d4\ub81b"}],"readingTime":2.75,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"crypto-exchange-security-structure","title":"\uac00\uc0c1\uc790\uc0b0 \uac70\ub798\uc18c \ubcf4\uc548 \uad6c\uc870, \ud56b\uc6d4\ub81b\uacfc \ucf5c\ub4dc\uc6d4\ub81b\uc744 \ub098\ub204\ub294 \uc774\uc720","authors":["way"],"tags":["finance","\uac00\uc0c1\uc790\uc0b0","\uac70\ub798\uc18c\ubcf4\uc548","\ud56b\uc6d4\ub81b","\ucf5c\ub4dc\uc6d4\ub81b"]},"unlisted":false,"nextItem":{"title":"\uc789\uc5ec\ud604\uae08\ud750\ub984\uc73c\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc5ec\uc720 \uc790\uae08, \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \uc0ac\ub840\ub85c \uc774\ud574\ud558\uae30","permalink":"/blog/en/finance/fcf-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ub300\uaddc\ubaa8 \uac70\ub798\uc18c \ud574\ud0b9 \ubcf4\ub3c4\ub97c \uacc4\uae30\ub85c \uac00\uc0c1\uc790\uc0b0 \uac70\ub798\uc18c\uc758 \ubcf4\uc548 \uad6c\uc870\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc138\uacc4 \ucd5c\ub300 \uac00\uc0c1\uc790\uc0b0 \uac70\ub798\uc18c \ubc14\uc774\ub0b8\uc2a4\uc5d0\uc11c \uc57d 63\uc5b5\ub2ec\ub7ec \uaddc\ubaa8\uc758 \ud574\ud0b9 \ud53c\ud574\uac00 \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\ud654\ub85c \ud658\uc0b0\ud558\uba74 \uc57d 8\uc8704,000\uc5b5\uc6d0\uc5d0 \uc774\ub974\ub294 \uaddc\ubaa8\uc785\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uacf5\uaca9\uc740 10\uc6d4 30\uc77c \uc624\uc804 5\uc2dc 5\ubd84 \ud55c\uad6d\uc2dc\uac04\uc5d0 \ud56b\uc6d4\ub81b\uc744 \ub300\uc0c1\uc73c\ub85c \uc774\ub904\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc14\uc774\ub0b8\uc2a4\ub294 \ucd9c\uae08\uc744 \uc77c\uc2dc \uc911\ub2e8\ud558\uace0 \ubcf4\uc548 \uc810\uac80\uc5d0 \ub4e4\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ud6c4 \ubc14\uc774\ub0b8\uc2a4\ub294 \ud53c\ud574\uc561\uc744 \uc774\uc6a9\uc790\uac00 \uc544\ub2cc \ud68c\uc0ac \uc790\uae08\uacfc \uc774\uc6a9\uc790 \ubcf4\ud638\uae30\uae08\uc73c\ub85c \uc804\uc561 \ubd80\ub2f4\ud558\uaca0\ub2e4\ub294 \ubc29\uce68\uc744 \ubc1d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \uacbd\uacfc\ub294 [\ud30c\uc774\ub0b8\uc15c\ub274\uc2a4 \ubcf4\ub3c4](https://www.fnnews.com/news/202610311336499530)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExemthdWkydWRmam1oZ2hneGZlcjM1amEybTl6ZDB2MDE5YXgxeDVqOCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/gHPOb1fEVWu5GHL2tk/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \ud56b\uc6d4\ub81b\uacfc \ucf5c\ub4dc\uc6d4\ub81b\uc758 \uad6c\ubd84\\n\\n\uac00\uc0c1\uc790\uc0b0 \uc9c0\uac11\uc740 \uc778\ud130\ub137 \uc5f0\uacb0 \uc5ec\ubd80\ub85c \ud06c\uac8c \ub450 \uac00\uc9c0\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\ud56b\uc6d4\ub81b\uc740 \uc778\ud130\ub137\uc5d0 \uc5f0\uacb0\ub41c \uc9c0\uac11\uc73c\ub85c, \uc785\ucd9c\uae08\uacfc \uac70\ub798\ub97c \ube60\ub974\uac8c \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf5c\ub4dc\uc6d4\ub81b\uc740 \uc778\ud130\ub137\uacfc \ubd84\ub9ac\ub41c \ud658\uacbd\uc5d0 \ubcf4\uad00\ud558\ub294 \uc9c0\uac11\uc73c\ub85c, \uc6d0\uaca9 \ud0c8\ucde8 \uc704\ud5d8\uc744 \ub0ae\ucd94\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uac70\ub798\uc18c\ub294 \ube60\ub978 \ucd9c\uae08\uc744 \uc704\ud574 \uc77c\ubd80 \uc790\uc0b0\uc744 \ud56b\uc6d4\ub81b\uc5d0 \ub450\uace0, \ub098\uba38\uc9c0 \uc790\uc0b0\uc744 \uc624\ud504\ub77c\uc778\uc5d0 \ubd84\uc0b0 \ubcf4\uad00\ud558\ub294 \ubc29\uc2dd\uc744 \uc501\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uc0ac\ud0dc \uc774\ud6c4 \ucf54\uc778\ubca0\uc774\uc2a4\ub294 \uac1c\uc778\ud0a4\ub97c \uc624\ud504\ub77c\uc778\uc5d0 \ubcf4\uad00\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \uc608\ubc29 \ucc28\uc6d0\uc5d0\uc11c \uc870\uc815\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud06c\ub77c\ucf04\ub3c4 \uc5c5\uacc4 \ubcf4\uc548 \uc0ac\uace0\ub97c \ubd84\uc11d\ud574 \uc790\uc0ac \ubc29\uc5b4 \uccb4\uacc4\uc5d0 \uc801\uc6a9\ud560 \ub300\uc751\ucc45\uc744 \uc810\uac80\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ub0b4\uc6a9\uc740 [EBN \ubcf4\ub3c4](https://www.ebn.co.kr/news/articleView.html?idxno=1729963)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uac70\ub798\uc18c\uac00 \ud568\uaed8 \uc9c0\ub294 \ub450 \uac00\uc9c0 \uc5ed\ud560\\n\\n\uac00\uc0c1\uc790\uc0b0 \uac70\ub798\uc18c\ub294 \uc8fc\uc2dd \uac70\ub798\uc18c\uc640 \uad6c\uc870\uac00 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uac70\ub798 \uc7a5\uc18c\uc778 \ub3d9\uc2dc\uc5d0 \uace0\uac1d \uc790\uc0b0\uc744 \ubcf4\uad00\ud558\ub294 \uc218\ud0c1\uae30\uad00 \uc5ed\ud560\uae4c\uc9c0 \uacb8\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 \ubcf4\uc548 \uc0ac\uace0\uc758 \ud30c\uae09 \ubc94\uc704\uac00 \uac70\ub798 \uc911\ub2e8\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc790\uc0b0 \ubcf4\uad00 \ubb38\uc81c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc14\uc774\ub0b8\uc2a4 \uc0ac\ub840\uc5d0\uc11c\ub294 \ud0c8\ucde8 \uc790\uc0b0 \uac00\uc6b4\ub370 \uc57d 30\uc5b5\ub2ec\ub7ec\uac00 \uc628\uccb4\uc778\uc5d0\uc11c \ub3d9\uacb0\ub410\ub2e4\uace0 \ubcf4\ub3c4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3d9\uacb0\uc740 \ud604\uae08\ud654\ub97c \ub9c9\ub294 \uc870\uce58\uc774\uc9c0\ub9cc, \ud53c\ud574 \ubcf5\uad6c\uc640\ub294 \ub2e4\ub978 \ub2e8\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\ubc14\uc774\ub0b8\uc2a4\ub294 \ud0c8\ucde8 \uc790\uc0b0\uacfc \ub3d9\uc77c\ud55c \uc885\ub958\uc758 \uac00\uc0c1\uc790\uc0b0\uc73c\ub85c \ud53c\ud574\uc561\uc758 \uc57d 80%\ub97c \ucda9\ub2f9\ud560 \uc790\uae08\uc744 \ud655\ubcf4\ud588\ub2e4\uace0 \ubc1d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uba38\uc9c0 20%\uc5d0 \ud574\ub2f9\ud558\ub294 \uac00\uc0c1\uc790\uc0b0\uc740 \uc2dc\uc7a5\uacfc \uc7a5\uc678\uac70\ub798\ub97c \ud1b5\ud574 \ucd94\uac00 \ub9e4\uc785\ud558\uace0 \uc788\ub2e4\uace0 \uc124\uba85\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc900\ube44\uae08 \uc99d\uba85\uacfc \uadf8 \ud55c\uacc4\\n\\n\ubc14\uc774\ub0b8\uc2a4\ub294 \ub2e4\uc74c \ub2ec 2\uc77c\uae4c\uc9c0 \uc900\ube44\uae08 \uc99d\uba85 \uacb0\uacfc\ub97c \uacf5\uac1c\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.<br/>\\n\uc900\ube44\uae08 \uc99d\uba85\uc740 \uac70\ub798\uc18c\uac00 \ubcf4\uc720\ud55c \uc790\uc0b0\uc744 \uc774\uc6a9\uc790\uac00 \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\uac8c \uacf5\uac1c\ud558\ub294 \uc808\ucc28\uc785\ub2c8\ub2e4.<br/>\\n\uc900\ube44\uae08 \uc99d\uba85\uc740 \ubcf4\uc720 \uc790\uc0b0\uc758 \uc874\uc7ac\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc790\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ubcf4\uc720 \uc790\uc0b0\ub9cc\uc73c\ub85c\ub294 \ubd80\ucc44 \uaddc\ubaa8\uc640 \uc790\uc0b0\uc758 \uc2e4\uc81c \ucc98\ubd84 \uac00\ub2a5\uc131\uc744 \ubaa8\ub450 \ud655\uc778\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc900\ube44\uae08 \uc99d\uba85\uc740 \ubcf4\uc548 \uc810\uac80\uc758 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc77d\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\ucd9c\uae08 \uc7ac\uac1c \uc77c\uc815, \uc870\uc0ac \uacb0\uacfc \uacf5\uac1c \uc5ec\ubd80, \uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc774 \ud568\uaed8 \ud655\uc778\ub3fc\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubc14\uc774\ub0b8\uc2a4\ub294 \ubcf4\uc548 \uc810\uac80\uacfc \uc2dc\uc2a4\ud15c \ubcf5\uad6c\ub97c \uac70\uccd0 \uc57d 34\uc2dc\uac04 \uc548\uc5d0 \ucd9c\uae08\uc744 \uc21c\ucc28\uc801\uc73c\ub85c \uc7ac\uac1c\ud558\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud55c\ub2e4\uace0 \ubc1d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc774\uc6a9\uc790\uac00 \ud655\uc778\ud560 \uc810\\n\\n\uac70\ub798\uc18c \ubcf4\uc548 \uc0ac\uace0\uac00 \ub0ac\uc744 \ub54c\ub294 \uacf5\uc2dd \uacf5\uc9c0\ubd80\ud130 \ud655\uc778\ud558\ub294 \uc21c\uc11c\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ucd9c\uae08 \uc911\ub2e8, \uc7ac\uac1c \uc77c\uc815, \ubcf4\uc0c1 \ubc29\uce68\uc740 \uac70\ub798\uc18c \uacf5\uc2dd \ucc44\ub110\uc758 \ubb38\uc7a5\uc73c\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc0ac\uace0\ub97c \ube59\uc790\ud55c \ud53c\uc2f1 \uba54\uc2dc\uc9c0\ub294 \uacf5\uc2dd \uacf5\uc9c0\ubcf4\ub2e4 \uba3c\uc800 \uc774\uc6a9\uc790\uc5d0\uac8c \ub3c4\ub2ec\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd9c\uae08 \uc7ac\uac1c\ub97c \uc548\ub0b4\ud55c\ub2e4\uba70 \uac1c\uc778\ud0a4\ub098 \uc778\uc99d \uc815\ubcf4\ub97c \uc694\uad6c\ud558\ub294 \uba54\uc2dc\uc9c0\ub294 \uc815\uc0c1\uc801\uc778 \uc808\ucc28\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc790\uc2e0\uc758 \uc790\uc0b0\uc774 \uc5b4\ub290 \uc9c0\uac11 \uad6c\uc870\uc5d0 \ubcf4\uad00\ub418\ub294\uc9c0, \ucd9c\uae08 \ud55c\ub3c4\uc640 \ubcf4\uc548 \uc124\uc815\uc774 \uc5b4\ub5bb\uac8c \ub3fc \uc788\ub294\uc9c0\ub3c4 \ud3c9\uc18c\uc5d0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\uc548 \uc0ac\uace0\ub294 \ud2b9\uc815 \uac70\ub798\uc18c\ub9cc\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uc5c5\uacc4 \uc804\uccb4\uc758 \ubcf4\uad00 \uad6c\uc870\ub97c \uc810\uac80\ud558\ub294 \uacc4\uae30\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\ud56b\uc6d4\ub81b\uacfc \ucf5c\ub4dc\uc6d4\ub81b\uc758 \uad6c\ubd84\uc740 \uc18d\ub3c4\uc640 \uc548\uc804 \uc0ac\uc774\uc758 \uc120\ud0dd\uc744 \uad6c\uc870\ub85c \ub9cc\ub4e0 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uad6c\uc870 \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uac70\ub798\uc18c\ub098 \uac00\uc0c1\uc790\uc0b0\uc5d0 \ub300\ud55c \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExemthdWkydWRmam1oZ2hneGZlcjM1amEybTl6ZDB2MDE5YXgxeDVqOCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/KzQPsa71LJUgYS913e/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"fcf-guide","metadata":{"permalink":"/blog/en/finance/fcf-guide","source":"@site/finance/2026-10-31-fcf-guide/index.mdx","title":"\uc789\uc5ec\ud604\uae08\ud750\ub984\uc73c\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc5ec\uc720 \uc790\uae08, \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \uc0ac\ub840\ub85c \uc774\ud574\ud558\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-31T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc789\uc5ec\ud604\uae08\ud750\ub984","permalink":"/blog/en/finance/tags/\uc789\uc5ec\ud604\uae08\ud750\ub984"},{"inline":true,"label":"\ud604\uae08\ud750\ub984","permalink":"/blog/en/finance/tags/\ud604\uae08\ud750\ub984"},{"inline":true,"label":"\uc2e4\uc801","permalink":"/blog/en/finance/tags/\uc2e4\uc801"},{"inline":true,"label":"\uc7ac\ubb34\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uc7ac\ubb34\uc9c0\ud45c"}],"readingTime":2.55,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"fcf-guide","title":"\uc789\uc5ec\ud604\uae08\ud750\ub984\uc73c\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc5ec\uc720 \uc790\uae08, \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \uc0ac\ub840\ub85c \uc774\ud574\ud558\uae30","authors":["way"],"tags":["finance","\uc789\uc5ec\ud604\uae08\ud750\ub984","\ud604\uae08\ud750\ub984","\uc2e4\uc801","\uc7ac\ubb34\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\uac00\uc0c1\uc790\uc0b0 \uac70\ub798\uc18c \ubcf4\uc548 \uad6c\uc870, \ud56b\uc6d4\ub81b\uacfc \ucf5c\ub4dc\uc6d4\ub81b\uc744 \ub098\ub204\ub294 \uc774\uc720","permalink":"/blog/en/finance/crypto-exchange-security-structure"},"nextItem":{"title":"\ud55c\ubbf8 \uae08\ub9ac\ucc28 1.00%\ud3ec\uc778\ud2b8, \uaca9\ucc28\uac00 \ud658\uc728\uacfc \uc790\uae08 \ud750\ub984\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5","permalink":"/blog/en/finance/korea-us-rate-gap"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc2e4\uc801 \ubc1c\ud45c\uc5d0\uc11c \uc790\uc8fc \ub4f1\uc7a5\ud558\ub294 \uc789\uc5ec\ud604\uae08\ud750\ub984\uc758 \uc758\ubbf8\uc640 \uc77d\ub294 \ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 \uc2e4\uc801 \uc2dc\uc98c\uc5d0\ub294 \uc21c\uc774\uc775\ubcf4\ub2e4 \ud604\uae08\ud750\ub984\uc774 \uc2dc\uc7a5\uc758 \ud3c9\uac00\ub97c \uac00\ub978 \uc0ac\ub840\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uae00 \ubaa8\ud68c\uc0ac \uc54c\ud30c\ubcb3\uc740 3\ubd84\uae30 \ub9e4\ucd9c\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc789\uc5ec\ud604\uae08\ud750\ub984\uc774 91\uc5b5\ub2ec\ub7ec \uc801\uc790\ub97c \uae30\ub85d\ud558\uba70 2\ubd84\uae30 \uc5f0\uc18d \ub9c8\uc774\ub108\uc2a4\ub97c \uc774\uc5b4\uac14\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \ubcf4\ub3c4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3 \uc8fc\uac00\ub294 12.64% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\ub9c8\uc874\ub3c4 3\ubd84\uae30 \uc2e4\uc801\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\uace0, \ucd5c\uadfc 12\uac1c\uc6d4 \uc789\uc5ec\ud604\uae08\ud750\ub984\uc774 424\uc5b5\ub2ec\ub7ec \uc21c\uc720\ucd9c\ub85c \uc804\ud658\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \uc54c\ud30c\ubcb3 \uc2e4\uc801 \ub0b4\uc6a9\uc740 [\uacbd\ud5a5\uc2e0\ubb38 \ubcf4\ub3c4](https://www.khan.co.kr/article/202610301616001)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZm40bWNndWl4Njc4Znl3OHRvamVvZTNweXo2bHZkc29ra3o0NHVxOSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/Mb45IG9wYMA4BhXghS/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc789\uc5ec\ud604\uae08\ud750\ub984\uc758 \uacc4\uc0b0\ubc95\\n\\n\uc789\uc5ec\ud604\uae08\ud750\ub984\uc740 \uae30\uc5c5\uc774 \ubcf8\uc5c5\uc5d0\uc11c \ubc8c\uc5b4\ub4e4\uc778 \ud604\uae08\uc5d0\uc11c \uc124\ube44\ud22c\uc790\uc5d0 \uc4f4 \ud604\uae08\uc744 \ube80 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0\uc2dd\uc740 `\uc789\uc5ec\ud604\uae08\ud750\ub984 = \uc601\uc5c5\ud65c\ub3d9\ud604\uae08\ud750\ub984 - \uc790\ubcf8\uc801 \uc9c0\ucd9c` \uc785\ub2c8\ub2e4.<br/>\\n\uc601\uc5c5\ud65c\ub3d9\ud604\uae08\ud750\ub984\uc740 \uc81c\ud488 \ud310\ub9e4\uc640 \uc11c\ube44\uc2a4 \uc81c\uacf5\uc73c\ub85c \uc2e4\uc81c\ub85c \ub4e4\uc5b4\uc624\uace0 \ub098\uac04 \ud604\uae08\uc758 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc790\ubcf8\uc801 \uc9c0\ucd9c\uc740 \uacf5\uc7a5, \uc124\ube44, \ub370\uc774\ud130\uc13c\ud130 \uac19\uc740 \uc7a5\uae30 \uc790\uc0b0\uc5d0 \ud22c\uc790\ud55c \ud604\uae08\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \uac12\uc744 \ube80 \ub098\uba38\uc9c0\uac00 \uae30\uc5c5\uc774 \uc790\uc720\ub86d\uac8c \uc4f8 \uc218 \uc788\ub294 \uc5ec\uc720 \uc790\uae08\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc5ec\uc720 \uc790\uae08\uc740 \ubd80\ucc44 \uc0c1\ud658, \ubc30\ub2f9, \uc790\uc0ac\uc8fc \ub9e4\uc785, \ucd94\uac00 \ud22c\uc790\uc758 \uc7ac\uc6d0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc21c\uc774\uc775\uacfc \ud604\uae08\ud750\ub984\uc774 \uc5b4\uae0b\ub098\ub294 \uc774\uc720\\n\\n\uc21c\uc774\uc775\uacfc \ud604\uae08\ud750\ub984\uc740 \uac19\uc740 \uae30\uac04\uc5d0\ub3c4 \ub2e4\ub978 \uc22b\uc790\ub97c \ubcf4\uc5ec\uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc21c\uc774\uc775\uc740 \ub9e4\ucd9c\uc774 \ubc1c\uc0dd\ud558\uba74 \ud604\uae08\uc774 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uc558\uc5b4\ub3c4 \uc218\uc775\uc73c\ub85c \uc778\uc2dd\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac10\uac00\uc0c1\uac01 \uac19\uc740 \ube44\ud604\uae08 \ube44\uc6a9\ub3c4 \uc21c\uc774\uc775\uc5d0\ub294 \ubc18\uc601\ub418\uc9c0\ub9cc \ud604\uae08 \uc720\ucd9c\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc7ac\uace0\uc640 \ub9e4\ucd9c\ucc44\uad8c \uac19\uc740 \uc6b4\uc804\uc790\ubcf8\uc758 \ubcc0\ub3d9\ub3c4 \ud604\uae08\ud750\ub984\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc124\ube44\ud22c\uc790\ub294 \uc21c\uc774\uc775\uc5d0 \ud55c \ubc88\uc5d0 \ubc18\uc601\ub418\uc9c0 \uc54a\uace0 \uc5ec\ub7ec \ud574\uc5d0 \ub098\ub220 \ube44\uc6a9 \ucc98\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc124\ube44\ud22c\uc790\uc5d0 \uc4f4 \ud604\uae08\uc740 \ud22c\uc790\ud55c \ud574\uc5d0 \ubc14\ub85c \ube60\uc838\ub098\uac11\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 \ub300\uaddc\ubaa8 \ud22c\uc790 \uc2dc\uae30\uc5d0\ub294 \uc21c\uc774\uc775\uc774 \uc591\ud638\ud574\ub3c4 \ud604\uae08\ud750\ub984\uc774 \uc545\ud654\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \uc0ac\ub840\ub85c \ubcf4\ub294 \ud574\uc11d\\n\\n\uc54c\ud30c\ubcb3 \uc0ac\ub840\uc5d0\uc11c\ub294 \ub9e4\ucd9c \ubd80\uc9c4\uacfc \ud604\uae08\ud750\ub984 \uc801\uc790\uac00 \ud568\uaed8 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ucd9c\uc774 \uc608\uc0c1\uc5d0 \ubbf8\uce58\uc9c0 \ubabb\ud55c \ub370\ub2e4 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790\uac00 \ud604\uae08 \uc9c0\ucd9c\uc744 \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc740 \ud22c\uc790 \uc790\uccb4\ubcf4\ub2e4, \ud22c\uc790 \ub300\ube44 \uc218\uc775\uc774 \uc5b8\uc81c \ub098\ud0c0\ub098\ub294\uc9c0\ub97c \ubb3c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\ub9c8\uc874 \uc0ac\ub840\uc5d0\uc11c\ub294 3\ubd84\uae30 \uc8fc\ub2f9\uc21c\uc774\uc775 1.89\ub2ec\ub7ec\uc640 \ub9e4\ucd9c 2,019\uc5b54,000\ub9cc\ub2ec\ub7ec\uac00 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc62c\ud574 \uc124\ube44\ud22c\uc790 \uacc4\ud68d\uc774 2,200\uc5b5\ub2ec\ub7ec\ub85c \uc720\uc9c0\ub41c\ub2e4\ub294 \uc810\ub3c4 \ud604\uae08 \uc9c0\ucd9c \ubd80\ub2f4\uc73c\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc0ac\ub840 \ubaa8\ub450 \ud22c\uc790 \ud655\ub300\uac00 \ub098\uc05c \uc2e0\ud638\ub77c\ub294 \uc758\ubbf8\ub294 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ud22c\uc790\ud55c \uc790\uc0b0\uc774 \ub9e4\ucd9c\uacfc \uc774\uc775\uc73c\ub85c \uc804\ud658\ub418\ub294 \uc18d\ub3c4\uac00 \uc2dc\uc7a5\uc758 \ud3c9\uac00 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \uc544\ub9c8\uc874 \uc2e4\uc801 \ub0b4\uc6a9\uc740 [\uc804\ub0a8\uc77c\ubcf4 \ubcf4\ub3c4](https://www.jnilbo.com/news/articleView.html?idxno=90000078310)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc789\uc5ec\ud604\uae08\ud750\ub984\uc740 \ud55c \ubd84\uae30 \uc218\uce58\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\uc124\ube44\ud22c\uc790\ub294 \ubd84\uae30\ubcc4\ub85c \ub4e4\ucb49\ub0a0\ucb49\ud558\uac8c \uc9d1\ud589\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \ubd84\uae30\ub97c \ud569\uc0b0\ud574 \ud750\ub984\uc744 \ubcf4\uac70\ub098, \uc804\ub144 \ub3d9\uae30 \uac19\uc740 \uacc4\uc808\uc131\uc744 \ube44\uad50\ud558\ub294 \ubc29\ubc95\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ud604\uae08\ud750\ub984\uc774 \uc801\uc790\ub77c\ub3c4 \ud22c\uc790 \ubaa9\uc801\uacfc \ud22c\uc790 \ud68c\uc218 \uacc4\ud68d\uc744 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130\ub098 \uacf5\uc7a5 \ud22c\uc790\ub294 \uc644\uacf5 \uc774\ud6c4 \ub9e4\ucd9c\ub85c \uc774\uc5b4\uc9c0\ub294 \ub370 \uc2dc\uac04\uc774 \uac78\ub9bd\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \ud604\uae08\ud750\ub984\uc774 \ud751\uc790\ub77c\ub3c4 \uc124\ube44\ud22c\uc790\ub97c \uc904\uc778 \uacb0\uacfc\uc778\uc9c0, \ubcf8\uc5c5 \ud604\uae08\uc774 \ub298\uc5b4\ub09c \uacb0\uacfc\uc778\uc9c0 \uad6c\ubd84\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uacfc \uc790\uc0ac\uc8fc \ub9e4\uc785\uc774 \uc789\uc5ec\ud604\uae08\ud750\ub984 \ubc94\uc704 \uc548\uc5d0\uc11c \uc774\ub904\uc9c0\ub294\uc9c0\ub3c4 \ud568\uaed8 \uc810\uac80\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc789\uc5ec\ud604\uae08\ud750\ub984\uc740 \uae30\uc5c5\uc774 \uc2e4\uc81c\ub85c \uc190\uc5d0 \uc954 \uc5ec\uc720 \uc790\uae08\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc9c0\ud45c \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc5d0 \ub300\ud55c \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZm40bWNndWl4Njc4Znl3OHRvamVvZTNweXo2bHZkc29ra3o0NHVxOSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/S5Rrp6vIOSxZGz8RE3/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"korea-us-rate-gap","metadata":{"permalink":"/blog/en/finance/korea-us-rate-gap","source":"@site/finance/2026-10-31-korea-us-rate-gap/index.mdx","title":"\ud55c\ubbf8 \uae08\ub9ac\ucc28 1.00%\ud3ec\uc778\ud2b8, \uaca9\ucc28\uac00 \ud658\uc728\uacfc \uc790\uae08 \ud750\ub984\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-31T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uae30\uc900\uae08\ub9ac","permalink":"/blog/en/finance/tags/\uae30\uc900\uae08\ub9ac"},{"inline":true,"label":"\ud55c\ubbf8\uae08\ub9ac\ucc28","permalink":"/blog/en/finance/tags/\ud55c\ubbf8\uae08\ub9ac\ucc28"},{"inline":true,"label":"\ud658\uc728","permalink":"/blog/en/finance/tags/\ud658\uc728"},{"inline":true,"label":"\ud55c\uad6d\uc740\ud589","permalink":"/blog/en/finance/tags/\ud55c\uad6d\uc740\ud589"},{"inline":true,"label":"\uc5f0\uc900","permalink":"/blog/en/finance/tags/\uc5f0\uc900"}],"readingTime":2.9,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"korea-us-rate-gap","title":"\ud55c\ubbf8 \uae08\ub9ac\ucc28 1.00%\ud3ec\uc778\ud2b8, \uaca9\ucc28\uac00 \ud658\uc728\uacfc \uc790\uae08 \ud750\ub984\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5","authors":["way"],"tags":["finance","\uae30\uc900\uae08\ub9ac","\ud55c\ubbf8\uae08\ub9ac\ucc28","\ud658\uc728","\ud55c\uad6d\uc740\ud589","\uc5f0\uc900"]},"unlisted":false,"prevItem":{"title":"\uc789\uc5ec\ud604\uae08\ud750\ub984\uc73c\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc5ec\uc720 \uc790\uae08, \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \uc0ac\ub840\ub85c \uc774\ud574\ud558\uae30","permalink":"/blog/en/finance/fcf-guide"},"nextItem":{"title":"10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc \uc2dc\uc7a5 \uc815\ub9ac, \ubbf8\uad6d \uae30\uc220\uc8fc \uae09\ub77d\uc774 \ub0a8\uae34 \ub2e4\uc74c \uc8fc \ud655\uc778 \ubaa9\ub85d","permalink":"/blog/en/finance/weekly-market-review-oct31"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ud55c\ubbf8 \uae30\uc900\uae08\ub9ac \uaca9\ucc28\uc758 \uc758\ubbf8\uc640 \ud658\uc728, \uc790\uae08 \ud750\ub984\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\ubbf8\uad6d \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\ub294 10\uc6d4 27\uc77c\uacfc 28\uc77c\uc5d0 \uc5f4\ub9b0 \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\uc5d0\uc11c \uae30\uc900\uae08\ub9ac\ub97c \ub3d9\uacb0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3d9\uacb0\ub41c \uae30\uc900\uae08\ub9ac\ub294 \uc5f0 3.75%\uc5d0\uc11c 4.00% \uc0ac\uc774\uc785\ub2c8\ub2e4.<br/>\\n\uc704\uc6d0 12\uba85 \uac00\uc6b4\ub370 10\uba85\uc774 \ub3d9\uacb0\uc5d0 \ucc2c\uc131\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9ac\uc0ac \ucfe1 \uc5f0\uc900 \uc774\uc0ac\uc640 \ubca0\uc2a4 \ud574\ub9e5 \ud074\ub9ac\ube14\ub79c\ub4dc \uc5f0\ubc29\uc900\ube44\uc740\ud589 \ucd1d\uc7ac\ub294 0.25%\ud3ec\uc778\ud2b8 \uc778\uc0c1\uc744 \uc8fc\uc7a5\ud558\uba70 \ubc18\ub300\ud45c\ub97c \ub358\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc740\ud589\uc740 10\uc6d4 22\uc77c\uc5d0 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub85c\uc368 \ud55c\uad6d\uacfc \ubbf8\uad6d\uc758 \uae30\uc900\uae08\ub9ac \uaca9\ucc28\ub294 \uc0c1\ub2e8 \uae30\uc900 1.00%\ud3ec\uc778\ud2b8\ub85c \uc720\uc9c0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \uacb0\uc815 \ubc30\uacbd\uc740 [\ub274\uc2dc\uc548 \ubcf4\ub3c4](https://www.newsian.co.kr/news/articleView.html?idxno=100347)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExcHh4Zm1zMW9ucWdocnR2ZHpjMHV5Nmpub2JhbHU1c2R1eWt6ZDhjNSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/GFIpUu2yP0C5UEN10L/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uae08\ub9ac\ucc28\uc758 \uacc4\uc0b0\ubc95\\n\\n\ud55c\ubbf8 \uae08\ub9ac\ucc28\ub294 \ub450 \ub098\ub77c \uae30\uc900\uae08\ub9ac\uc758 \ucc28\uc774\ub85c \uacc4\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\ud604\uc7ac \ubbf8\uad6d\uc758 \uae30\uc900\uae08\ub9ac \uc0c1\ub2e8\uc740 4.00%\uc774\uace0, \ud55c\uad6d\uc758 \uae30\uc900\uae08\ub9ac\ub294 3.00%\uc785\ub2c8\ub2e4.<br/>\\n\uc0c1\ub2e8 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud558\uba74 `4.00% - 3.00% = 1.00%\ud3ec\uc778\ud2b8` \uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\ucc28\ub294 \uc5b4\ub290 \ud55c\ucabd \uae08\ub9ac\ub9cc\uc73c\ub85c \uc815\ud574\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc774 \uae08\ub9ac\ub97c \uc62c\ub9ac\uac70\ub098 \ud55c\uad6d\uc774 \uae08\ub9ac\ub97c \ub0b4\ub9ac\uba74 \uaca9\ucc28\ub294 \ubc8c\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \ubbf8\uad6d\uc774 \uae08\ub9ac\ub97c \ub0b4\ub9ac\uac70\ub098 \ud55c\uad6d\uc774 \uae08\ub9ac\ub97c \uc62c\ub9ac\uba74 \uaca9\ucc28\ub294 \uc881\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uae08\ub9ac\ucc28\ub294 \ub450 \ub098\ub77c \ud1b5\ud654\uc815\ucc45\uc758 \uc0c1\ub300\uc801\uc778 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uaca9\ucc28\uac00 \uc790\uae08 \ud750\ub984\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\\n\\n\uae08\ub9ac\uac00 \ub192\uc740 \ub098\ub77c\uc758 \uc790\uc0b0\uc740 \uc774\uc790 \uc218\uc775 \uce21\uba74\uc5d0\uc11c \uc0c1\ub300\uc801\uc73c\ub85c \uc720\ub9ac\ud574 \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 \uae08\ub9ac\ucc28\uac00 \ubc8c\uc5b4\uc9c0\uba74 \uc790\uae08\uc774 \uae08\ub9ac\uac00 \ub192\uc740 \ucabd\uc73c\ub85c \uc774\ub3d9\ud560 \uc720\uc778\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc790\uae08 \uc774\ub3d9\uc774 \uc6d0\ud654 \uc57d\uc138 \uc555\ub825\uc73c\ub85c \uc774\uc5b4\uc9c0\uba74 \uc218\uc785 \ubb3c\uac00\ub97c \ud1b5\ud574 \uad6d\ub0b4 \ubb3c\uac00\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uae08\ub9ac\ucc28\uac00 \uc881\uc544\uc9c0\uba74 \uc790\uae08 \uc720\ucd9c \uc555\ub825\uc740 \uc0c1\ub300\uc801\uc73c\ub85c \uc644\ud654\ub429\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc790\uae08 \ud750\ub984\uc740 \uae08\ub9ac\ucc28 \ud558\ub098\ub9cc\uc73c\ub85c \uacb0\uc815\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc131\uc7a5 \uc804\ub9dd, \ud658\uc728 \ubcc0\ub3d9\uc131, \uc9c0\uc815\ud559\uc801 \uc704\ud5d8, \uc790\uc0b0 \uc2dc\uc7a5\uc758 \uc218\uc775\ub960\ub3c4 \ud568\uaed8 \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\ucc28\uc640 \uc790\uae08 \ud750\ub984\uc744 \uc5f0\uacb0\ud560 \ub54c\ub294 \ub2e4\ub978 \ubcc0\uc218\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud55c\uad6d\uc740\ud589\uc774 \ucd94\uac00 \uc778\uc0c1\uc744 \uc800\uc6b8\uc9c8\ud558\ub294 \uc774\uc720\\n\\n\ud55c\uad6d\uc740\ud589\uc740 \uc62c\ud574 7\uc6d4\uacfc 8\uc6d4\uc5d0 \uae30\uc900\uae08\ub9ac\ub97c \ub450 \ucc28\ub840 \uc62c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n7\uc6d4\uc5d0\ub294 \uc5f0 2.50%\uc5d0\uc11c 2.75%\ub85c, 8\uc6d4\uc5d0\ub294 \uc5f0 3.00%\ub85c \uc778\uc0c1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ub3d9\uacb0\uc740 \uae34\ucd95 \uc0ac\uc774\ud074\uc758 \uc885\ub8cc\ub97c \uc758\ubbf8\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ud568\uaed8 \uc124\uba85\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd94\uac00 \uc778\uc0c1\ub860\uc5d0 \ud798\uc774 \uc2e4\ub9ac\ub294 \uadfc\uac70\ub85c\ub294 \uac15\ud55c \uc131\uc7a5\uc138\uc640 \ub192\uc740 \ubb3c\uac00\uac00 \uaf3d\ud799\ub2c8\ub2e4.<br/>\\n\uc62c\ud574 3\ubd84\uae30 \uc2e4\uc9c8 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0\uc740 \uc804\ubd84\uae30 \ub300\ube44 1.0%, \uc804\ub144 \ub3d9\uae30 \ub300\ube44 3.4% \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n9\uc6d4 \uc18c\ube44\uc790\ubb3c\uac00\ub294 \uc804\ub144 \ub3d9\uc6d4 \ub300\ube44 2.9% \uc62c\ub790\uace0, \uc2dd\ub8cc\ud488\uacfc \uc5d0\ub108\uc9c0\ub97c \uc81c\uc678\ud55c \uadfc\uc6d0\ubb3c\uac00\ub3c4 2.8% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc218\uce58 \ubaa8\ub450 \ud55c\uad6d\uc740\ud589 \ubb3c\uac00\uc548\uc815 \ubaa9\ud45c\uc778 2.0%\ub97c \uc6c3\ub3d5\ub2c8\ub2e4.<br/>\\n\\n\uae08\ub9ac \uc778\uc0c1\uc758 \ubd80\ub2f4\ub3c4 \ud568\uaed8 \uacc4\uc0b0\ub429\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc740\ud589 \ubd84\uc11d\uc5d0 \ub530\ub974\uba74 \uae08\ub9ac\uac00 0.25%\ud3ec\uc778\ud2b8 \uc624\ub974\uba74 \uac00\uacc4 \uc774\uc790 \ubd80\ub2f4\uc740 \uc57d 3\uc8703,000\uc5b5\uc6d0 \uc99d\uac00\ud569\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc870\uac74\uc5d0\uc11c \uae30\uc5c5 \uc774\uc790 \ubd80\ub2f4\uc740 \uc57d 3\uc8706,000\uc5b5\uc6d0 \uc99d\uac00\ud558\ub294 \uac83\uc73c\ub85c \ubd84\uc11d\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\uc6b8 \uc678\ud658\uc2dc\uc7a5\uc5d0\uc11c \uc6d0\ub2ec\ub7ec \ud658\uc728\uc740 10\uc6d4 30\uc77c\uc5d0 1,334.3\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacb0\uc815\uc740 \ubb3c\uac00\uc640 \uc131\uc7a5, \ud658\uc728, \uac00\uacc4\uc640 \uae30\uc5c5\uc758 \uc774\uc790 \ubd80\ub2f4\uc744 \ud568\uaed8 \uc800\uc6b8\uc9c8\ud558\ub294 \uacfc\uc815\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uae08\ub9ac\ucc28\ub97c \ubcfc \ub54c\ub294 \uc0c1\ub2e8\uacfc \ud558\ub2e8\uc744 \uad6c\ubd84\ud574\uc11c \uacc4\uc0b0\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uae30\uc900\uae08\ub9ac\ub294 \uad6c\uac04\uc73c\ub85c \ubc1c\ud45c\ub418\ubbc0\ub85c, \uc0c1\ub2e8 \uae30\uc900\uacfc \ud558\ub2e8 \uae30\uc900\uc758 \uaca9\ucc28\ub294 \ub2e4\ub974\uac8c \ub098\uc635\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \ud655\uc778 \uc9c0\uc810\uc740 11\uc6d4 3\uc77c\uc5d0 \ubc1c\ud45c\ub418\ub294 10\uc6d4 \uc18c\ube44\uc790\ubb3c\uac00\uc785\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00\uac00 \ubaa9\ud45c \uc218\uc900\uc73c\ub85c \uc218\ub834\ud558\ub294\uc9c0\uac00 \ud55c\uad6d\uc740\ud589\uc758 \ub2e4\uc74c \uacb0\uc815\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc758 \ub2e4\uc74c \ud589\ubcf4\ub97c \ubcfc \ub54c\ub294 \uc5f0\uc900 \uc704\uc6d0\ub4e4\uc758 \ubc1c\uc5b8\ubcf4\ub2e4 \uacbd\uc81c\uc9c0\ud45c\uc758 \ubc29\ud5a5\uc744 \uba3c\uc800 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\ucc28 \uc790\uccb4\ubcf4\ub2e4, \uaca9\ucc28\uac00 \uc881\uc544\uc9c0\ub294\uc9c0 \ubc8c\uc5b4\uc9c0\ub294\uc9c0\uc758 \ubc29\ud5a5\uc774 \uc790\uae08 \ud750\ub984 \ud574\uc11d\uc758 \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\ud55c\ubbf8 \uae08\ub9ac\ucc28 1.00%\ud3ec\uc778\ud2b8\ub294 \ub450 \ub098\ub77c \ud1b5\ud654\uc815\ucc45 \ubc29\ud5a5\uc758 \ucc28\uc774\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc22b\uc790\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc9c0\ud45c \uc815\ub9ac\uc774\uba70, \uae08\ub9ac \uc804\ub9dd\uc774\ub098 \ud22c\uc790 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExcHh4Zm1zMW9ucWdocnR2ZHpjMHV5Nmpub2JhbHU1c2R1eWt6ZDhjNSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/LfdqXjLQB6YGhyMhVQ/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"weekly-market-review-oct31","metadata":{"permalink":"/blog/en/finance/weekly-market-review-oct31","source":"@site/finance/2026-10-31-weekly-market-review-oct31/index.mdx","title":"10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc \uc2dc\uc7a5 \uc815\ub9ac, \ubbf8\uad6d \uae30\uc220\uc8fc \uae09\ub77d\uc774 \ub0a8\uae34 \ub2e4\uc74c \uc8fc \ud655\uc778 \ubaa9\ub85d","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-31T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/finance/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\ub2e4\uc74c\uc8fc\uc77c\uc815","permalink":"/blog/en/finance/tags/\ub2e4\uc74c\uc8fc\uc77c\uc815"}],"readingTime":3.13,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"weekly-market-review-oct31","title":"10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc \uc2dc\uc7a5 \uc815\ub9ac, \ubbf8\uad6d \uae30\uc220\uc8fc \uae09\ub77d\uc774 \ub0a8\uae34 \ub2e4\uc74c \uc8fc \ud655\uc778 \ubaa9\ub85d","authors":["way"],"tags":["finance","\uc2dc\uc7a5\uc815\ub9ac","\ub098\uc2a4\ub2e5","\ucf54\uc2a4\ud53c","\ub2e4\uc74c\uc8fc\uc77c\uc815"]},"unlisted":false,"prevItem":{"title":"\ud55c\ubbf8 \uae08\ub9ac\ucc28 1.00%\ud3ec\uc778\ud2b8, \uaca9\ucc28\uac00 \ud658\uc728\uacfc \uc790\uae08 \ud750\ub984\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5","permalink":"/blog/en/finance/korea-us-rate-gap"},"nextItem":{"title":"\uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654\uc5d0 \ub728\uc9c0 \uc54a\ub294 \uc601\uc218\uc99d, 11\uc6d4\uc5d0 \ubbf8\ub9ac \ucc59\uae30\ub294 \uc11c\ub958 \uc810\uac80","permalink":"/blog/en/finance/yearend-tax-documents"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ud1a0\uc694\uc77c \ud734\uc7a5\uc744 \ub9de\uc544 10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc \uc2dc\uc7a5 \ud750\ub984\uacfc \ub2e4\uc74c \uc8fc\uc5d0 \ud655\uc778\ud560 \uc77c\uc815\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \uc2dc\uc7a5 \uc804\uccb4\ub85c \ubc88\uc9c4 \ud55c \uc8fc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uae00 \ubaa8\ud68c\uc0ac \uc54c\ud30c\ubcb3\uc758 \uc2e4\ub9dd\uc2a4\ub7ec\uc6b4 \uc2e4\uc801\uc5d0 \uc774\uc5b4 \uc544\ub9c8\uc874\uacfc \uc778\ud154\uc758 \uc2e4\uc801 \ubc1c\ud45c\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uae30\uc220\uc8fc \ub9e4\ub3c4\uc138\uac00 \uad6d\ub0b4 \uc99d\uc2dc\ub85c \uc804\uc774\ub418\uba70 \ucf54\uc2a4\ud53c\ub294 10\uc6d4 30\uc77c\uc5d0 3% \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc99d\uc2dc\ub294 10\uc6d4 31\uc77c \ud1a0\uc694\uc77c\uc5d0 \ud734\uc7a5\ud558\ubbc0\ub85c, \uc774\ub0a0 \uc815\ub9ac\ub294 \uae08\uc694\uc77c \ub9c8\uac10 \uc218\uce58\uc640 \ubbf8\uad6d \uae08\uc694\uc77c \ubc24 \ub9c8\uac10\uc744 \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdzZucGM5Ymo4NGJjNW0zcmIybnZsZnlteXZqZGN0NDQ4c3RxaWU2OCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/7KORtZeI56nUfLyhCs/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \ubbf8\uad6d \uc99d\uc2dc \uae08\uc694\uc77c \ub9c8\uac10\\n\\n10\uc6d4 30\uc77c \ubbf8\uad6d \uc99d\uc2dc\ub294 \uc8fc\uc694 \uc9c0\uc218\uac00 \uc77c\uc81c\ud788 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 747.73\ud3ec\uc778\ud2b8, 2.86% \ub0b4\ub9b0 25,437.00\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 140.32\ud3ec\uc778\ud2b8, 1.82% \ub0b4\ub9b0 7,580.07\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 30 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 572.25\ud3ec\uc778\ud2b8, 1.09% \ub0b4\ub9b0 51,770.31\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \ub9c8\uac10 \uc218\uce58\ub294 [\uc774\ud22c\ub370\uc774 \ubcf4\ub3c4](https://www.etoday.co.kr/news/view/2642505?trc=right_categori_news)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\ud558\ub77d\uc744 \uc774\ub048 \uac83\uc740 \uc778\ud154\uacfc \uc544\ub9c8\uc874\uc758 \uc2e4\uc801 \ubc1c\ud45c\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\ud154\uc740 3\ubd84\uae30 \uc2e4\uc801\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uc744 \uc6c3\ub3cc\uc558\uc73c\ub098 4\ubd84\uae30 \ub9e4\ucd9c \uc804\ub9dd\uc744 150\uc5b5\ub2ec\ub7ec\uc5d0\uc11c 160\uc5b5\ub2ec\ub7ec \uc0ac\uc774\ub85c \uc81c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uc608\uc0c1\uce58\uc778 171\uc5b5\ub2ec\ub7ec\ub97c \ud06c\uac8c \ubc11\ub3c4\ub294 \uc804\ub9dd\uc5d0 \uc778\ud154 \uc8fc\uac00\ub294 28.58% \ud3ed\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\ub9c8\uc874\uc740 3\ubd84\uae30 \uc8fc\ub2f9\uc21c\uc774\uc775 1.89\ub2ec\ub7ec\uc640 \ub9e4\ucd9c 2,019\uc5b54,000\ub9cc\ub2ec\ub7ec\ub97c \uae30\ub85d\ud574 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubaa8\ub450 \ubc11\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\ub9c8\uc874 \uc8fc\uac00\ub294 1.41% \ud558\ub77d\ud558\ub294 \ub370 \uadf8\ucce4\uc73c\ub098, \ubc18\ub3c4\uccb4\uc8fc \uc804\ubc18\uc73c\ub85c \ub9e4\ub3c4\uc138\uac00 \ud655\uc0b0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d4\ube44\ub514\uc544\ub294 4.22%, AMD\ub294 10.88%, SK\ud558\uc774\ub2c9\uc2a4 \ubbf8\uad6d\uc8fc\uc2dd\uc608\ud0c1\uc99d\uc11c\ub294 7.95% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uad6d\ub0b4 \uc99d\uc2dc \ud55c \uc8fc \ud750\ub984\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 10\uc6d4 30\uc77c \ucf54\uc2a4\ud53c \uc885\uac00\ub294 5,730.74\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 206.92\ud3ec\uc778\ud2b8, 3.48% \ud558\ub77d\ud55c \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 28.85\ud3ec\uc778\ud2b8, 3.83% \ub0b4\ub9b0 724.38\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,599.42\uae4c\uc9c0 \ubc00\ub838\ub2e4\uac00 \ub099\ud3ed\uc744 \uc77c\ubd80 \uc904\uc774\uba70 5,700\uc120\uc744 \ud68c\ubcf5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 10\uc2dc 4\ubd84 55\ucd08\uaed8\uc5d0\ub294 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5\uc5d0 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\uac19\uc740 \uae30\uc900 \ucf54\uc2a4\ud53c \uc218\uae09\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 1\uc8706,149\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc740 7,540\uc5b5\uc6d0, \uac1c\uc778\uc740 5,781\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 2\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ud588\uace0, \uae30\uad00\uc740 1,342\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uac1c\uc778\uc740 1,253\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900 \ubcf4\uc548 \uad00\ub828 \ud14c\ub9c8\ub294 2.77% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc790\uae08\uc774 \ubaa8\ub4e0 \uc5c5\uc885\uc5d0\uc11c \ub3d9\uc2dc\uc5d0 \ube60\uc838\ub098\uac04 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub2e4\uc74c \uc8fc\uc5d0 \ud655\uc778\ud560 \uc77c\uc815\\n\\n\ub2e4\uc74c \uc8fc\uc5d0\ub294 \uad6d\ub0b4 \ubb3c\uac00\uc640 \ub300\uc678 \uac70\ub798 \ud750\ub984\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uac00 \uacf5\uac1c\ub429\ub2c8\ub2e4.<br/>\\n\uad6d\uac00\ub370\uc774\ud130\ucc98\ub294 11\uc6d4 3\uc77c\uc5d0 10\uc6d4 \uc18c\ube44\uc790\ubb3c\uac00\ub3d9\ud5a5\uc744 \ubc1c\ud45c\ud569\ub2c8\ub2e4.<br/>\\n9\uc6d4 \uc18c\ube44\uc790\ubb3c\uac00\ub294 \uc804\ub144 \ub3d9\uc6d4 \ub300\ube44 2.9% \uc0c1\uc2b9\ud588\uace0, \ud55c\uad6d\uc740\ud589 \ubb3c\uac00\uc548\uc815 \ubaa9\ud45c\uc778 2.0%\ub97c \uc6c3\ub3cc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc740\ud589\uc740 11\uc6d4 5\uc77c\uc5d0 9\uc6d4 \uad6d\uc81c\uc218\uc9c0\ub97c \ubc1c\ud45c\ud569\ub2c8\ub2e4.<br/>\\n\uc62c\ud574 1\uc6d4\ubd80\ud130 8\uc6d4\uae4c\uc9c0 \ub204\uc801 \uacbd\uc0c1\uc218\uc9c0 \ud751\uc790\ub294 2,792\uc5b5\ub2ec\ub7ec\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735\ub2f9\uad6d \uc77c\uc815\uc73c\ub85c\ub294 11\uc6d4 2\uc77c \uc0dd\uc0b0\uc801 \uae08\uc735 \ub300\uc804\ud658 \ud68c\uc758\uc640 11\uc6d4 5\uc77c \uae08\uc735\uad8c \ud574\ud0b9 \ub300\uc751 \uc804 \uae08\uc735\uad8c \ud68c\uc758\uac00 \uc608\uc815\ub3fc \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \ub2e4\uc74c \uc8fc \uc77c\uc815\uc740 [\uc5f0\ud569\ub274\uc2a4 \ubcf4\ub3c4](https://www.yna.co.kr/amp/view/AKR20261031012200002)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uae09\ub77d \uc774\ud6c4\uc5d0\ub294 \ud558\ub8e8 \ubc18\ub4f1\ubcf4\ub2e4 \ud558\ub77d\uc758 \uc6d0\uc778\uc774 \ud574\uc18c\ub410\ub294\uc9c0\ub97c \uba3c\uc800 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \ud558\ub77d\uc758 \ucd9c\ubc1c\uc810\uc740 \uc2e4\uc801\uacfc \uc804\ub9dd, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ube44\uc6a9\uc5d0 \ub300\ud55c \ud3c9\uac00\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \ubc1c\ud45c\uac00 \uc774\uc5b4\uc9c0\ub294 \ub3d9\uc548\uc5d0\ub294 \uac1c\ubcc4 \uae30\uc5c5\uc758 \uc804\ub9dd\uce58\uac00 \uc2dc\uc7a5 \uc608\uc0c1\uacfc \uc5bc\ub9c8\ub098 \uc5b4\uae0b\ub098\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc218\uae09\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4\uac00 \ud558\ub8e8\ub85c \uadf8\uce58\ub294\uc9c0, \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00 \uc9c0\ud45c\uac00 \ubc1c\ud45c\ub418\ub294 \uc8fc\uc5d0\ub294 \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \ud574\uc11d\uc774 \ub2e4\uc2dc \ubc14\ub014 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ud45c \ubc1c\ud45c \ub2f9\uc77c\uc758 \uc218\uce58\ubcf4\ub2e4, \ubc1c\ud45c \uc774\ud6c4 \uae08\ub9ac\uc640 \ud658\uc728\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \ubc29\ud5a5\uc744 \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc775\uc131 \ub17c\ub780\uc774 \ubbf8\uad6d\uacfc \ud55c\uad6d \uc99d\uc2dc\ub97c \ud568\uaed8 \ud754\ub4e0 \ud55c \uc8fc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNDU4dm1ja3JqaDJnMDdqMDc1YjJqdHN2Y3JmYmV1dzFrcTNyaTU1cSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3ShFD4IvX96027JjhH/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"yearend-tax-documents","metadata":{"permalink":"/blog/en/finance/yearend-tax-documents","source":"@site/finance/2026-10-31-yearend-tax-documents/index.mdx","title":"\uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654\uc5d0 \ub728\uc9c0 \uc54a\ub294 \uc601\uc218\uc99d, 11\uc6d4\uc5d0 \ubbf8\ub9ac \ucc59\uae30\ub294 \uc11c\ub958 \uc810\uac80","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-31T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc5f0\ub9d0\uc815\uc0b0","permalink":"/blog/en/finance/tags/\uc5f0\ub9d0\uc815\uc0b0"},{"inline":true,"label":"\uc808\uc138","permalink":"/blog/en/finance/tags/\uc808\uc138"},{"inline":true,"label":"\uc11c\ub958\uc810\uac80","permalink":"/blog/en/finance/tags/\uc11c\ub958\uc810\uac80"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"}],"readingTime":2.82,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"yearend-tax-documents","title":"\uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654\uc5d0 \ub728\uc9c0 \uc54a\ub294 \uc601\uc218\uc99d, 11\uc6d4\uc5d0 \ubbf8\ub9ac \ucc59\uae30\ub294 \uc11c\ub958 \uc810\uac80","authors":["way"],"tags":["finance","\uc5f0\ub9d0\uc815\uc0b0","\uc808\uc138","\uc11c\ub958\uc810\uac80","\uac1c\uc778\uc7ac\ubb34"]},"unlisted":false,"prevItem":{"title":"10\uc6d4 \ub9c8\uc9c0\ub9c9 \uc8fc \uc2dc\uc7a5 \uc815\ub9ac, \ubbf8\uad6d \uae30\uc220\uc8fc \uae09\ub77d\uc774 \ub0a8\uae34 \ub2e4\uc74c \uc8fc \ud655\uc778 \ubaa9\ub85d","permalink":"/blog/en/finance/weekly-market-review-oct31"},"nextItem":{"title":"\ubca0\ud0c0\ub85c \uc77d\ub294 \uc885\ubaa9\uc758 \uc2dc\uc7a5 \ubbfc\uac10\ub3c4, 1\ubcf4\ub2e4 \ud06c\ub2e4\ub294 \uac83\uc758 \uc758\ubbf8","permalink":"/blog/en/finance/beta-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654 \uc11c\ube44\uc2a4\uc5d0 \uc790\ub3d9\uc73c\ub85c \ub728\uc9c0 \uc54a\ub294 \uc601\uc218\uc99d\uc744 \ubbf8\ub9ac \ucc59\uae30\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654 \uc11c\ube44\uc2a4\ub294 \ubcd1\uc6d0\uacfc \ud559\uad50, \uc740\ud589, \uce74\ub4dc\uc0ac \uac19\uc740 \ubc1c\uae09\uae30\uad00\uc774 \uad6d\uc138\uccad\uc5d0 \uc81c\ucd9c\ud55c \uacf5\uc81c \uc790\ub8cc\ub97c \ud55c\uacf3\uc5d0 \ubaa8\uc544 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc774 \uc11c\ube44\uc2a4\ub294 \ub9e4\ub144 1\uc6d4 15\uc77c \uc804\ud6c4\uc5d0 \uac1c\ud1b5\ub418\ub294 \uac83\uc774 \ud1b5\uc0c1\uc801\uc778 \uc77c\uc815\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\ub09c\ud574\uc5d0\ub294 1\uc6d4 15\uc77c\uc5d0 \uac1c\ud1b5\ud574 45\uac1c \ud56d\ubaa9\uc758 \uacf5\uc81c \uc790\ub8cc\ub97c \uc81c\uacf5\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uac04\uc18c\ud654 \ud654\uba74\uc5d0 \ubaa8\ub4e0 \uacf5\uc81c \uc790\ub8cc\uac00 \uc790\ub3d9\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ubc1c\uae09\uae30\uad00\uc774 \uc790\ub8cc\ub97c \uc81c\ucd9c\ud558\uc9c0 \uc54a\ub294 \ud56d\ubaa9\uc740 \ud654\uba74\uc5d0 \ub728\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud654\uba74\uc5d0 \ub728\uc9c0 \uc54a\ub294\ub2e4\uace0 \ud574\uc11c \uacf5\uc81c \uc790\uccb4\uac00 \uc5c6\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ub0b4\uc6a9\uc740 [\uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654 \uc815\ub9ac \uae00](https://blog.importants-studio.com/posts/yearend-simplified-missing-items-2026/)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExcXkwdDFqYnF0MTE2Z2pqMG4xNWZlaG1hcTRvZXFkMTJwZ3E0ZG55MyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/du6sP3xarXdeg/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uac04\uc18c\ud654\uc5d0 \ub728\uc9c0 \uc54a\uae30 \uc26c\uc6b4 \ud56d\ubaa9\\n\\n\uc2dc\ub825\ubcf4\uc815\uc6a9 \uc548\uacbd\uacfc \ucf58\ud0dd\ud2b8\ub80c\uc988 \uad6c\uc785\ube44\ub294 \uc790\uc8fc \ub204\ub77d\ub418\ub294 \ud56d\ubaa9\uc73c\ub85c \uaf3d\ud799\ub2c8\ub2e4.<br/>\\n\uae30\ubcf8\uacf5\uc81c\ub300\uc0c1\uc790 1\uba85\ub2f9 \uc5f0 50\ub9cc\uc6d0 \ud55c\ub3c4\uac00 \uc801\uc6a9\ub418\ub294 \uac83\uc73c\ub85c \uc815\ub9ac\ub3fc \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\ud559\uc0dd\uacfc \uace0\ub4f1\ud559\uc0dd\uc758 \uad50\ubcf5 \uad6c\uc785\ube44\ub3c4 \ube44\uc2b7\ud55c \uc131\uaca9\uc758 \ud56d\ubaa9\uc785\ub2c8\ub2e4.<br/>\\n\ud559\uc0dd 1\uba85\ub2f9 \uc5f0 50\ub9cc\uc6d0 \ud55c\ub3c4\uac00 \uc801\uc6a9\ub418\ub294 \uac83\uc73c\ub85c \uc815\ub9ac\ub3fc \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucde8\ud559 \uc804 \uc544\ub3d9\uc758 \ud559\uc6d0\ube44\uc640 \uccb4\uc721\uc2dc\uc124 \uad50\uc721\ube44\ub3c4 \ubc1c\uae09\uae30\uad00 \uc81c\ucd9c \uc5ec\ubd80\uc5d0 \ub530\ub77c \ud654\uba74\uc5d0\uc11c \ube60\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\uccad\uae30\uc640 \uc758\ub8cc\uc6a9\uad6c \uad6c\uc785\ube44, \uc77c\ubd80 \uae30\ubd80\uae08 \uc601\uc218\uc99d\ub3c4 \uc9c1\uc811 \ucc59\uaca8\uc57c \ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcd1\uc6d0\uc5d0\uc11c \ub204\ub77d\ud55c \uc758\ub8cc\ube44\ub294 \uc9c4\ub8cc\ube44 \ub0a9\uc785\ud655\uc778\uc11c\ub97c \ubc1c\uae09\ubc1b\uc544 \ubcf4\uc644\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc9c1\uc811 \uc81c\ucd9c\uc774 \ud544\uc694\ud55c \uc11c\ub958\\n\\n\uc6d4\uc138 \uc138\uc561\uacf5\uc81c\ub294 \uc784\ub300\ucc28\uacc4\uc57d\uc11c\uc640 \uc6d4\uc138 \uc774\uccb4 \ub0b4\uc5ed\uc744 \uc9c1\uc811 \uc81c\ucd9c\ud574\uc57c \ud558\ub294 \ud56d\ubaa9\uc785\ub2c8\ub2e4.<br/>\\n\ud604\uae08\uc73c\ub85c \uc9c0\uae09\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc778\uc815\uc774 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc73c\ubbc0\ub85c \uc774\uccb4 \uae30\ub85d\uc744 \ub0a8\uae30\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uae30\ubd80\uae08 \uac00\uc6b4\ub370 \uac04\uc18c\ud654\uc5d0\uc11c \uc81c\uacf5\ub418\uc9c0 \uc54a\ub294 \ud56d\ubaa9\uc740 \uae30\ubd80\uae08 \uc601\uc218\uc99d\uc744 \uc9c1\uc811 \ubc1b\uc544 \ud68c\uc0ac\uc5d0 \uc81c\ucd9c\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc2e4\uc190\ubcf4\ud5d8\uc73c\ub85c \uc218\ub839\ud55c \uae08\uc561\uc740 \uacf5\uc81c \ub300\uc0c1 \uc758\ub8cc\ube44\uc5d0\uc11c \uc81c\uc678\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubcf4\ud5d8\uae08 \uc218\ub839 \ub0b4\uc5ed\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uc758\ub8cc\ube44 \uc804\uc561\uc744 \uc2e0\uccad\ud558\uba74 \ub098\uc911\uc5d0 \uc218\uc815 \uc2e0\uace0\uac00 \ud544\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ud3b8\uacb0\uc81c\ub97c \ud1b5\ud55c \uce74\ub4dc \uc0ac\uc6a9\ubd84\uc740 \uce74\ub4dc\uc0ac\ub098 \uacb0\uc81c \uc571\uc5d0\uc11c \ubcc4\ub3c4 \uc99d\ube59\uc744 \ud655\uc778\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\uc81c \ud56d\ubaa9\ub9c8\ub2e4 \uc778\uc815\ub418\ub294 \uacb0\uc81c \uc2dc\uc810\uacfc \uc99d\ube59 \ud615\uc2dd\uc774 \ub2e4\ub974\ubbc0\ub85c, \ud68c\uc0ac \uc548\ub0b4\uc640 \uad6d\uc138\uccad \uc548\ub0b4\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### 11\uc6d4\uc5d0 \ubbf8\ub9ac \ud560 \uc810\uac80\\n\\n11\uc6d4\uc740 \uc601\uc218\uc99d\uc744 \ubaa8\uc73c\uae30 \uc88b\uc740 \uc2dc\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc548\uacbd\uacfc \uad50\ubcf5\uc740 \ud55c \ud574\uc5d0 \ud55c\ub450 \ubc88 \uc0ac\ub294 \ubb3c\uac74\uc774\ub77c \uc601\uc218\uc99d\uc744 \ubc84\ub9ac\uba74 \ub2e4\uc2dc \uc694\uccad\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uad6c\uc785\ucc98\uc5d0 \uc5f0\ub9d0\uc815\uc0b0\uc6a9 \uc601\uc218\uc99d \ubc1c\uae09\uc744 \uc694\uccad\ud574 \ub450\uba74 1\uc6d4\uc758 \ubc88\uac70\ub85c\uc6c0\uc774 \uc904\uc5b4\ub4ed\ub2c8\ub2e4.<br/>\\n\uc758\ub8cc\ube44\ub294 \ubcd1\uc6d0\ubcc4\ub85c \uc870\ud68c \uc5ec\ubd80\ub97c \ubbf8\ub9ac \ud655\uc778\ud558\uace0, \ub204\ub77d\ub41c \ub0b4\uc5ed\uc774 \uc788\uc73c\uba74 \ub0a9\uc785\ud655\uc778\uc11c\ub97c \uc694\uccad\ud569\ub2c8\ub2e4.<br/>\\n\ubd80\uc591\uac00\uc871 \uacf5\uc81c\ub97c \ubc1b\uc73c\ub824\uba74 \uac00\uc871\uc758 \uc790\ub8cc\uc81c\uacf5 \ub3d9\uc758\uac00 \ud544\uc694\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \ubbf8\ub9ac \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n12\uc6d4 31\uc77c \uc774\uc804 \uacb0\uc81c \uac74\ub9cc \uc778\uc815\ub418\ub294 \ud56d\ubaa9\uc774 \ub9ce\ub2e4\ub294 \uc810\ub3c4 \uc77c\uc815 \uc810\uac80\uc5d0 \ud3ec\ud568\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc5f0\ub9d0\uc5d0 \ubab0\uc544\uc11c \uacb0\uc81c\ud558\uae30\ubcf4\ub2e4, \uacf5\uc81c \ub300\uc0c1 \uc9c0\ucd9c\uc774 \uc5f0\ub0b4\uc5d0 \uc774\ub904\uc84c\ub294\uc9c0 \ub0a0\uc9dc\ubd80\ud130 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc81c\ucd9c\ud560 \ub54c \ud655\uc778\ud560 \uc810\\n\\n\uac04\uc18c\ud654 \uc790\ub8cc\uac00 \ubcf4\uc778\ub2e4\uace0 \ud574\uc11c \uacf5\uc81c \uc694\uac74\uc774 \uc790\ub3d9\uc73c\ub85c \ucda9\uc871\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uad6d\uc138\uccad \uc548\ub0b4\uc5d0\uc11c\ub3c4 \uacf5\uc81c \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294\uc9c0\ub294 \uadfc\ub85c\uc790 \ubcf8\uc778\uc774 \uc9c1\uc811 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\uace0 \uc124\uba85\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\ud1b5 \uc9c1\ud6c4\uc5d0\ub294 \ucd94\uac00\ub418\uac70\ub098 \uc218\uc815\ub41c \uc790\ub8cc\uac00 \uba70\uce60 \ub4a4\uc5d0 \ubc18\uc601\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885 \ud655\uc815\uc790\ub8cc\uac00 \ub098\uc628 \ub4a4\uc5d0 \uc81c\ucd9c \uc11c\ub958\ub97c \ub2e4\uc2dc \ub300\uc870\ud558\ub294 \uc21c\uc11c\uac00 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\uc62c\ud574 \uac1c\ud1b5 \uc77c\uc815\uacfc \uc81c\uacf5 \ud56d\ubaa9\uc740 \uad6d\uc138\uccad \ud648\ud0dd\uc2a4 \uacf5\uc9c0\ub85c \ucd5c\uc885 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc5d0\uc11c \uc18c\uac1c\ud55c \uc77c\uc815\uacfc \ud55c\ub3c4\ub294 \uc608\ub144 \ud328\ud134\uacfc \ubcf4\ub3c4\ub41c \uc815\ub9ac \ub0b4\uc6a9\uc744 \uae30\uc900\uc73c\ub85c \ud55c \uac83\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uac04\uc18c\ud654 \uc11c\ube44\uc2a4\ub294 \uc11c\ub958\ub97c \ubaa8\uc544\uc8fc\ub294 \ub3c4\uad6c\uc774\uace0, \ube60\uc9c4 \uc11c\ub958\ub97c \ucc59\uae30\ub294 \uc77c\uc740 \uadfc\ub85c\uc790\uc758 \ubaab\uc73c\ub85c \ub0a8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \uc815\ubcf4 \uc81c\uacf5 \ubaa9\uc801\uc758 \uc815\ub9ac\uc774\uba70, \uac1c\uc778\ubcc4 \uc138\ubb34 \ud310\ub2e8\uc740 \uad6d\uc138\uccad \uc548\ub0b4\uc640 \ud68c\uc0ac \uc548\ub0b4\ub85c \ucd5c\uc885 \ud655\uc778\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExcXkwdDFqYnF0MTE2Z2pqMG4xNWZlaG1hcTRvZXFkMTJwZ3E0ZG55MyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/i8nNwZo3Ew31m/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"beta-guide","metadata":{"permalink":"/blog/en/finance/beta-guide","source":"@site/finance/2026-10-30-beta-guide/index.mdx","title":"\ubca0\ud0c0\ub85c \uc77d\ub294 \uc885\ubaa9\uc758 \uc2dc\uc7a5 \ubbfc\uac10\ub3c4, 1\ubcf4\ub2e4 \ud06c\ub2e4\ub294 \uac83\uc758 \uc758\ubbf8","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ubca0\ud0c0","permalink":"/blog/en/finance/tags/\ubca0\ud0c0"},{"inline":true,"label":"\ubcc0\ub3d9\uc131","permalink":"/blog/en/finance/tags/\ubcc0\ub3d9\uc131"},{"inline":true,"label":"\ub9ac\uc2a4\ud06c\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\ub9ac\uc2a4\ud06c\uc9c0\ud45c"}],"readingTime":3.12,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"beta-guide","title":"\ubca0\ud0c0\ub85c \uc77d\ub294 \uc885\ubaa9\uc758 \uc2dc\uc7a5 \ubbfc\uac10\ub3c4, 1\ubcf4\ub2e4 \ud06c\ub2e4\ub294 \uac83\uc758 \uc758\ubbf8","authors":["way"],"tags":["finance","\ubca0\ud0c0","\ubcc0\ub3d9\uc131","\ub9ac\uc2a4\ud06c\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654\uc5d0 \ub728\uc9c0 \uc54a\ub294 \uc601\uc218\uc99d, 11\uc6d4\uc5d0 \ubbf8\ub9ac \ucc59\uae30\ub294 \uc11c\ub958 \uc810\uac80","permalink":"/blog/en/finance/yearend-tax-documents"},"nextItem":{"title":"\uae09\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc624\ub978 \uc815\ubcf4\ubcf4\uc548 \ud14c\ub9c8\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","permalink":"/blog/en/finance/information-security-theme"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc885\ubaa9\uc758 \uc2dc\uc7a5 \ubbfc\uac10\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 \ubca0\ud0c0\uc758 \uc758\ubbf8\uc640 \ud55c\uacc4\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc8fc\uac00\uac00 \uc2dc\uc7a5\ubcf4\ub2e4 \ud06c\uac8c \uc6c0\uc9c1\uc774\ub294 \uc885\ubaa9\uc774 \uc788\uace0, \uc2dc\uc7a5\ubcf4\ub2e4 \uc791\uac8c \uc6c0\uc9c1\uc774\ub294 \uc885\ubaa9\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ucc28\uc774\ub97c \ud558\ub098\uc758 \uc22b\uc790\ub85c \ud45c\ud604\ud55c \uc9c0\ud45c\uac00 \ubca0\ud0c0\uc785\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\ub294 \uc2dc\uc7a5\uc758 \uc6c0\uc9c1\uc784\uc744 \uae30\uc900\uc73c\ub85c \uac1c\ubcc4 \uc885\ubaa9\uc758 \ubbfc\uac10\ub3c4\ub97c \uce21\uc815\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc7a5\uc5d0\uc11c\ub294 \ubca0\ud0c0\uac00 \ub192\uc740 \uc885\ubaa9\uc774 \ub354 \ud06c\uac8c \ud558\ub77d\ud558\ub294 \uacbd\ud5a5\uc774 \uad00\ucc30\ub418\uace4 \ud569\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ubca0\ud0c0\ub294 \uc608\uce21 \ub3c4\uad6c\uac00 \uc544\ub2c8\ub77c \uacfc\uac70 \ub370\uc774\ud130\ub85c \ucd94\uc815\ud55c \ud1b5\uacc4\ub7c9\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc810\uc744 \uba3c\uc800 \uc774\ud574\ud558\uace0 \uc9c0\ud45c\ub97c \uc77d\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExejY2anNjZnVxeHRuYXBqYjE3eWQ2d3A4N2tscXQ5bDQyMzBvcWlrciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/XVMeBWrKBpb5m/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \ubca0\ud0c0\uc758 \uacc4\uc0b0\ubc95\\n\\n\ubca0\ud0c0\ub294 \uc885\ubaa9 \uc218\uc775\ub960\uacfc \uc2dc\uc7a5 \uc218\uc775\ub960\uc758 \uacf5\ubd84\uc0b0\uc744 \uc2dc\uc7a5 \uc218\uc775\ub960\uc758 \ubd84\uc0b0\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0\uc2dd\uc740 `\ubca0\ud0c0 = \uacf5\ubd84\uc0b0(\uc885\ubaa9 \uc218\uc775\ub960, \uc2dc\uc7a5 \uc218\uc775\ub960) / \ubd84\uc0b0(\uc2dc\uc7a5 \uc218\uc775\ub960)` \uc785\ub2c8\ub2e4.<br/>\\n\uacf5\ubd84\uc0b0\uc740 \ub450 \uc218\uc775\ub960\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uc815\ub3c4\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\ubd84\uc0b0\uc740 \uc2dc\uc7a5 \uc218\uc775\ub960 \uc790\uccb4\uc758 \ubcc0\ub3d9 \uc815\ub3c4\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc758 \uc6c0\uc9c1\uc784\uc744 1\ub85c \ub193\uace0, \uc885\ubaa9\uc774 \uadf8\uc5d0 \ube44\ud574 \uba87 \ubc30\ub85c \ubc18\uc751\ud588\ub294\uc9c0\ub97c \uc7ac\ub294 \uc148\uc785\ub2c8\ub2e4.<br/>\\n\uc2e4\ubb34\uc5d0\uc11c\ub294 \uc77c\uc815 \uae30\uac04\uc758 \uc77c\ubcc4 \ub610\ub294 \uc8fc\ubcc4 \uc218\uc775\ub960\uc744 \uc774\uc6a9\ud574 \ubca0\ud0c0\ub97c \ucd94\uc815\ud569\ub2c8\ub2e4.<br/>\\n\uc0ac\uc6a9\ud558\ub294 \uc9c0\uc218\ub294 \ucf54\uc2a4\ud53c\ub098 \ucf54\uc2a4\ud53c200 \uac19\uc740 \uc2dc\uc7a5 \ub300\ud45c \uc9c0\uc218\uac00 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ubca0\ud0c0 \uac12\uc758 \ud574\uc11d\\n\\n\ubca0\ud0c0\uc758 \ud574\uc11d\uc740 \uae30\uc900\uac12 1\uc744 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\\n| \ubca0\ud0c0 \uad6c\uac04 | \uc758\ubbf8 |\\n| --- | --- |\\n| \ubca0\ud0c0\uac00 1\uc778 \uacbd\uc6b0 | \uc2dc\uc7a5\uacfc \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \ube44\uc2b7\ud55c \ud3ed\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5 |\\n| \ubca0\ud0c0\uac00 1\ubcf4\ub2e4 \ud070 \uacbd\uc6b0 | \uc2dc\uc7a5\ubcf4\ub2e4 \ud070 \ud3ed\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5 |\\n| \ubca0\ud0c0\uac00 1\ubcf4\ub2e4 \uc791\uc740 \uacbd\uc6b0 | \uc2dc\uc7a5\ubcf4\ub2e4 \uc791\uc740 \ud3ed\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5 |\\n| \ubca0\ud0c0\uac00 0\uc5d0 \uac00\uae4c\uc6b4 \uacbd\uc6b0 | \uc2dc\uc7a5 \uc6c0\uc9c1\uc784\uacfc\uc758 \uc5f0\uad00\uc131\uc774 \uc57d\ud55c \uacbd\ud5a5 |\\n| \ubca0\ud0c0\uac00 \uc74c\uc218\uc778 \uacbd\uc6b0 | \uc2dc\uc7a5\uacfc \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5 |\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ubca0\ud0c0\uac00 1.5\uc778 \uc885\ubaa9\uc740 \uc2dc\uc7a5\uc774 1% \uc6c0\uc9c1\uc77c \ub54c \ud3c9\uade0\uc801\uc73c\ub85c 1.5% \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \ubca0\ud0c0\uac00 0.5\uc778 \uc885\ubaa9\uc740 \uc2dc\uc7a5\uc774 1% \uc6c0\uc9c1\uc77c \ub54c \ud3c9\uade0\uc801\uc73c\ub85c 0.5% \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc11c \ud3c9\uade0\uc801\uc774\ub77c\ub294 \ud45c\ud604\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\ub294 \uac1c\ubcc4 \ub0a0\uc9dc\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \ubc1c\ud45c\ub098 \uc218\uc8fc \uc18c\uc2dd \uac19\uc740 \uac1c\ubcc4 \uc7ac\ub8cc\uac00 \uc788\uc73c\uba74 \ubca0\ud0c0\uc640 \ubb34\uad00\ud558\uac8c \uc8fc\uac00\uac00 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ubca0\ud0c0\uc640 \ubcc0\ub3d9\uc131\uc758 \ucc28\uc774\\n\\n\ubca0\ud0c0\uc640 \ubcc0\ub3d9\uc131\uc740 \uc790\uc8fc \ud63c\ub3d9\ub418\uc9c0\ub9cc \ub2e4\ub978 \uac1c\ub150\uc785\ub2c8\ub2e4.<br/>\\n\ubcc0\ub3d9\uc131\uc740 \uc885\ubaa9 \uc790\uccb4\uc758 \uac00\uaca9 \uc6c0\uc9c1\uc784 \ud06c\uae30\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\ud45c\uc900\ud3b8\ucc28\uac00 \ub300\ud45c\uc801\uc778 \ubcc0\ub3d9\uc131 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\ub294 \uc2dc\uc7a5 \ub300\ube44 \uc0c1\ub300\uc801\uc778 \ubbfc\uac10\ub3c4\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\ubcc0\ub3d9\uc131\uc774 \ud070 \uc885\ubaa9\uc774 \ubc18\ub4dc\uc2dc \ubca0\ud0c0\uac00 \ub192\uc740 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uac1c\ubcc4 \uc7ac\ub8cc\ub85c \ud06c\uac8c \uc6c0\uc9c1\uc774\uc9c0\ub9cc \uc2dc\uc7a5\uacfc \ubb34\uad00\ud55c \uc885\ubaa9\uc740 \ubcc0\ub3d9\uc131\uc740 \ud06c\uace0 \ubca0\ud0c0\ub294 \ub0ae\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc2dc\uc7a5\uacfc \ubc00\uc811\ud558\uac8c \uc5f0\ub3d9\ub418\ub294 \uc885\ubaa9\uc740 \ubcc0\ub3d9\uc131\uc774 \ud06c\uc9c0 \uc54a\uc544\ub3c4 \ubca0\ud0c0\uac00 \ub192\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\ud45c\ub294 \ud568\uaed8 \ubd10\uc57c \uc885\ubaa9\uc758 \uc704\ud5d8 \uc131\uaca9\uc774 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ubca0\ud0c0\uc758 \ud55c\uacc4 \uc138 \uac00\uc9c0\\n\\n\uccab\uc9f8 \ud55c\uacc4\ub294 \ucd94\uc815 \uae30\uac04\uc758 \uc758\uc874\uc131\uc785\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc 1\ub144\uc73c\ub85c \uacc4\uc0b0\ud55c \ubca0\ud0c0\uc640 \ucd5c\uadfc 3\ub144\uc73c\ub85c \uacc4\uc0b0\ud55c \ubca0\ud0c0\ub294 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0ac\uc5c5 \uad6c\uc870\uac00 \ubc14\ub00c\uac70\ub098 \uc720\ub3d9\uc131\uc774 \ubcc0\ud558\uba74 \uacfc\uac70 \ubca0\ud0c0\uc758 \uc758\ubbf8\ub3c4 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8 \ud55c\uacc4\ub294 \uae30\uc900 \uc9c0\uc218\uc758 \uc120\ud0dd\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uc900 \ubca0\ud0c0\uc640 \ucf54\uc2a4\ub2e5 \uae30\uc900 \ubca0\ud0c0\ub294 \uac19\uc740 \uc885\ubaa9\uc774\ub77c\ub3c4 \ub2e4\ub974\uac8c \ub098\uc635\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885 \uc9c0\uc218\ub97c \uae30\uc900\uc73c\ub85c \uc0bc\uc73c\uba74 \ud574\uc11d\ub3c4 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8 \ud55c\uacc4\ub294 \uadf9\ub2e8\uc801\uc778 \uc7a5\uc138\uc5d0\uc11c\uc758 \ubd88\uc548\uc815\uc131\uc785\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc7a5\uc5d0\uc11c\ub294 \uc885\ubaa9 \uac04 \uc0c1\uad00\uad00\uacc4\uac00 \ud3c9\uc18c\ubcf4\ub2e4 \ub192\uc544\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud3c9\uc18c\uc758 \ubca0\ud0c0\uac00 \uae09\ub77d\uc7a5\uc5d0\uc11c \uadf8\ub300\ub85c \uc801\uc6a9\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ubca0\ud0c0\ub97c \ud655\uc778\ud560 \ub54c\ub294 \uc0b0\ucd9c \uae30\uac04\uacfc \uae30\uc900 \uc9c0\uc218\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc99d\uad8c\uc0ac\ub098 \ub370\uc774\ud130 \uc5c5\uccb4\ub9c8\ub2e4 \ubca0\ud0c0 \uc0b0\ucd9c \ubc29\uc2dd\uc774 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\uac00 \ub192\uc740 \uc885\ubaa9\uc740 \uc0c1\uc2b9\uc7a5\uc5d0\uc11c\ub294 \ud0c4\ub825\uc774 \ud06c\uace0, \ud558\ub77d\uc7a5\uc5d0\uc11c\ub294 \ub099\ud3ed\uc774 \ud074 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc2e0\uc758 \uc704\ud5d8 \uac10\uc218 \uc218\uc900\uc5d0 \ub9de\ub294 \ubca0\ud0c0 \uad6c\uac04\uc744 \ubbf8\ub9ac \uc815\ud574\ub450\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\uac00 \ub0ae\ub2e4\uace0 \ud574\uc11c \uc704\ud5d8\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc720\ub3d9\uc131\uc774 \ub0ae\uac70\ub098 \uac1c\ubcc4 \uc545\uc7ac\uac00 \uc788\ub294 \uc885\ubaa9\uc740 \ubca0\ud0c0\uc640 \ubb34\uad00\ud558\uac8c \uae09\ub77d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\ub294 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc804\uccb4\uc758 \uc2dc\uc7a5 \ubbfc\uac10\ub3c4\ub97c \uc870\uc808\ud558\ub294 \ub3c4\uad6c\ub85c \uc4f0\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\ubcc4 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \ud310\ub2e8\uc740 \ubca0\ud0c0 \ud558\ub098\ub85c \ub0b4\ub9ac\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\ubca0\ud0c0\ub294 \uc2dc\uc7a5 \ub300\ube44 \ubbfc\uac10\ub3c4\ub97c \uc694\uc57d\ud55c \ud1b5\uacc4\ub7c9\uc774\uc9c0 \ubbf8\ub798 \uc218\uc775\uc744 \ubcf4\uc7a5\ud558\ub294 \uc218\uce58\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc0b0\ucd9c \uc870\uac74\uacfc \ud55c\uacc4\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \ubca0\ud0c0\ub97c \ud6e8\uc52c \uc720\uc6a9\ud558\uac8c \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNms5ZDU1bTI2M2d5bGo5ZGFvcjkwbHFxemNoNDVxNTA5bTJpbndibCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/73vsXqHC22yuA/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"information-security-theme","metadata":{"permalink":"/blog/en/finance/information-security-theme","source":"@site/finance/2026-10-30-information-security-theme/index.mdx","title":"\uae09\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc624\ub978 \uc815\ubcf4\ubcf4\uc548 \ud14c\ub9c8\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc815\ubcf4\ubcf4\uc548","permalink":"/blog/en/finance/tags/\uc815\ubcf4\ubcf4\uc548"},{"inline":true,"label":"\ud14c\ub9c8","permalink":"/blog/en/finance/tags/\ud14c\ub9c8"},{"inline":true,"label":"\uc0b0\uc5c5\uad6c\uc870","permalink":"/blog/en/finance/tags/\uc0b0\uc5c5\uad6c\uc870"}],"readingTime":3.17,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"information-security-theme","title":"\uae09\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc624\ub978 \uc815\ubcf4\ubcf4\uc548 \ud14c\ub9c8\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","authors":["way"],"tags":["finance","\uc815\ubcf4\ubcf4\uc548","\ud14c\ub9c8","\uc0b0\uc5c5\uad6c\uc870"]},"unlisted":false,"prevItem":{"title":"\ubca0\ud0c0\ub85c \uc77d\ub294 \uc885\ubaa9\uc758 \uc2dc\uc7a5 \ubbfc\uac10\ub3c4, 1\ubcf4\ub2e4 \ud06c\ub2e4\ub294 \uac83\uc758 \uc758\ubbf8","permalink":"/blog/en/finance/beta-guide"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 5,730.74 \ub9c8\uac10, 3.48% \uae09\ub77d\ud55c 10\uc6d4 30\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-plunge-close-oct30"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 10\uc6d4 30\uc77c \uae09\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud55c \uc815\ubcf4\ubcf4\uc548 \ud14c\ub9c8\uc758 \uad6c\uc870\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 30\uc77c \ucf54\uc2a4\ud53c\ub294 3.48%, \ucf54\uc2a4\ub2e5\uc740 3.83% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900 \ubcf4\uc548 \uad00\ub828 \ud14c\ub9c8\ub294 2.77% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud574\ub2f9 \ud14c\ub9c8\ub294 29\uac1c \uc885\ubaa9\uc73c\ub85c \uad6c\uc131\ub410\uace0, \uc0c1\uc2b9 15\uac1c, \ud558\ub77d 12\uac1c, \ubcf4\ud569 2\uac1c\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS\uc758 \uc2dc\uc7a5 \uc694\uc57d\uc5d0\uc11c\ub294 \ubcf4\uc548 \ucde8\uc57d\uc810 \uacbd\ubcf4\uc640 \uae08\uc735\uad8c\uc758 \ubcf4\uc548 \ud22c\uc790 \ud655\ub300 \uc18c\uc2dd\uc774 \uad00\ub828\uc8fc\uc758 \ub3d9\ubc18 \uc0c1\uc2b9 \ubc30\uacbd\uc73c\ub85c \uc5b8\uae09\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uc640 \ud14c\ub9c8\uc758 \ubc29\ud5a5\uc774 \uc5c7\uac08\ub9b0 \ub0a0\uc740 \ud14c\ub9c8\uc758 \uad6c\uc870\ub97c \uc810\uac80\ud558\uae30 \uc88b\uc740 \uc0ac\ub840\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ud2b9\uc815 \uc885\ubaa9\uc744 \ucd94\ucc9c\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c \uc0b0\uc5c5 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \ud574\uc124\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMWRrc2NhMTQ1dnU3YTlmMWJmZGh4MXY1ZGV4bTF0a3gwb2d2M2ZkNCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/FIxqsozdqLDHftboUt/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc815\ubcf4\ubcf4\uc548 \uc0b0\uc5c5\uc758 \ub124 \uac00\uc9c0 \ucd95\\n\\n\uc815\ubcf4\ubcf4\uc548 \uc0b0\uc5c5\uc740 \ud06c\uac8c \ub124 \uac00\uc9c0 \ucd95\uc73c\ub85c \ub098\ub220\uc11c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub124\ud2b8\uc6cc\ud06c \ubcf4\uc548\\n\\n\ub124\ud2b8\uc6cc\ud06c \uacbd\uacc4\ub97c \uc9c0\ud0a4\ub294 \ubc29\ud654\ubcbd\uacfc \uce68\uc785 \ud0d0\uc9c0, \ucc28\ub2e8 \uc194\ub8e8\uc158\uc774 \ud574\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\uae30\uc5c5 \ub0b4\ubd80\ub9dd\uacfc \uc678\ubd80\ub9dd \uc0ac\uc774\uc5d0\uc11c \uc624\uac00\ub294 \ud2b8\ub798\ud53d\uc744 \uac80\uc0ac\ud558\uace0 \ud1b5\uc81c\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.<br/>\\n\ud074\ub77c\uc6b0\ub4dc \uc774\uc6a9\uc774 \ub298\uba74\uc11c \uacbd\uacc4\uc758 \uac1c\ub150\uc740 \uc0ac\ub0b4\ub9dd\uc5d0\uc11c \uacc4\uc815\uacfc \uae30\uae30 \ub2e8\uc704\ub85c \ub113\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc5d4\ub4dc\ud3ec\uc778\ud2b8\uc640 \uc778\uc99d \ubcf4\uc548\\n\\nPC\uc640 \uc11c\ubc84, \ubaa8\ubc14\uc77c \uae30\uae30 \uac19\uc740 \ub2e8\ub9d0\uc744 \uc9c0\ud0a4\ub294 \uc194\ub8e8\uc158\uc774 \ud574\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\uc545\uc131\ucf54\ub4dc \ud0d0\uc9c0\uc640 \ub300\uc751, \ubc31\uc2e0\uacfc \ub2e8\ub9d0 \uad00\ub9ac \uae30\ub2a5\uc774 \ud3ec\ud568\ub429\ub2c8\ub2e4.<br/>\\n\ubcf8\uc778 \uc778\uc99d\uacfc \uc811\uadfc \uad8c\ud55c \uad00\ub9ac\ub3c4 \uc774 \ucd95\uc5d0 \uc18d\ud569\ub2c8\ub2e4.<br/>\\n\uc778\uc99d \uc218\ub2e8\uc740 \ube44\ubc00\ubc88\ud638\uc5d0\uc11c \uc0dd\uccb4 \uc778\uc99d\uacfc \ub2e4\ub2e8\uacc4 \uc778\uc99d\uc73c\ub85c \ub113\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubcf4\uc548\uad00\uc81c\uc640 \ub300\uc751 \uc11c\ube44\uc2a4\\n\\n\ubcf4\uc548 \uc774\ubca4\ud2b8\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \uac10\uc2dc\ud558\uace0 \uce68\ud574 \uc0ac\uace0\uc5d0 \ub300\uc751\ud558\ub294 \uc11c\ube44\uc2a4\uac00 \ud574\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\uad00\uc81c\uc13c\ud130\uac00 \uacbd\ubcf4\ub97c \ubd84\ub958\ud558\uace0, \uae30\uc5c5\uacfc \ud568\uaed8 \uc6d0\uc778 \ubd84\uc11d\uacfc \ubcf5\uad6c\ub97c \uc218\ud589\ud569\ub2c8\ub2e4.<br/>\\n\uc81c\ud488 \ud310\ub9e4\uac00 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc774 \uac1c\uc785\ub418\ub294 \uc11c\ube44\uc2a4 \ube44\uc911\uc774 \ud06c\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ud074\ub77c\uc6b0\ub4dc\uc640 \ub370\uc774\ud130 \ubcf4\uc548\\n\\n\ud074\ub77c\uc6b0\ub4dc \ud658\uacbd\uc758 \uc124\uc815 \uc624\ub958\uc640 \uacc4\uc815 \uad8c\ud55c\uc744 \uc810\uac80\ud558\ub294 \uc194\ub8e8\uc158\uc774 \ud574\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc815\ubcf4\uc640 \uc8fc\uc694 \ub370\uc774\ud130\ub97c \uc554\ud638\ud654\ud558\uace0 \uc811\uadfc \uae30\ub85d\uc744 \uad00\ub9ac\ud558\ub294 \uae30\ub2a5\ub3c4 \ud3ec\ud568\ub429\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uac00 \ud074\ub77c\uc6b0\ub4dc\ub85c \uc774\ub3d9\ud560\uc218\ub85d \uc774 \ucd95\uc758 \uc911\uc694\ub3c4\ub294 \ud568\uaed8 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\uc694\ub97c \ub9cc\ub4dc\ub294 \uc138 \uac00\uc9c0 \ub3d9\uc778\\n\\n\uccab\uc9f8 \ub3d9\uc778\uc740 \uaddc\uc81c\uc640 \ucef4\ud50c\ub77c\uc774\uc5b8\uc2a4\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\uc640 \uae08\uc735 \ubcf4\uc548 \uaddc\uc81c\ub294 \uae30\uc5c5\uc5d0 \ucd5c\uc18c\ud55c\uc758 \ubcf4\uc548 \ud22c\uc790\ub97c \uc694\uad6c\ud569\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uac15\ud654 \uad6d\uba74\uc5d0\uc11c\ub294 \ubcf4\uc548 \uc608\uc0b0\uc774 \uacbd\uae30\uc640 \ubb34\uad00\ud558\uac8c \uc720\uc9c0\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8 \ub3d9\uc778\uc740 \ub514\uc9c0\ud138 \uc804\ud658\uc758 \ud655\ub300\uc785\ub2c8\ub2e4.<br/>\\n\uc6d0\uaca9\uadfc\ubb34\uc640 \ud074\ub77c\uc6b0\ub4dc, \uc778\uacf5\uc9c0\ub2a5 \ub3c4\uc785\uc774 \ub298\uba74 \uacf5\uaca9 \ud45c\uba74\ub3c4 \ud568\uaed8 \ub113\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc0c8\ub85c\uc6b4 \uc2dc\uc2a4\ud15c\uc774 \ub3c4\uc785\ub420 \ub54c\ub9c8\ub2e4 \ubcf4\uc548 \uac80\ud1a0 \ub300\uc0c1\uc774 \ub298\uc5b4\ub098\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8 \ub3d9\uc778\uc740 \uc0ac\uace0\uc758 \ube44\uc6a9 \uc0c1\uc2b9\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc815\ubcf4 \uc720\ucd9c\uacfc \uc11c\ube44\uc2a4 \uc911\ub2e8\uc774 \ubc1c\uc0dd\ud558\uba74 \uacfc\uc9d5\uae08\uacfc \ubcf5\uad6c \ube44\uc6a9, \uc2e0\ub8b0 \ud558\ub77d\uc774 \ud568\uaed8 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\uc0ac\uace0 \ube44\uc6a9\uc774 \ucee4\uc9c8\uc218\ub85d \ubcf4\uc548 \ud22c\uc790\ub294 \ube44\uc6a9\uc774 \uc544\ub2c8\ub77c \uc704\ud5d8 \uad00\ub9ac\ub85c \uc778\uc2dd\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\uc775 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c\\n\\n\uc815\ubcf4\ubcf4\uc548 \uae30\uc5c5\uc758 \uc218\uc775\uc740 \uc81c\ud488 \ud310\ub9e4\uc640 \uad6c\ub3c5, \uad6c\ucd95\uacfc \uc720\uc9c0\ubcf4\uc218\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uad6c\ub3c5\ud615 \ub9e4\ucd9c \ube44\uc911\uc774 \ub192\uc744\uc218\ub85d \ub9e4\ucd9c\uc758 \ubc18\ubcf5\uc131\uc774 \ub192\uc544\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\ucd95 \ub9e4\ucd9c\uc740 \ud504\ub85c\uc81d\ud2b8 \uc218\uc8fc\uc5d0 \ub530\ub77c \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ud560 \uc9c0\ud45c\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud655\uc778 \ud56d\ubaa9 | \uc0b4\ud3b4\ubcfc \uc810 |\\n| --- | --- |\\n| \ubc18\ubcf5 \ub9e4\ucd9c \ube44\uc911 | \uad6c\ub3c5\uacfc \uc720\uc9c0\ubcf4\uc218 \ub9e4\ucd9c\uc774 \uc804\uccb4\uc5d0\uc11c \ucc28\uc9c0\ud558\ub294 \ube44\uc911 |\\n| \uc218\uc8fc\uc794\uace0 | \uc55e\uc73c\ub85c \uc778\uc2dd\ub420 \uad6c\ucd95 \ub9e4\ucd9c\uc758 \uaddc\ubaa8\uc640 \uae30\uac04 |\\n| \uace0\uac1d \uc720\uc9c0\uc728 | \uae30\uc874 \uace0\uac1d\uc774 \uacc4\uc57d\uc744 \uc5f0\uc7a5\ud558\ub294 \ube44\uc728 |\\n| \uc5f0\uad6c\uac1c\ubc1c \ube44\uc911 | \uc2e0\uae30\uc220 \ub300\uc751\uc744 \uc704\ud55c \ud22c\uc790 \uac15\ub3c4 |\\n| \ub9e4\ucd9c\ucc44\uad8c \ud68c\uc804 | \uc218\uc8fc \uc99d\uac00\uac00 \ud604\uae08 \ud68c\uc218\ub85c \uc774\uc5b4\uc9c0\ub294 \uc18d\ub3c4 |\\n\\n\uc218\uc8fc \uc18c\uc2dd\ub9cc\uc73c\ub85c \uae30\uc5c5\uc744 \ud310\ub2e8\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4.<br/>\\n\uc218\uc8fc\uac00 \ub9e4\ucd9c\ub85c \uc778\uc2dd\ub418\ub294 \uc2dc\uc810\uacfc \ub9c8\uc9c4 \uc218\uc900\uae4c\uc9c0 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubcf4\uc548 \ucde8\uc57d\uc810 \uacbd\ubcf4 \uac19\uc740 \ub2e8\uae30 \ub274\uc2a4\ub294 \ud14c\ub9c8 \uc804\uccb4\ub97c \uc6c0\uc9c1\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ub274\uc2a4\uc758 \ud6a8\uacfc\uac00 \uc77c\ud68c\uc131\uc778\uc9c0, \uc608\uc0b0 \ud655\ub300\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0\ub294 \uad6c\ubd84\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ud14c\ub9c8 \ub4f1\ub77d\ub960\uc740 \uad6c\uc131 \uc885\ubaa9\uc758 \ud3c9\uade0\uc801\uc778 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ubcf4\uc548 \ud14c\ub9c8\uc5d0\uc11c\ub3c4 12\uac1c \uc885\ubaa9\uc740 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8\uac00 \uc62c\ub790\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uac1c\ubcc4 \uae30\uc5c5\uc758 \uc2e4\uc801\uc774 \uc88b\uc544\uc84c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \ubc1c\ud45c\uc5d0\uc11c\ub294 \ubc18\ubcf5 \ub9e4\ucd9c \uc131\uc7a5\ub960\uacfc \uc601\uc5c5\uc774\uc775\ub960\uc744 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uc8fc \uacf5\uc2dc\uc5d0\uc11c\ub294 \uacc4\uc57d \uae30\uac04\uacfc \uc778\uc2dd \ubc29\uc2dd\uc744 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\uc548 \uc0b0\uc5c5\uc740 \uae30\uc220 \ubcc0\ud654 \uc18d\ub3c4\uac00 \ube60\ub978 \ud3b8\uc785\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uae30\uc220\uc5d0 \ub300\ud55c \uc758\uc874\ub3c4\uac00 \ub192\uc740 \uae30\uc5c5\uc740 \uae30\uc220 \uad50\uccb4 \uad6d\uba74\uc5d0\uc11c \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc815\ubcf4\ubcf4\uc548\uc740 \uc0ac\uace0\uc640 \uaddc\uc81c, \ub514\uc9c0\ud138 \uc804\ud658\uc774 \ud568\uaed8 \uc218\uc694\ub97c \ub9cc\ub4dc\ub294 \uc0b0\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8\uc758 \ud558\ub8e8 \uc0c1\uc2b9\ubcf4\ub2e4 \uc218\uc775 \uad6c\uc870\uc640 \ubc18\ubcf5 \ub9e4\ucd9c\uc758 \uc9c0\uc18d\uc131\uc744 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNGpybHg0MDRhaDliY2NvY2dpYTB2c2FjZGs0OWhseHd3Zzg5anR6ZyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/111Z8z6B8226vm/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-plunge-close-oct30","metadata":{"permalink":"/blog/en/finance/kospi-plunge-close-oct30","source":"@site/finance/2026-10-30-kospi-plunge-close-oct30/index.mdx","title":"\ucf54\uc2a4\ud53c 5,730.74 \ub9c8\uac10, 3.48% \uae09\ub77d\ud55c 10\uc6d4 30\uc77c \uc2dc\uc7a5 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ub2e5"}],"readingTime":3.02,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-plunge-close-oct30","title":"\ucf54\uc2a4\ud53c 5,730.74 \ub9c8\uac10, 3.48% \uae09\ub77d\ud55c 10\uc6d4 30\uc77c \uc2dc\uc7a5 \uc815\ub9ac","authors":["way"],"tags":["finance","\ucf54\uc2a4\ud53c","\uc2dc\uc7a5\uc815\ub9ac","\ucf54\uc2a4\ub2e5"]},"unlisted":false,"prevItem":{"title":"\uae09\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc624\ub978 \uc815\ubcf4\ubcf4\uc548 \ud14c\ub9c8\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","permalink":"/blog/en/finance/information-security-theme"},"nextItem":{"title":"ROE\uc640 ROA\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc218\uc775\uc131, \uacc4\uc0b0\ubc95\uacfc \ud568\uc815","permalink":"/blog/en/finance/roe-roa-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ucf54\uc2a4\ud53c\uac00 3.48% \uae09\ub77d\ud558\uba70 5,730\uc120\uc73c\ub85c \ubc00\ub9b0 10\uc6d4 30\uc77c \uc2dc\uc7a5\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\uc5d0\uc11c \ub300\ud615 \uae30\uc220\uc8fc\uac00 \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uae00 \ubaa8\ud68c\uc0ac \uc54c\ud30c\ubcb3\uc758 3\ubd84\uae30 \ub9e4\ucd9c\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\uace0, \uc789\uc5ec\ud604\uae08\ud750\ub984\uc774 2\ubd84\uae30 \uc5f0\uc18d \uc801\uc790\ub97c \uae30\ub85d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3 \uc8fc\uac00\ub294 12% \ub118\uac8c \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ube44\uc6a9\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uae30\uc220\uc8fc \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub418\uba70 \ub274\uc695 \uc99d\uc2dc\uc758 \ud22c\uc790 \uc2ec\ub9ac\uac00 \uc704\ucd95\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,184.72\ub85c \uc804\uc77c \ub300\ube44 365.13\ud3ec\uc778\ud2b8, 1.38% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,720.39\ub85c \uc804\uc77c \ub300\ube44 23.59\ud3ec\uc778\ud2b8, 0.30% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \ud750\ub984\uc740 [\uacbd\ud5a5\uc2e0\ubb38 \ubcf4\ub3c4](https://www.khan.co.kr/article/202610301616001)\uc640 [\ub514\uc9c0\ud138\ub370\uc77c\ub9ac \ubcf4\ub3c4](https://m.ddaily.co.kr/page/view/2026103015521622280)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExb2JvbnAyeTZvNnl4aG1vOTMwOHp4NjV5Zmk3d2c5NzB1djJoZ3VkZSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/BGgtEk3v62kD6oUJen/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc624\ub298\uc758 \uc9c0\uc218\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub9c8\uac10 \uc9c0\uc218\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 |\\n| --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,730.74 | 206.92 \ud558\ub77d | 3.48% |\\n| \ucf54\uc2a4\ub2e5 | 724.38 | 28.85 \ud558\ub77d | 3.83% |\\n| \ucf54\uc2a4\ud53c200 | 899.78 | 36.09 \ud558\ub77d | 3.86% |\\n| \uc6d0\ub2ec\ub7ec \ud658\uc728 | 1,333.90\uc6d0 | \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS 20\uc2dc 40\ubd84 \uae30\uc900 | - |\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 177.31\ud3ec\uc778\ud2b8, 2.99% \ub0b4\ub9b0 5,760.35\uc5d0 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \ub099\ud3ed\uc774 \ucee4\uc9c0\uba70 \uc7a5\uc911 5,599.42\uae4c\uc9c0 \ubc00\ub838\uace0, 5,600\uc120\uc774 \uc77c\uc2dc\uc801\uc73c\ub85c \ubb34\ub108\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ud6c4 \ub4e4\uc5b4 \ub099\ud3ed\uc744 \uc77c\ubd80 \uc904\uc600\uc73c\ub098 \uc885\uac00\ub294 5,730.74\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 737.76\uc5d0 \ucd9c\ubc1c\ud574 \uc7a5\uc911 717.27\uae4c\uc9c0 \ub0b4\ub9b0 \ub4a4 724.38\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ub09c 28\uc77c 6,000\uc120\uc744 \ub3cc\ud30c\ud588\ub358 \ucf54\uc2a4\ud53c\ub294 \uc774\ud2c0 \uc5f0\uc18d \ud558\ub77d\ud558\uba70 5,700\uc120\uc73c\ub85c \ub0b4\ub824\uc549\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc774 \uac70\uc138\uc9c0\uc790 \uc624\uc804 10\uc2dc 4\ubd84 55\ucd08\uaed8 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5\uc5d0 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9\uc740 \uc9c0\ub09c 15\uc77c \uc774\ud6c4 11\uac70\ub798\uc77c \ub9cc\uc785\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\ub294 \ucf54\uc2a4\ud53c200 \uc120\ubb3c\uac00\uaca9\uc774 \uc804\uc77c \uc885\uac00\ubcf4\ub2e4 5% \uc774\uc0c1 \ud558\ub77d\ud55c \uc0c1\ud0dc\uac00 1\ubd84 \uc774\uc0c1 \uc774\uc5b4\uc9c8 \ub54c \ubc1c\ub3d9\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc624\ub298\uc758 \uc218\uae09\uacfc \uc548\uc804\uc790\uc0b0 \ud750\ub984\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778\uc774 1\uc870 6,149\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uae30\uc900 \uae30\uad00\uc740 7,540\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ud588\uace0, \uac1c\uc778\uc740 5,781\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 2\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ud588\uace0, \uae30\uad00\uc740 1,342\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uac1c\uc778\uc740 1,253\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d\uc744 \uc678\uad6d\uc778\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4\uac00 \uc8fc\ub3c4\ud55c \ud558\ub8e8\ub85c \uc815\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9\uc5d0\uc11c\ub294 \uc0bc\uc131\uc804\uc790\uac00 3.02% \ub0b4\ub9b0 225,000\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nSK\ud558\uc774\ub2c9\uc2a4\ub294 7.08% \ub0b4\ub9b0 1,418,000\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc \uc548\uc5d0\uc11c\ub3c4 \ud558\ub77d \ud3ed\uc740 \uc885\ubaa9\ub9c8\ub2e4 \ub2ec\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ucc44\uad8c \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc548\uc804\uc790\uc0b0 \uc120\ud638\uac00 \uac15\ud574\uc9c0\uba70 \uae08\ub9ac\uac00 \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n[\uc774\ud22c\ub370\uc774 \ubcf4\ub3c4](https://www.etoday.co.kr/news/view/2642445)\uc5d0 \ub530\ub974\uba74 \uad6d\uace0 3\ub144\ubb3c \uae08\ub9ac\ub294 5.1bp \ub0b4\ub9b0 3.715%\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\uace0 10\ub144\ubb3c \uae08\ub9ac\ub294 7.3bp \ub0b4\ub9b0 4.008%\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\uc6b8 \uc678\ud658\uc2dc\uc7a5\uc5d0\uc11c \uc6d0\ub2ec\ub7ec \ud658\uc728\uc740 \uc804\uc77c \ub300\ube44 2.5\uc6d0 \ub0b4\ub9b0 1,334.3\uc6d0\uc5d0 \ub9c8\uac10\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00 \uae09\ub77d\uacfc \ucc44\uad8c \uac15\uc138, \ud658\uc728 \uc548\uc815\uc774 \ud568\uaed8 \ub098\ud0c0\ub09c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uae09\ub77d\uc77c\uc5d0\ub294 \uc885\uac00\ubcf4\ub2e4 \uc7a5\uc911 \uc800\uc810\uacfc \ubc18\ub4f1 \uacfc\uc815\uc744 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,599.42\uae4c\uc9c0 \ubc00\ub838\ub2e4\uac00 5,730.74\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed\uc744 \uc5bc\ub9c8\ub098 \ub418\ub3cc\ub838\ub294\uc9c0\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \ucd9c\ubc1c \uc704\uce58\ub97c \uac00\ub2a0\ud558\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc218\uae09\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc758 \uc21c\ub9e4\ub3c4\uac00 \ud558\ub8e8\ub85c \uadf8\uce58\ub294\uc9c0, \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uacfc \uac1c\uc778\uc758 \uc21c\ub9e4\uc218\uac00 \uc9c0\uc218\ub97c \ub5a0\ubc1b\uce58\ub294 \ud798\uc778\uc9c0, \ub2e8\uae30 \ubc18\ub4f1 \ub9e4\uc218\uc778\uc9c0\ub3c4 \uad6c\ubd84\ud574\uc11c \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885\ubcc4\ub85c\ub294 \ud558\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \uc624\ub978 \ud14c\ub9c8\uac00 \uc788\uc5c8\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900 \ubcf4\uc548 \uad00\ub828 \ud14c\ub9c8\ub294 2.77% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8\uc758 \uc0c1\uc2b9\uc774 \uc2e4\uc801\uc774\ub098 \uc218\uc8fc \uac19\uc740 \uadfc\uac70\ub97c \ub3d9\ubc18\ud588\ub294\uc9c0\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ucc44\uad8c \uae08\ub9ac \ud558\ub77d\uc774 \uc77c\uc2dc\uc801\uc778 \uc548\uc804\uc790\uc0b0 \uc120\ud638\uc778\uc9c0, \ucd94\uc138\uc801\uc778 \ubcc0\ud654\uc778\uc9c0\ub3c4 \ud568\uaed8 \uc810\uac80\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ubbf8\uad6d \uae30\uc220\uc8fc \uae09\ub77d\uc758 \uc5ec\ud30c\ub85c \ub450 \uc9c0\uc218 \ubaa8\ub450 3% \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdXJ6dmlhZGlwbXFwdnFhNDI0MG00MjJjaDdrdzJ3YTdjbnQydDBiZiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/15wP7gXnu230nEh9xu/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"roe-roa-guide","metadata":{"permalink":"/blog/en/finance/roe-roa-guide","source":"@site/finance/2026-10-30-roe-roa-guide/index.mdx","title":"ROE\uc640 ROA\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc218\uc775\uc131, \uacc4\uc0b0\ubc95\uacfc \ud568\uc815","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"ROE","permalink":"/blog/en/finance/tags/roe"},{"inline":true,"label":"ROA","permalink":"/blog/en/finance/tags/roa"},{"inline":true,"label":"\uc7ac\ubb34\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uc7ac\ubb34\uc9c0\ud45c"}],"readingTime":2.92,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"roe-roa-guide","title":"ROE\uc640 ROA\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc218\uc775\uc131, \uacc4\uc0b0\ubc95\uacfc \ud568\uc815","authors":["way"],"tags":["finance","ROE","ROA","\uc7ac\ubb34\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 5,730.74 \ub9c8\uac10, 3.48% \uae09\ub77d\ud55c 10\uc6d4 30\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-plunge-close-oct30"},"nextItem":{"title":"\uc5f0\ub9d0 \uc0c1\uc5ec\uae08\uc744 \ubc1b\uae30 \uc804\uc5d0 \uc815\ud558\ub294 \uc790\uae08 \ubc30\ubd84 \uc21c\uc11c","permalink":"/blog/en/finance/year-end-bonus-allocation"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uae30\uc5c5\uc758 \uc218\uc775\uc131\uc744 \uc77d\ub294 \ub300\ud45c \uc9c0\ud45c\uc778 ROE\uc640 ROA\uc758 \uacc4\uc0b0\ubc95\uacfc \ud568\uc815\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uae30\uc5c5\uc758 \uc2e4\uc801\uc744 \ubcfc \ub54c \uc21c\uc774\uc775\uc758 \uc808\ub300 \uaddc\ubaa8\ub9cc\uc73c\ub85c\ub294 \uc218\uc775\uc131\uc744 \ube44\uad50\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\ubcf8 1,000\uc5b5\uc6d0\uc73c\ub85c 100\uc5b5\uc6d0\uc744 \ubc84\ub294 \uae30\uc5c5\uacfc \uc790\ubcf8 1\uc870\uc6d0\uc73c\ub85c 100\uc5b5\uc6d0\uc744 \ubc84\ub294 \uae30\uc5c5\uc740 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\ud22c\uc785\ud55c \uc790\ubcf8 \ub300\ube44 \uc5bc\ub9c8\ub098 \ubc8c\uc5c8\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uac00 ROE\uc640 ROA\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\ud45c\ub294 \uac19\uc740 \uc21c\uc774\uc775\uc744 \uc11c\ub85c \ub2e4\ub978 \ubd84\ubaa8\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ubd84\ubaa8\uac00 \ub2e4\ub974\ub2e4\ub294 \uc810\uc774 \ub450 \uc9c0\ud45c\uc758 \ucc28\uc774\ub97c \ub9cc\ub4ed\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzc5ZTFhd2I4azVkdnl3ZWdyYjU5ZXUxZWk5NjludzF3MzFqYzJmcCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/G2b7D9VylgJYbvr9rD/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### ROE\uc758 \uacc4\uc0b0\ubc95\\n\\nROE\ub294 \uc790\uae30\uc790\ubcf8\uc774\uc775\ub960\uc785\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0\uc2dd\uc740 `ROE = \ub2f9\uae30\uc21c\uc774\uc775 / \uc790\uae30\uc790\ubcf8 \xd7 100` \uc785\ub2c8\ub2e4.<br/>\\n\uc790\uae30\uc790\ubcf8\uc740 \uc8fc\uc8fc\uac00 \uae30\uc5c5\uc5d0 \ub9e1\uae34 \uc790\ubcf8\uc744 \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0 \uc608\uc2dc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud56d\ubaa9 | \uae08\uc561 |\\n| --- | --- |\\n| \ub2f9\uae30\uc21c\uc774\uc775 | 100\uc5b5\uc6d0 |\\n| \uc790\uae30\uc790\ubcf8 | 1,000\uc5b5\uc6d0 |\\n| ROE | 10% |\\n\\nROE 10%\ub294 \uc790\uae30\uc790\ubcf8 100\uc6d0\ub2f9 10\uc6d0\uc758 \uc21c\uc774\uc775\uc744 \ub0c8\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uc8fc \uc785\uc7a5\uc5d0\uc11c \uc790\ubcf8\uc774 \uc5bc\ub9c8\ub098 \ud6a8\uc728\uc801\uc73c\ub85c \uc4f0\uc600\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n#### ROA\uc758 \uacc4\uc0b0\ubc95\\n\\nROA\ub294 \ucd1d\uc790\uc0b0\uc774\uc775\ub960\uc785\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0\uc2dd\uc740 `ROA = \ub2f9\uae30\uc21c\uc774\uc775 / \ucd1d\uc790\uc0b0 \xd7 100` \uc785\ub2c8\ub2e4.<br/>\\n\ucd1d\uc790\uc0b0\uc740 \uc790\uae30\uc790\ubcf8\uc5d0 \ubd80\ucc44\ub97c \ub354\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0 \uc608\uc2dc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud56d\ubaa9 | \uae08\uc561 |\\n| --- | --- |\\n| \ub2f9\uae30\uc21c\uc774\uc775 | 100\uc5b5\uc6d0 |\\n| \ucd1d\uc790\uc0b0 | 2,000\uc5b5\uc6d0 |\\n| ROA | 5% |\\n\\nROA 5%\ub294 \uc790\uc0b0 100\uc6d0\ub2f9 5\uc6d0\uc758 \uc21c\uc774\uc775\uc744 \ub0c8\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\ubd80\ucc44\uae4c\uc9c0 \ud3ec\ud568\ud55c \uc804\uccb4 \uc790\uc0b0\uc758 \uc6b4\uc6a9 \ud6a8\uc728\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uae30\uc5c5\uc774\ub77c\ub3c4 ROA\ub294 ROE\ubcf4\ub2e4 \ub0ae\uac8c \ub098\uc624\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd1d\uc790\uc0b0\uc774 \uc790\uae30\uc790\ubcf8\ubcf4\ub2e4 \ud06c\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n#### ROE\uc640 ROA\uc758 \ucc28\uc774\ub85c \uc77d\ub294 \uc7ac\ubb34 \ub808\ubc84\ub9ac\uc9c0\\n\\n\ub450 \uc9c0\ud45c\uc758 \ucc28\uc774\ub294 \uc7ac\ubb34 \ub808\ubc84\ub9ac\uc9c0\uc640 \uc5f0\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\ub4c0\ud3f0 \ubd84\ud574\uc5d0 \ub530\ub974\uba74 ROE\ub294 \uc21c\uc774\uc775\ub960\uacfc \ucd1d\uc790\uc0b0\ud68c\uc804\uc728, \uc7ac\ubb34 \ub808\ubc84\ub9ac\uc9c0\uc758 \uacf1\uc73c\ub85c \ub098\ub220\uc9d1\ub2c8\ub2e4.<br/>\\n\uc7ac\ubb34 \ub808\ubc84\ub9ac\uc9c0\ub294 \ucd1d\uc790\uc0b0\uc744 \uc790\uae30\uc790\ubcf8\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uc704\uc758 \uc608\uc2dc\uc5d0\uc11c\ub294 \ucd1d\uc790\uc0b0 2,000\uc5b5\uc6d0\uc744 \uc790\uae30\uc790\ubcf8 1,000\uc5b5\uc6d0\uc73c\ub85c \ub098\ub208 \uac12\uc774 2\ubc30\uc785\ub2c8\ub2e4.<br/>\\nROE 10%\ub294 ROA 5%\uc5d0 \ub808\ubc84\ub9ac\uc9c0 2\ubc30\ub97c \uacf1\ud55c \uacb0\uacfc\uc640 \uac19\uc2b5\ub2c8\ub2e4.<br/>\\nROE\uc640 ROA\uc758 \uaca9\ucc28\uac00 \ud074\uc218\ub85d \ubd80\ucc44 \uc758\uc874\ub3c4\uac00 \ub192\ub2e4\uace0 \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uaca9\ucc28\uac00 \uc791\uc744\uc218\ub85d \uc790\uae30\uc790\ubcf8 \uc911\uc2ec\uc73c\ub85c \uc790\uc0b0\uc744 \uc6b4\uc6a9\ud55c\ub2e4\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uaca9\ucc28\ub9cc\uc73c\ub85c \uac74\uc804\uc131\uc744 \ub2e8\uc815\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885\uc5d0 \ub530\ub77c \uc801\uc815 \ub808\ubc84\ub9ac\uc9c0 \uc218\uc900\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n#### ROE\uc758 \ud568\uc815 \uc138 \uac00\uc9c0\\n\\n\uccab\uc9f8 \ud568\uc815\uc740 \uc790\uae30\uc790\ubcf8 \ucd95\uc18c \ud6a8\uacfc\uc785\ub2c8\ub2e4.<br/>\\n\ub300\uaddc\ubaa8 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc774\ub098 \ubc30\ub2f9\uc73c\ub85c \uc790\uae30\uc790\ubcf8\uc774 \uc904\uba74 ROE\ub294 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\uc774\uc775\uc774 \ub298\uc9c0 \uc54a\uc558\ub294\ub370\ub3c4 \ubd84\ubaa8\uac00 \uc791\uc544\uc838 \uc9c0\ud45c\uac00 \uac1c\uc120\ub418\ub294 \ud604\uc0c1\uc785\ub2c8\ub2e4.<br/>\\nROE \uc0c1\uc2b9\uc758 \uc6d0\uc778\uc774 \uc774\uc775 \uc99d\uac00\uc778\uc9c0, \uc790\uae30\uc790\ubcf8 \uac10\uc18c\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8 \ud568\uc815\uc740 \uc77c\ud68c\uc131 \uc774\uc775\uc785\ub2c8\ub2e4.<br/>\\n\uc790\uc0b0 \ub9e4\uac01 \ucc28\uc775\uc774\ub098 \ud3c9\uac00 \uc774\uc775\uc774 \ud3ec\ud568\ub41c \uc21c\uc774\uc775\uc740 \ubc18\ubcf5\uc131\uc774 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\uc77c\ud68c\uc131 \uc774\uc775\uc744 \uc81c\uc678\ud55c \uacbd\uc0c1\uc801\uc778 \uc774\uc775 \uae30\uc900\uc73c\ub85c \ub2e4\uc2dc \uacc4\uc0b0\ud574 \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8 \ud568\uc815\uc740 \uc5c5\uc885 \uac04 \ube44\uad50\uc785\ub2c8\ub2e4.<br/>\\n\uae08\uc735\uc5c5\uacfc \uc81c\uc870\uc5c5, \ud50c\ub7ab\ud3fc \uae30\uc5c5\uc758 \uc790\ubcf8 \uad6c\uc870\ub294 \uc11c\ub85c \ub2e4\ub985\ub2c8\ub2e4.<br/>\\nROE\uc640 ROA\ub294 \uac19\uc740 \uc5c5\uc885 \uc548\uc5d0\uc11c \ube44\uad50\ud560 \ub54c \uc758\ubbf8\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc2e4\uc801 \ubc1c\ud45c\uc5d0\uc11c\ub294 ROE\uc640 ROA\ub97c \ud55c \ubd84\uae30\ub9cc \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n3\ub144 \uc774\uc0c1\uc758 \ucd94\uc774\ub97c \ubcf4\uba74 \uc77c\ud68c\uc131 \uc694\uc778\uc758 \uc601\ud5a5\uc744 \uac00\ub824\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nROE\uac00 \uc624\ub974\ub294 \uad6d\uba74\uc5d0\uc11c\ub294 \uc790\uae30\uc790\ubcf8\uc758 \ubcc0\ub3d9 \uc6d0\uc778\uc744 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uacfc \uc790\uc0ac\uc8fc \ub9e4\uc785, \uc720\uc0c1\uc99d\uc790\uac00 \uc790\uae30\uc790\ubcf8\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc92c\ub294\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.<br/>\\nROA\uac00 \uc624\ub974\ub294 \uad6d\uba74\uc5d0\uc11c\ub294 \uc790\uc0b0 \uc99d\uac00\uc758 \uc18d\ub3c4\ub97c \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc0b0\uc774 \uc774\uc775\ubcf4\ub2e4 \ube60\ub974\uac8c \ub298\uba74 ROA\ub294 \ud558\ub77d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nROE\uc640 ROA\ub294 \uc218\uc775\uc131\uc758 \ucd9c\ubc1c\uc810\uc774\uc9c0 \uc644\uacb0\ub41c \ud310\ub2e8\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc601\uc5c5\uc774\uc775\ub960\uacfc \ubd80\ucc44\ube44\uc728, \ud604\uae08\ud750\ub984\uc744 \ud568\uaed8 \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\nROE\ub294 \uc8fc\uc8fc \uc790\ubcf8\uc758 \ud6a8\uc728\uc744, ROA\ub294 \uc804\uccb4 \uc790\uc0b0\uc758 \ud6a8\uc728\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\ud45c\uc758 \uaca9\ucc28\ub97c \ud568\uaed8 \ubcf4\uba74 \uc218\uc775\uc131\uc758 \uc9c8\uc744 \ub354 \uc815\ud655\ud788 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZjg5amJ5b3l3eW55ZzZ6eW54NXB5OHQ0amU3bWgyYXc4bzVjYzc5dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3og0IExSrnfW2kUaaI/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"year-end-bonus-allocation","metadata":{"permalink":"/blog/en/finance/year-end-bonus-allocation","source":"@site/finance/2026-10-30-year-end-bonus-allocation/index.mdx","title":"\uc5f0\ub9d0 \uc0c1\uc5ec\uae08\uc744 \ubc1b\uae30 \uc804\uc5d0 \uc815\ud558\ub294 \uc790\uae08 \ubc30\ubd84 \uc21c\uc11c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc0c1\uc5ec\uae08","permalink":"/blog/en/finance/tags/\uc0c1\uc5ec\uae08"},{"inline":true,"label":"\uc790\uae08\uad00\ub9ac","permalink":"/blog/en/finance/tags/\uc790\uae08\uad00\ub9ac"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"}],"readingTime":3.32,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"year-end-bonus-allocation","title":"\uc5f0\ub9d0 \uc0c1\uc5ec\uae08\uc744 \ubc1b\uae30 \uc804\uc5d0 \uc815\ud558\ub294 \uc790\uae08 \ubc30\ubd84 \uc21c\uc11c","authors":["way"],"tags":["finance","\uc0c1\uc5ec\uae08","\uc790\uae08\uad00\ub9ac","\uac1c\uc778\uc7ac\ubb34"]},"unlisted":false,"prevItem":{"title":"ROE\uc640 ROA\ub85c \uc77d\ub294 \uae30\uc5c5\uc758 \uc218\uc775\uc131, \uacc4\uc0b0\ubc95\uacfc \ud568\uc815","permalink":"/blog/en/finance/roe-roa-guide"},"nextItem":{"title":"\uc2e4\uc801\uc740 \uc88b\uc558\ub294\ub370 \uc8fc\uac00\ub294 \uc65c \ub5a8\uc5b4\uc9c8\uae4c, \uae30\ub300\uce58\uc640 \uc8fc\uac00 \ubc18\uc751","permalink":"/blog/en/finance/earnings-expectations-stock-reaction"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc5f0\ub9d0 \uc0c1\uc5ec\uae08\uc744 \ubc1b\uae30 \uc804\uc5d0 \ubbf8\ub9ac \uc815\ud574\ub450\uba74 \uc88b\uc740 \uc790\uae08 \ubc30\ubd84 \uc21c\uc11c\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc5f0\ub9d0\uc774 \ub2e4\uac00\uc624\uba74 \uc131\uacfc\uae09\uc774\ub098 \uc0c1\uc5ec\uae08\uc744 \ubc1b\ub294 \uc9c1\uc7a5\uc778\uc774 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc5ec\uae08\uc740 \ud3c9\uc18c \uc6d4\uae09\ubcf4\ub2e4 \uae08\uc561\uc774 \ucee4\uc11c \uc9c0\ucd9c \uacc4\ud68d \uc5c6\uc774 \ubc1b\uc73c\uba74 \uc27d\uac8c \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\ud1b5\uc7a5\uc5d0 \ub4e4\uc5b4\uc628 \uae08\uc561\uc744 \ubcf4\uace0 \uacc4\ud68d\uc744 \uc138\uc6b0\uba74 \uc774\ubbf8 \uc18c\ube44\uac00 \uba3c\uc800 \uc9c4\ud589\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub798\uc11c \ubc30\ubd84 \uc21c\uc11c\ub294 \ub3c8\uc744 \ubc1b\uae30 \uc804\uc5d0 \uc815\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ud2b9\uc815 \uae08\uc735\uc0c1\ud488\uc744 \uad8c\uc720\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c \uc790\uae08 \uad00\ub9ac \uc21c\uc11c\ub97c \uc124\uba85\ud558\ub294 \ud574\uc124\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExemZjM3EwNHZ0ZW43N2oyc2xrZng4dGRlanoycnVsemJycHBwdWxwNyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/7z4uPuB39V9G8/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uccab \ub2e8\uacc4, \uc138\ud6c4 \uc2e4\uc218\ub839\uc561 \ud655\uc778\ud558\uae30\\n\\n\uc0c1\uc5ec\uae08\ub3c4 \uadfc\ub85c\uc18c\ub4dd\uc5d0 \ud574\ub2f9\ud574 \uc18c\ub4dd\uc138\uc640 \uc0ac\ud68c\ubcf4\ud5d8\ub8cc\uac00 \ubd80\uacfc\ub429\ub2c8\ub2e4.<br/>\\n\uba85\uc138\uc11c\uc0c1\uc758 \uc0c1\uc5ec\uae08 \ucd1d\uc561\uc774 \uadf8\ub300\ub85c \ud1b5\uc7a5\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc138\uc728 \uad6c\uac04\uc5d0 \ub530\ub77c \uacf5\uc81c\uc561\uc774 \ub2ec\ub77c\uc9c0\ubbc0\ub85c \uc2e4\uc218\ub839\uc561\uc740 \uac1c\uc778\ub9c8\ub2e4 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\ubc30\ubd84 \uacc4\ud68d\uc740 \ucd1d\uc561\uc774 \uc544\ub2c8\ub77c \uc138\ud6c4 \uc2e4\uc218\ub839\uc561\uc744 \uae30\uc900\uc73c\ub85c \uc138\uc6cc\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc804\ub144\ub3c4 \uc0c1\uc5ec\uae08 \uba85\uc138\uc11c\uac00 \uc788\ub2e4\uba74 \uc62c\ud574 \uc2e4\uc218\ub839\uc561\uc744 \uac00\ub2a0\ud558\ub294 \ucc38\uace0 \uc790\ub8cc\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\ud68c\uc0ac\uc758 \uc0c1\uc5ec\uae08 \uc9c0\uae09 \uc2dc\uae30\uc640 \ubd84\ud560 \uc9c0\uae09 \uc5ec\ubd80\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ubd84 \uc21c\uc11c\uc758 \ub2e4\uc12f \ub2e8\uacc4\\n\\n\uc790\uae08 \ubc30\ubd84\uc740 \uc544\ub798 \uc21c\uc11c\ub85c \uac80\ud1a0\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uace0\uae08\ub9ac \ubd80\ucc44\ubd80\ud130 \uc815\ub9ac\ud558\uae30\\n\\n\uce74\ub4dc \ub9ac\ubcfc\ube59\uc774\ub098 \ud604\uae08\uc11c\ube44\uc2a4, \uace0\uae08\ub9ac \uc2e0\uc6a9\ub300\ucd9c\uc774 \uc788\ub2e4\uba74 \uc0c1\ud658\uc744 \uba3c\uc800 \uac80\ud1a0\ud569\ub2c8\ub2e4.<br/>\\n\uace0\uae08\ub9ac \ubd80\ucc44\uc758 \uc774\uc790\ub294 \uc800\ucd95 \uc218\uc775\ubcf4\ub2e4 \ud070 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd80\ucc44\ub97c \uc904\uc774\uba74 \ub9e4\ub2ec \ub098\uac00\ub294 \uc774\uc790 \ubd80\ub2f4\uc774 \ud568\uaed8 \uc904\uc5b4\ub4ed\ub2c8\ub2e4.<br/>\\n\ub2e8, \uc911\ub3c4\uc0c1\ud658\uc218\uc218\ub8cc\uac00 \uc788\ub294 \ub300\ucd9c\uc740 \uc218\uc218\ub8cc\uc640 \uc774\uc790 \uc808\uac10\uc561\uc744 \ube44\uad50\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ube44\uc0c1\uc790\uae08 \ubcf4\ucda9\ud558\uae30\\n\\n\ube44\uc0c1\uc790\uae08\uc740 \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc774\ub098 \uc18c\ub4dd \uacf5\ubc31\uc5d0 \ub300\ube44\ud558\ub294 \uc790\uae08\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18\uc801\uc73c\ub85c \uc6d4 \uc0dd\ud65c\ube44\uc758 3\uac1c\uc6d4\ubd84\uc5d0\uc11c 6\uac1c\uc6d4\ubd84\uc744 \uae30\uc900\uc73c\ub85c \uc124\uba85\ub429\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uc790\uae08\uc774 \uae30\uc900\uc5d0 \ubabb \ubbf8\uce5c\ub2e4\uba74 \uc0c1\uc5ec\uae08\uc758 \uc77c\ubd80\ub85c \ubcf4\ucda9\ud558\ub294 \uac83\uc744 \uac80\ud1a0\ud569\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uc790\uae08\uc740 \uc218\uc775\ubcf4\ub2e4 \ud544\uc694\ud560 \ub54c \ubc14\ub85c \uc4f8 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ud22c\uc790 \uc790\uae08\uacfc \ube44\uc0c1\uc790\uae08\uc744 \uac19\uc740 \ud1b5\uc7a5\uc5d0\uc11c \uad00\ub9ac\ud558\uba74 \uad6c\ubd84\uc774 \ud750\ub824\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc138\uc81c \ud61c\ud0dd \uacc4\uc88c\uc758 \ub0a9\uc785 \ud55c\ub3c4 \uc810\uac80\ud558\uae30\\n\\n\uc5f0\uae08\uc800\ucd95\uacfc \uac1c\uc778\ud615\ud1f4\uc9c1\uc5f0\uae08\uc740 \uc5f0\uac04 \ub0a9\uc785 \ud55c\ub3c4\uc640 \uc138\uc561\uacf5\uc81c \ud55c\ub3c4\uac00 \uc815\ud574\uc838 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\ub9d0\uc774 \ub418\uae30 \uc804\uc5d0 \uc62c\ud574 \ub0a9\uc785\uc561\uc774 \ud55c\ub3c4\uc5d0 \ub3c4\ub2ec\ud588\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ub3c4\uc5d0 \uc5ec\uc720\uac00 \uc788\ub2e4\uba74 \uc0c1\uc5ec\uae08\uc758 \uc77c\ubd80\ub97c \ub0a9\uc785\uc5d0 \ud65c\uc6a9\ud558\ub294 \ubc29\uc548\uc744 \uac80\ud1a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc138\uc561\uacf5\uc81c \ud55c\ub3c4\ub294 \uc18c\ub4dd \uc218\uc900\uacfc \uac00\uc785 \ud615\ud0dc\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uad6c\uccb4\uc801\uc778 \uacf5\uc81c\uc561\uc740 \uad6d\uc138\uccad \uc5f0\ub9d0\uc815\uc0b0 \uc548\ub0b4\ub098 \uac00\uc785 \uae08\uc735\uae30\uad00 \uc790\ub8cc\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790 \uc790\uae08\uc740 \ube44\uc728\ub85c \uc815\ud558\uae30\\n\\n\ud22c\uc790\uc5d0 \uc4f8 \uc790\uae08\uc740 \uae08\uc561\uc774 \uc544\ub2c8\ub77c \ube44\uc728\ub85c \uc815\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc5ec\uae08 \ucd1d\uc561\uc774 \ub2ec\ub77c\uc838\ub3c4 \ube44\uc728\uc740 \uadf8\ub300\ub85c \uc801\uc6a9\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ud22c\uc790 \uc790\uae08\uc740 \ud3c9\uc18c\uc758 \uc790\uc0b0 \ubc30\ubd84 \uc6d0\uce59\uacfc \uac19\uc740 \uae30\uc900\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc0c1\uc5ec\uae08\uc744 \ubc1b\uc558\ub2e4\ub294 \uc774\uc720\ub85c \ud3c9\uc18c\ubcf4\ub2e4 \uc704\ud5d8\ud55c \uc790\uc0b0\uc5d0 \ubab0\uc544\ub123\ub294 \uacb0\uc815\uc740 \uc8fc\uc758\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ud22c\uc790 \uc790\uae08\uc758 \uc785\uae08\uc77c\uc744 \ubbf8\ub9ac \uc815\ud574\ub450\uba74 \uac10\uc815\uc5d0 \ub530\ub978 \uacb0\uc815\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc18c\ube44 \uc608\uc0b0\uc5d0 \uc0c1\ud55c \uc815\ud558\uae30\\n\\n\uc0c1\uc5ec\uae08\uc758 \uc77c\ubd80\ub97c \uc18c\ube44\uc5d0 \uc4f0\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc77c\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc18c\ube44 \uc608\uc0b0\ub3c4 \uc0c1\ud55c\uc744 \uc815\ud574\ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\ud55c\uc744 \uc815\ud558\uc9c0 \uc54a\uc73c\uba74 \uc18c\ube44\uac00 \ubc30\ubd84\uc758 \ub098\uba38\uc9c0\ub97c \ubaa8\ub450 \ucc28\uc9c0\ud558\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\uac00\uc871 \ud589\uc0ac\ub098 \ud734\uac00\ucc98\ub7fc \uc2dc\uae30\uac00 \uc815\ud574\uc9c4 \uc9c0\ucd9c\uc740 \ud56d\ubaa9\ubcc4\ub85c \uae08\uc561\uc744 \ub098\ub220 \uc801\uc2b5\ub2c8\ub2e4.<br/>\\n\ub0a8\uc740 \uae08\uc561\uc774 \uc0dd\uae30\uba74 \uc18c\ube44\ub85c \ub118\uae30\uae30\ubcf4\ub2e4 \uc800\ucd95\uacfc \ud22c\uc790\ub85c \ub3cc\ub9ac\ub294 \uaddc\uce59\uc744 \uc815\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ubd84 \uc608\uc2dc\\n\\n\uc138\ud6c4 \uc2e4\uc218\ub839\uc561 300\ub9cc\uc6d0\uc744 \uac00\uc815\ud55c \ubc30\ubd84 \uc608\uc2dc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud56d\ubaa9 | \uae08\uc561 | \ube44\uc911 |\\n| --- | --- | --- |\\n| \uace0\uae08\ub9ac \ubd80\ucc44 \uc0c1\ud658 | 100\ub9cc\uc6d0 | 33% |\\n| \ube44\uc0c1\uc790\uae08 \ubcf4\ucda9 | 100\ub9cc\uc6d0 | 33% |\\n| \uc800\ucd95\uacfc \ud22c\uc790 | 70\ub9cc\uc6d0 | 23% |\\n| \uc18c\ube44 | 30\ub9cc\uc6d0 | 10% |\\n| \ud569\uacc4 | 300\ub9cc\uc6d0 | 100% |\\n\\n\uc774 \ud45c\ub294 \uc774\ud574\ub97c \ub3d5\uae30 \uc704\ud55c \uc608\uc2dc\uc77c \ubfd0, \uc815\ub2f5 \ube44\uc728\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ubd80\ucc44\uac00 \uc5c6\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubd80\ucc44 \uc0c1\ud658 \ud56d\ubaa9\uc774 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uc790\uae08\uc774 \uc774\ubbf8 \ucda9\ubd84\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc800\ucd95\uacfc \ud22c\uc790 \ube44\uc911\uc744 \ub192\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc2e0\uc758 \ubd80\ucc44\uc640 \ube44\uc0c1\uc790\uae08, \ub0a9\uc785 \ud55c\ub3c4\ub97c \uba3c\uc800 \ud655\uc778\ud55c \ub4a4 \ube44\uc728\uc744 \uc870\uc815\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc0c1\uc5ec\uae08 \uc9c0\uae09 \uc804\uc5d0 \uc790\ub3d9\uc774\uccb4\ub97c \uc124\uc815\ud574\ub450\ub294 \uac83\uc774 \uc2e4\ud589\ub825\uc744 \ub192\uc785\ub2c8\ub2e4.<br/>\\n\uc0c1\uc5ec\uae08\uc774 \ub4e4\uc5b4\uc624\ub294 \ub0a0\uc5d0 \ubd80\ucc44 \uc0c1\ud658\uacfc \uc800\ucd95 \uc774\uccb4\uac00 \ud568\uaed8 \ub098\uac00\ub3c4\ub85d \uc124\uc815\ud569\ub2c8\ub2e4.<br/>\\n\ud1b5\uc7a5\uc744 \ubaa9\uc801\ubcc4\ub85c \ub098\ub204\uba74 \ubc30\ubd84 \uacb0\uacfc\ub97c \ud55c\ub208\uc5d0 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\ub9d0\uc815\uc0b0\uc5d0\uc11c\ub294 \uc0c1\uc5ec\uae08\ub3c4 \uadfc\ub85c\uc18c\ub4dd\uc5d0 \ud3ec\ud568\ub41c\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc0c1\uc5ec\uae08\uc73c\ub85c \ub0a9\uc785\ud55c \uc5f0\uae08 \uacc4\uc88c\uc758 \uacf5\uc81c \uc5ec\ubd80\ub294 \uc5f0\ub9d0\uc815\uc0b0 \uac04\uc18c\ud654 \uc790\ub8cc\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ubd84 \uacc4\ud68d\uc740 \ud55c \ubc88 \uc138\uc6b0\uace0 \ub05d\ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub9e4\ub144 \uc810\uac80\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc18c\ub4dd\uacfc \ubd80\ucc44, \uac00\uc871 \uc0c1\ud669\uc774 \ubc14\ub00c\uba74 \ubc30\ubd84 \ube44\uc728\ub3c4 \ud568\uaed8 \uc870\uc815\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc0c1\uc5ec\uae08 \uad00\ub9ac\uc758 \ud575\uc2ec\uc740 \ub3c8\uc744 \ubc1b\uae30 \uc804\uc5d0 \uc21c\uc11c\ub97c \uc815\ud558\ub294 \uc77c\uc785\ub2c8\ub2e4.<br/>\\n\ubd80\ucc44\uc640 \ube44\uc0c1\uc790\uae08, \uc138\uc81c \ud61c\ud0dd, \ud22c\uc790, \uc18c\ube44\uc758 \uc21c\uc11c\ub97c \ubbf8\ub9ac \uc815\ud558\uba74 \uc5f0\ub9d0 \uc790\uae08\uc774 \ud6e8\uc52c \ub2e8\ub2e8\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExM2t2Y2k5b3YyMTAyOHFwbDFteXRyendjZGNhOW1qajE2ZzVyZXV0NSZlcD12MV9jaGFubmVsc19zZWFyY2gmY3Q9Zw/hotSIeuobzreofMOdw/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"earnings-expectations-stock-reaction","metadata":{"permalink":"/blog/en/finance/earnings-expectations-stock-reaction","source":"@site/finance/2026-10-29-earnings-expectations-stock-reaction/index.mdx","title":"\uc2e4\uc801\uc740 \uc88b\uc558\ub294\ub370 \uc8fc\uac00\ub294 \uc65c \ub5a8\uc5b4\uc9c8\uae4c, \uae30\ub300\uce58\uc640 \uc8fc\uac00 \ubc18\uc751","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc2e4\uc801\ubc1c\ud45c","permalink":"/blog/en/finance/tags/\uc2e4\uc801\ubc1c\ud45c"},{"inline":true,"label":"\uae30\ub300\uce58","permalink":"/blog/en/finance/tags/\uae30\ub300\uce58"},{"inline":true,"label":"\ucee8\uc13c\uc11c\uc2a4","permalink":"/blog/en/finance/tags/\ucee8\uc13c\uc11c\uc2a4"}],"readingTime":2.44,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"earnings-expectations-stock-reaction","title":"\uc2e4\uc801\uc740 \uc88b\uc558\ub294\ub370 \uc8fc\uac00\ub294 \uc65c \ub5a8\uc5b4\uc9c8\uae4c, \uae30\ub300\uce58\uc640 \uc8fc\uac00 \ubc18\uc751","authors":["way"],"tags":["finance","\uc2e4\uc801\ubc1c\ud45c","\uae30\ub300\uce58","\ucee8\uc13c\uc11c\uc2a4"]},"unlisted":false,"prevItem":{"title":"\uc5f0\ub9d0 \uc0c1\uc5ec\uae08\uc744 \ubc1b\uae30 \uc804\uc5d0 \uc815\ud558\ub294 \uc790\uae08 \ubc30\ubd84 \uc21c\uc11c","permalink":"/blog/en/finance/year-end-bonus-allocation"},"nextItem":{"title":"\uae08\uc735\uc9c0\uc8fc\uc758 \uc0ac\uc5c5 \uad6c\uc870\uc640 \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc744 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/financial-holdings-shareholder-return"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc2e4\uc801\uc740 \uc88b\uc544 \ubcf4\uc600\ub294\ub370 \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720\ub97c \uae30\ub300\uce58 \uac1c\ub150\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 29\uc77c \ucf54\uc2a4\ud53c\ub294 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uc758 \uc2e4\uc801 \ubc1c\ud45c\ub97c \uc804\ud6c4\ub85c \ud558\ub77d \uc804\ud658\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \uc790\uccb4\ub294 \uc5ed\ub300 \ucd5c\ub300 \uc218\uc900\uc73c\ub85c \uc804\ud574\uc84c\uc9c0\ub9cc, \uc8fc\uc8fc\ud658\uc6d0 \uc138\ubd80\uc548\uc5d0 \ub300\ud55c \ubd88\ud655\uc2e4\uc131\uc774 \ubd80\uac01\ub418\uba70 \ud574\ub2f9 \uc885\ubaa9\uc740 4.13% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \ub2e4\ub978 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\ub294 2.62% \uc0c1\uc2b9\ud558\uba70 \ubc29\ud5a5\uc774 \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \uc22b\uc790\uc640 \uc8fc\uac00 \ubc29\ud5a5\uc774 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc774\ub294 \ub0a0\uc5d0\ub294, \uc2dc\uc7a5\uc774 \uc774\ubbf8 \ubb34\uc5c7\uc744 \uae30\ub300\ud558\uace0 \uc788\uc5c8\ub294\uc9c0\ub97c \uba3c\uc800 \uc0b4\ud3b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExYnptbGlqdDFsazY5NDhpeTFwazFjOHYycXVzenp0Nnl6NWQ1bXhoZiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/8acGIeFnqLA7S/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \ucee8\uc13c\uc11c\uc2a4\uc640 \uc5b4\ub2dd \uc11c\ud504\ub77c\uc774\uc988\\n\\n\ucee8\uc13c\uc11c\uc2a4\ub294 \uc5ec\ub7ec \uc99d\uad8c\uc0ac \uc560\ub110\ub9ac\uc2a4\ud2b8\uc758 \uc2e4\uc801 \uc804\ub9dd\uce58\ub97c \ud3c9\uade0\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uc5b4\ub2dd \uc11c\ud504\ub77c\uc774\uc988\ub294 \uc2e4\uc81c \uc2e4\uc801\uc774 \ucee8\uc13c\uc11c\uc2a4\ub97c \uc6c3\ub3c4\ub294 \uacbd\uc6b0, \uc5b4\ub2dd \uc1fc\ud06c\ub294 \ubc11\ub3c4\ub294 \uacbd\uc6b0\ub97c \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\ub294 \uc2e4\uc801 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uc2e4\uc801\uacfc \ucee8\uc13c\uc11c\uc2a4\uc758 \ucc28\uc774, \uc989 \uc11c\ud504\ub77c\uc774\uc988 \ud3ed\uc5d0 \ubc18\uc751\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uad6c\ubd84 | \uc2e4\uc81c \uc2e4\uc801\uacfc \ucee8\uc13c\uc11c\uc2a4 | \uc2dc\uc7a5 \ubc18\uc751\uc758 \ubc29\ud5a5 |\\n| --- | --- | --- |\\n| \uc5b4\ub2dd \uc11c\ud504\ub77c\uc774\uc988 | \uc2e4\uc81c\uac00 \ucee8\uc13c\uc11c\uc2a4\ubcf4\ub2e4 \ub192\uc74c | \uae0d\uc815\uc801\uc73c\ub85c \ud574\uc11d\ub418\uae30 \uc26c\uc6c0 |\\n| \ucee8\uc13c\uc11c\uc2a4 \ubd80\ud569 | \uc2e4\uc81c\uac00 \ucee8\uc13c\uc11c\uc2a4\uc640 \ube44\uc2b7\ud568 | \uc7ac\ub8cc \uc18c\uc9c4\uc73c\ub85c \ud574\uc11d\ub418\uae30 \uc26c\uc6c0 |\\n| \uc5b4\ub2dd \uc1fc\ud06c | \uc2e4\uc81c\uac00 \ucee8\uc13c\uc11c\uc2a4\ubcf4\ub2e4 \ub0ae\uc74c | \ubd80\uc815\uc801\uc73c\ub85c \ud574\uc11d\ub418\uae30 \uc26c\uc6c0 |\\n\\n\ub2e8, \uc704 \ud45c\ub294 \uc77c\ubc18\uc801\uc778 \uacbd\ud5a5\uc774\uba70, \ud56d\uc0c1 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801\uc774 \ucee8\uc13c\uc11c\uc2a4\ub97c \uc6c3\ub3cc\uc544\ub3c4 \uac00\uc774\ub358\uc2a4\uac00 \ub0ae\uc544\uc9c0\uba74 \uc8fc\uac00\uac00 \ud558\ub77d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc120\ubc18\uc601\uacfc \uac00\uc774\ub358\uc2a4\\n\\n\uc120\ubc18\uc601\uc740 \uc88b\uc740 \uc2e4\uc801\uc774 \uc608\uc0c1\ub420 \ub54c \uc8fc\uac00\uac00 \ubc1c\ud45c \uc804\uc5d0 \uc774\ubbf8 \uc624\ub978 \uc0c1\ud0dc\ub97c \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uacbd\uc6b0 \uc2e4\uc801\uc774 \uc608\uc0c1\ub300\ub85c \ub098\uc640\ub3c4 \uc0c8\ub85c \uc0b4 \uc774\uc720\uac00 \uc904\uc5b4\ub4e4\uc5b4 \ucc28\uc775\uc2e4\ud604 \ub9e4\ubb3c\uc774 \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac00\uc774\ub358\uc2a4\ub294 \uae30\uc5c5\uc774 \uc81c\uc2dc\ud558\ub294 \ub2e4\uc74c \ubd84\uae30\ub098 \uc5f0\uac04 \uc2e4\uc801 \uc804\ub9dd\uc785\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \ubc1c\ud45c \ub0a0\uc5d0\ub294 \uc9c0\ub09c \ubd84\uae30 \uc22b\uc790\ubcf4\ub2e4 \uac00\uc774\ub358\uc2a4\uc640 \uc8fc\uc8fc\ud658\uc6d0 \uacc4\ud68d\uc774 \ub354 \ud06c\uac8c \uc791\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 29\uc77c\uc758 \uc0ac\ub840\ub3c4 \uac19\uc740 \ub9e5\ub77d\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uc8fc\ud658\uc6d0 \ucd1d\uc561 \uaddc\ubaa8\ub294 \uc81c\uc2dc\ub410\uc9c0\ub9cc \uc138\ubd80 \ub0b4\uc6a9\uc774 \ubbf8\uacf5\uac1c \uc0c1\ud0dc\uc600\uace0, \uc2dc\uc7a5\uc740 \uc774\ub97c \ubd88\ud655\uc2e4\uc131\uc73c\ub85c \ubc1b\uc544\ub4e4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uacc4\uc0b0 \uc608\uc2dc\\n\\n\ub2e4\uc74c\uc740 \uac1c\ub150\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uac00\uc0c1\uc758 \uc608\uc2dc\uc774\uba70, \uc2e4\uc81c \uae30\uc5c5\uc758 \uc218\uce58\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n| \ud56d\ubaa9 | \ucee8\uc13c\uc11c\uc2a4 | \uc2e4\uc81c \uc2e4\uc801 | \ucc28\uc774 |\\n| --- | --- | --- | --- |\\n| \ubd84\uae30 \uc601\uc5c5\uc774\uc775 | 10\uc870 \uc6d0 | 12\uc870 \uc6d0 | 20% \uc0c1\ud68c |\\n| \ub2e4\uc74c \ubd84\uae30 \uac00\uc774\ub358\uc2a4 | 13\uc870 \uc6d0 | 11\uc870 \uc6d0 | \ud558\ud5a5 |\\n\\n\uc774 \uc608\uc2dc\uc5d0\uc11c\ub294 \ubd84\uae30 \uc2e4\uc801\uc774 \ucee8\uc13c\uc11c\uc2a4\ub97c 20% \uc6c3\ub3cc\uc558\uc9c0\ub9cc, \uac00\uc774\ub358\uc2a4\uac00 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc740 \uacfc\uac70 \uc2e4\uc801\ubcf4\ub2e4 \ubbf8\ub798 \uc774\uc775 \uc804\ub9dd\uc5d0 \ubb34\uac8c\ub97c \ub450\uae30 \ub54c\ubb38\uc5d0, \uc8fc\uac00\uac00 \ud558\ub77d\uc73c\ub85c \ubc18\uc751\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc2e4\uc801\uc774 \uae30\ub300\uc5d0 \ubabb \ubbf8\uccd0\ub3c4 \uac00\uc774\ub358\uc2a4\uac00 \uc0c1\ud5a5\ub418\uba74 \uc8fc\uac00\uac00 \uc624\ub974\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc2e4\uc801 \ubc1c\ud45c \uc804\uc5d0 \ucee8\uc13c\uc11c\uc2a4 \uc218\uc900\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc7a0\uc815 \uc2e4\uc801\uacfc \ud655\uc815 \uc2e4\uc801\uc744 \uad6c\ubd84\ud569\ub2c8\ub2e4.<br/>\\n\uc7a0\uc815 \uc2e4\uc801\uc740 \ub9e4\ucd9c\uacfc \uc601\uc5c5\uc774\uc775 \uc911\uc2ec\uc758 \uc694\uc57d \uc218\uce58\uc774\uba70, \ud655\uc815 \uc2e4\uc801\uc5d0\uc11c \uc138\ubd80 \ud56d\ubaa9\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc2e4\uc801 \ubc1c\ud45c\uc640 \ud568\uaed8 \ub098\uc628 \uac00\uc774\ub358\uc2a4, \ubc30\ub2f9, \uc790\uc0ac\uc8fc \uacc4\ud68d\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc2e4\uc801 \ubc1c\ud45c \uc9c1\ud6c4\uc758 \uc8fc\uac00 \ubc18\uc751\ub9cc\uc73c\ub85c \uae30\uc5c5\uc758 \uac00\uce58\ub97c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub8e8\uc758 \ubc18\uc751\uc740 \uae30\ub300 \uc870\uc815 \uacfc\uc815\uc77c \uc218 \uc788\uace0, \uc911\uae30 \ubc29\ud5a5\uc740 \ub2e4\uc74c \ubd84\uae30 \uc2e4\uc801\uc73c\ub85c \ub2e4\uc2dc \uac80\uc99d\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc8fc\uac00\ub294 \uc2e4\uc801\uc758 \uc808\ub300 \uc218\uc900\ubcf4\ub2e4 \uae30\ub300\uc640\uc758 \ucc28\uc774\uc640 \ubbf8\ub798 \uc804\ub9dd\uc5d0 \ubc18\uc751\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExYnptbGlqdDFsazY5NDhpeTFwazFjOHYycXVzenp0Nnl6NWQ1bXhoZiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/Qs1uMrvmHAKIUXxO2g/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"financial-holdings-shareholder-return","metadata":{"permalink":"/blog/en/finance/financial-holdings-shareholder-return","source":"@site/finance/2026-10-29-financial-holdings-shareholder-return/index.mdx","title":"\uae08\uc735\uc9c0\uc8fc\uc758 \uc0ac\uc5c5 \uad6c\uc870\uc640 \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc744 \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uae08\uc735\uc9c0\uc8fc","permalink":"/blog/en/finance/tags/\uae08\uc735\uc9c0\uc8fc"},{"inline":true,"label":"\uc8fc\uc8fc\ud658\uc6d0","permalink":"/blog/en/finance/tags/\uc8fc\uc8fc\ud658\uc6d0"},{"inline":true,"label":"\ubc30\ub2f9","permalink":"/blog/en/finance/tags/\ubc30\ub2f9"}],"readingTime":2.41,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"financial-holdings-shareholder-return","title":"\uae08\uc735\uc9c0\uc8fc\uc758 \uc0ac\uc5c5 \uad6c\uc870\uc640 \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc744 \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","\uae08\uc735\uc9c0\uc8fc","\uc8fc\uc8fc\ud658\uc6d0","\ubc30\ub2f9"]},"unlisted":false,"prevItem":{"title":"\uc2e4\uc801\uc740 \uc88b\uc558\ub294\ub370 \uc8fc\uac00\ub294 \uc65c \ub5a8\uc5b4\uc9c8\uae4c, \uae30\ub300\uce58\uc640 \uc8fc\uac00 \ubc18\uc751","permalink":"/blog/en/finance/earnings-expectations-stock-reaction"},"nextItem":{"title":"\ud22c\uc790 \uc77c\uc9c0 \uc4f0\ub294 \ubc95, \ub9e4\ub9e4 \uae30\ub85d\uacfc \ubcf5\uae30 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","permalink":"/blog/en/finance/investment-journal-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uae08\uc735\uc9c0\uc8fc\uc758 \uc0ac\uc5c5 \uad6c\uc870\uc640 \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc744 \uc77d\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 29\uc77c \uc7a5\uc5d0\uc11c\ub294 \uae08\uc735\uc8fc\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud558\ub294 \ud750\ub984\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\nKB\uae08\uc735\uc774 1.82% \uc0c1\uc2b9 \ub9c8\uac10\ud55c \uac83\uc774 \ub300\ud45c\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \uc804\ud574\uc9c4 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 5\ub300 \uae08\uc735\uc9c0\uc8fc\uc758 \uc62c\ud574 \uc21c\uc774\uc775\uc740 20\uc870 \uc6d0 \uaddc\ubaa8\ub85c \uc5ed\ub300 \ucd5c\ub300 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801\uc774 \uc88b\uc544\uc84c\ub2e4\ub294 \uc18c\uc2dd\uacfc \uc8fc\uc8fc\ud658\uc6d0 \uae30\ub300\uac00 \ud568\uaed8 \uc5b8\uae09\ub418\ub294 \ub0a0\uc5d0\ub294, \uae08\uc735\uc9c0\uc8fc\uac00 \ub3c8\uc744 \uc5b4\ub5bb\uac8c \ubc8c\uace0 \uc5b4\ub5bb\uac8c \ub098\ub204\ub294\uc9c0\ub97c \uba3c\uc800 \uc774\ud574\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExejdoejBpNHRzc24wMTFjeWtkeDdyNmFoMWVlajg0N3ZoNmwxb3ZvbyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/19RHp41ibAqSFkaPuq/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uae08\uc735\uc9c0\uc8fc\uc758 \uc0ac\uc5c5 \uad6c\uc870\\n\\n\uae08\uc735\uc9c0\uc8fc\ub294 \uc740\ud589, \uc99d\uad8c, \ubcf4\ud5d8, \uce74\ub4dc \ub4f1 \uc5ec\ub7ec \uae08\uc735 \uacc4\uc5f4\uc0ac\ub97c \uc544\ub798\uc5d0 \ub454 \uc9c0\ubc30 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uac01 \uacc4\uc5f4\uc0ac\ub294 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc774\uc775\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.<br/>\\n\\n| \uacc4\uc5f4\uc0ac | \uc8fc\uc694 \uc774\uc775 \uc6d0\ucc9c |\\n| --- | --- |\\n| \uc740\ud589 | \uc608\ub300\uae08\ub9ac\ucc28\uc5d0 \ub530\ub978 \uc774\uc790\uc774\uc775 |\\n| \uc99d\uad8c | \uc704\ud0c1\ub9e4\ub9e4 \uc218\uc218\ub8cc, \uc790\uc0b0\uad00\ub9ac \uc218\uc218\ub8cc, \uc790\uae30\ub9e4\ub9e4 \uc190\uc775 |\\n| \ubcf4\ud5d8 | \ubcf4\ud5d8\ub8cc\uc5d0\uc11c \ubcf4\ud5d8\uae08\uacfc \uc0ac\uc5c5\ube44\ub97c \ube80 \ubcf4\ud5d8\uc190\uc775, \uc6b4\uc6a9\uc218\uc775 |\\n| \uce74\ub4dc | \uac00\ub9f9\uc810 \uc218\uc218\ub8cc, \uce74\ub4dc\ub860 \ub4f1 \uae08\uc735\uc218\uc775 |\\n\\n\uc740\ud589\uc758 \uc774\uc790\uc774\uc775\uc740 \ub300\ucd9c\uae08\ub9ac\uc640 \uc608\uae08\uae08\ub9ac\uc758 \ucc28\uc774\uc5d0\uc11c \ub098\uc635\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \uc624\ub974\uba74 \ub300\ucd9c\uae08\ub9ac\ub3c4 \ub530\ub77c \uc624\ub974\uc9c0\ub9cc, \uc608\uae08\uae08\ub9ac \uc778\uc0c1 \uc18d\ub3c4\uc640 \ub300\ucd9c \uad6c\uc870\uc5d0 \ub530\ub77c \uc774\uc775 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc99d\uad8c\uacfc \uce74\ub4dc\uc758 \uc218\uc218\ub8cc\uc774\uc775\uc740 \uac70\ub798\ub7c9\uacfc \uc18c\ube44 \ud750\ub984\uc5d0 \ubbfc\uac10\ud569\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uae08\uc735\uc9c0\uc8fc \uc2e4\uc801\uc744 \ubcfc \ub54c\ub294 \uc5b4\ub290 \uacc4\uc5f4\uc0ac\uac00 \uc774\uc775\uc744 \ub04c\uc5b4\uc62c\ub838\ub294\uc9c0 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc758 \uc138 \uac00\uc9c0 \ucd95\\n\\n\uc8fc\uc8fc\ud658\uc6d0\uc740 \uae30\uc5c5\uc774 \ubc88 \ub3c8\uc744 \uc8fc\uc8fc\uc5d0\uac8c \ub3cc\ub824\uc8fc\ub294 \ubc29\uc2dd\uc73c\ub85c, \ud06c\uac8c \uc138 \uac00\uc9c0 \ucd95\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud604\uae08\ubc30\ub2f9\\n\\n\ud604\uae08\ubc30\ub2f9\uc740 \uc8fc\uc8fc\uc5d0\uac8c \ud604\uae08\uc744 \uc9c1\uc811 \uc9c0\uae09\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc131\ud5a5\uc740 \uc21c\uc774\uc775 \uc911\uc5d0\uc11c \ubc30\ub2f9\uc73c\ub85c \uc9c0\uae09\ud558\ub294 \ube44\uc728\uc744 \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc21c\uc774\uc775 10\uc870 \uc6d0\uc5d0 \ubc30\ub2f9 \ucd1d\uc561 3\uc870 \uc6d0\uc774\uba74 \ubc30\ub2f9\uc131\ud5a5\uc740 30%\uc785\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc218\uc775\ub960\uc740 \uc8fc\uac00 \ub300\ube44 \ubc30\ub2f9\uae08\uc758 \ube44\uc728\uc774\uba70, \uc8fc\uac00\uac00 \uc624\ub974\uba74 \uc218\uc775\ub960\uc740 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01\\n\\n\uc790\uc0ac\uc8fc \ub9e4\uc785\uc740 \uae30\uc5c5\uc774 \uc790\uae30 \uc8fc\uc2dd\uc744 \uc2dc\uc7a5\uc5d0\uc11c \uc0ac\ub4e4\uc774\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\uc18c\uac01\uae4c\uc9c0 \uc774\uc5b4\uc9c0\uba74 \uc720\ud1b5 \uc8fc\uc2dd \uc218\uac00 \uc904\uc5b4 \uc8fc\ub2f9 \uc774\uc775\uc774 \ub192\uc544\uc9c0\ub294 \ud6a8\uacfc\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\uc785\ub9cc \ud558\uace0 \uc18c\uac01\ud558\uc9c0 \uc54a\uc740 \uc790\uc0ac\uc8fc\ub294 \ub098\uc911\uc5d0 \ub2e4\uc2dc \uc2dc\uc7a5\uc5d0 \ub098\uc62c \uc218 \uc788\uc5b4, \uc18c\uac01 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\ubcf8\ube44\uc728\uacfc \ud658\uc6d0 \uc5ec\ub825\\n\\n\uae08\uc735\ud68c\uc0ac\ub294 \uac74\uc804\uc131 \uaddc\uc81c\ub97c \ubc1b\uae30 \ub54c\ubb38\uc5d0, \ubc88 \ub3c8\uc744 \ubaa8\ub450 \ub098\ub220\uc904 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ud1b5\uc8fc\uc790\ubcf8\ube44\uc728\uc774 \ub192\uc744\uc218\ub85d \uc190\uc2e4 \ud761\uc218 \uc5ec\ub825\uc774 \ud06c\uace0, \uc8fc\uc8fc\ud658\uc6d0\uc744 \ub298\ub9b4 \uc5ec\uc9c0\ub3c4 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uacbd\uae30\uac00 \ub098\ube60\uc9c0\uba74 \ub300\uc190\ucda9\ub2f9\uae08\uc744 \uc313\uc544\uc57c \ud558\uace0, \ud658\uc6d0 \uc5ec\ub825\uc740 \uc904\uc5b4\ub4ed\ub2c8\ub2e4.<br/>\\n\uadf8\ub798\uc11c \uc8fc\uc8fc\ud658\uc6d0 \uaddc\ubaa8\ub294 \uc2e4\uc801\ubfd0 \uc544\ub2c8\ub77c \uc790\ubcf8\ube44\uc728\uacfc \uacbd\uae30 \uc804\ub9dd\uc744 \ud568\uaed8 \ubcf4\uace0 \uacb0\uc815\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ubc30\ub2f9 \ucd1d\uc561\uacfc \uc790\uc0ac\uc8fc \ub9e4\uc785, \uc18c\uac01 \uaddc\ubaa8\ub97c \ud569\uccd0 \ucd1d\uc8fc\uc8fc\ud658\uc6d0\uc728\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ud658\uc6d0 \uacc4\ud68d\uc774 \ud655\uc815\ubd84\uc778\uc9c0, \ubaa9\ud45c \ubc94\uc704\uc778\uc9c0, \uc138\ubd80 \uc77c\uc815\uc774 \uc815\ud574\uc84c\ub294\uc9c0\ub97c \uad6c\ubd84\ud569\ub2c8\ub2e4.<br/>\\n10\uc6d4 29\uc77c \uc2dc\uc7a5 \ubc18\uc751\uc774 \ubcf4\uc5ec\uc8fc\ub4ef, \ucd1d\uc561 \uaddc\ubaa8\ub9cc \ud06c\ub2e4\uace0 \ud574\uc11c \uc8fc\uac00\uac00 \ubc14\ub85c \ubc18\uc751\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138\ubd80\uc548\uc774 \ubbf8\uacf5\uac1c \uc0c1\ud0dc\uc774\uba74 \ubd88\ud655\uc2e4\uc131\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ubc30\ub2f9\ub77d\uc77c\uacfc \ubc30\ub2f9 \uc9c0\uae09 \uc2dc\uae30\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc744 \ubc1b\uae30 \uc704\ud574\uc11c\ub294 \ubc30\ub2f9 \uae30\uc900\uc77c \uc804\uc5d0 \uc8fc\uc2dd\uc744 \ubcf4\uc720\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uae08\uc735\uc9c0\uc8fc \uc2e4\uc801\uc740 \uc5ec\ub7ec \uacc4\uc5f4\uc0ac\uc758 \ud569\uc0b0 \uacb0\uacfc\uc774\uba70, \uc8fc\uc8fc\ud658\uc6d0\uc740 \uadf8 \uc2e4\uc801\uc744 \ub098\ub204\ub294 \uc57d\uc18d\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExejdoejBpNHRzc24wMTFjeWtkeDdyNmFoMWVlajg0N3ZoNmwxb3ZvbyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/Ifbl3BS14c725VUlpR/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"investment-journal-guide","metadata":{"permalink":"/blog/en/finance/investment-journal-guide","source":"@site/finance/2026-10-29-investment-journal-guide/index.mdx","title":"\ud22c\uc790 \uc77c\uc9c0 \uc4f0\ub294 \ubc95, \ub9e4\ub9e4 \uae30\ub85d\uacfc \ubcf5\uae30 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ud22c\uc790\uc77c\uc9c0","permalink":"/blog/en/finance/tags/\ud22c\uc790\uc77c\uc9c0"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"},{"inline":true,"label":"\ubcf5\uae30","permalink":"/blog/en/finance/tags/\ubcf5\uae30"}],"readingTime":2.41,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"investment-journal-guide","title":"\ud22c\uc790 \uc77c\uc9c0 \uc4f0\ub294 \ubc95, \ub9e4\ub9e4 \uae30\ub85d\uacfc \ubcf5\uae30 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","authors":["way"],"tags":["finance","\ud22c\uc790\uc77c\uc9c0","\uac1c\uc778\uc7ac\ubb34","\ubcf5\uae30"]},"unlisted":false,"prevItem":{"title":"\uae08\uc735\uc9c0\uc8fc\uc758 \uc0ac\uc5c5 \uad6c\uc870\uc640 \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc744 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/financial-holdings-shareholder-return"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 5,937.66 \ub9c8\uac10, 6,000\uc120\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub0b4\uc900 10\uc6d4 29\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-gives-back-6000-oct29"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ub9e4\ub9e4 \ud310\ub2e8\uc758 \uadfc\uac70\ub97c \ub0a8\uae30\ub294 \ud22c\uc790 \uc77c\uc9c0 \uc4f0\ub294 \ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 29\uc77c\ucc98\ub7fc \ud558\ub8e8 \ub9cc\uc5d0 \uc9c0\uc218 \ubc29\ud5a5\uc774 \ubc14\ub00c\ub294 \ub0a0\uc5d0\ub294, \ub9e4\ub9e4 \uc9c1\ud6c4\uc758 \uac10\uc815\uc774 \uae30\ub85d\uc744 \uc65c\uace1\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uae09\ub4f1\uc5d0 \ub530\ub77c \uc0c0\ub2e4\uac00 \ub2f9\uc77c \uc870\uc815\uc5d0 \ud314\uc558\ub2e4\uba74, \uadf8 \ud310\ub2e8\uc774 \uacc4\ud68d\uc5d0 \ub530\ub978 \uac83\uc778\uc9c0 \uac10\uc815\uc5d0 \ub530\ub978 \uac83\uc778\uc9c0 \uad6c\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ud22c\uc790 \uc77c\uc9c0\ub294 \uc218\uc775\ub960\uc744 \uc790\ub791\ud558\ub294 \uae30\ub85d\uc774 \uc544\ub2c8\ub77c, \ud310\ub2e8 \uadfc\uac70\ub97c \ub0a8\uaca8 \ub2e4\uc74c \ud310\ub2e8\uc744 \uac1c\uc120\ud558\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\uc9c0\ub97c \uc4f0\uc9c0 \uc54a\uc73c\uba74 \uac19\uc740 \uc2e4\uc218\ub97c \ubc18\ubcf5\ud574\ub3c4 \uc6d0\uc778\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExN3VkODBiYWs5ZzI1dGlqcWRkcm5leGk0eWI4MzNiMXcweGkzbWtxcyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/YWWeEeFThzFS6VKmyX/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc77c\uc9c0\uc5d0 \ub0a8\uae38 \ud56d\ubaa9\\n\\n\ud22c\uc790 \uc77c\uc9c0\ub294 \ub9e4\ub9e4 \uccb4\uacb0 \ub0b4\uc5ed\uc774 \uc544\ub2c8\ub77c \ud310\ub2e8 \uacfc\uc815\uc744 \uae30\ub85d\ud569\ub2c8\ub2e4.<br/>\\n\uc99d\uad8c\uc0ac \uc571\uc758 \uccb4\uacb0 \ub0b4\uc5ed\uc740 \uac00\uaca9\uacfc \uc218\ub7c9\ub9cc \ubcf4\uc5ec\uc8fc\uace0, \uc65c \uc0c0\ub294\uc9c0\ub294 \ubcf4\uc5ec\uc8fc\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n| \ud56d\ubaa9 | \uae30\ub85d \ub0b4\uc6a9 |\\n| --- | --- |\\n| \ub0a0\uc9dc\uc640 \uc2dc\uc7a5 \uc0c1\ud669 | \ub9e4\ub9e4 \ub2f9\uc2dc \uc9c0\uc218 \ud750\ub984\uacfc \uc8fc\uc694 \uc7ac\ub8cc |\\n| \ub9e4\ub9e4 \uc774\uc720 | \uc2e4\uc801, \ubc38\ub958\uc5d0\uc774\uc158, \ubd84\uc0b0 \ubaa9\uc801 \ub4f1 \ud310\ub2e8 \uadfc\uac70 |\\n| \uc9c4\uc785 \uae30\uc900 | \uc5b4\ub5a4 \uc870\uac74\uc774 \ucda9\uc871\ub3fc \ub9e4\uc218\ud588\ub294\uc9c0 |\\n| \uccad\uc0b0 \uae30\uc900 | \uc190\uc808 \uae30\uc900\uacfc \uc775\uc808 \uae30\uc900\uc744 \uc0ac\uc804\uc5d0 \uc815\ud588\ub294\uc9c0 |\\n| \ube44\uc911 | \uc804\uccb4 \uc790\uc0b0 \ub300\ube44 \ud574\ub2f9 \ud22c\uc790 \ube44\uc911 |\\n| \uac10\uc815 \uc0c1\ud0dc | \uc870\uae09\ud568, \ud655\uc2e0, \ubd88\uc548 \ub4f1 \ub2f9\uc2dc \uc2ec\ub9ac |\\n| \uacb0\uacfc\uc640 \ubcf5\uae30 | \uacc4\ud68d\ub300\ub85c \uc6c0\uc9c1\uc600\ub294\uc9c0, \ubb34\uc5c7\uc744 \ubc30\uc6e0\ub294\uc9c0 |\\n\\n\ube44\uc911\uc740 \ubc18\ub4dc\uc2dc \ud568\uaed8 \uc801\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ud310\ub2e8\uc774\ub77c\ub3c4 \ube44\uc911\uc774 5%\uc77c \ub54c\uc640 30%\uc77c \ub54c\ub294 \uacb0\uacfc\uac00 \uc804\ud600 \ub2e4\ub974\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uac10\uc815 \uc0c1\ud0dc\ub3c4 \ud568\uaed8 \uc801\uc2b5\ub2c8\ub2e4.<br/>\\n\uc870\uae09\ud560 \ub54c \ud55c \ub9e4\ub9e4\uc640 \ucc28\ubd84\ud560 \ub54c \ud55c \ub9e4\ub9e4\ub294 \uac19\uc740 \uc2e4\uc218\ub77c\ub3c4 \uc6d0\uc778\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\\n#### \ubcf5\uae30 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\\n\\n\ubcf5\uae30\ub294 \ub9e4\ub9e4 \uc9c1\ud6c4\uac00 \uc544\ub2c8\ub77c \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub09c \ub4a4\uc5d0 \ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c1\ud6c4 \ubcf5\uae30\ub294 \uacb0\uacfc\uc5d0 \ub530\ub77c \ud310\ub2e8 \uc790\uccb4\ub97c \ubbf8\ud654\ud558\uac70\ub098 \ud3c4\ud558\ud558\uae30 \uc27d\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc8fc\uac04 \ubcf5\uae30\\n\\n\uc8fc\uac04 \ubcf5\uae30\uc5d0\uc11c\ub294 \uc774\ubc88 \uc8fc \ub9e4\ub9e4\uac00 \uc0ac\uc804 \uacc4\ud68d\uc5d0 \ub530\ub978 \uac83\uc778\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uacc4\ud68d \uc5c6\uc774 \ud55c \ub9e4\ub9e4\uac00 \uba87 \uac74\uc778\uc9c0 \uc138\uc5b4\ubd05\ub2c8\ub2e4.<br/>\\n\uacc4\ud68d \uc5c6\ub294 \ub9e4\ub9e4\uac00 \ubc18\ubcf5\ub41c\ub2e4\uba74, \uc9c4\uc785 \uae30\uc900 \uc790\uccb4\uac00 \ub290\uc2a8\ud55c \uac83\uc778\uc9c0 \uc810\uac80\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc6d4\uac04 \ubcf5\uae30\\n\\n\uc6d4\uac04 \ubcf5\uae30\uc5d0\uc11c\ub294 \uc218\uc775\ub960\ubcf4\ub2e4 \ud310\ub2e8\uc758 \uc9c8\uc744 \uc810\uac80\ud569\ub2c8\ub2e4.<br/>\\n\uc190\uc2e4\uc774 \ub09c \ub9e4\ub9e4 \uc911 \uacc4\ud68d\ub300\ub85c \uc190\uc808\ud55c \uacbd\uc6b0\uc640 \uacc4\ud68d \uc5c6\uc774 \ubc84\ud2f4 \uacbd\uc6b0\ub97c \uad6c\ubd84\ud569\ub2c8\ub2e4.<br/>\\n\uacc4\ud68d\ub300\ub85c \uc190\uc808\ud55c \uc190\uc2e4\uc740 \uc2dc\uc2a4\ud15c \ube44\uc6a9\uc73c\ub85c \ubcf4\uace0, \uacc4\ud68d \uc5c6\uc774 \ubc84\ud2f4 \uc190\uc2e4\uc740 \uac1c\uc120 \ub300\uc0c1\uc73c\ub85c \ubd05\ub2c8\ub2e4.<br/>\\n\uc774\uc775\uc774 \ub09c \ub9e4\ub9e4\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uc6b4\uc73c\ub85c \ub09c \uc774\uc775\uacfc \uacc4\ud68d\ub300\ub85c \ub09c \uc774\uc775\uc740 \ub2e4\uc74c \ud310\ub2e8\uc5d0 \uc8fc\ub294 \uad50\ud6c8\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\\n#### \uc77c\uc9c0 \uc791\uc131 \uc2b5\uad00\\n\\n\uccab\uc9f8, \ub9e4\ub9e4 \ub2f9\uc77c\uc5d0 5\ubd84 \uc548\uc5d0 \uc774\uc720\ub97c \uc801\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uc774\uc720\ub294 \uacb0\uacfc\uc5d0 \ub9de\ucdb0 \ub2e4\uc2dc \uc4f0\uc774\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc77c\uc9c0\ub294 \uacf5\uac1c\ud558\uc9c0 \uc54a\ub294 \uac1c\uc778 \uae30\ub85d\uc73c\ub85c \ub461\ub2c8\ub2e4.<br/>\\n\ud0c0\uc778\uc758 \ud3c9\uac00\ub97c \uc758\uc2dd\ud558\uba74 \uc194\uc9c1\ud55c \uae30\ub85d\uc774 \uc5b4\ub824\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc77c\uc9c0 \uc591\uc2dd\uc740 \ub2e8\uc21c\ud558\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4.<br/>\\n\ud56d\ubaa9\uc774 \ub108\ubb34 \ub9ce\uc73c\uba74 \uba70\uce60 \ub9cc\uc5d0 \uc791\uc131\uc774 \uc911\ub2e8\ub429\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc6d4 1\ud68c \uc77c\uc9c0\ub97c \ub2e4\uc2dc \uc77d\uace0 \ubc18\ubcf5\ub418\ub294 \uc2e4\uc218 \ud55c \uac00\uc9c0\ub9cc \uace8\ub77c \ub2e4\uc74c \ub2ec \uaddc\uce59\uc73c\ub85c \uc815\ud569\ub2c8\ub2e4.<br/>\\n\ud55c \ubc88\uc5d0 \uc5ec\ub7ec \uac00\uc9c0\ub97c \uace0\uce58\ub824 \ud558\uba74 \uc5b4\ub290 \uac83\ub3c4 \uace0\uccd0\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\ud22c\uc790 \uc77c\uc9c0\ub294 \uacfc\uac70\ub97c \uc815\ub9ac\ud558\ub294 \uae30\ub85d\uc774 \uc544\ub2c8\ub77c \ub2e4\uc74c \ud310\ub2e8\uc744 \uac1c\uc120\ud558\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExN3VkODBiYWs5ZzI1dGlqcWRkcm5leGk0eWI4MzNiMXcweGkzbWtxcyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/dQpUkK59l5Imxsh8jN/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-gives-back-6000-oct29","metadata":{"permalink":"/blog/en/finance/kospi-gives-back-6000-oct29","source":"@site/finance/2026-10-29-kospi-gives-back-6000-oct29/index.mdx","title":"\ucf54\uc2a4\ud53c 5,937.66 \ub9c8\uac10, 6,000\uc120\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub0b4\uc900 10\uc6d4 29\uc77c \uc2dc\uc7a5 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ub2e5"}],"readingTime":2.04,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-gives-back-6000-oct29","title":"\ucf54\uc2a4\ud53c 5,937.66 \ub9c8\uac10, 6,000\uc120\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub0b4\uc900 10\uc6d4 29\uc77c \uc2dc\uc7a5 \uc815\ub9ac","authors":["way"],"tags":["finance","\ucf54\uc2a4\ud53c","\uc2dc\uc7a5\uc815\ub9ac","\ucf54\uc2a4\ub2e5"]},"unlisted":false,"prevItem":{"title":"\ud22c\uc790 \uc77c\uc9c0 \uc4f0\ub294 \ubc95, \ub9e4\ub9e4 \uae30\ub85d\uacfc \ubcf5\uae30 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","permalink":"/blog/en/finance/investment-journal-guide"},"nextItem":{"title":"\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc640 \uc218\uae09 \uc9c0\ud45c, \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/program-trading-flow-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ucf54\uc2a4\ud53c\uac00 6,000\uc120\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub0b4\uc900 10\uc6d4 29\uc77c \uc2dc\uc7a5\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc804\uc77c \ucf54\uc2a4\ud53c\ub294 6.63% \uae09\ub4f1\ud558\uba70 6,012.44\uc5d0 \ub9c8\uac10\ud588\uace0, 6,000\uc120\uc744 \ud68c\ubcf5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n29\uc77c \uc9c0\uc218\ub294 6,017.22\ub85c \uac15\ubcf4\ud569 \ucd9c\ubc1c\ud574 \uc7a5 \ucd08\ubc18 6,100.11\uae4c\uc9c0 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uc758 \uc2e4\uc801 \ubc1c\ud45c\ub97c \uc804\ud6c4\ub85c \ud558\ub77d \uc804\ud658\ud588\uace0, \uc624\uc804 \ud55c\ub54c 5,817.92\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\uac00 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.75~4.00%\ub85c \ub3d9\uacb0\ud55c \uc810\uc740 \uc7a5 \ucd08\ubc18 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \uc7ac\ub8cc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7fc\uc5d0\ub3c4 \uc8fc\uc8fc\ud658\uc6d0 \uc138\ubd80\uc548\uc5d0 \ub300\ud55c \ubd88\ud655\uc2e4\uc131\uc774 \ubd80\uac01\ub418\uba70 \ud22c\uc790 \uc2ec\ub9ac\uac00 \uaebe\uc600\ub2e4\ub294 \ubd84\uc11d\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \ub9c8\uac10 \ud750\ub984\uc740 [\ud55c\uad6d\uacbd\uc81c \ubcf4\ub3c4](https://www.hankyung.com/article/2026102939116)\uc640 [EBN \ubcf4\ub3c4](https://www.ebn.co.kr/news/articleView.html?idxno=1729739)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ2FhYXowNjRwcmY5ZjZnd3c2c2ludmttbjBoNm5ndnU4Z3pzcHI4bCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1NWhyf9vsi90HWGaBb/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc624\ub298\uc758 \uc9c0\uc218\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub9c8\uac10 \uc9c0\uc218\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 |\\n| --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,937.66 | 74.78 \ud558\ub77d | 1.24% |\\n| \ucf54\uc2a4\ub2e5 | 753.23 | 18.05 \ud558\ub77d | 2.34% |\\n| \ucf54\uc2a4\ud53c200 | 935.87 | 10.53 \ud558\ub77d | 1.11% |\\n| \uc6d0\ub2ec\ub7ec \ud658\uc728 | 1,338.00\uc6d0 | 4.00\uc6d0 \ud558\ub77d | 0.30% |\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\ucd08 6,017.22\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 6,100.11\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc885\uac00\ub294 5,937.66\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 767.78\ub85c \ucd9c\ubc1c\ud574 753.23\uc5d0 \ub9c8\uac10\ud588\uace0, \ub099\ud3ed\uc774 \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09\uc744 \ubcf4\uba74 \ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uae30\uad00\uc774 4,472\uc5b5 \uc6d0 \uc21c\ub9e4\ub3c4\ud588\uace0, \uc678\uad6d\uc778\uacfc \uac1c\uc778\uc740 \uac01\uac01 762\uc5b5 \uc6d0\uacfc 327\uc5b5 \uc6d0 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub294 \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798\ub97c \ud569\uccd0 \uc57d 1,180\uc5b5 \uc6d0 \uc21c\ub9e4\uc218\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9\uc5d0\uc11c\ub294 \uc0bc\uc131\uc804\uc790\uac00 4.13% \ud558\ub77d\ud55c 232,000\uc6d0\uc5d0 \ub9c8\uac10\ud588\uace0, SK\ud558\uc774\ub2c9\uc2a4\ub294 2.62% \uc0c1\uc2b9\ud55c 1,526,000\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc \uc548\uc5d0\uc11c\ub3c4 \uc8fc\uc8fc\ud658\uc6d0 \uc138\ubd80\uc548\uc5d0 \ub300\ud55c \ud574\uc11d\uc774 \uc5c7\uac08\ub9ac\uba70 \uc8fc\uac00 \ubc29\ud5a5\uc774 \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud655\uc778\ud560 \uc9c0\ud45c\\n\\n\uccab\uc9f8, 6,000\uc120 \uc544\ub798\uc5d0\uc11c \uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc218\uae09 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uc758 \uc8fc\uc8fc\ud658\uc6d0 \uc138\ubd80\uc548\uc774 \ucd94\uac00\ub85c \uacf5\uac1c\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc138\ubd80\uc548\uc774 \uad6c\uccb4\ud654\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uae30\ub300\uc640 \uc2e4\ub9dd\uc774 \ubc88\uac08\uc544 \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc6d0\ub2ec\ub7ec \ud658\uc728\uc774 1,330\uc6d0\ub300\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ud558\ub8e8\uc758 \uae09\ub4f1 \ub4a4\uc5d0 \ucc3e\uc544\uc628 \uc870\uc815\uc740 \ubc29\ud5a5 \uc804\ud658\uc77c \uc218\ub3c4 \uc788\uace0, \ubcc0\ub3d9\uc131 \ud655\ub300 \uad6d\uba74\uc758 \uc77c\ubd80\uc77c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc22b\uc790 \ud558\ub098\ub9cc\uc73c\ub85c \ub2e4\uc74c \ubc29\ud5a5\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0, \uc218\uae09\uacfc \uc7ac\ub8cc\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n10\uc6d4 29\uc77c\uc740 \uc804\uc77c\uc758 \uae09\ub4f1\ubd84\uc744 \uc77c\ubd80 \ubc18\ub0a9\ud558\uba70 6,000\uc120\uc744 \ub0b4\uc900 \ub0a0\ub85c \uae30\ub85d\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNDBrNXQwMG9wM3luaDk2b2hoeng4bmZjbHRqMTNrcXZlazZuN3RyciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/Um4xbb9aZQ5dSvC5au/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"program-trading-flow-guide","metadata":{"permalink":"/blog/en/finance/program-trading-flow-guide","source":"@site/finance/2026-10-29-program-trading-flow-guide/index.mdx","title":"\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc640 \uc218\uae09 \uc9c0\ud45c, \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798 \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ud504\ub85c\uadf8\ub7a8\ub9e4\ub9e4","permalink":"/blog/en/finance/tags/\ud504\ub85c\uadf8\ub7a8\ub9e4\ub9e4"},{"inline":true,"label":"\uc218\uae09","permalink":"/blog/en/finance/tags/\uc218\uae09"},{"inline":true,"label":"\ucc28\uc775\uac70\ub798","permalink":"/blog/en/finance/tags/\ucc28\uc775\uac70\ub798"}],"readingTime":2.5,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"program-trading-flow-guide","title":"\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc640 \uc218\uae09 \uc9c0\ud45c, \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798 \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","\ud504\ub85c\uadf8\ub7a8\ub9e4\ub9e4","\uc218\uae09","\ucc28\uc775\uac70\ub798"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 5,937.66 \ub9c8\uac10, 6,000\uc120\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub0b4\uc900 10\uc6d4 29\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-gives-back-6000-oct29"},"nextItem":{"title":"HBM \uace0\ub300\uc5ed\ud3ed\uba54\ubaa8\ub9ac \uad6c\uc870\uc640 \ubc38\ub958\uccb4\uc778 \ud574\uc124","permalink":"/blog/en/finance/hbm-structure-value-chain"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc640 \ud22c\uc790 \uc8fc\uccb4\ubcc4 \uc218\uae09 \uc9c0\ud45c\ub97c \uc77d\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 29\uc77c \ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uae30\uad00\uc774 4,472\uc5b5 \uc6d0 \uc21c\ub9e4\ub3c4\ud588\uace0, \uc678\uad6d\uc778\uacfc \uac1c\uc778\uc740 \uac01\uac01 762\uc5b5 \uc6d0\uacfc 327\uc5b5 \uc6d0 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub294 \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798\ub97c \ud569\uccd0 \uc57d 1,180\uc5b5 \uc6d0 \uc21c\ub9e4\uc218\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \ud558\ub77d\ud55c \ub0a0\uc5d0\ub3c4 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uac00 \uc21c\ub9e4\uc218\uc600\ub2e4\ub294 \uc810\uc740, \uc218\uae09 \uc9c0\ud45c\ub97c \ud558\ub098\ub85c\ub9cc \ubcf4\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4\ub294 \uc0ac\ub840\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uc218\uce58\ub294 \uc9d1\uacc4 \uae30\uc900\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \ubcf4\ub3c4\ub9c8\ub2e4 \uae30\uad00\uacfc \uc678\uad6d\uc778 \uc21c\ub9e4\uc218 \uaddc\ubaa8\uac00 \ub2e4\ub974\uac8c \ub098\uc628 \uac83\uc740, \ud55c\uad6d\uac70\ub798\uc18c \ub2e8\ub3c5 \uc9d1\uacc4\uc640 \ub125\uc2a4\ud2b8\ub808\uc774\ub4dc \ud569\uc0b0 \uc9d1\uacc4\uc758 \ucc28\uc774 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ2FhYXowNjRwcmY5ZjZnd3c2c2ludmttbjBoNm5ndnU4Z3pzcHI4bCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/BGgtEk3v62kD6oUJen/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub780 \ubb34\uc5c7\uc778\uac00\\n\\n\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub294 \ucef4\ud4e8\ud130 \ud504\ub85c\uadf8\ub7a8\uc774 \uc815\ud574\uc9c4 \uaddc\uce59\uc5d0 \ub530\ub77c \uc5ec\ub7ec \uc885\ubaa9\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc0ac\uace0\ud30c\ub294 \uac70\ub798\uc785\ub2c8\ub2e4.<br/>\\n\uc0ac\ub78c\uc774 \uc885\ubaa9 \ud558\ub098\uc529 \uc8fc\ubb38\ud558\ub294 \ubc29\uc2dd\uacfc \ub2ec\ub9ac, \ubc14\uc2a4\ucf13 \ub2e8\uc704\ub85c \uc8fc\ubb38\uc774 \ub098\uac00\uae30 \ub54c\ubb38\uc5d0 \uaddc\ubaa8\uac00 \ud07d\ub2c8\ub2e4.<br/>\\n\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub294 \ud06c\uac8c \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\\n#### \ucc28\uc775\uac70\ub798\\n\\n\ucc28\uc775\uac70\ub798\ub294 \uc120\ubb3c \uac00\uaca9\uacfc \ud604\ubb3c \uac00\uaca9\uc758 \ucc28\uc774, \uc989 \ubca0\uc774\uc2dc\uc2a4\ub97c \uc774\uc6a9\ud558\ub294 \uac70\ub798\uc785\ub2c8\ub2e4.<br/>\\n\uc120\ubb3c\uc774 \ud604\ubb3c\ubcf4\ub2e4 \ube44\uc2f8\uba74 \ud604\ubb3c\uc744 \uc0ac\uace0 \uc120\ubb3c\uc744 \ud314\uace0, \ubc18\ub300\uc774\uba74 \ud604\ubb3c\uc744 \ud314\uace0 \uc120\ubb3c\uc744 \uc0bd\ub2c8\ub2e4.<br/>\\n\uac00\uaca9 \ucc28\uc774\uac00 \uc815\uc0c1 \uc218\uc900\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \ub450 \ud3ec\uc9c0\uc158\uc744 \uccad\uc0b0\ud574 \ucc28\uc775\uc744 \ud655\uc815\ud569\ub2c8\ub2e4.<br/>\\n\ucc28\uc775\uac70\ub798 \ub9e4\ub9e4\ub294 \uc120\ubb3c\uacfc \ud604\ubb3c \uc0ac\uc774\uc758 \uac00\uaca9 \uad00\uacc4\uc5d0 \ub530\ub77c \uae30\uacc4\uc801\uc73c\ub85c \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ucc28\uc775\uac70\ub798 \uc21c\ub9e4\uc218\uac00 \uc9c0\uc218 \ubc29\ud5a5\uc5d0 \ub300\ud55c \ud310\ub2e8\uc774\ub77c\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ube44\ucc28\uc775\uac70\ub798\\n\\n\ube44\ucc28\uc775\uac70\ub798\ub294 \uc120\ubb3c\uacfc\uc758 \uac00\uaca9 \ucc28\uc774\ub97c \uc774\uc6a9\ud558\uc9c0 \uc54a\ub294 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucd94\uc885, \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc870\uc815, \uc790\uc0b0\ubc30\ubd84 \ubcc0\uacbd \ub4f1\uc774 \uc5ec\uae30\uc5d0 \ud3ec\ud568\ub429\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc774 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ube44\uc911\uc744 \uc870\uc815\ud560 \ub54c \ube44\ucc28\uc775\uac70\ub798\uac00 \ud06c\uac8c \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\ucc28\uc775\uac70\ub798\ub294 \ucc28\uc775\uac70\ub798\ubcf4\ub2e4 \ud22c\uc790 \ud310\ub2e8\uc5d0 \uac00\uae5d\uc9c0\ub9cc, \uc5ed\uc2dc \ud558\ub8e8 \uc218\uce58\ub9cc\uc73c\ub85c \uc758\ub3c4\ub97c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uad6c\ubd84 | \uac70\ub798 \ub3d9\uae30 | \ud574\uc11d \uc2dc \uc8fc\uc758\uc810 |\\n| --- | --- | --- |\\n| \ucc28\uc775\uac70\ub798 | \uc120\ubb3c\uacfc \ud604\ubb3c \uac00\uaca9 \ucc28\uc774 | \uae30\uacc4\uc801 \uac70\ub798\ub77c \ubc29\ud5a5 \ud310\ub2e8\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6c0 |\\n| \ube44\ucc28\uc775\uac70\ub798 | \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc870\uc815, \uc9c0\uc218 \ucd94\uc885 | \uaddc\ubaa8\ub294 \ucc38\uace0\ud558\ub418 \uc758\ub3c4 \ub2e8\uc815\uc740 \uae08\ubb3c |\\n\\n#### \ud22c\uc790 \uc8fc\uccb4\ubcc4 \uc218\uae09 \uc77d\ub294 \ubc95\\n\\n\ud22c\uc790 \uc8fc\uccb4\ub294 \uac1c\uc778, \uc678\uad6d\uc778, \uae30\uad00, \uae30\ud0c0\ubc95\uc778\uc73c\ub85c \uad6c\ubd84\ud574 \ubc1c\ud45c\ub429\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \uc218\uae09\uc740 \ud658\uc728\uacfc \uae00\ub85c\ubc8c \uc790\uae08 \ud750\ub984\uacfc \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \uc218\uae09\uc740 \uc5f0\uae30\uae08, \uc790\uc0b0\uc6b4\uc6a9\uc0ac, \ubcf4\ud5d8\uc0ac \ub4f1 \uc131\uaca9\uc774 \ub2e4\ub978 \uc8fc\uccb4\uc758 \ud569\uc0b0\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uae30\uad00\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc778 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uac1c\uc778 \uc218\uae09\uc740 \ubc18\ub300\ub9e4\ub9e4\ub098 \uc2e0\uc6a9\uac70\ub798\uc640 \ud568\uaed8 \ubcf4\uba74 \ub9e5\ub77d\uc774 \ub354 \uc798 \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\ud558\ub8e8\uc758 \uc218\uae09\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ucc38\uace0 \uc790\ub8cc\uc774\uba70, \ucd94\uc138\ub294 \uc5ec\ub7ec \ub0a0\uc758 \ub204\uc801 \uc218\uae09\uc73c\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub97c \ubcfc \ub54c\ub294 \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798\ub97c \ubd84\ub9ac\ud574\uc11c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc218\uae09 \uc218\uce58\uc758 \uc9d1\uacc4 \uae30\uc900\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uac70\ub798\uc18c \ub2e8\ub3c5 \uc218\uce58\uc640 \ubcf5\uc218 \uac70\ub798\uc2dc\uc7a5 \ud569\uc0b0 \uc218\uce58\ub294 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc218\uae09\uacfc \uc9c0\uc218 \ubc29\ud5a5\uc774 \uc5b4\uae0b\ub098\ub294 \ub0a0\uc5d0\ub294 \uc120\ubb3c \ubca0\uc774\uc2dc\uc2a4\uc640 \uc7a5\uc911 \ud750\ub984\uc744 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ud558\ub8e8\uc758 \uc21c\ub9e4\uc218 \uaddc\ubaa8\ub97c \uc808\ub300\uac12\uc774 \uc544\ub2c8\ub77c \ucd5c\uadfc \ud3c9\uade0 \uac70\ub798\ub300\uae08\uacfc \ube44\uad50\ud569\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub300\uae08 \ub300\ube44 \uc791\uc740 \uaddc\ubaa8\uc758 \uc218\uae09\uc740 \uc9c0\uc218 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \ud798\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc640 \uc218\uae09 \uc9c0\ud45c\ub294 \uc2dc\uc7a5\uc758 \ud798\uc744 \uac00\ub2a0\ud558\ub294 \ucc38\uace0 \uc790\ub8cc\uc774\uba70, \ubc29\ud5a5\uc744 \ub2e8\uc815\ud558\ub294 \uc2e0\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ2FhYXowNjRwcmY5ZjZnd3c2c2ludmttbjBoNm5ndnU4Z3pzcHI4bCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/M4RxfLCjCskZcrZ5Ov/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"hbm-structure-value-chain","metadata":{"permalink":"/blog/en/finance/hbm-structure-value-chain","source":"@site/finance/2026-10-28-hbm-structure-value-chain/index.mdx","title":"HBM \uace0\ub300\uc5ed\ud3ed\uba54\ubaa8\ub9ac \uad6c\uc870\uc640 \ubc38\ub958\uccb4\uc778 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-28T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"HBM","permalink":"/blog/en/finance/tags/hbm"},{"inline":true,"label":"\ubc18\ub3c4\uccb4","permalink":"/blog/en/finance/tags/\ubc18\ub3c4\uccb4"},{"inline":true,"label":"AI","permalink":"/blog/en/finance/tags/ai"}],"readingTime":2.6,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"hbm-structure-value-chain","title":"HBM \uace0\ub300\uc5ed\ud3ed\uba54\ubaa8\ub9ac \uad6c\uc870\uc640 \ubc38\ub958\uccb4\uc778 \ud574\uc124","authors":["way"],"tags":["finance","HBM","\ubc18\ub3c4\uccb4","AI"]},"unlisted":false,"prevItem":{"title":"\ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc640 \uc218\uae09 \uc9c0\ud45c, \ucc28\uc775\uac70\ub798\uc640 \ube44\ucc28\uc775\uac70\ub798 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/program-trading-flow-guide"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 6,012.44 \ub9c8\uac10, 6,000\uc120 \ud68c\ubcf5\ud55c 10\uc6d4 28\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-6000-recovery-oct28"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc778\uacf5\uc9c0\ub2a5 \uac00\uc18d\uae30\uc758 \ud575\uc2ec \ubd80\ud488\uc73c\ub85c \uc5b8\uae09\ub418\ub294 HBM\uc758 \uad6c\uc870\uc640 \ubc38\ub958\uccb4\uc778\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc778\uacf5\uc9c0\ub2a5 \ubaa8\ub378\uc774 \ucee4\uc9c0\uba74\uc11c \uc5f0\uc0b0 \uc7a5\uce58\ub9cc \ube68\ub77c\uc838\uc11c\ub294 \uc804\uccb4 \uc18d\ub3c4\uac00 \uc62c\ub77c\uac00\uc9c0 \uc54a\ub294 \uad6c\uac04\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa8\ub378\uc758 \uac00\uc911\uce58\uc640 \uc911\uac04 \uacc4\uc0b0 \uacb0\uacfc\ub97c \uba54\ubaa8\ub9ac\uc5d0\uc11c \uc5f0\uc0b0 \uc7a5\uce58\ub85c \uc5bc\ub9c8\ub098 \ube68\ub9ac \uac00\uc838\uc624\ub290\ub0d0\uac00 \ubcd1\ubaa9\uc774 \ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\nHBM\uc740 \uc774 \ubcd1\ubaa9\uc744 \uc904\uc774\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 \uba54\ubaa8\ub9ac \uad6c\uc870\uc774\uba70, 10\uc6d4 28\uc77c \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900 HBM \ud14c\ub9c8\ub294 8.29% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud14c\ub9c8 \uc0c1\uc2b9\ub960\uc740 \ud558\ub8e8\uc758 \uc2dc\uc7a5 \ubd84\uc704\uae30\ub97c \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70, \uae30\uc220 \uad6c\uc870\ub97c \uc774\ud574\ud558\ub294 \uac83\uacfc \ud22c\uc790 \ud310\ub2e8\uc744 \ub0b4\ub9ac\ub294 \uac83\uc740 \ubcc4\uac1c\uc758 \uc77c\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHh4ejI2c3JucXRuemltZW5vd3c2NWd3NXByM3B0MDV6Z3ZvdWFheCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/fapvHdWzoHtYY/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### HBM\uc774\ub780 \ubb34\uc5c7\uc778\uac00\\n\\nHBM\uc740 \uace0\ub300\uc5ed\ud3ed\uba54\ubaa8\ub9ac\uc758 \uc904\uc784\ub9d0\uc774\uba70, \uc5ec\ub7ec \uc7a5\uc758 D\ub7a8\uc744 \uc218\uc9c1\uc73c\ub85c \uc313\uc740 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18 \uba54\ubaa8\ub9ac\uac00 \uae30\ud310 \uc704\uc5d0 \ud3bc\uccd0\uc838 \uc788\ub294 \ud615\ud0dc\ub77c\uba74, HBM\uc740 \uce35\uc744 \uc313\uc544 \uc881\uc740 \uba74\uc801\uc5d0 \uc6a9\ub7c9\uc744 \ub123\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\uc313\uc778 \uba54\ubaa8\ub9ac\uc640 \uc5f0\uc0b0 \uc7a5\uce58\ub294 \uc778\ud130\ud3ec\uc800\ub77c\ub294 \uc911\uac04 \uae30\ud310 \uc704\uc5d0 \ub098\ub780\ud788 \ubc30\uce58\ub418\uba70, \uc9e7\uace0 \ub113\uc740 \ud1b5\ub85c\ub85c \uc5f0\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uc870\uc5d0 \ub300\ud55c \uac1c\uc694\ub294 [\uc0bc\uc131\uc804\uc790 \ubc18\ub3c4\uccb4 \uae30\uc220 \ube14\ub85c\uadf8](https://semiconductor.samsung.com/news-events/tech-blog/part-1-the-evolution-of-ai-and-ai-chips-and-the-hbm-that-powers-them/)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc801\uce35\uacfc TSV\uac00 \ub9cc\ub4dc\ub294 \ucc28\uc774\\n\\n\uc5ec\ub7ec \uc7a5\uc758 D\ub7a8\uc744 \uc5f0\uacb0\ud558\ub294 \ud575\uc2ec \uae30\uc220\uc740 TSV\uc785\ub2c8\ub2e4.<br/>\\nTSV\ub294 \uc2e4\ub9ac\ucf58\uc744 \uad00\ud1b5\ud558\ub294 \uc218\uc9c1 \ubc30\uc120\uc774\uba70, \uce35\uacfc \uce35 \uc0ac\uc774\ub97c \uc9c1\uc811 \uc5f0\uacb0\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\uc120\uc774 \uc9e7\uc544\uc9c0\uba74 \uc2e0\ud638\uac00 \uc774\ub3d9\ud558\ub294 \uac70\ub9ac\ub3c4 \uc9e7\uc544\uc9c0\uace0, \ub113\uc740 \uc785\ucd9c\ub825 \ud1b5\ub85c\ub97c \ud568\uaed8 \uc4f0\uba74 \ud55c \ubc88\uc5d0 \ub9ce\uc740 \ub370\uc774\ud130\ub97c \uc62e\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nHBM4 \ud45c\uc900\uc5d0\uc11c\ub294 \uc2a4\ud0dd\ub2f9 2,048\ube44\ud2b8 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uc0ac\uc6a9\ud558\uba70, \uc2a4\ud0dd\ub2f9 \ucd5c\ub300 2TB \uc218\uc900\uc758 \ub300\uc5ed\ud3ed\uc774 \uc81c\uc2dc\ub429\ub2c8\ub2e4.<br/>\\n\ub300\uc5ed\ud3ed\uc774 \ub113\uc5b4\uc9c4\ub2e4\ub294 \uac83\uc740 \uc18d\ub3c4 \uc790\uccb4\uac00 \ube68\ub77c\uc9c4\ub2e4\ub294 \uc758\ubbf8\uc640 \ud568\uaed8, \ub2e8\uc704 \uc2dc\uac04\uc5d0 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \ub370\uc774\ud130\ub7c9\uc774 \ucee4\uc9c4\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ubc38\ub958\uccb4\uc778 \ub2e8\uacc4\ubcc4 \uc5ed\ud560\\n\\nHBM\uc758 \ubc38\ub958\uccb4\uc778\uc740 \ud06c\uac8c \ub2e4\uc12f \ub2e8\uacc4\ub85c \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ub2e8\uacc4 | \uc5ed\ud560 | \ud655\uc778\ud560 \uc810 |\\n| --- | --- | --- |\\n| \uba54\ubaa8\ub9ac \uc124\uacc4\uc640 \uc81c\uc870 | D\ub7a8 \uc140\uacfc \uc801\uce35\uc6a9 \ub2e4\uc774\ub97c \ub9cc\ub4e0\ub2e4 | \uacf5\uc815 \uc218\uc728\uacfc \uc138\ub300 \uc804\ud658 \uc18d\ub3c4 |\\n| \uc801\uce35\uacfc \ubcf8\ub529 | TSV\ub85c \ub2e4\uc774\ub97c \uc5f0\uacb0\ud558\uace0 \uc313\ub294\ub2e4 | \uc218\uc728\uacfc \ubc1c\uc5f4 \uad00\ub9ac |\\n| \ud328\ud0a4\uc9d5\uacfc \uc778\ud130\ud3ec\uc800 | \uc5f0\uc0b0 \uc7a5\uce58\uc640 \uba54\ubaa8\ub9ac\ub97c \ud55c \ud328\ud0a4\uc9c0\ub85c \ubb36\ub294\ub2e4 | \ud328\ud0a4\uc9d5 \uc218\uc728\uacfc \uacf5\uae09 \ub2a5\ub825 |\\n| \ud14c\uc2a4\ud2b8\uc640 \uac80\uc99d | \uc801\uce35 \uc81c\ud488\uc758 \ub3d9\uc791\uacfc \uc2e0\ub8b0\uc131\uc744 \ud655\uc778\ud55c\ub2e4 | \uace0\uac1d\uc0ac \uac80\uc99d \ud1b5\uacfc \uc5ec\ubd80 |\\n| \uc218\uc694\ucc98 | \uc778\uacf5\uc9c0\ub2a5 \uac00\uc18d\uae30\uc640 \uc11c\ubc84\uc5d0 \ud0d1\uc7ac\ub41c\ub2e4 | \uc218\uc694 \uc9c0\uc18d\uc131\uacfc \uc7ac\uace0 \uc218\uc900 |\\n\\n\uac01 \ub2e8\uacc4\ub294 \uc11c\ub85c \ub2e4\ub978 \uae30\uc220 \ub09c\uc774\ub3c4\uc640 \uacf5\uae09 \uad6c\uc870\ub97c \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ud55c \ub2e8\uacc4\uc758 \ubcd1\ubaa9\uc774 \uc804\uccb4 \uacf5\uae09\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc73c\uba70, \ubc18\ub300\ub85c \uc5b4\ub290 \ud55c \ub2e8\uacc4\uc758 \uac1c\uc120\ub9cc\uc73c\ub85c \uc804\uccb4 \uc2dc\uc7a5\uc774 \ubc14\ub00c\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc138\ub300 \uc804\ud658 \uc77c\uc815\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\nHBM \uc138\ub300\uac00 \ubc14\ub00c\uba74 \uace0\uac1d\uc0ac \uac80\uc99d\uacfc \uc591\uc0b0 \uc77c\uc815\uc774 \ub2e4\uc2dc \uc870\uc815\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc218\uc728\uacfc \uacf5\uae09 \ub2a5\ub825\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc801\uce35 \uad6c\uc870\ub294 \uacf5\uc815\uc774 \ubcf5\uc7a1\ud558\uae30 \ub54c\ubb38\uc5d0 \uc218\uc728\uc774 \uacf5\uae09\ub7c9\uc744 \uc88c\uc6b0\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uba54\ubaa8\ub9ac \uc0ac\uc774\ud074\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uacf5\uae09\uc774 \uc218\uc694\ub97c \ub530\ub77c\uc7a1\uc73c\uba74 \uac00\uaca9\uacfc \uc774\uc775\ub960\uc774 \ud568\uaed8 \uc870\uc815\ub418\ub294 \uad6d\uba74\uc774 \uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ud2b9\uc815 \uae30\uc5c5\uc774\ub098 \uc81c\ud488\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uc544\ub2c8\ub77c, \ubc38\ub958\uccb4\uc778 \uc804\uccb4\uc758 \uacf5\uae09\uacfc \uc218\uc694 \uade0\ud615\uc744 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\nHBM\uc740 \ub113\uc740 \ud1b5\ub85c\uc640 \uc9e7\uc740 \uac70\ub9ac\ub77c\ub294 \ub2e8\uc21c\ud55c \uc6d0\ub9ac\ub85c \uc778\uacf5\uc9c0\ub2a5 \uac00\uc18d\uae30\uc758 \ubcd1\ubaa9\uc744 \uc904\uc774\ub294 \uae30\uc220\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdHl1b3o4eW0wYzE1ZzQ3djBrZnVpY3Joa25seXU1eGR4Yjd2dmFxYyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/mi6DsSSNKDbUY/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-6000-recovery-oct28","metadata":{"permalink":"/blog/en/finance/kospi-6000-recovery-oct28","source":"@site/finance/2026-10-28-kospi-6000-recovery-oct28/index.mdx","title":"\ucf54\uc2a4\ud53c 6,012.44 \ub9c8\uac10, 6,000\uc120 \ud68c\ubcf5\ud55c 10\uc6d4 28\uc77c \uc2dc\uc7a5 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-28T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ubc18\ub3c4\uccb4","permalink":"/blog/en/finance/tags/\ubc18\ub3c4\uccb4"}],"readingTime":2.19,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-6000-recovery-oct28","title":"\ucf54\uc2a4\ud53c 6,012.44 \ub9c8\uac10, 6,000\uc120 \ud68c\ubcf5\ud55c 10\uc6d4 28\uc77c \uc2dc\uc7a5 \uc815\ub9ac","authors":["way"],"tags":["finance","\ucf54\uc2a4\ud53c","\uc2dc\uc7a5\uc815\ub9ac","\ubc18\ub3c4\uccb4"]},"unlisted":false,"prevItem":{"title":"HBM \uace0\ub300\uc5ed\ud3ed\uba54\ubaa8\ub9ac \uad6c\uc870\uc640 \ubc38\ub958\uccb4\uc778 \ud574\uc124","permalink":"/blog/en/finance/hbm-structure-value-chain"},"nextItem":{"title":"\uc601\uc5c5\uc774\uc775\ub960\ub85c \uc77d\ub294 \uc2e4\uc801, \ub9e4\ucd9c\uacfc \uc774\uc775\uc758 \ucc28\uc774","permalink":"/blog/en/finance/operating-margin-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ucf54\uc2a4\ud53c\uac00 6,000\uc120\uc744 \ud68c\ubcf5\ud558\uba70 \ub9c8\uac10\ud55c 10\uc6d4 28\uc77c \uc2dc\uc7a5\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\uc7a5 \uc2dc\uc791 \uc804\uc5d0 \ubc1c\ud45c\ub41c \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 3\ubd84\uae30 \uc2e4\uc801\uacfc \ub300\uaddc\ubaa8 \uc8fc\uc8fc\ud658\uc6d0 \uacc4\ud68d\uc774 \ud22c\uc790 \uc2ec\ub9ac\ub97c \ub04c\uc5b4\uc62c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ud574\ub2f9 \uae30\uc5c5\uc740 \ubd84\uae30 \ub9e4\ucd9c\uacfc \uc601\uc5c5\uc774\uc775\uc774 \ubaa8\ub450 \uc5ed\ub300 \ucd5c\ub300 \uc218\uc900\uc774\ub77c\uace0 \ubc1d\ud614\uace0, 100\uc870 \uc6d0 \uaddc\ubaa8\uc758 \uc8fc\uc8fc\ud658\uc6d0 \uacc4\ud68d\uc744 \ud568\uaed8 \uacf5\uac1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\uc5d0 \ub530\ub77c \ucf54\uc2a4\ud53c\ub294 \uc2dc\ucd08\ubd80\ud130 \uac15\ud558\uac8c \ucd9c\ubc1c\ud588\uace0, \uc624\uc804\uc5d0\ub294 \ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uac00 \uc774\ud2c0 \uc5f0\uc18d \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc138\ud55c \ub9c8\uac10 \uc218\uce58\ub294 [\uc544\uc8fc\ud504\ub808\uc2a4 \ubcf4\ub3c4](https://www.ajupress.com/view/20261028173670406)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdHl1b3o4eW0wYzE1ZzQ3djBrZnVpY3Joa25seXU1eGR4Yjd2dmFxYyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/mi6DsSSNKDbUY/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc624\ub298\uc758 \uc9c0\uc218\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 20\uc2dc 40\ubd84 \ud1b5\ud569 \uc2dc\uc138\ub85c \uc815\ub9ac\ud55c \ub9c8\uac10 \uc9c0\uc218\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 |\\n| --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 6,012.44 | 374.10 \uc0c1\uc2b9 | 6.63% |\\n| \ucf54\uc2a4\ub2e5 | 771.28 | 27.45 \uc0c1\uc2b9 | 3.69% |\\n| \ucf54\uc2a4\ud53c200 | 946.40 | 65.33 \uc0c1\uc2b9 | 7.41% |\\n| \uc6d0\ub2ec\ub7ec \ud658\uc728 | 1,340.70\uc6d0 | 13.70\uc6d0 \uc0c1\uc2b9 | 1.03% |\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\ucd08 5,763.85\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 6,032.28\uae4c\uc9c0 \uc62c\ub790\uace0, \uc885\uac00 \uae30\uc900\uc73c\ub85c 10\uac70\ub798\uc77c \ub9cc\uc5d0 6,000\uc120\uc744 \ud68c\ubcf5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\ub2ec\ub7ec \ud658\uc728\uc774 \uc624\ub978 \uac83\uc740 \uc6d0\ud654 \uac00\uce58\uac00 \uc57d\ud574\uc84c\ub2e4\ub294 \uc758\ubbf8\uc774\uba70, \uc9c0\uc218 \uc0c1\uc2b9\uacfc \ud658\uc728 \uc6c0\uc9c1\uc784\uc774 \ud56d\uc0c1 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09\uc744 \ubcf4\uba74 \ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ub97c, \uac1c\uc778\uc774 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778 7,691\uc5b5 \uc6d0 \uc21c\ub9e4\uc218, \uae30\uad00 9,146\uc5b5 \uc6d0 \uc21c\ub9e4\uc218, \uac1c\uc778 1\uc870 7,051\uc5b5 \uc6d0 \uc21c\ub9e4\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4, \uae30\uad00 \uc21c\ub9e4\uc218, \uac1c\uc778 \uc21c\ub9e4\ub3c4\uac00 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc624\ub298 \uac15\ud588\ub358 \ud14c\ub9c8\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900\uc73c\ub85c\ub294 SNS \ud14c\ub9c8\uac00 10.64%, CXL \ud14c\ub9c8\uac00 10.32%, HBM \ud14c\ub9c8\uac00 8.29% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\nHBM \ud14c\ub9c8\uc5d0 \ud3ec\ud568\ub41c 15\uac1c \uc885\ubaa9\uc774 \ubaa8\ub450 \uc0c1\uc2b9\ud588\uace0, \uc628\ub514\ubc14\uc774\uc2a4 AI \ud14c\ub9c8\ub3c4 8.19% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8 \ub4f1\ub77d\ub960\uc740 \ud558\ub8e8\uc758 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70, \ud14c\ub9c8 \uc548\uc5d0 \ud3ec\ud568\ub41c \uc885\ubaa9\uc758 \uad6c\uc131\uacfc \ube44\uc911\uc740 \uc218\uc2dc\ub85c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ud14c\ub9c8 \uc0c1\uc2b9\ub960\ub9cc\uc73c\ub85c \ud2b9\uc815 \uc885\ubaa9\uc758 \uac00\uce58\ub97c \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud655\uc778\ud560 \uc9c0\ud45c\\n\\n\uccab\uc9f8, \ubbf8\uad6d \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c \uacb0\uc815 \uacb0\uacfc\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \uc2e0\ud638\ub294 \uad6d\ub0b4 \uc99d\uc2dc\uc640 \ud658\uc728, \ucc44\uad8c \uae08\ub9ac\uc5d0 \ud568\uaed8 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 \ud655\uc815 \uc2e4\uc801 \ubc1c\ud45c \uc77c\uc815\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a0\uc815 \uc2e4\uc801\uacfc \ud655\uc815 \uc2e4\uc801 \uc0ac\uc774\uc5d0\ub294 \uc138\ubd80 \ud56d\ubaa9\uc758 \ucc28\uc774\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc678\uad6d\uc778 \uc21c\ub9e4\uc218\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc6d0\ub2ec\ub7ec \ud658\uc728\uc774 1,340\uc6d0\ub300\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ud558\ub8e8\uc758 \uae09\ub4f1\uc740 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \uacc4\uae30\uac00 \ub420 \uc218\ub3c4 \uc788\uace0, \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c0\ub294 \uad6d\uba74\uc758 \uc2dc\uc791\uc77c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n10\uc6d4 28\uc77c\uc740 \uc2e4\uc801 \uc7ac\ub8cc\uac00 \uc9c0\uc218 \uc804\uccb4\ub97c \ub04c\uc5b4\uc62c\ub9b0 \ub0a0\ub85c \uae30\ub85d\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExdnRxNGJmcDRidTA4MmhvZ3FkemlqNXVvYXBrNGliaXBkYzZ5M2szZSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/a0h7sAqON67nO/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"operating-margin-guide","metadata":{"permalink":"/blog/en/finance/operating-margin-guide","source":"@site/finance/2026-10-28-operating-margin-guide/index.mdx","title":"\uc601\uc5c5\uc774\uc775\ub960\ub85c \uc77d\ub294 \uc2e4\uc801, \ub9e4\ucd9c\uacfc \uc774\uc775\uc758 \ucc28\uc774","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-28T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc601\uc5c5\uc774\uc775\ub960","permalink":"/blog/en/finance/tags/\uc601\uc5c5\uc774\uc775\ub960"},{"inline":true,"label":"\uc2e4\uc801","permalink":"/blog/en/finance/tags/\uc2e4\uc801"},{"inline":true,"label":"\uc7ac\ubb34\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uc7ac\ubb34\uc9c0\ud45c"}],"readingTime":2.03,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"operating-margin-guide","title":"\uc601\uc5c5\uc774\uc775\ub960\ub85c \uc77d\ub294 \uc2e4\uc801, \ub9e4\ucd9c\uacfc \uc774\uc775\uc758 \ucc28\uc774","authors":["way"],"tags":["finance","\uc601\uc5c5\uc774\uc775\ub960","\uc2e4\uc801","\uc7ac\ubb34\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 6,012.44 \ub9c8\uac10, 6,000\uc120 \ud68c\ubcf5\ud55c 10\uc6d4 28\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-6000-recovery-oct28"},"nextItem":{"title":"\uae09\ub4f1\uc7a5 \uc774\ud6c4 \uc810\uac80\ud558\ub294 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ub9ac\ubc38\ub7f0\uc2f1 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","permalink":"/blog/en/finance/portfolio-rebalancing-checklist"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc2e4\uc801 \uae30\uc0ac\uc5d0\uc11c \uc790\uc8fc \ub4f1\uc7a5\ud558\ub294 \uc601\uc5c5\uc774\uc775\ub960\uc744 \uacc4\uc0b0\ud558\uace0 \ud574\uc11d\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n\ubd84\uae30 \uc2e4\uc801\uc774 \ubc1c\ud45c\ub418\uba74 \ub9e4\ucd9c\uc561\uacfc \uc601\uc5c5\uc774\uc775\uc774\ub77c\ub294 \ub450 \uc22b\uc790\uac00 \ud568\uaed8 \ubcf4\ub3c4\ub429\ub2c8\ub2e4.<br/>\\n\ub9e4\ucd9c\uc561\uc774 \uc5ed\ub300 \ucd5c\ub300\ub77c\uace0 \ud574\uc11c \uc774\uc775\ub3c4 \uac19\uc740 \ube44\uc728\ub85c \ub298\uc5b4\ub09c \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ub9e4\ucd9c\uc5d0\uc11c \uc6d0\uac00\uc640 \ud310\ub9e4\uad00\ub9ac\ube44\ub97c \ube80 \ub098\uba38\uc9c0\uac00 \uc601\uc5c5\uc774\uc775\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc601\uc5c5\uc774\uc775\ub960\uc740 \uc774 \uad00\uacc4\ub97c \ud558\ub098\uc758 \ube44\uc728\ub85c \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n10\uc6d4 28\uc77c\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 \uc5ed\ub300 \ucd5c\ub300 \uc2e4\uc801\uc774 \ubcf4\ub3c4\ub418\uba74\uc11c, \ub9e4\ucd9c \uaddc\ubaa8\uc640 \uc774\uc775 \uaddc\ubaa8\ub97c \ud568\uaed8 \ubcf4\ub294 \uad00\uc810\uc774 \ub2e4\uc2dc \uc8fc\ubaa9\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media2.giphy.com/media/v1.Y2lkPTc5MGI3NjExcWRiYWt5eHhnemx2dXl6anM1cXlxNXd2amJjbWU5czkwc3V3ZjNxMyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/aw8pRJdvmX24ZOC3vs/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc601\uc5c5\uc774\uc775\ub960 \uacc4\uc0b0\ubc95\\n\\n\uc601\uc5c5\uc774\uc775\ub960\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uacc4\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\\n`\uc601\uc5c5\uc774\uc775\ub960 = \uc601\uc5c5\uc774\uc775 / \ub9e4\ucd9c\uc561 x 100`\\n\\n\uacc4\uc0b0 \uc608\uc2dc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uad6c\ubd84 | \ub9e4\ucd9c\uc561 | \uc601\uc5c5\uc774\uc775 | \uc601\uc5c5\uc774\uc775\ub960 |\\n| --- | --- | --- | --- |\\n| \uae30\uc5c5 A | 100 | 20 | 20% |\\n| \uae30\uc5c5 B | 100 | 5 | 5% |\\n\\n\ub9e4\ucd9c\uc561\uc774 \uac19\uc740 100\uc774\uc5b4\ub3c4 \uc601\uc5c5\uc774\uc775\uc774 \ub2e4\ub974\uba74 \uc601\uc5c5\uc774\uc775\ub960\uc740 \ud06c\uac8c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc601\uc5c5\uc774\uc775\uc740 \ub9e4\ucd9c\uc561\uc5d0\uc11c \ub9e4\ucd9c\uc6d0\uac00\uc640 \ud310\ub9e4\uad00\ub9ac\ube44\ub97c \ube80 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uc774\uc790\ub098 \uc138\uae08, \uc601\uc5c5 \uc678 \uc190\uc775\uc740 \uc601\uc5c5\uc774\uc775\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc601\uc5c5\uc774\uc775\ub960\uc740 \ubcf8\uc5c5\uc758 \uc218\uc775\uc131\uc744 \ubcf4\ub294 \uc9c0\ud45c\uc774\uba70, \ucd5c\uc885 \uc21c\uc774\uc775\uacfc\ub294 \ub2e4\ub978 \uac1c\ub150\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc601\uc5c5\uc774\uc775\ub960\uc774 \ub192\ub2e4\uace0 \uc88b\uc740 \ud68c\uc0ac\uc778\uac00\\n\\n\uc601\uc5c5\uc774\uc775\ub960\uc774 \ub192\ub2e4\ub294 \uac83\uc740 \ub9e4\ucd9c\uc5d0\uc11c \ubcf8\uc5c5\uc758 \uc774\uc775\uc774 \ub9ce\uc774 \ub0a8\ub294\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ub192\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud68c\uc0ac\uc758 \uac00\uce58\ub97c \ud310\ub2e8\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \uc5c5\uc885\ub9c8\ub2e4 \uc815\uc0c1\uc801\uc778 \uc601\uc5c5\uc774\uc775\ub960 \uc218\uc900\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc720\ud1b5\uc5c5\uc740 \ub0ae\uc740 \ub9c8\uc9c4\uc73c\ub85c \ub300\ub7c9 \ud310\ub9e4\ub97c \ud558\ub294 \uad6c\uc870\uac00 \ub9ce\uace0, \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub098 \ud2b9\ud5c8 \uae30\ubc18 \uc0ac\uc5c5\uc740 \ub192\uc740 \ub9c8\uc9c4\uc774 \ub098\ud0c0\ub098\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc77c\ud68c\uc131 \uc694\uc778\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc790\uc0b0 \ub9e4\uac01\uc774\ub098 \uc77c\ud68c\uc131 \ube44\uc6a9\uc774 \ubc18\uc601\ub41c \ubd84\uae30\ub294 \ud3c9\uc18c\uc640 \ub2e4\ub978 \uc774\uc775\ub960\uc774 \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc9c0\uc18d\uc131\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ud55c \ubd84\uae30\uc758 \ub192\uc740 \uc774\uc775\ub960\uc774 \ub2e4\uc74c \ubd84\uae30\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0, \uc6d0\uac00\uc640 \ud310\uad00\ube44 \uad6c\uc870\uac00 \uc548\uc815\uc801\uc778\uc9c0 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc601\uc5c5\uc774\uc775\ub960\uacfc \ud568\uaed8 \uc21c\uc774\uc775\ub960\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc601\uc5c5\uc774\uc775\uc740 \uc88b\uc544\ub3c4 \uc774\uc790 \ubd80\ub2f4\uc774\ub098 \uc77c\ud68c\uc131 \uc190\uc2e4\uc774 \ud06c\uba74 \ucd5c\uc885 \uc774\uc775\uc740 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc804\ub144 \uac19\uc740 \ubd84\uae30\uc640 \ube44\uad50\ud569\ub2c8\ub2e4.<br/>\\n\uacc4\uc808\uc131\uc774 \uc788\ub294 \uc0ac\uc5c5\uc740 \uc9c1\uc804 \ubd84\uae30\ubcf4\ub2e4 \uc804\ub144 \ub3d9\uae30 \ube44\uad50\uac00 \ud574\uc11d\uc5d0 \ub3c4\uc6c0\uc774 \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ud604\uae08\ud750\ub984\uc744 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ud68c\uacc4\uc0c1 \uc774\uc775\uacfc \uc2e4\uc81c \ud604\uae08 \uc720\uc785\uc740 \uc7ac\uace0\ub098 \ub9e4\ucd9c\ucc44\uad8c, \uc124\ube44\ud22c\uc790 \ub54c\ubb38\uc5d0 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc5c5\uc885 \ud3c9\uade0\uacfc \ube44\uad50\ud569\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc5c5\uc885 \uc548\uc5d0\uc11c\uc758 \uc0c1\ub300\uc801 \uc704\uce58\uac00 \uc808\ub300 \uc218\uce58\ubcf4\ub2e4 \ud574\uc11d\uc5d0 \ub3c4\uc6c0\uc774 \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc601\uc5c5\uc774\uc775\ub960\uc740 \ub9e4\ucd9c\uacfc \uc774\uc775\uc758 \uad00\uacc4\ub97c \ud55c\ub208\uc5d0 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc774\uc9c0\ub9cc, \ub2e8\ub3c5\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExYjkzdmk5ZGNrOTQzZ3B1cnBxY3ZtejFxbjRreXl2bjRpc3hwOXoxciZlcD12MV9naWZzX3NlYXJjaCZjdD1nJmc9MTMyNjk1OCZhPTE2MTczNDMmYz0xMjY2MzI4JnBiPWtkLjE3MWVlNmJlLTYyZWEtNGJlNi05NDhiLWRkNDQwY2Q2OTA3NyZhcD0x/3orieWKVD1LN9uoDaU/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"portfolio-rebalancing-checklist","metadata":{"permalink":"/blog/en/finance/portfolio-rebalancing-checklist","source":"@site/finance/2026-10-28-portfolio-rebalancing-checklist/index.mdx","title":"\uae09\ub4f1\uc7a5 \uc774\ud6c4 \uc810\uac80\ud558\ub294 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ub9ac\ubc38\ub7f0\uc2f1 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-28T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\ub9ac\ubc38\ub7f0\uc2f1","permalink":"/blog/en/finance/tags/\ub9ac\ubc38\ub7f0\uc2f1"},{"inline":true,"label":"\ubd84\uc0b0\ud22c\uc790","permalink":"/blog/en/finance/tags/\ubd84\uc0b0\ud22c\uc790"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"}],"readingTime":2.3,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"portfolio-rebalancing-checklist","title":"\uae09\ub4f1\uc7a5 \uc774\ud6c4 \uc810\uac80\ud558\ub294 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ub9ac\ubc38\ub7f0\uc2f1 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","authors":["way"],"tags":["finance","\ub9ac\ubc38\ub7f0\uc2f1","\ubd84\uc0b0\ud22c\uc790","\uac1c\uc778\uc7ac\ubb34"]},"unlisted":false,"prevItem":{"title":"\uc601\uc5c5\uc774\uc775\ub960\ub85c \uc77d\ub294 \uc2e4\uc801, \ub9e4\ucd9c\uacfc \uc774\uc775\uc758 \ucc28\uc774","permalink":"/blog/en/finance/operating-margin-guide"},"nextItem":{"title":"\ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uc640 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4, \uc2dc\uc7a5 \uae09\ubcc0\ub3d9 \uc81c\ub3d9\uc7a5\uce58 \ud574\uc124","permalink":"/blog/en/finance/sidecar-circuit-breaker-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc9c0\uc218\uac00 \ud06c\uac8c \uc624\ub978 \ub0a0 \uc774\ud6c4\uc5d0 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ube44\uc911\uc774 \uc6d0\ub798 \uacc4\ud68d\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ubc97\uc5b4\ub0ac\ub294\uc9c0 \uc810\uac80\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 28\uc77c \ucf54\uc2a4\ud53c\ub294 6.63% \uc624\ub974\uba70 6,012.44\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ucc98\ub7fc \ud2b9\uc815 \uc790\uc0b0\uc774 \ud558\ub8e8\uc5d0 \ud06c\uac8c \uc624\ub974\uba74, \uc804\uccb4 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uc5d0\uc11c \uadf8 \uc790\uc0b0\uc774 \ucc28\uc9c0\ud558\ub294 \ube44\uc911\ub3c4 \ud568\uaed8 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ube44\uc911\uc774 \ucee4\uc84c\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \ubb38\uc81c\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ubb38\uc81c\ub294 \uc6d0\ub798 \uc815\ud55c \uc704\ud5d8 \uc218\uc900\uc744 \ub118\uc5b4\uc11c \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \uadf8 \ubcc0\ud654\ub97c \uc778\uc9c0\ud558\uace0 \uc788\ub294\uc9c0\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uc5d0 \uc0dd\uae41\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \uc774 \ube44\uc911\uc744 \uc810\uac80\ud558\uace0 \uc6d0\ub798 \uacc4\ud68d\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294 \uac1c\ub150\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media2.giphy.com/media/v1.Y2lkPTc5MGI3NjExZGNsYXRjMnBzcHp3MGtqYnR2MG9raXp6OGc2Z2lieDd4NTV4NjEzcCZlcD12MV9naWZzX3NlYXJjaCZjdD1nJmc9MTI4NTA1OCZhPTE1ODY4NTEmYz0xMjI0NjI2JnBiPWtkLmIwMTE2ZTFmLTViZjAtNDdmZi1hN2M4LWUwMmJkMmJhMGQyZSZhcD0x/ZECkzzRuzbWdBu19jz/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \ub9ac\ubc38\ub7f0\uc2f1\uc774\ub780 \ubb34\uc5c7\uc778\uac00\\n\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \uc790\uc0b0\ubcc4 \ubaa9\ud45c \ube44\uc911\uc744 \ub2e4\uc2dc \ub9de\ucd94\ub294 \uc791\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc8fc\uc2dd 60, \ucc44\uad8c 30, \ud604\uae08 10\uc774\ub77c\ub294 \ubaa9\ud45c \ube44\uc911\uc744 \uc815\ud588\ub2e4\uace0 \uac00\uc815\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd\uc774 \ud06c\uac8c \uc624\ub974\uba74 \ube44\uc911\uc740 \uc8fc\uc2dd 70, \ucc44\uad8c 22, \ud604\uae08 8\uacfc \uac19\uc774 \ubc14\ub014 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \ubc14\ub010 \ube44\uc911\uc744 \ub2e4\uc2dc \uc8fc\uc2dd 60, \ucc44\uad8c 30, \ud604\uae08 10\uc5d0 \uac00\uae5d\uac8c \uc870\uc815\ud558\ub294 \uac1c\ub150\uc785\ub2c8\ub2e4.<br/>\\n\uc870\uc815 \ubc29\ubc95\uc740 \ube44\uc911\uc774 \ub298\uc5b4\ub09c \uc790\uc0b0\uc744 \uc904\uc774\uace0, \ube44\uc911\uc774 \uc904\uc5b4\ub4e0 \uc790\uc0b0\uc744 \ub298\ub9ac\ub294 \ud615\ud0dc\uac00 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc870\uc815 \uc790\uccb4\uac00 \uc218\uc775\uc744 \ubcf4\uc7a5\ud558\ub294 \uc7a5\uce58\ub294 \uc544\ub2c8\uba70, \uc2dc\uc7a5\uc744 \uc608\uce21\ud558\ub294 \ubc29\ubc95\ub3c4 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n#### \uc8fc\uae30\uc640 \uae30\uc900\\n\\n\ub9ac\ubc38\ub7f0\uc2f1\uc758 \uae30\uc900\uc740 \ud06c\uac8c \uc815\uae30 \ubc29\uc2dd\uacfc \uc784\uacc4\uac12 \ubc29\uc2dd\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc815\uae30 \ubc29\uc2dd\uc740 \ubc18\uae30\ub098 \uc5f0 \ub2e8\uc704\ucc98\ub7fc \ubbf8\ub9ac \uc815\ud55c \uc8fc\uae30\uc5d0 \uc810\uac80\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\uc784\uacc4\uac12 \ubc29\uc2dd\uc740 \ubaa9\ud45c \ube44\uc911\uc5d0\uc11c \uc77c\uc815 \ud3ed \uc774\uc0c1 \ubc97\uc5b4\ub0ac\uc744 \ub54c \uc810\uac80\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \ubaa9\ud45c \ube44\uc911\uc5d0\uc11c 5%\ud3ec\uc778\ud2b8 \uc774\uc0c1 \ubc97\uc5b4\ub098\uba74 \uc810\uac80\ud55c\ub2e4\ub294 \uc2dd\uc758 \uae30\uc900\uc744 \uac1c\uc778\uc774 \uc815\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ubc29\uc2dd\uc774\ub4e0 \uac70\ub798\ube44\uc6a9\uacfc \uc138\uae08\uc744 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc7a6\uc740 \uc870\uc815\uc740 \uac70\ub798\ube44\uc6a9\uacfc \uc138\uae08 \ubd80\ub2f4\uc744 \ub298\ub9b4 \uc218 \uc788\uc73c\uba70, \uc5f0\uae08\uacc4\uc88c\uc640 \uacfc\uc138 \uacc4\uc88c\uc5d0\uc11c\ub294 \uc138\uae08 \ucc98\ub9ac \ubc29\uc2dd\uc774 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc870\uc815 \ube48\ub3c4\ub97c \uc815\ud560 \ub54c\ub294 \ube44\uc6a9\uacfc \uc138\uae08\uae4c\uc9c0 \ud3ec\ud568\ud55c \uc804\uccb4 \uad00\uc810\uc5d0\uc11c \ud310\ub2e8\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uae09\ub4f1\uc7a5\uc5d0\uc11c \uc810\uac80\ud560 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\\n\\n\uccab\uc9f8, \ubaa9\ud45c \ube44\uc911\uc744 \ub2e4\uc2dc \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uae09\ub4f1 \uc804\ud6c4\ub85c \uc790\uc2e0\uc758 \ubaa9\ud45c \ube44\uc911\uc774 \ubb34\uc5c7\uc774\uc5c8\ub294\uc9c0 \uae30\ub85d\uc73c\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub2e8\uc77c \ud14c\ub9c8\ub098 \ub2e8\uc77c \uc790\uc0b0\uc758 \uc9d1\uc911\ub3c4\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \ud14c\ub9c8\uac00 \ud06c\uac8c \uc624\ub978 \ub0a0\uc5d0\ub294 \uadf8 \ud14c\ub9c8\uc758 \ube44\uc911\uc774 \uc0dd\uac01\ubcf4\ub2e4 \ucee4\uc838 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ube44\uc0c1\uc790\uae08\uacfc \uc0dd\ud65c\uc790\uae08\uc774 \ud22c\uc790 \uc790\uae08\uacfc \ubd84\ub9ac\ub418\uc5b4 \uc788\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30\uac04\uc5d0 \uc0ac\uc6a9\ud560 \uc790\uae08\uc774 \ud22c\uc790 \uc790\uc0b0\uc5d0 \uc11e\uc5ec \uc788\uc73c\uba74, \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \ub54c \uc0dd\ud65c \uacc4\ud68d\uae4c\uc9c0 \ud754\ub4e4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uac10\uc815\uc801\uc778 \ud310\ub2e8\uc744 \uad6c\ubd84\ud569\ub2c8\ub2e4.<br/>\\n\uae09\ub4f1\uc7a5\uc5d0\uc11c\ub294 \ub4a4\ucc98\uc9c8 \uc218 \uc788\ub2e4\ub294 \ubd88\uc548\uc774, \uae09\ub77d\uc7a5\uc5d0\uc11c\ub294 \uc190\uc2e4\uc744 \ud53c\ud558\uace0 \uc2f6\ub2e4\ub294 \uc2ec\ub9ac\uac00 \ud310\ub2e8\uc744 \uc55e\uc9c0\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f\uc9f8, \uc810\uac80 \uacb0\uacfc\ub97c \uae30\ub85d\uc73c\ub85c \ub0a8\uae41\ub2c8\ub2e4.<br/>\\n\uc870\uc815 \uc5ec\ubd80\uc640 \uadf8 \uc774\uc720\ub97c \uae30\ub85d\ud558\uba74, \ub2e4\uc74c \uc810\uac80 \ub54c \uac19\uc740 \uc9c8\ubb38\uc744 \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \ud558\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\ub9ac\ubc38\ub7f0\uc2f1\uc758 \ubaa9\uc801\uc740 \uc2dc\uc7a5\uc744 \ub9de\ud788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc790\uc2e0\uc774 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uc704\ud5d8 \uc218\uc900\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdHl1b3o4eW0wYzE1ZzQ3djBrZnVpY3Joa25seXU1eGR4Yjd2dmFxYyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/mi6DsSSNKDbUY/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"sidecar-circuit-breaker-guide","metadata":{"permalink":"/blog/en/finance/sidecar-circuit-breaker-guide","source":"@site/finance/2026-10-28-sidecar-circuit-breaker-guide/index.mdx","title":"\ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uc640 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4, \uc2dc\uc7a5 \uae09\ubcc0\ub3d9 \uc81c\ub3d9\uc7a5\uce58 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-28T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc0ac\uc774\ub4dc\uce74","permalink":"/blog/en/finance/tags/\uc0ac\uc774\ub4dc\uce74"},{"inline":true,"label":"\uc11c\ud0b7\ube0c\ub808\uc774\ucee4","permalink":"/blog/en/finance/tags/\uc11c\ud0b7\ube0c\ub808\uc774\ucee4"},{"inline":true,"label":"\uc2dc\uc7a5\uc81c\ub3c4","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc81c\ub3c4"}],"readingTime":2.34,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"sidecar-circuit-breaker-guide","title":"\ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uc640 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4, \uc2dc\uc7a5 \uae09\ubcc0\ub3d9 \uc81c\ub3d9\uc7a5\uce58 \ud574\uc124","authors":["way"],"tags":["finance","\uc0ac\uc774\ub4dc\uce74","\uc11c\ud0b7\ube0c\ub808\uc774\ucee4","\uc2dc\uc7a5\uc81c\ub3c4"]},"unlisted":false,"prevItem":{"title":"\uae09\ub4f1\uc7a5 \uc774\ud6c4 \uc810\uac80\ud558\ub294 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ub9ac\ubc38\ub7f0\uc2f1 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","permalink":"/blog/en/finance/portfolio-rebalancing-checklist"},"nextItem":{"title":"2\ucc28\uc804\uc9c0\uc640 ESS \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","permalink":"/blog/en/finance/battery-ess-industry-structure"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 10\uc6d4 28\uc77c \uc624\uc804\uc5d0 \uc774\ud2c0 \uc5f0\uc18d \ubc1c\ub3d9\ud55c \ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uc640 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uc758 \ucc28\uc774\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uacbd\\n\\n10\uc6d4 28\uc77c \uc624\uc804 9\uc2dc 54\ubd84 \ubb34\ub835 \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0\uc11c \ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200 \uc120\ubb3c\uc774 \uae30\uc900\uac00 \ub300\ube44 5.17% \uc624\ub978 928.02\uae4c\uc9c0 \uc0c1\uc2b9\ud588\uace0, \uadf8 \uc218\uc900\uc774 1\ubd84 \uc774\uc0c1 \uc720\uc9c0\ub41c \uac83\uc774 \ubc1c\ub3d9 \uc870\uac74\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1c\ub3d9 \uc774\ud6c4 \ud504\ub85c\uadf8\ub7a8 \ub9e4\uc218\ud638\uac00\uc758 \ud6a8\ub825\uc740 5\ubd84\uac04 \uc815\uc9c0\ub418\uc5c8\uace0, 5\ubd84\uc774 \uc9c0\ub098\uba74 \uc790\ub3d9\uc73c\ub85c \ud574\uc81c\ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub0a0\uc778 10\uc6d4 27\uc77c\uc5d0\ub3c4 \ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uae30 \ub54c\ubb38\uc5d0, \uc774\ud2c0 \uc5f0\uc18d \ubc1c\ub3d9\uc774\ub77c\ub294 \uc810\uc774 \uc8fc\ubaa9\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1c\ub3d9 \uacbd\uc704\ub294 [SBS \ubcf4\ub3c4](https://news.sbs.co.kr/english/article.do?news_id=N1008818555)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHh4ejI2c3JucXRuemltZW5vd3c2NWd3NXByM3B0MDV6Z3ZvdWFheCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/fapvHdWzoHtYY/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n#### \uc0ac\uc774\ub4dc\uce74\ub780 \ubb34\uc5c7\uc778\uac00\\n\\n\uc0ac\uc774\ub4dc\uce74\ub294 \uc120\ubb3c \uc2dc\uc7a5\uc758 \uae09\ubcc0\ub3d9\uc774 \ud604\ubb3c \uc2dc\uc7a5\uc73c\ub85c \uacfc\ub3c4\ud558\uac8c \uc804\uc774\ub418\ub294 \uac83\uc744 \ub2a6\ucd94\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\ub294 \ucf54\uc2a4\ud53c200 \uc120\ubb3c \uac00\uaca9\uc774 \uae30\uc900\uac00 \ub300\ube44 5% \uc774\uc0c1 \uc0c1\uc2b9\ud55c \uc0c1\ud0dc\uac00 1\ubd84 \uc774\uc0c1 \uc9c0\uc18d\ub420 \ub54c \ubc1c\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\ubc1c\ub3d9\ud558\uba74 \ud504\ub85c\uadf8\ub7a8 \ub9e4\uc218\ud638\uac00\uc758 \ud6a8\ub825\uc774 5\ubd84\uac04 \uc815\uc9c0\ub429\ub2c8\ub2e4.<br/>\\n\uc911\uc694\ud55c \uc810\uc740 \ud604\ubb3c \uac70\ub798 \uc790\uccb4\uac00 \uc911\ub2e8\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18 \ud22c\uc790\uc790\uc758 \uc8fc\ubb38\uc740 \uacc4\uc18d \uccb4\uacb0\ub420 \uc218 \uc788\uc73c\uba70, \uc815\uc9c0\ub418\ub294 \uac83\uc740 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc758 \ub9e4\uc218\ud638\uac00\ub85c \ud55c\uc815\ub429\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\ub3c4 \uac19\uc740 \uad6c\uc870\uc774\uba70, \uc120\ubb3c \uac00\uaca9\uc774 5% \uc774\uc0c1 \ud558\ub77d\ud55c \uc0c1\ud0dc\uac00 1\ubd84 \uc774\uc0c1 \uc9c0\uc18d\ub420 \ub54c \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub3c4\ud638\uac00\uac00 \uc815\uc9c0\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uc640 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uac00\\n\\n\uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub294 \ud604\ubb3c \uc9c0\uc218 \uc790\uccb4\uac00 \uae09\ub77d\ud560 \ub54c \uc804\uccb4 \uac70\ub798\ub97c \uc77c\uc2dc \uc911\ub2e8\ud558\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc0ac\uc774\ub4dc\uce74\uac00 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\ub9cc \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \ub370 \ube44\ud574, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub294 \uc2dc\uc7a5 \uc804\uccb4\uc758 \uac70\ub798\ub97c \uba48\ucd94\ub294 \uc810\uc5d0\uc11c \uac15\ub3c4\uac00 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\ub610\ud55c \uc0ac\uc774\ub4dc\uce74\ub294 \uc0c1\uc2b9\uacfc \ud558\ub77d \uc591\ubc29\ud5a5\uc5d0 \ubaa8\ub450 \uc874\uc7ac\ud558\uc9c0\ub9cc, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub294 \uae09\ub77d \uad6d\uba74\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98 \uc81c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\\n| \uad6c\ubd84 | \uc0ac\uc774\ub4dc\uce74 | \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 |\\n| --- | --- | --- |\\n| \ubc1c\ub3d9 \uae30\uc900 | \uc120\ubb3c \uac00\uaca9 \uae09\ubcc0 | \ud604\ubb3c \uc9c0\uc218 \uae09\ub77d |\\n| \ub300\uc0c1 | \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc758 \ub9e4\uc218 \ub610\ub294 \ub9e4\ub3c4\ud638\uac00 | \uc2dc\uc7a5 \uc804\uccb4 \uac70\ub798 |\\n| \uc870\uce58 \uc2dc\uac04 | 5\ubd84\uac04 \ud6a8\ub825 \uc815\uc9c0 | \ub2e8\uacc4\ubcc4\ub85c \uac70\ub798 \uc77c\uc2dc \uc911\ub2e8 |\\n| \ubaa9\uc801 | \uc120\ubb3c \ucda9\uaca9\uc758 \ud604\ubb3c \uc804\uc774\ub97c \ub2a6\ucd94\ub294 \uac83 | \uae09\ub77d \uc18d\ub3c4\ub97c \ub2a6\ucd94\uace0 \uac00\uaca9\uc744 \uc7ac\ud3c9\uac00\ud560 \uc2dc\uac04\uc744 \uc8fc\ub294 \uac83 |\\n\\n#### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9 \uc790\uccb4\ub97c \ub9e4\uc218 \uc2e0\ud638\ub098 \ub9e4\ub3c4 \uc2e0\ud638\ub85c \ud574\uc11d\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0ac\uc774\ub4dc\uce74\ub294 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\ub824\uc8fc\ub294 \uc81c\ub3c4\uc801 \ud45c\uc2dc\uc77c \ubfd0\uc785\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ud574\uc81c \uc774\ud6c4\uc758 \uc6c0\uc9c1\uc784\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n5\ubd84\uc758 \uc815\uc9c0\uac00 \ub05d\ub098\uba74 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uac00 \ub2e4\uc2dc \uc7ac\uac1c\ub418\uba70, \ubcc0\ub3d9\uc131\uc774 \uace7\ubc14\ub85c \uac00\ub77c\uc549\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc774\ud2c0 \uc5f0\uc18d \ubc1c\ub3d9\uc740 \ubcc0\ub3d9\uc131 \ud655\ub300 \uad6d\uba74\uc774\ub77c\ub294 \uc2e0\ud638\ub85c \uc77d\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\uc5f0\uc18d \ubc1c\ub3d9\uc774 \ubc29\ud5a5\uc758 \uc9c0\uc18d\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\uc73c\uba70, \uae09\ub4f1 \uc774\ud6c4 \ub418\ub3cc\ub9bc\ub3c4 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9 \uc2dc\uac04\ub300\uc758 \uc9c0\uc218 \uc218\uc900\ub9cc \ubcf4\uace0 \ud558\ub8e8 \uc804\uccb4\ub97c \ud310\ub2e8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uc810\uacfc \uc885\uac00\ub294 \ub2e4\ub97c \uc218 \uc788\uc73c\uba70, \ub9c8\uac10 \uc9c0\uc218\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc0ac\uc774\ub4dc\uce74\ub294 \uc2dc\uc7a5\uc744 \uba48\ucd94\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub77c, \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4\uc758 \uc18d\ub3c4\ub97c \uc7a0\uc2dc \ub2a6\ucd94\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExdnRxNGJmcDRidTA4MmhvZ3FkemlqNXVvYXBrNGliaXBkYzZ5M2szZSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/a0h7sAqON67nO/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"battery-ess-industry-structure","metadata":{"permalink":"/blog/en/finance/battery-ess-industry-structure","source":"@site/finance/2026-10-27-battery-ess-industry-structure/index.mdx","title":"2\ucc28\uc804\uc9c0\uc640 ESS \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-27T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc139\ud130","permalink":"/blog/en/finance/tags/\uc139\ud130"},{"inline":true,"label":"2\ucc28\uc804\uc9c0","permalink":"/blog/en/finance/tags/2-\ucc28\uc804\uc9c0"},{"inline":true,"label":"ESS","permalink":"/blog/en/finance/tags/ess"},{"inline":true,"label":"\ubc30\ud130\ub9ac","permalink":"/blog/en/finance/tags/\ubc30\ud130\ub9ac"},{"inline":true,"label":"\uc0b0\uc5c5\uad6c\uc870","permalink":"/blog/en/finance/tags/\uc0b0\uc5c5\uad6c\uc870"}],"readingTime":2.17,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"battery-ess-industry-structure","title":"2\ucc28\uc804\uc9c0\uc640 ESS \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","authors":["way"],"tags":["finance","\uc139\ud130","2\ucc28\uc804\uc9c0","ESS","\ubc30\ud130\ub9ac","\uc0b0\uc5c5\uad6c\uc870"]},"unlisted":false,"prevItem":{"title":"\ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uc640 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4, \uc2dc\uc7a5 \uae09\ubcc0\ub3d9 \uc81c\ub3d9\uc7a5\uce58 \ud574\uc124","permalink":"/blog/en/finance/sidecar-circuit-breaker-guide"},"nextItem":{"title":"\uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/buyback-cancellation-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 2\ucc28\uc804\uc9c0 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640 \uc5d0\ub108\uc9c0\uc800\uc7a5\uc7a5\uce58(ESS) \uc2dc\uc7a5\uc758 \uc758\ubbf8\ub97c \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n2\ucc28\uc804\uc9c0\ub294 \ucda9\uc804\ud574\uc11c \ub2e4\uc2dc \uc4f8 \uc218 \uc788\ub294 \uc804\uc9c0\ub97c \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uae30\ucc28\uc640 \uc5d0\ub108\uc9c0\uc800\uc7a5\uc7a5\uce58, \ud734\ub300\uc6a9 \uc804\uc790\uae30\uae30\uc5d0 \ub450\ub8e8 \uc4f0\uc774\uba70, \uc804\ub3d9\ud654 \ud750\ub984\uc758 \ud575\uc2ec \ubd80\ud488\uc73c\ub85c \uc790\ub9ac \uc7a1\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc\uc5d0\ub294 \uc804\uae30\ucc28 \uc2dc\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uc804\ub825\ub9dd\uc6a9 ESS \uc218\uc694\uac00 \uc0b0\uc5c5\uc758 \uc0c8\ub85c\uc6b4 \ucd95\uc73c\ub85c \ubd80\uc0c1\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130\uc758 \uc804\ub825 \uc218\uc694\uac00 \ucee4\uc9c0\uba74\uc11c \uc804\ub825\ub9dd \uc548\uc815\uc131\uc744 \ub192\uc774\ub294 \uc7a5\uce58\ub85c\uc11c ESS\uc758 \uc5ed\ud560\ub3c4 \ud568\uaed8 \uc8fc\ubaa9\ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExenZnMmp3dWFwajUxY3Mydmt3OHJ5M2YzZDYxbzVyN3MzcXdtOWd5NSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/26FPJGjhefSJuaRhu/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc0b0\uc5c5\uc758 \uad6c\uc870\\n\\n#### \uc140\uacfc \uc18c\uc7ac\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uac00\uce58\uc0ac\uc2ac\\n\\n2\ucc28\uc804\uc9c0 \uac00\uce58\uc0ac\uc2ac\uc740 \ud06c\uac8c \uc18c\uc7ac, \uc140, \ud329\uacfc \uc2dc\uc2a4\ud15c\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc18c\uc7ac \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc591\uadf9\uc7ac, \uc74c\uadf9\uc7ac, \uc804\ud574\uc9c8, \ubd84\ub9ac\ub9c9\uc774 \ub9cc\ub4e4\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc591\uadf9\uc7ac\ub294 \uc804\uc9c0\uc758 \uc6a9\ub7c9\uacfc \ucd9c\ub825 \ud2b9\uc131\uc744 \uc88c\uc6b0\ud558\ub294 \ud575\uc2ec \uc18c\uc7ac\ub85c \uaf3d\ud799\ub2c8\ub2e4.<br/>\\n\uc140 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc18c\uc7ac\ub97c \uc870\ub9bd\ud574 \uc804\uc9c0 \ub2e8\ud488\uc744 \ub9cc\ub4e4\uace0, \ud329 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc140\uc744 \ubb36\uc5b4 \ub0c9\uac01\uacfc \uc81c\uc5b4 \uc7a5\uce58\ub97c \ub354\ud569\ub2c8\ub2e4.<br/>\\nESS\uc5d0\uc11c\ub294 \ud329\uc5d0 \uc804\ub825\ubcc0\ud658\uc7a5\uce58\uc640 \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc744 \uacb0\ud569\ud574 \ud558\ub098\uc758 \uc124\ube44\ub85c \uc644\uc131\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc0bc\uc6d0\uacc4\uc640 LFP\uc758 \uad6c\ubd84\\n\\n\ub9ac\ud2ac\uc774\uc628\uc804\uc9c0\ub294 \uc591\uadf9\uc7ac \uc870\uc131\uc5d0 \ub530\ub77c \ud06c\uac8c \uc0bc\uc6d0\uacc4\uc640 LFP\ub85c \uad6c\ubd84\ub429\ub2c8\ub2e4.<br/>\\n\uc0bc\uc6d0\uacc4\ub294 \ub2c8\ucf08, \ucf54\ubc1c\ud2b8, \ub9dd\uac04\uc744 \uc0ac\uc6a9\ud558\uba70 \uc5d0\ub108\uc9c0 \ubc00\ub3c4\uac00 \ub192\uc740 \ud3b8\uc785\ub2c8\ub2e4.<br/>\\nLFP\ub294 \ub9ac\ud2ac\uc778\uc0b0\ucca0\uc744 \uc0ac\uc6a9\ud558\uba70 \uc6d0\uac00\uac00 \ub0ae\uace0 \uc548\uc815\uc131\uc774 \ub192\ub2e4\uace0 \ud3c9\uac00\ub429\ub2c8\ub2e4.<br/>\\n\uc804\uae30\ucc28\uc5d0\uc11c\ub294 \uc8fc\ud589\uac70\ub9ac\uc640 \uc6d0\uac00\ub97c \ud568\uaed8 \uace0\ub824\ud574 \ub450 \ubc29\uc2dd\uc774 \uc6a9\ub3c4\ubcc4\ub85c \ub098\ub258\uc5b4 \uc4f0\uc785\ub2c8\ub2e4.<br/>\\nESS\uc5d0\uc11c\ub294 \uc6d0\uac00\uc640 \uc218\uba85, \uc548\uc804\uc131\uc774 \uc911\uc694\ud574 LFP\uc758 \ube44\uc911\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ub192\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### ESS\uac00 \uc8fc\ubaa9\ubc1b\ub294 \uc774\uc720\\n\\nESS\ub294 \uc804\uae30\ub97c \uc800\uc7a5\ud588\ub2e4\uac00 \ud544\uc694\ud560 \ub54c \ubc29\ucd9c\ud558\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ud0dc\uc591\uad11\uacfc \ud48d\ub825 \uac19\uc740 \uc7ac\uc0dd\uc5d0\ub108\uc9c0\ub294 \ubc1c\uc804\ub7c9\uc774 \uc2dc\uac04\uc5d0 \ub530\ub77c \ud06c\uac8c \ubcc0\ub3d9\ud569\ub2c8\ub2e4.<br/>\\nESS\ub294 \ub0a8\ub294 \uc804\uae30\ub97c \uc800\uc7a5\ud574 \uc218\uc694\uac00 \ub9ce\uc740 \uc2dc\uac04\uc5d0 \uacf5\uae09\ud568\uc73c\ub85c\uc368 \uc804\ub825\ub9dd\uc758 \ubcc0\ub3d9\uc131\uc744 \uc644\ud654\ud569\ub2c8\ub2e4.<br/>\\n\ubd81\ubbf8 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc804\ub825\ub9dd\uc6a9 ESS \uacf5\uae09 \uacc4\uc57d\uc774 \uc774\uc5b4\uc9c0\uba70 \uad6d\ub0b4 \uae30\uc5c5\ub4e4\uc758 \uc0ac\uc5c5 \uae30\ud68c\ub3c4 \ud655\ub300\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uace0\uccb4 \uc804\uc9c0\uc6a9 \ud669\ud654\ub9ac\ud2ac \uc18c\uc7ac\uc758 \uc591\uc0b0 \uae30\ubc18\uc774 \ub9c8\ub828\ub418\ub294 \ub4f1 \ucc28\uc138\ub300 \uc18c\uc7ac \uac1c\ubc1c\ub3c4 \ud568\uaed8 \uc9c4\ud589\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n2\ucc28\uc804\uc9c0 \uc0b0\uc5c5\uc744 \ubcfc \ub54c\ub294 \uc18c\uc7ac \uac00\uaca9\uacfc \uc218\uc8fc, \uac00\ub3d9\ub960\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9ac\ud2ac\uacfc \ub2c8\ucf08 \uac19\uc740 \uc6d0\uc790\uc7ac \uac00\uaca9 \ubcc0\ub3d9\uc740 \uc18c\uc7ac \uae30\uc5c5\uc758 \uc218\uc775\uc131\uc5d0 \uc9c1\uc811 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc218\uc8fc \uc18c\uc2dd\ub9cc\uc73c\ub85c \uc2e4\uc801\uc744 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4, \uc2e4\uc81c \ub9e4\ucd9c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc2dc\uc810\uacfc \uace0\uac1d\uc0ac\uc758 \uc0dd\uc0b0 \uacc4\ud68d\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\nESS \uc0ac\uc5c5\uc5d0\uc11c\ub294 \ud504\ub85c\uc81d\ud2b8\uc758 \uaddc\ubaa8\uc640 \ub0a9\uae30, \uc804\ub825\ub9dd \uc5f0\uacc4 \uc77c\uc815\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uae30\ucc28 \uc218\uc694 \ub454\ud654 \uad6d\uba74\uc5d0\uc11c\ub294 ESS \ube44\uc911\uc774 \ub192\uc740 \uae30\uc5c5\uacfc \uc804\uae30\ucc28 \ube44\uc911\uc774 \ub192\uc740 \uae30\uc5c5\uc758 \uc2e4\uc801 \ud750\ub984\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n2\ucc28\uc804\uc9c0 \uc0b0\uc5c5\uc740 \uc18c\uc7ac\ubd80\ud130 \uc140, \ud329, \uc2dc\uc2a4\ud15c\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uae34 \uac00\uce58\uc0ac\uc2ac\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nESS \uc2dc\uc7a5\uc758 \ud655\ub300\ub294 \uc774 \uc0b0\uc5c5\uc758 \uc218\uc694 \ucd95\uc744 \uc804\uae30\ucc28\uc5d0\uc11c \uc804\ub825\ub9dd\uc73c\ub85c \ub113\ud788\ub294 \ubcc0\ud654\ub85c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExc2VsdDZkcDZkdjU2ZHFudXcwcXJlZXQ0d3psemtwNHZ4b3NuOHc3dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/BfFFYPSVYr9UR6EtEL/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"buyback-cancellation-guide","metadata":{"permalink":"/blog/en/finance/buyback-cancellation-guide","source":"@site/finance/2026-10-27-buyback-cancellation-guide/index.mdx","title":"\uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01 \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-27T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\ub150","permalink":"/blog/en/finance/tags/\uac1c\ub150"},{"inline":true,"label":"\uc790\uc0ac\uc8fc","permalink":"/blog/en/finance/tags/\uc790\uc0ac\uc8fc"},{"inline":true,"label":"\uc8fc\uc8fc\ud658\uc6d0","permalink":"/blog/en/finance/tags/\uc8fc\uc8fc\ud658\uc6d0"},{"inline":true,"label":"\ubc30\ub2f9","permalink":"/blog/en/finance/tags/\ubc30\ub2f9"}],"readingTime":2.25,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"buyback-cancellation-guide","title":"\uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01 \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","\uac1c\ub150","\uc790\uc0ac\uc8fc","\uc8fc\uc8fc\ud658\uc6d0","\ubc30\ub2f9"]},"unlisted":false,"prevItem":{"title":"2\ucc28\uc804\uc9c0\uc640 ESS \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","permalink":"/blog/en/finance/battery-ess-industry-structure"},"nextItem":{"title":"\ube44\uc0c1\uae08 \ub9c8\ub828\ud558\ub294 \ubc95","permalink":"/blog/en/finance/emergency-fund-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uae30\uc5c5\uc758 \uc8fc\uc8fc\ud658\uc6d0 \uc218\ub2e8\uc778 \uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01\uc744 \uc77d\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc790\uc0ac\uc8fc\ub294 \uae30\uc5c5\uc774 \uc790\uae30 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \ub2e4\uc2dc \uc0ac\ub4e4\uc778 \uc8fc\uc2dd\uc744 \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uae30\uc5c5\uc740 \uc5ec\uc720 \uc790\uae08\uc744 \ud65c\uc6a9\ud574 \uc790\uc0ac\uc8fc\ub97c \ub9e4\uc785\ud558\uace0, \uc774\ub97c \uc18c\uac01\ud558\uac70\ub098 \uc784\uc9c1\uc6d0 \ubcf4\uc0c1, \uc778\uc218 \ub300\uae08 \ub4f1\uc73c\ub85c \ud65c\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc790\uc0ac\uc8fc \ub9e4\uc785\uc740 \uc2dc\uc7a5\uc5d0 \ub9e4\uc218 \uc218\uc694\ub97c \ub354\ud558\uace0, \uc18c\uac01\uc740 \ubc1c\ud589 \uc8fc\uc2dd \uc218\ub97c \uc904\uc774\ub294 \ud6a8\uacfc\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc\uc5d0\ub294 \ubc30\ub2f9\uacfc \ud568\uaed8 \uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01\uc744 \uc8fc\uc8fc\ud658\uc6d0 \uc815\ucc45\uc758 \ud55c \ucd95\uc73c\ub85c \uacf5\uc2dc\ud558\ub294 \uae30\uc5c5\uc774 \ub298\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMjhleml6aHhheThkNWl1emU1MDQ3cGRzejI5Nnp3eXlzZHhtZHo1cCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/o75ajIFH0QnQC3nCeD/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ud575\uc2ec \uac1c\ub150\\n\\n#### \ub9e4\uc785\uacfc \uc18c\uac01\uc758 \ucc28\uc774\\n\\n\uc790\uc0ac\uc8fc \ub9e4\uc785 \uc790\uccb4\ub9cc\uc73c\ub85c\ub294 \ubc1c\ud589 \uc8fc\uc2dd \uc218\uac00 \uc904\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\uc785\ud55c \uc8fc\uc2dd\uc740 \uc790\uc0ac\uc8fc\ub85c \ubcf4\uc720\ub418\uba70, \ub098\uc911\uc5d0 \ub2e4\uc2dc \uc2dc\uc7a5\uc5d0 \ub9e4\uac01\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc18c\uac01\uc740 \ub9e4\uc785\ud55c \uc8fc\uc2dd\uc744 \uc5c6\uc560\ub294 \uc808\ucc28\ub85c, \uc18c\uac01\uc774 \uc644\ub8cc\ub3fc\uc57c \ubc1c\ud589 \uc8fc\uc2dd \uc218\uac00 \uc2e4\uc81c\ub85c \uac10\uc18c\ud569\ub2c8\ub2e4.<br/>\\n\ubc1c\ud589 \uc8fc\uc2dd \uc218\uac00 \uc904\uba74 \uac19\uc740 \uc21c\uc774\uc775\uc744 \ub354 \uc801\uc740 \uc8fc\uc2dd \uc218\ub85c \ub098\ub204\uac8c \ub418\ubbc0\ub85c \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc774 \ub192\uc544\uc9c0\ub294 \ud6a8\uacfc\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc18c\uac01 \uacc4\ud68d\uc774 \uacf5\uc2dc\ub9cc \ub418\uace0 \uc2e4\ud589\ub418\uc9c0 \uc54a\uc73c\uba74 \ud6a8\uacfc\uac00 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \uc2e4\ud589 \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc8fc\uc8fc\ud658\uc6d0\uc728\ub85c \ubcf4\ub294 \uc804\uccb4 \uadf8\ub9bc\\n\\n\uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \ubc30\ub2f9\uc744 \ud569\uccd0\uc11c \ubcf4\ub294 \uc9c0\ud45c\uac00 \uc8fc\uc8fc\ud658\uc6d0\uc728\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uc8fc\ud658\uc6d0\uc728\uc740 \ubc30\ub2f9 \ucd1d\uc561\uacfc \uc790\uc0ac\uc8fc \ub9e4\uc785\uc561\uc744 \ud569\ud55c \uae08\uc561\uc744 \ub2f9\uae30\uc21c\uc774\uc775\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc21c\uc774\uc775 1\uc870 \uc6d0, \ubc30\ub2f9 3\ucc9c\uc5b5 \uc6d0, \uc790\uc0ac\uc8fc \ub9e4\uc785 2\ucc9c\uc5b5 \uc6d0\uc774\ub77c\uba74 \uc8fc\uc8fc\ud658\uc6d0\uc728\uc740 50%\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc8fc\uc8fc\ud658\uc6d0\uc728\uc774 \ub192\ub2e4\uace0 \ubb34\uc870\uac74 \uc88b\uc740 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc124\ube44 \ud22c\uc790\ub098 \uc5f0\uad6c\uac1c\ubc1c\uc774 \ud544\uc694\ud55c \uae30\uc5c5\uc774 \ubb34\ub9ac\ud558\uac8c \ud658\uc6d0 \uaddc\ubaa8\ub97c \ub298\ub9ac\uba74 \ubbf8\ub798 \uc131\uc7a5 \uc7ac\uc6d0\uc774 \uc904\uc5b4\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\uc0ac\uc8fc \ub9e4\uc785\uc758 \uc790\uae08 \ucd9c\ucc98\\n\\n\uc790\uc0ac\uc8fc \ub9e4\uc785 \uc790\uae08\uc774 \uc5b4\ub514\uc5d0\uc11c \ub098\uc654\ub294\uc9c0\ub3c4 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc601\uc5c5\uc73c\ub85c \ubc88 \ud604\uae08\uc73c\ub85c \ub9e4\uc785\ud558\ub294 \uacbd\uc6b0\uc640 \ucc28\uc785\uc73c\ub85c \ub9e4\uc785\ud558\ub294 \uacbd\uc6b0\uc758 \uc7ac\ubb34 \ubd80\ub2f4\uc740 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\ubd80\ucc44\ube44\uc728\uc774 \uc774\ubbf8 \ub192\uc740 \uae30\uc5c5\uc774 \ucc28\uc785\uc73c\ub85c \uc790\uc0ac\uc8fc\ub97c \ub9e4\uc785\ud558\uba74 \uc7ac\ubb34 \uc548\uc815\uc131\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\uc785 \uaddc\ubaa8\uac00 \uc2dc\uac00\ucd1d\uc561 \ub300\ube44 \uc5bc\ub9c8\ub098 \ud070\uc9c0, \ub9e4\uc785 \uae30\uac04\uc774 \uc5bc\ub9c8\ub098 \uae34\uc9c0\ub3c4 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30\uac04\uc5d0 \ub300\uaddc\ubaa8 \ub9e4\uc785\uc774 \uc9d1\uc911\ub418\uba74 \uc8fc\uac00 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc790\uc0ac\uc8fc \uacf5\uc2dc\ub97c \ubcfc \ub54c\ub294 \ub9e4\uc785 \ubaa9\uc801\uacfc \uc18c\uac01 \uc5ec\ubd80\ub97c \uba3c\uc800 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc18c\uac01 \ubaa9\uc801\uc758 \ub9e4\uc785\uc778\uc9c0, \uc784\uc9c1\uc6d0 \ubcf4\uc0c1\uc774\ub098 \ucc98\ubd84 \ubaa9\uc801\uc758 \ub9e4\uc785\uc778\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uacf5\uc2dc\ub41c \ub9e4\uc785 \ud55c\ub3c4\uac00 \uc2e4\uc81c \ub9e4\uc785\uc73c\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0\ub294 \ubd84\uae30 \ubcf4\uace0\uc11c\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uc0ac\uc8fc \ub9e4\uc785 \ubc1c\ud45c \uc9c1\ud6c4\uc758 \uc8fc\uac00 \uc6c0\uc9c1\uc784\ub9cc \ubcf4\uace0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4, \uc2e4\uc801\uacfc \uc7ac\ubb34 \uc0c1\ud0dc\uac00 \ud568\uaed8 \ub4b7\ubc1b\uce68\ub418\ub294\uc9c0\ub97c \ubcf4\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uacfc \uc790\uc0ac\uc8fc\ub97c \ud569\uce5c \uc804\uccb4 \ud658\uc6d0 \uaddc\ubaa8\ub97c \uc5f0\ub3c4\ubcc4\ub85c \ube44\uad50\ud558\uba74 \uae30\uc5c5\uc758 \ud658\uc6d0 \uae30\uc870\ub97c \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc790\uc0ac\uc8fc \ub9e4\uc785\uc740 \uc218\uc694\ub97c \ub354\ud558\ub294 \uc870\uce58\uc774\uace0, \uc18c\uac01\uc740 \ubc1c\ud589 \uc8fc\uc2dd \uc218\ub97c \uc904\uc774\ub294 \uc870\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \ub2e8\uacc4\ub97c \uad6c\ubd84\ud558\uace0 \uc790\uae08 \ucd9c\ucc98\uc640 \uc2e4\ud589 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \uc8fc\uc8fc\ud658\uc6d0 \uacf5\uc2dc\uc758 \uc758\ubbf8\ub97c \ub354 \uc815\ud655\ud788 \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExc2VsdDZkcDZkdjU2ZHFudXcwcXJlZXQ0d3psemtwNHZ4b3NuOHc3dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/djN2KXp5dfQxIEhW0Z/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"emergency-fund-guide","metadata":{"permalink":"/blog/en/finance/emergency-fund-guide","source":"@site/finance/2026-10-27-emergency-fund-guide/index.mdx","title":"\ube44\uc0c1\uae08 \ub9c8\ub828\ud558\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-27T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"},{"inline":true,"label":"\ube44\uc0c1\uae08","permalink":"/blog/en/finance/tags/\ube44\uc0c1\uae08"},{"inline":true,"label":"\uc800\ucd95","permalink":"/blog/en/finance/tags/\uc800\ucd95"},{"inline":true,"label":"\uac00\uacc4\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac00\uacc4\uc7ac\ubb34"}],"readingTime":2.23,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"emergency-fund-guide","title":"\ube44\uc0c1\uae08 \ub9c8\ub828\ud558\ub294 \ubc95","authors":["way"],"tags":["finance","\uac1c\uc778\uc7ac\ubb34","\ube44\uc0c1\uae08","\uc800\ucd95","\uac00\uacc4\uc7ac\ubb34"]},"unlisted":false,"prevItem":{"title":"\uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \uc18c\uac01 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/buyback-cancellation-guide"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 3.09% \ubc18\ub4f1, 5,638\uc120 \ud68c\ubcf5","permalink":"/blog/en/finance/kospi-rebound-oct27"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud558\ub294 \ube44\uc0c1\uae08\uc744 \ub9c8\ub828\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ube44\uc0c1\uae08\uc740 \uc2e4\uc9c1, \uc9c8\ubcd1, \uac00\uc804 \uad50\uccb4 \uac19\uc740 \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud574 \ub530\ub85c \ub9c8\ub828\ud574 \ub450\ub294 \ub3c8\uc785\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uc774 \uc5c6\uc73c\uba74 \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc774 \uc0dd\uacbc\uc744 \ub54c \uace0\uae08\ub9ac \ub300\ucd9c\uc774\ub098 \ud22c\uc790 \uc790\uc0b0\uc758 \uae09\ub9e4\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud22c\uc790\ub97c \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \ube44\uc0c1\uae08\uc744 \uba3c\uc800 \ub9c8\ub828\ud558\ub77c\ub294 \uc870\uc5b8\uc774 \ub9ce\uc740 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uc740 \uc218\uc775\uc744 \ub0b4\uae30 \uc704\ud55c \ub3c8\uc774 \uc544\ub2c8\ub77c, \uc0dd\ud65c\uc758 \uc548\uc804\ub9dd\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud55c \ub3c8\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHRqaHVodHpibHVmdnd4MmYwZDA1c2l1OTAwOWI1bHNscDlnZW9nMyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/0dKHpamGLycEt3Ffyg/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ub9c8\ub828 \ubc29\ubc95\\n\\n#### \ubaa9\ud45c \uae08\uc561 \uc815\ud558\uae30\\n\\n\ube44\uc0c1\uae08\uc758 \uae30\uc900\uc73c\ub85c \ud754\ud788 \uc81c\uc2dc\ub418\ub294 \uaddc\ubaa8\ub294 \uc6d4 \uc0dd\ud65c\ube44\uc758 3\uac1c\uc6d4\uc5d0\uc11c 6\uac1c\uc6d4\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\uc6d4 \uc0dd\ud65c\ube44\uac00 200\ub9cc \uc6d0\uc774\ub77c\uba74 600\ub9cc \uc6d0\uc5d0\uc11c 1,200\ub9cc \uc6d0\uc774 \ubaa9\ud45c \ubc94\uc704\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc18c\ub4dd\uc774 \ubd88\uc548\uc815\ud55c \uc790\uc601\uc5c5\uc790\ub098 \uc678\ubc8c\uc774 \uac00\uad6c\ub77c\uba74 6\uac1c\uc6d4\ubd84 \uc774\uc0c1\uc744 \ubaa9\ud45c\ub85c \uc7a1\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9de\ubc8c\uc774\ub85c \uc18c\ub4dd\uc6d0\uc774 \ubd84\uc0b0\ub41c \uac00\uad6c\ub77c\uba74 3\uac1c\uc6d4\ubd84\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud558\ub2e4\ub294 \uacac\ud574\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa9\ud45c\ub294 \ud55c \ubc88\uc5d0 \ucc44\uc6b0\uae30\ubcf4\ub2e4, \ub2e8\uacc4\uc801\uc73c\ub85c \ucc44\uc6cc \ub098\uac00\ub294 \uac83\uc774 \ud604\uc2e4\uc801\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc5b4\ub514\uc5d0 \ub450\ub294 \uac83\uc774 \uc88b\uc740\uac00\\n\\n\ube44\uc0c1\uae08\uc740 \ud544\uc694\ud560 \ub54c \ubc14\ub85c \uaebc\ub0bc \uc218 \uc788\ub294 \uacf3\uc5d0 \ub450\ub294 \uac83\uc774 \uc6d0\uce59\uc785\ub2c8\ub2e4.<br/>\\n\uc785\ucd9c\uae08\uc774 \uc790\uc720\ub85c\uc6b4 \uc608\uae08\uc774\ub098 \uba38\ub2c8\ub9c8\ucf13\ud380\ub4dc(MMF) \uac19\uc740 \uc720\ub3d9\uc131 \ub192\uc740 \uc0c1\ud488\uc774 \uc8fc\ub85c \uc4f0\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00 \ubcc0\ub3d9\uc5d0 \ub530\ub77c \uc6d0\uae08\uc774 \uc904\uc5b4\ub4e4 \uc218 \uc788\ub294 \uc0c1\ud488\uc740 \ube44\uc0c1\uae08 \uc6a9\ub3c4\ub85c\ub294 \uc801\ud569\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uae30\uc608\uae08\ucc98\ub7fc \uc911\ub3c4 \ud574\uc9c0 \uc2dc \uc774\uc790 \uc190\uc2e4\uc774 \uc0dd\uae30\ub294 \uc0c1\ud488\ub3c4 \uae34\uae09 \uc0c1\ud669\uc5d0\uc11c \ubd88\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uc740 \uc0dd\ud65c\ube44 \uacc4\uc88c\uc640 \ubd84\ub9ac\ud574 \ub450\uba74, \ubb34\uc2ec\ucf54 \uc368 \ubc84\ub9ac\ub294 \uc77c\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ucc44\uc6b0\ub294 \uc21c\uc11c\uc640 \uc720\uc9c0 \ubc29\ubc95\\n\\n\ube44\uc0c1\uae08\uc740 \ud22c\uc790\ubcf4\ub2e4 \uba3c\uc800, \ub9e4\ub2ec \uc77c\uc815 \uae08\uc561\uc744 \uc790\ub3d9\uc774\uccb4\ub85c \uc313\ub294 \ubc29\uc2dd\uc774 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \ub9e4\ub2ec 30\ub9cc \uc6d0\uc529 \uc801\ub9bd\ud558\uba74 1\ub144 \ub4a4\uc5d0\ub294 360\ub9cc \uc6d0\uc774 \ubaa8\uc785\ub2c8\ub2e4.<br/>\\n1\ucc28 \ubaa9\ud45c\uc778 1\uac1c\uc6d4\ubd84\uc744 \uba3c\uc800 \ucc44\uc6b0\uace0, \uc774\ud6c4 3\uac1c\uc6d4\ubd84, 6\uac1c\uc6d4\ubd84\uc73c\ub85c \ub2e8\uacc4\ub97c \ub192\uc774\ub294 \ubc29\ubc95\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uc744 \uc0ac\uc6a9\ud55c \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \ucc44\uc6b0\ub294 \uac83\uc744 \uc0dd\ud65c\ube44 \uacc4\ud68d\uc5d0 \ud3ec\ud568\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0dd\ud65c\ube44 \uaddc\ubaa8\uac00 \ubc14\ub00c\uba74 \ube44\uc0c1\uae08 \ubaa9\ud45c\ub3c4 \ud568\uaed8 \uc870\uc815\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ube44\uc0c1\uae08 \ubaa9\ud45c\ub97c \uc815\ud560 \ub54c\ub294 \uace0\uc815\uc9c0\ucd9c\uacfc \ubcc0\ub3d9\uc9c0\ucd9c\uc744 \ub098\ub204\uc5b4 \uc0dd\ud65c\ube44\ub97c \uacc4\uc0b0\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uac70\ube44, \ud1b5\uc2e0\ube44, \ubcf4\ud5d8\ub8cc \uac19\uc740 \uace0\uc815\uc9c0\ucd9c\uc774 \uae30\uc900\uc774 \ub418\uba70, \uc678\uc2dd\ube44 \uac19\uc740 \ubcc0\ub3d9\uc9c0\ucd9c\uc740 \uc5ec\uc720 \uc788\uac8c \uc7a1\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uacfc \ud22c\uc790\uae08\uc744 \uac19\uc740 \uacc4\uc88c\uc5d0 \ub450\uba74, \uc2dc\uc7a5\uc774 \ud754\ub4e4\ub9b4 \ub54c \ube44\uc0c1\uae08\uae4c\uc9c0 \uc704\ud5d8\uc5d0 \ub178\ucd9c\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uc774 \ucda9\ubd84\ud788 \uc313\uc774\uae30 \uc804\uc5d0\ub294 \uace0\uc704\ud5d8 \uc0c1\ud488\uc758 \ube44\uc911\uc744 \ub0ae\ucd94\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\uc740 \ud55c \ubc88 \ub9c8\ub828\ud558\uace0 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc0dd\ud65c \ubcc0\ud654\uc5d0 \ub530\ub77c \uc8fc\uae30\uc801\uc73c\ub85c \uc810\uac80\ud558\ub294 \ud56d\ubaa9\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ube44\uc0c1\uae08\uc740 \uc218\uc775\uc744 \uc704\ud55c \ub3c8\uc774 \uc544\ub2c8\ub77c \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc5d0\ub3c4 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\uac8c \ud558\ub294 \uc548\uc804\ub9dd\uc785\ub2c8\ub2e4.<br/>\\n\uc6d4 \uc0dd\ud65c\ube44 3\uac1c\uc6d4\ubd84\uc5d0\uc11c 6\uac1c\uc6d4\ubd84\uc744 \ubaa9\ud45c\ub85c, \ubc14\ub85c \uaebc\ub0bc \uc218 \uc788\ub294 \uacf3\uc5d0 \ubd84\ub9ac\ud574 \ub450\ub294 \uac83\uc774 \uae30\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExc2VsdDZkcDZkdjU2ZHFudXcwcXJlZXQ0d3psemtwNHZ4b3NuOHc3dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/h0MTqLyvgG0Ss/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-rebound-oct27","metadata":{"permalink":"/blog/en/finance/kospi-rebound-oct27","source":"@site/finance/2026-10-27-kospi-rebound-oct27/index.mdx","title":"\ucf54\uc2a4\ud53c 3.09% \ubc18\ub4f1, 5,638\uc120 \ud68c\ubcf5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-27T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ub2e5"},{"inline":true,"label":"\ubc18\ub3c4\uccb4","permalink":"/blog/en/finance/tags/\ubc18\ub3c4\uccb4"},{"inline":true,"label":"\uc678\uad6d\uc778","permalink":"/blog/en/finance/tags/\uc678\uad6d\uc778"}],"readingTime":2.54,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-rebound-oct27","title":"\ucf54\uc2a4\ud53c 3.09% \ubc18\ub4f1, 5,638\uc120 \ud68c\ubcf5","authors":["way"],"tags":["finance","\uc2dc\uc7a5\uc815\ub9ac","\ucf54\uc2a4\ud53c","\ucf54\uc2a4\ub2e5","\ubc18\ub3c4\uccb4","\uc678\uad6d\uc778"]},"unlisted":false,"prevItem":{"title":"\ube44\uc0c1\uae08 \ub9c8\ub828\ud558\ub294 \ubc95","permalink":"/blog/en/finance/emergency-fund-guide"},"nextItem":{"title":"\uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/trading-volume-value-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 2026\ub144 10\uc6d4 27\uc77c \uad6d\ub0b4 \uc99d\uc2dc\uc758 \ubc18\ub4f1 \ud750\ub984\uacfc \uadf8 \ubc30\uacbd\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n10\uc6d4 27\uc77c \ucf54\uc2a4\ud53c\ub294 \uc804 \uac70\ub798\uc77c\ubcf4\ub2e4 168.87\ud3ec\uc778\ud2b8(3.09%) \uc624\ub978 5,638.34\uc5d0 \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \uc57d 7\uac1c\uc6d4 \ub9cc\uc5d0 \ucd5c\uc800\uce58\ub85c \ub5a8\uc5b4\uc84c\ub358 \uc9c0\uc218\ub294 \ud558\ub8e8 \ub9cc\uc5d0 \ubc18\ub4f1\ud558\uba70 5,600\uc120\uc744 \ub418\ucc3e\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uc804 \uac70\ub798\uc77c\ubcf4\ub2e4 16.62\ud3ec\uc778\ud2b8(2.29%) \uc624\ub978 743.83\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \uc9c0\uc218\ub294 \uac1c\uc7a5 \uc9c1\ud6c4\ubd80\ud130 \uac15\ud558\uac8c \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804 \uac70\ub798\uc77c\ubcf4\ub2e4 189.18\ud3ec\uc778\ud2b8(3.46%) \uc624\ub978 5,658.65\uc5d0 \uac1c\uc7a5\ud588\uace0, \uc7a5\uc911 5,737.61\uae4c\uc9c0 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ud3ed\uc774 \ucee4\uc9c0\uc790 \uc624\uc804 10\uc2dc 13\ubd84\uc5d0\ub294 \ucf54\uc2a4\ud53c200 \uc120\ubb3c \uae09\ub4f1\uc5d0 \ub530\ub978 \ub9e4\uc218 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub418\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMjhleml6aHhheThkNWl1emU1MDQ3cGRzejI5Nnp3eXlzZHhtZHo1cCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/26gsobowozGM9umBi/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubc18\ub4f1\uc758 \ubc30\uacbd\\n\\n#### \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\ud654\uc5d0 \ub300\ud55c \uae30\ub300 \ud68c\ubcf5\\n\\n\uc774\ubc88 \ubc18\ub4f1\uc758 \uc9c1\uc811\uc801\uc778 \uacc4\uae30\ub294 \ubbf8\uad6d \uc778\uacf5\uc9c0\ub2a5 \uae30\uc5c5 \uc564\ud2b8\ub85c\ud53d\uc758 \uc0c1\uc7a5 \uc2e0\uccad \uc11c\ub958 \uacf5\uac1c\ub85c \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\uc2e0\uc99d\uad8c \ubd84\uc11d\uc5d0 \ub530\ub974\uba74 \uc564\ud2b8\ub85c\ud53d\uc740 2026\ub144 2\ubd84\uae30 \ucef4\ud4e8\ud305 \ube44\uc6a9 1\ub2ec\ub7ec\ub2f9 \ub9e4\ucd9c\uc561 2.1\ub2ec\ub7ec\ub97c \uae30\ub85d\ud588\uace0, \uc601\uc5c5\uc774\uc775\uc740 9\uc5b5 7\ucc9c\ub9cc \ub2ec\ub7ec\ub85c \ud751\uc790 \uc804\ud658\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790\uc5d0 \ub300\ud55c \uc218\uc775\ud654 \uc6b0\ub824\uac00 \uc644\ud654\ub418\uba74\uc11c \ubc18\ub3c4\uccb4\uc8fc\uc5d0 \ub9e4\uc218\uc138\uac00 \uc720\uc785\ub410\ub2e4\ub294 \ud574\uc11d\uc785\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc2ec\ub9ac\uac00 \ud68c\ubcf5\ub418\ub294 \uacfc\uc815\uc5d0\uc11c \uad6d\ub0b4 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uac00 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc678\uad6d\uc778 \ub9e4\uc218\uc138 \ubcf5\uadc0\\n\\n\uc218\uae09 \uce21\uba74\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc758 \ubcf5\uadc0\uac00 \ub208\uc5d0 \ub744\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uac70\ub798\uc18c\uc640 \ub125\uc2a4\ud2b8\ub808\uc774\ub4dc \uae30\uc900\uc73c\ub85c \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0\uc11c \uc678\uad6d\uc778\uc740 8,359\uc5b5 \uc6d0, \uae30\uad00\uc740 4,185\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uac1c\uc778\uc740 1\uc870 4,046\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 4\uac70\ub798\uc77c \ub9cc\uc5d0 \ud604\ubb3c\uacfc \uc120\ubb3c \ub3d9\ubc18 \uc21c\ub9e4\uc218\ub85c \uc804\ud658\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uac01\uac01 647\uc5b5 \uc6d0, 1,537\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uac1c\uc778\uc740 2,062\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub300\ud615\uc8fc \ud750\ub984\\n\\n\uc0bc\uc131\uc804\uc790\ub294 \uc804 \uac70\ub798\uc77c\ubcf4\ub2e4 9,000\uc6d0(4.23%) \uc624\ub978 22\ub9cc 2,000\uc6d0\uc5d0 \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\nSK\ud558\uc774\ub2c9\uc2a4\ub294 6\ub9cc 6,000\uc6d0(5.18%) \uc624\ub978 134\ub9cc 1,000\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nSK\uc2a4\ud018\uc5b4(7.67%)\uc640 \uc0bc\uc131\uc804\uae30(7.42%)\ub3c4 7%\ub300 \uc0c1\uc2b9\ub960\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc0bc\uc131\ubc14\uc774\uc624\ub85c\uc9c1\uc2a4\ub294 5.37% \ud558\ub77d\ud558\uba70 \uc5c5\uc885\ubcc4 \ud750\ub984\uc774 \uc5c7\uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 \uc8fc\uac04\uac70\ub798 \uae30\uc900 \uc804\uc77c\ubcf4\ub2e4 0.6\uc6d0 \uc624\ub978 1,323.7\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \uacf5\uac1c\ub41c \ud55c\uad6d 3\ubd84\uae30 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0(GDP)\uc740 \uc804\ub144 \ub3d9\uae30 \ub300\ube44 3.4% \uc131\uc7a5\ud558\uba70 \uacac\uc870\ud55c \uacbd\uae30 \ud750\ub984\uc744 \ud655\uc778\ud574 \uc8fc\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ud558\ub8e8\uc758 \uae09\ubc18\ub4f1\ub9cc\uc73c\ub85c \ucd94\uc138 \uc804\ud658\uc744 \ub2e8\uc815\ud558\ub294 \uac83\uc740 \uc704\ud5d8\ud569\ub2c8\ub2e4.<br/>\\n\uae09\ub4f1\uc77c\uc5d0\ub294 \ub2e8\uae30 \ucc28\uc775 \ub9e4\ubb3c\uc774 \ub098\uc62c \uc218 \uc788\uace0, \uc9c0\uc218\uc640 \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc774 \ub2e4\ub974\uac8c \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\uc218\uc138\uac00 \uba70\uce60 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ubc18\ub3c4\uccb4 \uc5c5\uc885\uc758 \uc2e4\uc801 \uc804\ub9dd\uc774 \uc720\uc9c0\ub418\ub294\uc9c0\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc9c0\ud45c\ub85c\ub294 \ubbf8\uad6d \uc778\uacf5\uc9c0\ub2a5 \uae30\uc5c5\uc758 \uc2e4\uc801 \ubc1c\ud45c\uc640 \uad6d\ub0b4 \uae30\uc5c5\uc758 3\ubd84\uae30 \uc2e4\uc801 \ubc1c\ud45c \uc77c\uc815\uc774 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uacfc \uae08\ub9ac \ubc29\ud5a5\ub3c4 \uc9c0\uc218 \ud750\ub984\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \ubcc0\uc218\uc774\ubbc0\ub85c \ud568\uaed8 \uc810\uac80\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n10\uc6d4 27\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc775\ud654 \uae30\ub300\uc640 \uc678\uad6d\uc778 \ub9e4\uc218\uc138 \ubcf5\uadc0\uc5d0 \ud798\uc785\uc5b4 \ud06c\uac8c \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc758 \uc9c0\uc18d \uc5ec\ubd80\ub294 \uc218\uae09\uc758 \uc5f0\uc18d\uc131\uacfc \uc2e4\uc801\uc774\ub77c\ub294 \uadfc\uac70\uac00 \ub4b7\ubc1b\uce68\ub418\ub294\uc9c0\uc5d0 \ub2ec\ub824 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHRqaHVodHpibHVmdnd4MmYwZDA1c2l1OTAwOWI1bHNscDlnZW9nMyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/879RsXB8GvEuY95LNl/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n\ucd9c\ucc98: [\ub274\uc2a4\ud54c \ub9c8\uac10\uc2dc\ud669](https://newspim.com/news/view/20261027000983), [\uba38\ub2c8\ud22c\ub370\uc774 \ub9c8\uac10\uc2dc\ud669](https://www.mt.co.kr/stock/2026/10/27/2026102715521372601)"},{"id":"trading-volume-value-guide","metadata":{"permalink":"/blog/en/finance/trading-volume-value-guide","source":"@site/finance/2026-10-27-trading-volume-value-guide/index.mdx","title":"\uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08 \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-27T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\ub150","permalink":"/blog/en/finance/tags/\uac1c\ub150"},{"inline":true,"label":"\uac70\ub798\ub7c9","permalink":"/blog/en/finance/tags/\uac70\ub798\ub7c9"},{"inline":true,"label":"\uac70\ub798\ub300\uae08","permalink":"/blog/en/finance/tags/\uac70\ub798\ub300\uae08"},{"inline":true,"label":"\uc2dc\uc7a5\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc9c0\ud45c"}],"readingTime":2.17,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"trading-volume-value-guide","title":"\uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08 \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","\uac1c\ub150","\uac70\ub798\ub7c9","\uac70\ub798\ub300\uae08","\uc2dc\uc7a5\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 3.09% \ubc18\ub4f1, 5,638\uc120 \ud68c\ubcf5","permalink":"/blog/en/finance/kospi-rebound-oct27"},"nextItem":{"title":"\uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640 \uc804\ub3d9\ud654 \uc804\ud658 \uc77d\uae30","permalink":"/blog/en/finance/auto-industry-structure"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uc8fc\uac00\uc640 \ud568\uaed8 \ud45c\uc2dc\ub418\ub294 \uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08\uc744 \uc77d\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uac70\ub798\ub7c9\uc740 \uc77c\uc815 \uae30\uac04 \ub3d9\uc548 \uac70\ub798\ub41c \uc8fc\uc2dd\uc758 \uc218\ub7c9\uc744 \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub300\uae08\uc740 \uac70\ub798\ub7c9\uc5d0 \uac70\ub798 \uac00\uaca9\uc744 \uacf1\ud55c \uae08\uc561\uc73c\ub85c, \uc2e4\uc81c\ub85c \uc624\uac04 \ub3c8\uc758 \uaddc\ubaa8\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\uac00 \uc62c\ub790\ub294\uc9c0 \ub0b4\ub838\ub294\uc9c0\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4, \uadf8 \uc6c0\uc9c1\uc784\uc5d0 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uac70\ub798\uac00 \ub3d9\ubc18\ub410\ub294\uc9c0\ub97c \ud568\uaed8 \ubcf4\uba74 \ud750\ub984\uc758 \uac15\ub3c4\ub97c \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub7c9\uc774 \uae09\uc99d\ud55c \ub0a0\uc740 \uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4\uc758 \uad00\uc2ec\uc774 \uc9d1\uc911\ub410\ub2e4\ub294 \uc2e0\ud638\ub85c \ud574\uc11d\ub418\uae30\ub3c4 \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMjhleml6aHhheThkNWl1emU1MDQ3cGRzejI5Nnp3eXlzZHhtZHo1cCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/FJcm8sN3t2WVyBATK7/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ud575\uc2ec \uac1c\ub150\\n\\n#### \uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08\uc758 \ucc28\uc774\\n\\n\uac70\ub798\ub7c9\uc774 \uac19\uc544\ub3c4 \uc8fc\uac00 \uc218\uc900\uc774 \ub2e4\ub974\uba74 \uac70\ub798\ub300\uae08\uc740 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc8fc\uac00\uac00 10\ub9cc \uc6d0\uc778 \uc8fc\uc2dd 1\ub9cc \uc8fc\uc640 \uc8fc\uac00\uac00 1\ub9cc \uc6d0\uc778 \uc8fc\uc2dd 1\ub9cc \uc8fc\uc758 \uac70\ub798\ub300\uae08\uc740 \uac01\uac01 10\uc5b5 \uc6d0\uacfc 1\uc5b5 \uc6d0\uc785\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc774 \ub192\uc740 \ub300\ud615\uc8fc\ub294 \uac70\ub798\ub7c9\uc774 \uc801\uc5b4\ub3c4 \uac70\ub798\ub300\uae08\uc774 \ud074 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uac00\uaca9\uc774 \ub0ae\uc740 \uc885\ubaa9\uc740 \uac70\ub798\ub7c9\uc774 \ub9ce\uc544\ub3c4 \uac70\ub798\ub300\uae08\uc774 \ud06c\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uc804\uccb4\uc758 \uc790\uae08 \ud750\ub984\uc744 \ubcfc \ub54c\ub294 \uac70\ub798\ub300\uae08\uc774, \uac1c\ubcc4 \uc885\ubaa9\uc758 \uac70\ub798 \ud65c\ubc1c\ub3c4\ub97c \ubcfc \ub54c\ub294 \uac70\ub798\ub7c9\uc774 \uc8fc\ub85c \uc4f0\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uac70\ub798\ub7c9 \uae09\uc99d\uc774 \uc758\ubbf8\ud558\ub294 \uac83\\n\\n\uc8fc\uac00\uac00 \uc624\ub974\uba74\uc11c \uac70\ub798\ub7c9\uc774 \ud568\uaed8 \ub298\uba74 \ub9e4\uc218\uc138\uac00 \uac15\ud558\ub2e4\ub294 \ud574\uc11d\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\uac00 \ub0b4\ub9ac\uba74\uc11c \uac70\ub798\ub7c9\uc774 \ub298\uba74 \ub9e4\ub3c4\uc138\uac00 \uac15\ud558\ub2e4\ub294 \ud574\uc11d\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\ub294 \ud06c\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub370 \uac70\ub798\ub7c9\ub9cc \uae09\uc99d\ud558\uba74 \ub9e4\uc218\uc138\uc640 \ub9e4\ub3c4\uc138\uac00 \ud33d\ud33d\ud788 \ub9de\uc11c\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uac70\ub798\ub7c9 \uae09\uc99d \uc790\uccb4\uac00 \ubc29\ud5a5\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub274\uc2a4\ub098 \uc2e4\uc801 \ubc1c\ud45c \uac19\uc740 \uc7ac\ub8cc\uc640 \ud568\uaed8 \ub098\ud0c0\ub09c \uac70\ub798\ub7c9 \uae09\uc99d\uc740 \uc7ac\ub8cc \uc18c\uba78 \uc774\ud6c4 \uac70\ub798\ub7c9\uc774 \ube60\ub974\uac8c \uc904\uc5b4\ub4e4\uae30\ub3c4 \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud3c9\uade0 \uac70\ub798\ub7c9\uacfc\uc758 \ube44\uad50\\n\\n\ud558\ub8e8\uc758 \uac70\ub798\ub7c9\uc740 \uacfc\uac70 \ud3c9\uade0\uacfc \ube44\uad50\ud560 \ub54c \uc758\ubbf8\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ud3c9\uc18c\ubcf4\ub2e4 \uba87 \ubc30 \ub9ce\uc740 \uac70\ub798\ub7c9\uc740 \uc774\ub840\uc801\uc778 \uad00\uc2ec\uc774\ub098 \uc218\uae09 \ubcc0\ud654\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc99d\uad8c\uc0ac MTS\uc5d0\uc11c\ub294 \ubcf4\ud1b5 20\uc77c \ud3c9\uade0 \uac70\ub798\ub7c9 \uac19\uc740 \uc9c0\ud45c\ub97c \ud568\uaed8 \uc81c\uacf5\ud569\ub2c8\ub2e4.<br/>\\n\ud3c9\uade0 \ub300\ube44 \uac70\ub798\ub7c9\uc774 \uae09\uc99d\ud55c \uc885\ubaa9\uc740 \ub2e8\uae30 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \uc8fc\uc758\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub7c9\uc774 \uc7a5\uae30\uac04 \uc904\uc5b4\ub4e0 \uc885\ubaa9\uc740 \uc6d0\ud558\ub294 \uac00\uaca9\uc5d0 \uac70\ub798\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uac70\ub798\ub7c9\uc744 \ubcfc \ub54c\ub294 \uac00\uaca9 \ubc29\ud5a5\uacfc \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uae30\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9\uc77c\uc5d0 \uac70\ub798\ub7c9\uc774 \ub298\uc5c8\ub294\uc9c0, \ud558\ub77d\uc77c\uc5d0 \uac70\ub798\ub7c9\uc774 \ub298\uc5c8\ub294\uc9c0\ub97c \uad6c\ubd84\ud558\uba74 \ud574\uc11d\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub300\uae08 \uc0c1\uc704 \uc885\ubaa9\uc744 \ubcf4\uba74 \ub2f9\uc77c \uc2dc\uc7a5\uc758 \uc790\uae08\uc774 \uc5b4\ub514\uc5d0 \ubab0\ub838\ub294\uc9c0\ub97c \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub7c9 \uae09\uc99d\uc774 \ub2e8 \ud558\ub8e8\uc5d0 \uadf8\uce58\ub294\uc9c0, \uba70\uce60 \uc774\uc5b4\uc9c0\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub7c9 \uc9c0\ud45c\ub9cc\uc73c\ub85c \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uacb0\uc815\ud558\uae30\ubcf4\ub2e4, \uc2e4\uc801\uacfc \uc218\uae09, \uc2dc\uc7a5 \ud750\ub984\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uac70\ub798\ub7c9\uc740 \uac70\ub798\uc758 \ud65c\ubc1c\ub3c4\ub97c, \uac70\ub798\ub300\uae08\uc740 \uc790\uae08\uc758 \uaddc\ubaa8\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uac00\uaca9 \ubc29\ud5a5\uacfc \ud3c9\uade0 \uac70\ub798\ub7c9\uc744 \ud568\uaed8 \ubcf4\uba74 \ud558\ub8e8 \uc8fc\uac00 \uc6c0\uc9c1\uc784\uc758 \uac15\ub3c4\ub97c \ub354 \uc815\ud655\ud788 \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExenZnMmp3dWFwajUxY3Mydmt3OHJ5M2YzZDYxbzVyN3MzcXdtOWd5NSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/YUUFqPfYVUrvIFzEUJ/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"auto-industry-structure","metadata":{"permalink":"/blog/en/finance/auto-industry-structure","source":"@site/finance/2026-10-26-auto-industry-structure/index.mdx","title":"\uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640 \uc804\ub3d9\ud654 \uc804\ud658 \uc77d\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-26T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc139\ud130","permalink":"/blog/en/finance/tags/\uc139\ud130"},{"inline":true,"label":"\uc790\ub3d9\ucc28","permalink":"/blog/en/finance/tags/\uc790\ub3d9\ucc28"},{"inline":true,"label":"\uc804\uae30\ucc28","permalink":"/blog/en/finance/tags/\uc804\uae30\ucc28"},{"inline":true,"label":"\ud558\uc774\ube0c\ub9ac\ub4dc","permalink":"/blog/en/finance/tags/\ud558\uc774\ube0c\ub9ac\ub4dc"},{"inline":true,"label":"\uc0b0\uc5c5\uad6c\uc870","permalink":"/blog/en/finance/tags/\uc0b0\uc5c5\uad6c\uc870"}],"readingTime":1.98,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"auto-industry-structure","title":"\uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640 \uc804\ub3d9\ud654 \uc804\ud658 \uc77d\uae30","authors":["way"],"tags":["finance","\uc139\ud130","\uc790\ub3d9\ucc28","\uc804\uae30\ucc28","\ud558\uc774\ube0c\ub9ac\ub4dc","\uc0b0\uc5c5\uad6c\uc870"]},"unlisted":false,"prevItem":{"title":"\uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/trading-volume-value-guide"},"nextItem":{"title":"\uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218(CPI) \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/cpi-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc758 \uac00\uce58\uc0ac\uc2ac \uad6c\uc870\uc640 \uc804\ub3d9\ud654 \uc804\ud658 \ud750\ub984\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc790\ub3d9\ucc28\ub294 \ub2e8\uc77c \uc81c\ud488\uc774 \uc544\ub2c8\ub77c \uc218\ub9cc \uac1c\uc758 \ubd80\ud488\uc774 \ubaa8\uc778 \uc2dc\uc2a4\ud15c \uc0b0\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc644\uc131\ucc28 \uc5c5\uccb4\ub97c \uc911\uc2ec\uc73c\ub85c \ubd80\ud488\uc0ac, \uc18c\uc7ac\uc0ac, \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uc5c5\uccb4\uac00 \uae34 \uacf5\uae09\ub9dd\uc73c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc\uc5d0\ub294 \ub0b4\uc5f0\uae30\uad00 \uc911\uc2ec\uc5d0\uc11c \ud558\uc774\ube0c\ub9ac\ub4dc\uc640 \uc804\uae30\ucc28\ub85c \ubb34\uac8c\uc911\uc2ec\uc774 \uc774\ub3d9\ud558\uba70 \uc0b0\uc5c5\uc758 \uad6c\uc870 \uc790\uccb4\uac00 \ubc14\ub00c\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub3d9\ud654\ub294 \ub2e8\uc21c\ud55c \ub3d9\ub825\uc6d0 \uad50\uccb4\uac00 \uc544\ub2c8\ub77c, \uc0b0\uc5c5\uc758 \uacbd\uc7c1 \uc694\uc18c\uac00 \ubb34\uc5c7\uc778\uc9c0\ub97c \ubc14\uafb8\ub294 \ubcc0\ud654\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExczhmYXRycm12OGhtODhiM2sxc3lmYmYzcDlpeGo1eGZxa3F5Mm9vOCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/A0fBO6nktSpxk9rO4L/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc758 \uac00\uce58\uc0ac\uc2ac\\n\\n#### \uc644\uc131\ucc28\uc640 \ubd80\ud488\uc758 \ubd84\uc5c5 \uad6c\uc870\\n\\n\uc644\uc131\ucc28 \uc5c5\uccb4\ub294 \ucc28\ub7c9\uc744 \uc124\uacc4\ud558\uace0 \ucd5c\uc885 \uc870\ub9bd\ud558\uba70 \ube0c\ub79c\ub4dc\uc640 \ud310\ub9e4\ub9dd\uc744 \ucc45\uc784\uc9d1\ub2c8\ub2e4.<br/>\\n\ubd80\ud488\uc0ac\ub294 \uc5d4\uc9c4, \ubcc0\uc18d\uae30, \ucc28\uccb4, \uc804\uc7a5 \ubd80\ud488 \ub4f1\uc744 \ub098\ub204\uc5b4 \ub9e1\uc2b5\ub2c8\ub2e4.<br/>\\n1\ucc28 \ubd80\ud488\uc0ac\uac00 \uc644\uc131\ucc28 \uc5c5\uccb4\uc5d0 \uc9c1\uc811 \ub0a9\ud488\ud558\uace0, 2\ucc28\uc640 3\ucc28 \ubd80\ud488\uc0ac\uac00 \uadf8 \uc544\ub798\uc5d0\uc11c \uc18c\uc7ac\uc640 \uc18c\ud615 \ubd80\ud488\uc744 \uacf5\uae09\ud558\ub294 \uacc4\uce35 \uad6c\uc870\uac00 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 \uc644\uc131\ucc28 \ud310\ub9e4\ub7c9\uc774 \ubcc0\ud558\uba74 \ubd80\ud488\uc0ac \uc2e4\uc801\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc804\ub3d9\ud654\uc5d0\uc11c \ubc14\ub00c\ub294 \ubd80\ud488 \uc9c0\ub3c4\\n\\n\uc804\uae30\ucc28\ub294 \uc5d4\uc9c4\uacfc \ubcc0\uc18d\uae30\uac00 \uc0ac\ub77c\uc9c0\uace0 \ubc30\ud130\ub9ac, \ubaa8\ud130, \uc804\ub825 \uc81c\uc5b4 \uc7a5\uce58\uac00 \ud575\uc2ec\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ubd80\ud488 \uc218\ub294 \ub0b4\uc5f0\uae30\uad00\ucc28\ubcf4\ub2e4 \uc904\uc5b4\ub4e4\uc9c0\ub9cc, \ubc30\ud130\ub9ac \uc6d0\uac00 \ube44\uc911\uc774 \ucee4\uc9c0\uba70 \uc6d0\uc7ac\ub8cc \uac00\uaca9\uc758 \uc601\ud5a5\ub825\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc18c\ud504\ud2b8\uc6e8\uc5b4 \ube44\uc911\ub3c4 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc8fc\ud589 \ubcf4\uc870, \uc778\ud3ec\ud14c\uc778\uba3c\ud2b8, \ubb34\uc120 \uc5c5\ub370\uc774\ud2b8 \uae30\ub2a5\uc774 \ucc28\ub7c9\uc758 \ucc28\ubcc4\ud654 \uc694\uc18c\ub85c \ub5a0\uc624\ub974\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud558\uc774\ube0c\ub9ac\ub4dc\uc758 \uac00\uad50 \uc5ed\ud560\\n\\n\ud558\uc774\ube0c\ub9ac\ub4dc\ub294 \ub0b4\uc5f0\uae30\uad00\uacfc \uc804\uae30 \uad6c\ub3d9\uc744 \ud568\uaed8 \uc4f0\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\ucda9\uc804 \uc778\ud504\ub77c\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc9c0\uc5ed\uc5d0\uc11c\ub3c4 \uc5f0\ube44\ub97c \uac1c\uc120\ud560 \uc218 \uc788\uc5b4 \uc804\ud658\uae30\uc758 \uac00\uad50 \uc5ed\ud560\uc744 \ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc \uae00\ub85c\ubc8c \ud310\ub9e4\uc5d0\uc11c\ub294 \ud558\uc774\ube0c\ub9ac\ub4dc \ube44\uc911\uc774 \ub2e4\uc2dc \uc8fc\ubaa9\ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uae30\ucc28 \uc804\ud658 \uc18d\ub3c4\uc640 \ud558\uc774\ube0c\ub9ac\ub4dc \uc218\uc694\uac00 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294\uc9c0\ub97c \ubcf4\ub294 \uac83\uc774 \uc0b0\uc5c5 \ud750\ub984\uc744 \uc77d\ub294 \ud558\ub098\uc758 \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc744 \ubcfc \ub54c\ub294 \ud310\ub9e4\ub7c9\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ud310\ub9e4\ub7c9, \ud3c9\uade0 \ud310\ub9e4 \uac00\uaca9, \uc778\uc13c\ud2f0\ube0c \uaddc\ubaa8, \uc7ac\uace0 \uc77c\uc218\ub97c \ud568\uaed8 \ubcf4\uba74 \uc218\uc775\uc131 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc5ed\ubcc4 \ud310\ub9e4 \ube44\uc911\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d, \uc720\ub7fd, \uc911\uad6d \uc2dc\uc7a5\uc758 \uaddc\uc81c\uc640 \uad00\uc138 \ud658\uacbd\uc774 \ub2ec\ub77c \uac19\uc740 \ud310\ub9e4\ub7c9\uc774\ub77c\ub3c4 \uc218\uc775\uc131\uc774 \ub2e4\ub974\uac8c \ub098\ud0c0\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ubc30\ud130\ub9ac \uc6d0\uc7ac\ub8cc \uac00\uaca9\uacfc \ud658\uc728\ub3c4 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9ac\ud2ac, \ub2c8\ucf08 \uac19\uc740 \uc6d0\uc7ac\ub8cc \uac00\uaca9\uacfc \uc6d0\ub2ec\ub7ec \ud658\uc728\uc740 \uc6d0\uac00\uc640 \uc218\ucd9c \ucc44\uc0b0\uc5d0 \ub3d9\uc2dc\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc740 \uc644\uc131\ucc28\ubd80\ud130 \ubd80\ud488, \uc18c\uc7ac, \uc18c\ud504\ud2b8\uc6e8\uc5b4\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uae34 \uc0ac\uc2ac\ub85c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\uc804\ub3d9\ud654 \uc804\ud658\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubd80\ud488\uc774 \uc0ac\ub77c\uc9c0\uace0 \uc5b4\ub5a4 \uc5ed\ub7c9\uc774 \uc0c8\ub85c \uc911\uc694\ud574\uc9c0\ub294\uc9c0\ub97c \uad6c\ubd84\ud574 \ubcf4\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMXF3dW45bzhuODVtbzFtZmY4eTJub2RscnJ1OHRqZnFxazAwbm1jYyZlcD12MV9jaGFubmVsc19zZWFyY2gmY3Q9cw/mXUhGMd5DczANEDiRm/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"cpi-guide","metadata":{"permalink":"/blog/en/finance/cpi-guide","source":"@site/finance/2026-10-26-cpi-guide/index.mdx","title":"\uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218(CPI) \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-26T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\ub150","permalink":"/blog/en/finance/tags/\uac1c\ub150"},{"inline":true,"label":"CPI","permalink":"/blog/en/finance/tags/cpi"},{"inline":true,"label":"\ubb3c\uac00","permalink":"/blog/en/finance/tags/\ubb3c\uac00"},{"inline":true,"label":"\uc778\ud50c\ub808\uc774\uc158","permalink":"/blog/en/finance/tags/\uc778\ud50c\ub808\uc774\uc158"},{"inline":true,"label":"\uacbd\uc81c\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uacbd\uc81c\uc9c0\ud45c"}],"readingTime":1.94,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"cpi-guide","title":"\uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218(CPI) \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","\uac1c\ub150","CPI","\ubb3c\uac00","\uc778\ud50c\ub808\uc774\uc158","\uacbd\uc81c\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\uc790\ub3d9\ucc28 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640 \uc804\ub3d9\ud654 \uc804\ud658 \uc77d\uae30","permalink":"/blog/en/finance/auto-industry-structure"},"nextItem":{"title":"\ud1f4\uc9c1\uc5f0\uae08 DC\ud615 \ub514\ud3f4\ud2b8\uc635\uc158 \uc774\ud574\ud558\uae30","permalink":"/blog/en/finance/dc-default-option"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \ubb3c\uac00\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub300\ud45c \uc9c0\ud45c\uc778 \uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218(CPI)\ub97c \uc77d\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218\ub294 \uc77c\ubc18 \uac00\uad6c\uac00 \uad6c\uc785\ud558\ub294 \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \uac00\uaca9 \ubcc0\ub3d9\uc744 \uce21\uc815\ud55c \uc9c0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc5d0\uc11c\ub294 \ub178\ub3d9\ud1b5\uacc4\uad6d\uc774 \ub9e4\ub2ec \ubc1c\ud45c\ud558\uace0, \ud55c\uad6d\uc5d0\uc11c\ub294 \ud1b5\uacc4\uccad\uc774 \uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218\ub97c \ubc1c\ud45c\ud569\ub2c8\ub2e4.<br/>\\n\uc911\uc559\uc740\ud589\uc774 \uae08\ub9ac\ub97c \uacb0\uc815\ud560 \ub54c \ubb3c\uac00 \uc9c0\ud45c\ub97c \ud575\uc2ec \uadfc\uac70\ub85c \uc0bc\uae30 \ub54c\ubb38\uc5d0, CPI \ubc1c\ud45c\uc77c\uc740 \uc2dc\uc7a5\uc774 \uc8fc\ubaa9\ud558\ub294 \uc77c\uc815\uc785\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00\uac00 \uc624\ub974\uba74 \ud654\ud3d0\uc758 \uad6c\ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c0\uace0, \uae08\ub9ac\uc640 \uc790\uc0b0 \uac00\uaca9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHlnbjZ4N3g5YmkybHQ2ODRpcndlcWh4b3Nwb3l3Njl0YnM0ZGZodCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3o7aTwT5vjBVfsYEj6/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### CPI\uc758 \uad6c\uc131\\n\\n#### \ubc14\uc2a4\ucf13\uacfc \uac00\uc911\uce58\\n\\nCPI\ub294 \uac00\uacc4\uac00 \uc18c\ube44\ud558\ub294 \ud488\ubaa9\uc744 \ub2f4\uc740 \ubc14\uc2a4\ucf13\uc744 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\ud488\ubaa9\ub9c8\ub2e4 \uac00\uacc4 \uc9c0\ucd9c\uc5d0\uc11c \ucc28\uc9c0\ud558\ub294 \ube44\uc911\uc5d0 \ub530\ub77c \uac00\uc911\uce58\uac00 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc8fc\uac70\ube44, \uc2dd\ub8cc\ud488, \uad50\ud1b5, \uc758\ub8cc \uac19\uc740 \ud56d\ubaa9\uc758 \uac00\uc911\uce58\uac00 \ud070 \ud3b8\uc785\ub2c8\ub2e4.<br/>\\n\uac00\uc911\uce58\ub294 \uc18c\ube44 \uad6c\uc870 \ubcc0\ud654\uc5d0 \ub530\ub77c \uc8fc\uae30\uc801\uc73c\ub85c \uc870\uc815\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ud5e4\ub4dc\ub77c\uc778\uacfc \uadfc\uc6d0 \uc9c0\uc218\\n\\n\ud5e4\ub4dc\ub77c\uc778 CPI\ub294 \ubaa8\ub4e0 \ud488\ubaa9\uc744 \ud3ec\ud568\ud55c \uc804\uccb4 \uc9c0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\uc6d0 CPI\ub294 \uac00\uaca9 \ubcc0\ub3d9\uc774 \ud070 \uc2dd\ub8cc\ud488\uacfc \uc5d0\ub108\uc9c0\ub97c \uc81c\uc678\ud55c \uc9c0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uc559\uc740\ud589\uc740 \uae30\uc870\uc801\uc778 \ubb3c\uac00 \ud750\ub984\uc744 \ubcf4\uae30 \uc704\ud574 \uadfc\uc6d0 \uc9c0\uc218\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uc2dd\ub8cc\ud488\uacfc \uc5d0\ub108\uc9c0 \uac00\uaca9\uc740 \uad6d\uc81c \uc6d0\uc790\uc7ac \uac00\uaca9\uc774\ub098 \uacc4\uc808 \uc694\uc778\uc5d0 \ud06c\uac8c \ud754\ub4e4\ub9ac\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc804\ub144 \ub300\ube44\uc640 \uc804\uc6d4 \ub300\ube44\\n\\nCPI\ub294 \ubcf4\ud1b5 \uc804\ub144 \uac19\uc740 \ub2ec \ub300\ube44 \uc0c1\uc2b9\ub960\uacfc \uc804\uc6d4 \ub300\ube44 \uc0c1\uc2b9\ub960 \ub450 \uac00\uc9c0\ub85c \ubc1c\ud45c\ub429\ub2c8\ub2e4.<br/>\\n\uc804\ub144 \ub300\ube44 \uc0c1\uc2b9\ub960\uc740 \uae30\uc870\ub97c, \uc804\uc6d4 \ub300\ube44 \uc0c1\uc2b9\ub960\uc740 \ucd5c\uadfc \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc804\ub144 \ub300\ube44 \uc0c1\uc2b9\ub960\uc774 3%\ub77c\uba74, 1\ub144 \uc804 \uac19\uc740 \ub2ec\ubcf4\ub2e4 \ubb3c\uac00\uac00 3% \uc62c\ub790\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc6d4 \ub300\ube44 \uc218\uce58\ub97c \uc5f0\uc728\ub85c \ud658\uc0b0\ud558\uba74 \ucd5c\uadfc \ubb3c\uac00 \uc555\ub825\uc744 \ub354 \ube60\ub974\uac8c \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\nCPI\ub97c \ubcfc \ub54c\ub294 \uc218\uce58 \ud558\ub098\ub9cc \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ud5e4\ub4dc\ub77c\uc778\uacfc \uadfc\uc6d0, \uc0c1\ud488 \ubb3c\uac00\uc640 \uc11c\ube44\uc2a4 \ubb3c\uac00\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74 \ubb3c\uac00 \uc0c1\uc2b9\uc758 \uc131\uaca9\uc774 \ub4dc\ub7ec\ub0a9\ub2c8\ub2e4.<br/>\\n\uc8fc\uac70\ube44\ucc98\ub7fc \uc9c0\uc218\uc5d0 \ubc18\uc601\uc774 \ub2a6\uac8c \ub098\ud0c0\ub098\ub294 \ud56d\ubaa9\uc740 \ubc29\ud5a5 \uc804\ud658 \uc2dc\uc810\uc744 \uac00\ub2a0\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\ub3c4 \uc5fc\ub450\uc5d0 \ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c \uc9c1\ud6c4 \uc2dc\uc7a5\uc774 \ud06c\uac8c \uc6c0\uc9c1\uc774\ub354\ub77c\ub3c4, \ud55c \ub2ec \uc218\uce58\ub9cc\uc73c\ub85c \uae08\ub9ac \uacbd\ub85c\ub97c \ub2e8\uc815\ud558\ub294 \uac83\uc740 \uc704\ud5d8\ud569\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \ub2ec\uc758 \ucd94\uc138\uc640 \uace0\uc6a9 \uc9c0\ud45c, \uc911\uc559\uc740\ud589 \uad00\uacc4\uc790\uc758 \ubc1c\uc5b8\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nCPI\ub294 \uac00\uacc4\uac00 \uccb4\uac10\ud558\ub294 \ubb3c\uac00 \ud750\ub984\uc744 \uc22b\uc790\ub85c \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\ud5e4\ub4dc\ub77c\uc778\uacfc \uadfc\uc6d0, \uc804\ub144 \ub300\ube44\uc640 \uc804\uc6d4 \ub300\ube44\ub97c \uad6c\ubd84\ud574 \uc77d\uc73c\uba74 \ubc1c\ud45c\uc758 \uc758\ubbf8\ub97c \ub354 \uc815\ud655\ud788 \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMThtNGQ0ajU2YWV5b2tiNm92eG41NnNmbGVlcjZleHRjajJmcmt6ZCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/G2b7D9VylgJYbvr9rD/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"dc-default-option","metadata":{"permalink":"/blog/en/finance/dc-default-option","source":"@site/finance/2026-10-26-dc-default-option/index.mdx","title":"\ud1f4\uc9c1\uc5f0\uae08 DC\ud615 \ub514\ud3f4\ud2b8\uc635\uc158 \uc774\ud574\ud558\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-26T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"},{"inline":true,"label":"\ud1f4\uc9c1\uc5f0\uae08","permalink":"/blog/en/finance/tags/\ud1f4\uc9c1\uc5f0\uae08"},{"inline":true,"label":"DC\ud615","permalink":"/blog/en/finance/tags/dc\ud615"},{"inline":true,"label":"\ub514\ud3f4\ud2b8\uc635\uc158","permalink":"/blog/en/finance/tags/\ub514\ud3f4\ud2b8\uc635\uc158"},{"inline":true,"label":"\ub178\ud6c4\uc900\ube44","permalink":"/blog/en/finance/tags/\ub178\ud6c4\uc900\ube44"}],"readingTime":1.93,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"dc-default-option","title":"\ud1f4\uc9c1\uc5f0\uae08 DC\ud615 \ub514\ud3f4\ud2b8\uc635\uc158 \uc774\ud574\ud558\uae30","authors":["way"],"tags":["finance","\uac1c\uc778\uc7ac\ubb34","\ud1f4\uc9c1\uc5f0\uae08","DC\ud615","\ub514\ud3f4\ud2b8\uc635\uc158","\ub178\ud6c4\uc900\ube44"]},"unlisted":false,"prevItem":{"title":"\uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218(CPI) \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/cpi-guide"},"nextItem":{"title":"\uc678\uad6d\uc778 \ub9e4\ub3c4\uc5d0 \ucf54\uc2a4\ud53c 5,500\uc120 \uc544\ub798\ub85c, \ucf54\uc2a4\ub2e5 3% \ub118\uac8c \ud558\ub77d","permalink":"/blog/en/finance/kospi-foreign-selling-oct26"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \ud1f4\uc9c1\uc5f0\uae08 DC\ud615\uc758 \ub514\ud3f4\ud2b8\uc635\uc158\uc774 \ubb34\uc5c7\uc778\uc9c0, \uc5b4\ub5bb\uac8c \ud65c\uc6a9\ub418\ub294\uc9c0 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ud1f4\uc9c1\uc5f0\uae08 DC\ud615\uc740 \ud68c\uc0ac\uac00 \ubd80\ub2f4\uae08\uc744 \ub0a9\uc785\ud558\uace0 \uadfc\ub85c\uc790\uac00 \uc9c1\uc811 \uc6b4\uc6a9\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\uc6b4\uc6a9 \uc9c0\uc2dc\ub97c \ud558\uc9c0 \uc54a\uc73c\uba74 \uc801\ub9bd\uae08\uc774 \uadf8\ub300\ub85c \uba38\ubb34\ub974\uba70 \uc218\uc775\uc744 \ub0b4\uc9c0 \ubabb\ud558\ub294 \ubb38\uc81c\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub97c \ubcf4\uc644\ud558\uae30 \uc704\ud574 \ub3c4\uc785\ub41c \uac83\uc774 \uc0ac\uc804\uc9c0\uc815\uc6b4\uc6a9\uc81c\ub3c4, \uc774\ub978\ubc14 \ub514\ud3f4\ud2b8\uc635\uc158\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\ub85c\uc790\uac00 \ubbf8\ub9ac \uc6b4\uc6a9 \ubc29\ubc95\uc744 \uc9c0\uc815\ud574 \ub450\uba74, \ubcc4\ub3c4 \uc9c0\uc2dc\uac00 \uc5c6\uc744 \ub54c \uadf8 \ubc29\ubc95\uc5d0 \ub530\ub77c \uc790\ub3d9\uc73c\ub85c \uc6b4\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMzBkcnh6OGNxdWVzMTNuNDNqMHp6cmFpMXk2cGZzbm1pZHc2OTR0YSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1rPw1VSqNiI7H8nvIg/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ub514\ud3f4\ud2b8\uc635\uc158\uc758 \uad6c\uc870\\n\\n#### \uc9c0\uc815\uacfc \uc790\ub3d9 \uc6b4\uc6a9\\n\\n\ub514\ud3f4\ud2b8\uc635\uc158\uc740 \uadfc\ub85c\uc790\uac00 \uc6b4\uc6a9 \uc0c1\ud488\uc744 \ubbf8\ub9ac \uc9c0\uc815\ud574 \ub450\ub294 \uc81c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc815 \uc774\ud6c4 \uc77c\uc815 \uae30\uac04 \uc6b4\uc6a9 \uc9c0\uc2dc\uac00 \uc5c6\uc73c\uba74, \uc801\ub9bd\uae08\uc740 \uc9c0\uc815\ud55c \uc0c1\ud488\uc73c\ub85c \uc790\ub3d9 \uc6b4\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\uc9c0\uc815\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc5d0\ub294 \uae30\uc874 \ubc29\uc2dd\ub300\ub85c \uc6b4\uc6a9 \uc9c0\uc2dc\ub97c \uc9c1\uc811 \ub0b4\ub824\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc9c0\uc815\uc740 \uc5b8\uc81c\ub4e0 \ubcc0\uacbd\ud560 \uc218 \uc788\uc5b4, \ud55c \ubc88 \uc815\ud588\ub2e4\uace0 \uace0\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n#### \uc0c1\ud488\uc758 \uc704\ud5d8 \ub2e8\uacc4\\n\\n\ub514\ud3f4\ud2b8\uc635\uc158 \uc0c1\ud488\uc740 \uc704\ud5d8 \uc218\uc900\uc5d0 \ub530\ub77c \ub2e8\uacc4\ubcc4\ub85c \uad6c\ubd84\ub429\ub2c8\ub2e4.<br/>\\n\uc6d0\ub9ac\uae08 \ubcf4\uc7a5\ud615\ubd80\ud130 \ucd08\uc800\uc704\ud5d8, \uc800\uc704\ud5d8, \uc911\uc704\ud5d8, \uace0\uc704\ud5d8\uae4c\uc9c0 \uc704\ud5d8 \ub2e8\uacc4\uac00 \ub098\ub269\ub2c8\ub2e4.<br/>\\n\ud1f4\uc9c1\uae4c\uc9c0 \ub0a8\uc740 \uae30\uac04\uc774 \uae38\uc218\ub85d \uc704\ud5d8 \uc790\uc0b0 \ube44\uc911\uc744 \ub192\uac8c \uac00\uc838\uac00\ub294 \uc0c1\ud488\uc774 \uc788\uace0, \uc740\ud1f4\uac00 \uac00\uae4c\uc6b8\uc218\ub85d \uc548\uc815\ud615 \ube44\uc911\uc744 \ub192\uc774\ub294 \uc0c1\ud488\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\ud488 \uc124\uba85\uc11c\uc5d0\ub294 \ubaa9\ud45c \uc218\uc775\ub960\uc774\ub098 \uacfc\uac70 \uc218\uc775\ub960\uc774 \uc544\ub2c8\ub77c, \uc6b4\uc6a9 \ubc29\uc2dd\uacfc \uc704\ud5d8 \ub2e8\uacc4\uac00 \uc911\uc2ec\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\uc218\ub8cc\uc640 \uc6b4\uc6a9 \ubcf4\uace0\\n\\n\ub514\ud3f4\ud2b8\uc635\uc158 \uc0c1\ud488\uc5d0\ub3c4 \uc6b4\uc6a9\uacfc \uad00\ub9ac\uc5d0 \ub530\ub978 \ubcf4\uc218\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\ubcf4\uc218\ub294 \uc0c1\ud488\ub9c8\ub2e4 \ub2e4\ub974\ubbc0\ub85c, \uc9c0\uc815\ud558\uae30 \uc804\uc5d0 \ubcf4\uc218 \uccb4\uacc4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6b4\uc6a9 \uacb0\uacfc\ub294 \uc815\uae30\uc801\uc73c\ub85c \ud1b5\uc9c0\ub418\uba70, \uc218\uc775\ub960\uacfc \uc801\ub9bd\uae08 \ubcc0\ub3d9\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uc775\ub960\uc774 \ub0ae\ub2e4\uace0 \ubc14\ub85c \uc0c1\ud488\uc744 \ubc14\uafb8\uae30\ubcf4\ub2e4, \uc6b4\uc6a9 \uae30\uac04\uacfc \uc2dc\uc7a5 \ud658\uacbd\uc744 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ub514\ud3f4\ud2b8\uc635\uc158\uc744 \uace0\ub97c \ub54c\ub294 \ud1f4\uc9c1\uae4c\uc9c0 \ub0a8\uc740 \uae30\uac04\uc744 \uba3c\uc800 \uc0dd\uac01\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc740\ud1f4\uac00 \uba40\uc218\ub85d \uc2dc\uac04 \ubd84\uc0b0 \ud6a8\uacfc\uac00 \ucee4\uc9c0\uace0, \uac00\uae4c\uc6b8\uc218\ub85d \uc6d0\uae08 \ubcc0\ub3d9\uc5d0 \ubbfc\uac10\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\uc790\uc2e0\uc758 \uc704\ud5d8 \uc131\ud5a5\uacfc \uae30\uc874\uc5d0 \ubcf4\uc720\ud55c \ub2e4\ub978 \ub178\ud6c4 \uc790\uc0b0\uacfc\uc758 \uade0\ud615\ub3c4 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ud1f4\uc9c1\uc5f0\uae08\uc740 \uac1c\uc778\uc5f0\uae08, \uad6d\ubbfc\uc5f0\uae08\uacfc \ud568\uaed8 \ub178\ud6c4 \uc18c\ub4dd\uc758 \ud55c \ucd95\uc774\ubbc0\ub85c, \ud55c \uacc4\uc88c\ub9cc\uc73c\ub85c \uc804\uccb4\ub97c \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc815 \uc0c1\ud488\uc740 \uc8fc\uae30\uc801\uc73c\ub85c \uc810\uac80\ud558\uace0, \uc0dd\uc560 \ub2e8\uacc4\uac00 \ubc14\ub00c\uba74 \uadf8\uc5d0 \ub9de\uac8c \uc870\uc815\ud558\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ub514\ud3f4\ud2b8\uc635\uc158\uc740 \uc6b4\uc6a9 \uc9c0\uc2dc\ub97c \ud558\uc9c0 \uc54a\uc544\ub3c4 \uc801\ub9bd\uae08\uc774 \ubc29\uce58\ub418\uc9c0 \uc54a\ub3c4\ub85d \ub3d5\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc704\ud5d8 \ub2e8\uacc4\uc640 \ubcf4\uc218, \ub0a8\uc740 \uae30\uac04\uc744 \uae30\uc900\uc73c\ub85c \uc790\uc2e0\uc5d0\uac8c \ub9de\ub294 \ubc29\uc2dd\uc744 \uc9c0\uc815\ud574 \ub450\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaDdiazlvM25jcXhzZ21scmpoZ3Q4aGh4cW9lcnc1MWZiaXdvczFnNiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/I9UwS3w3ADupdRSNZJ/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-foreign-selling-oct26","metadata":{"permalink":"/blog/en/finance/kospi-foreign-selling-oct26","source":"@site/finance/2026-10-26-kospi-foreign-selling/index.mdx","title":"\uc678\uad6d\uc778 \ub9e4\ub3c4\uc5d0 \ucf54\uc2a4\ud53c 5,500\uc120 \uc544\ub798\ub85c, \ucf54\uc2a4\ub2e5 3% \ub118\uac8c \ud558\ub77d","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-26T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ub2e5"},{"inline":true,"label":"\uc678\uad6d\uc778","permalink":"/blog/en/finance/tags/\uc678\uad6d\uc778"},{"inline":true,"label":"\ud658\uc728","permalink":"/blog/en/finance/tags/\ud658\uc728"}],"readingTime":2.07,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-foreign-selling-oct26","title":"\uc678\uad6d\uc778 \ub9e4\ub3c4\uc5d0 \ucf54\uc2a4\ud53c 5,500\uc120 \uc544\ub798\ub85c, \ucf54\uc2a4\ub2e5 3% \ub118\uac8c \ud558\ub77d","authors":["way"],"tags":["finance","\uc2dc\uc7a5\uc815\ub9ac","\ucf54\uc2a4\ud53c","\ucf54\uc2a4\ub2e5","\uc678\uad6d\uc778","\ud658\uc728"]},"unlisted":false,"prevItem":{"title":"\ud1f4\uc9c1\uc5f0\uae08 DC\ud615 \ub514\ud3f4\ud2b8\uc635\uc158 \uc774\ud574\ud558\uae30","permalink":"/blog/en/finance/dc-default-option"},"nextItem":{"title":"\uacf5\ub9e4\ub3c4 \uc81c\ub3c4\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","permalink":"/blog/en/finance/short-selling-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 10\uc6d4 26\uc77c \uad6d\ub0b4 \uc99d\uc2dc \ub9c8\uac10 \ud750\ub984\uc744 \uc815\ub9ac\ud558\uace0, \uc774\ubc88 \uc8fc\uc5d0 \ud655\uc778\ud560 \uc9c0\ud45c\ub97c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n10\uc6d4 26\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804 \uac70\ub798\uc77c\ubcf4\ub2e4 80.83\ud3ec\uc778\ud2b8, 1.46% \ub0b4\ub9b0 5,469.47\uc5d0 \uc7a5\uc744 \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uac00 5,500\uc120 \uc544\ub798\uc5d0\uc11c \ub9c8\uac10\ud55c \uac83\uc740 \uc9c0\ub09c 4\uc6d4 7\uc77c \uc774\ud6c4 \ucc98\uc74c\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 24.48\ud3ec\uc778\ud2b8, 3.26% \ub0b4\ub9b0 727.21\uc5d0 \ub9c8\uac10\ud558\uba70 \ub099\ud3ed\uc774 \ub354 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc99d\uc2dc\ub3c4 \uc9c0\ub09c \uc8fc\ub9d0 \ub2e4\uc6b0\uc874\uc2a4 1.23%, S&P500 0.52%, \ub098\uc2a4\ub2e5 0.21% \ud558\ub77d\ud558\uba70 \uc57d\ud55c \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExa2N4NmppemVtdmUxOW92ajZuYWRxcXdqMngyeGpteWxvenpxOWJlbSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/S4178TW2Rm1LW/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### 26\uc77c \uc2dc\uc7a5 \ud750\ub984\\n\\n#### \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \uc9c0\uc218\ub97c \ub20c\ub800\ub2e4\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \uc678\uad6d\uc778\uc740 6,972\uc5b5 \uc6d0\uac00\ub7c9\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uacfc \uae30\uad00\uc774 \uac01\uac01 538\uc5b5 \uc6d0, 6,047\uc5b5 \uc6d0\uac00\ub7c9\uc744 \uc21c\ub9e4\uc218\ud558\uba70 \ubc1b\ucce4\uc9c0\ub9cc \uc9c0\uc218 \ud558\ub77d\uc744 \ub9c9\uc9c0\ub294 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uae30\uad00\uc774 1,279\uc5b5 \uc6d0\uac00\ub7c9\uc744 \uc21c\ub9e4\ub3c4\ud558\uba70 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud588\uace0, \uac1c\uc778\uacfc \uc678\uad6d\uc778\uc740 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uc8fc\uccb4\ubcc4\ub85c \ubc29\ud5a5\uc774 \uc5c7\uac08\ub838\ub2e4\ub294 \uc810\uc774 \uc774\ub0a0 \uc2dc\uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ub300\ud615\uc8fc \uc804\ubc18\uc774 \uc57d\ud588\ub2e4\\n\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9\uc740 \ub300\ubd80\ubd84 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud604\ub300\ucc28, KB\uae08\uc735, \uc2e0\ud55c\uc9c0\uc8fc, \uc140\ud2b8\ub9ac\uc628 \ub4f1\uc774 2% \ub118\uac8c \ub0b4\ub838\uace0, \uc0bc\uc131\uc804\uc790\ub3c4 1.16% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nSK\ud558\uc774\ub2c9\uc2a4\ub294 0.16% \ud558\ub77d\uc5d0 \uadf8\uce58\uba70 \uc0c1\ub300\uc801\uc73c\ub85c \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc0bc\uc131\ubb3c\uc0b0\uacfc \uc0bc\uc131\uc0dd\uba85\uc740 \uc18c\ud3ed \uc0c1\uc2b9\ud558\uba70 \uc5c7\uac08\ub9b0 \ubaa8\uc2b5\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc6d0\ub2ec\ub7ec \ud658\uc728\uc740 1,325\uc6d0\ub300\\n\\n\uc6d0\ub2ec\ub7ec \ud658\uc728\uc740 1,325.3\uc6d0\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911\uc5d0\ub294 1,323\uc6d0\ub300\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub2e4 \uc624\ud6c4 \ub4e4\uc5b4 \uc18c\ud3ed \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uc774 \uc624\ub974\uba74 \uc218\uc785 \ubb3c\uac00\uc5d0 \ubd80\ub2f4\uc774 \ucee4\uc9c0\uace0, \uc218\ucd9c \uae30\uc5c5\uc5d0\ub294 \uac00\uaca9 \uacbd\uc7c1\ub825 \uce21\uba74\uc5d0\uc11c \ubcc0\uc218\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0\uc740 \uc9c0\uc218 \ud558\ub77d\uacfc \ud568\uaed8 \ud658\uc728\ub3c4 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\ub294 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc774\ubc88 \uc8fc\uc5d0 \ud655\uc778\ud560 \uc810\\n\\n\uc774\ubc88 \uc8fc\ub294 \ubbf8\uad6d \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c(FOMC) \ud68c\uc758\uc640 \uad6d\ub0b4 \ub300\ud615 \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 3\ubd84\uae30 \uc2e4\uc801 \ubc1c\ud45c\uac00 \uacb9\uccd0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nSK\ud558\uc774\ub2c9\uc2a4\ub294 28\uc77c, \uc0bc\uc131\uc804\uc790\ub294 29\uc77c\uc5d0 3\ubd84\uae30 \ud655\uc815 \uc2e4\uc801\uc744 \ubc1c\ud45c\ud560 \uc608\uc815\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uc559\uc740\ud589\uc758 \uae08\ub9ac \uacb0\uc815\uc740 \ub2ec\ub7ec\uc640 \uae00\ub85c\ubc8c \uc790\uae08 \ud750\ub984\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \ub9cc\ud07c, \ubc1c\ud45c \ubb38\uad6c\uc640 \uae30\uc790\ud68c\uacac \ub0b4\uc6a9\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \ubc1c\ud45c\uc5d0\uc11c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ubc18\ub3c4\uccb4 \uc218\uc694\uc640 \uba54\ubaa8\ub9ac \uac00\uaca9\uc5d0 \ub300\ud55c \uc5b8\uae09\uc774 \uc2dc\uc7a5\uc758 \uad00\uc2ec\uc0ac\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \ub2e8\uae30\uac04\uc5d0 \ud06c\uac8c \uc6c0\uc9c1\uc778 \ub4a4\uc5d0\ub294 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c, \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc18c\uc2dd\ubcf4\ub2e4 \uacf5\uc2dd \ubc1c\ud45c\uc640 \uacf5\uc2dc \uc911\uc2ec\uc73c\ub85c \ud750\ub984\uc744 \uc810\uac80\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n26\uc77c\uc740 \uc678\uad6d\uc778 \ub9e4\ub3c4\uc640 \ubbf8\uad6d \uc99d\uc2dc \uc57d\uc138\uac00 \uacb9\uce58\uba70 \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ud568\uaed8 \ub0b4\ub9b0 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uc8fc\ub294 \uae08\ub9ac \uacb0\uc815\uacfc \ub300\ud615\uc8fc \uc2e4\uc801\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \uc77c\uc815\uc774 \uc2dc\uc7a5\uc758 \ubc29\ud5a5\uc744 \uac00\ub97c \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNWt3dTE0N2h3djgxNjAwb3d0anBkcHdjeDU0eGt0bDNuMzkwZGZ3dSZlcD12MV9jaGFubmVsc19zZWFyY2gmY3Q9cw/gevDVFkQLwKDvJNlr6/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"short-selling-guide","metadata":{"permalink":"/blog/en/finance/short-selling-guide","source":"@site/finance/2026-10-26-short-selling-guide/index.mdx","title":"\uacf5\ub9e4\ub3c4 \uc81c\ub3c4\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-26T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\ub150","permalink":"/blog/en/finance/tags/\uac1c\ub150"},{"inline":true,"label":"\uacf5\ub9e4\ub3c4","permalink":"/blog/en/finance/tags/\uacf5\ub9e4\ub3c4"},{"inline":true,"label":"\ub300\ucc28\uac70\ub798","permalink":"/blog/en/finance/tags/\ub300\ucc28\uac70\ub798"},{"inline":true,"label":"\uc2dc\uc7a5\uc81c\ub3c4","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc81c\ub3c4"},{"inline":true,"label":"\ubcc0\ub3d9\uc131","permalink":"/blog/en/finance/tags/\ubcc0\ub3d9\uc131"}],"readingTime":2.08,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"short-selling-guide","title":"\uacf5\ub9e4\ub3c4 \uc81c\ub3c4\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","authors":["way"],"tags":["finance","\uac1c\ub150","\uacf5\ub9e4\ub3c4","\ub300\ucc28\uac70\ub798","\uc2dc\uc7a5\uc81c\ub3c4","\ubcc0\ub3d9\uc131"]},"unlisted":false,"prevItem":{"title":"\uc678\uad6d\uc778 \ub9e4\ub3c4\uc5d0 \ucf54\uc2a4\ud53c 5,500\uc120 \uc544\ub798\ub85c, \ucf54\uc2a4\ub2e5 3% \ub118\uac8c \ud558\ub77d","permalink":"/blog/en/finance/kospi-foreign-selling-oct26"},"nextItem":{"title":"\ubaa9\uc801\ubcc4 \ub3c8 \ub098\ub204\uae30: \ub2e8\uae30\xb7\uc911\uae30\xb7\uc7a5\uae30 \ubc84\ud0b7\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc7ac\ubb34 \uad6c\uc870","permalink":"/blog/en/finance/goal-based-money-buckets"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uacf5\ub9e4\ub3c4\uac00 \uc5b4\ub5a4 \uad6c\uc870\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uc9c0\ud45c\ub97c \ud568\uaed8 \ubcf4\uba74 \uc88b\uc740\uc9c0 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uacf5\ub9e4\ub3c4\ub294 \uc8fc\uc2dd\uc744 \ube4c\ub824\uc11c \ud310 \ub4a4, \ub098\uc911\uc5d0 \ub2e4\uc2dc \uc0ac\uc11c \uac1a\ub294 \uac70\ub798\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\uac00 \ub0b4\ub9b4 \uac83\uc73c\ub85c \uc608\uc0c1\ud560 \ub54c \uc218\uc775\uc744 \ub0bc \uc218 \uc788\ub294 \uad6c\uc870\uc774\uc9c0\ub9cc, \uc8fc\uac00\uac00 \uc624\ub974\uba74 \uc190\uc2e4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc5d0\uc11c\ub294 \ud55c\ub54c \uacf5\ub9e4\ub3c4\uac00 \uae08\uc9c0\ub418\uc5c8\ub2e4\uac00 2025\ub144\uc5d0 \uc7ac\uac1c\ub418\uba70 \uc81c\ub3c4\uac00 \ub2e4\uc2dc \uc815\ube44\ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\ub9e4\ub3c4\ub294 \uac00\uaca9 \ubc1c\uacac\uacfc \uc720\ub3d9\uc131 \uacf5\uae09\uc5d0 \uae30\uc5ec\ud55c\ub2e4\ub294 \ud3c9\uac00\uc640 \ubcc0\ub3d9\uc131\uc744 \ud0a4\uc6b4\ub2e4\ub294 \uc6b0\ub824\uac00 \ud568\uaed8 \uc874\uc7ac\ud558\ub294 \uc81c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY3Q0MW8yYWxodmJtM3NldWJwbmIybGlnaDk2cmY1bDlrNHpqZXE1ZiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/8Vrefmr1uZZa8/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uacf5\ub9e4\ub3c4\uc758 \uad6c\uc870\\n\\n#### \ube4c\ub9ac\uace0, \ud314\uace0, \uac1a\ub294 \uc21c\uc11c\\n\\n\uacf5\ub9e4\ub3c4\ub294 \uba3c\uc800 \uc8fc\uc2dd\uc744 \ube4c\ub9ac\ub294 \ub300\ucc28 \uac70\ub798\uc5d0\uc11c \uc2dc\uc791\ud569\ub2c8\ub2e4.<br/>\\n\ube4c\ub9b0 \uc8fc\uc2dd\uc744 \uc2dc\uc7a5\uc5d0\uc11c \ud310 \ub4a4, \uc8fc\uac00\uac00 \ub0b4\ub9ac\uba74 \ub354 \ub0ae\uc740 \uac00\uaca9\uc5d0 \ub2e4\uc2dc \uc0ac\uc11c \uac1a\uc2b5\ub2c8\ub2e4.<br/>\\n\ud310 \uac00\uaca9\uacfc \ub2e4\uc2dc \uc0b0 \uac00\uaca9\uc758 \ucc28\uc774\uac00 \uc218\uc775\uc774 \ub418\uace0, \ube4c\ub9ac\ub294 \ub3d9\uc548 \ub300\ucc28 \uc218\uc218\ub8cc\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\uac00 \uc608\uc0c1\uacfc \ubc18\ub300\ub85c \uc624\ub974\uba74 \ub354 \ube44\uc2fc \uac00\uaca9\uc5d0 \uc0ac\uc11c \uac1a\uc544\uc57c \ud558\ubbc0\ub85c \uc190\uc2e4\uc774 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc5c5\ud2f1\ub8f0\uacfc \uc2dc\uc7a5 \uc548\uc804\uc7a5\uce58\\n\\n\uacf5\ub9e4\ub3c4\uc5d0\ub294 \uac00\uaca9 \ud558\ub77d\uc744 \uac00\uc18d\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uc548\uc804\uc7a5\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud45c\uc801\uc778 \uac83\uc774 \uc5c5\ud2f1\ub8f0\uc785\ub2c8\ub2e4.<br/>\\n\uc9c1\uc804 \uccb4\uacb0 \uac00\uaca9\ubcf4\ub2e4 \ub192\uc740 \uac00\uaca9\uc5d0\uc11c\ub9cc \uacf5\ub9e4\ub3c4 \uc8fc\ubb38\uc744 \ub0bc \uc218 \uc788\ub3c4\ub85d \uc81c\ud55c\ud558\ub294 \uaddc\uce59\uc785\ub2c8\ub2e4.<br/>\\n\ub610\ud55c \uac1c\ubcc4 \uc885\ubaa9\uc758 \uacf5\ub9e4\ub3c4 \uc794\uace0\uc640 \uac70\ub798 \ube44\uc911\uc774 \uacf5\uac1c\ub418\uc5b4 \uc2dc\uc7a5 \ucc38\uc5ec\uc790\uac00 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798\uc18c\ub294 \uacf5\ub9e4\ub3c4 \uacfc\uc5f4 \uc885\ubaa9\uc5d0 \ub300\ud55c \ubaa8\ub2c8\ud130\ub9c1\uacfc \ud544\uc694\uc2dc \uc81c\ud55c \uc870\uce58\ub97c \uc6b4\uc601\ud558\ub294 \uccb4\uacc4\ub97c \uac16\ucd94\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc20f\uc2a4\ud034\uc988\uc640 \ubc18\ub300\ub9e4\ub9e4\\n\\n\uacf5\ub9e4\ub3c4 \uc794\uace0\uac00 \ub9ce\uc774 \uc313\uc778 \uc885\ubaa9\uc5d0\uc11c \uc8fc\uac00\uac00 \uae09\ub4f1\ud558\uba74 \uc20f\uc2a4\ud034\uc988\uac00 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc190\uc2e4\uc744 \uc904\uc774\ub824\ub294 \ub9e4\uc218 \ud658\ub9e4\uac00 \ubab0\ub9ac\uba70 \uc8fc\uac00\uac00 \ub354 \uc624\ub974\ub294 \ud604\uc0c1\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c\ub294, \uc2e0\uc6a9 \uac70\ub798\uc640 \ub2ec\ub9ac \uacf5\ub9e4\ub3c4\ub294 \ube4c\ub9b0 \uc8fc\uc2dd\uc744 \uac1a\uc544\uc57c \ud558\ub294 \uae30\ud55c\uacfc \uc218\uc218\ub8cc \ubd80\ub2f4\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\ud55c\uc774 \ub2e4\uac00\uc624\uba74 \ud658\ub9e4 \ub9e4\uc218\uac00 \ub098\uc62c \uc218 \uc788\uc5b4 \uc218\uae09 \ubcc0\uc218\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uacf5\ub9e4\ub3c4\ub97c \ubcfc \ub54c\ub294 \uacf5\ub9e4\ub3c4 \uc794\uace0 \ube44\uc911\uacfc \ub300\ucc28 \uc794\uace0 \ucd94\uc774\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc794\uace0 \ube44\uc911\uc774 \ub192\uc740 \uc885\ubaa9\uc740 \uc8fc\uac00 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uace0, \ud658\ub9e4 \ub9e4\uc218\uac00 \ub098\uc62c \ub54c \ubc29\ud5a5\uc774 \ube60\ub974\uac8c \ubc14\ub014 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\ub9e4\ub3c4 \uac70\ub798 \ube44\uc911\uc774 \ud558\ub8e8\ub9cc \ub192\ub2e4\uace0 \ud574\uc11c \uc758\ubbf8\ub97c \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \ub0a0\uc758 \ucd94\uc138\uc640 \ud568\uaed8, \ud574\ub2f9 \uc885\ubaa9\uc758 \uc2e4\uc801\uacfc \uacf5\uc2dc \uac19\uc740 \uae30\ubcf8 \uc694\uc778\uc744 \uac19\uc774 \ubcf4\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uacf5\ub9e4\ub3c4 \uc790\uccb4\ub294 \uc8fc\uac00 \ubc29\ud5a5\uc744 \uacb0\uc815\uc9d3\ub294 \uc720\uc77c\ud55c \uc694\uc778\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\ub3c4 \uae30\uc5b5\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uacf5\ub9e4\ub3c4\ub294 \ube4c\ub824\uc11c \ud314\uace0 \ub098\uc911\uc5d0 \uac1a\ub294 \uad6c\uc870\uc758 \uac70\ub798\ub85c, \uc0c1\uc2b9\uacfc \ud558\ub77d \uc591\ucabd\uc758 \uc704\ud5d8\uc744 \ubaa8\ub450 \uc548\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc794\uace0\uc640 \uac70\ub798 \ube44\uc911 \uac19\uc740 \uacf5\uac1c \uc9c0\ud45c\ub97c \ucd94\uc138\ub85c \ubcf4\uba74\uc11c, \uae30\ubcf8 \uc694\uc778\uacfc \ud568\uaed8 \ud310\ub2e8\ud558\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZjhiOWRqODJkZ2N5ZzY5dWI1MGN2MDlvbDY5bjdiam13ejR1Zzg2YSZlcD12MV9jaGFubmVsc19zZWFyY2gmY3Q9Zw/RGXhikrzGUUyh8vrsH/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"goal-based-money-buckets","metadata":{"permalink":"/blog/en/finance/goal-based-money-buckets","source":"@site/finance/2026-10-25-goal-based-money-buckets/index.mdx","title":"\ubaa9\uc801\ubcc4 \ub3c8 \ub098\ub204\uae30: \ub2e8\uae30\xb7\uc911\uae30\xb7\uc7a5\uae30 \ubc84\ud0b7\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc7ac\ubb34 \uad6c\uc870","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-25T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uac1c\uc778\uc7ac\ubb34","permalink":"/blog/en/finance/tags/\uac1c\uc778\uc7ac\ubb34"},{"inline":true,"label":"\uc790\uc0b0\ubc30\ubd84","permalink":"/blog/en/finance/tags/\uc790\uc0b0\ubc30\ubd84"},{"inline":true,"label":"\ube44\uc0c1\uae08","permalink":"/blog/en/finance/tags/\ube44\uc0c1\uae08"},{"inline":true,"label":"\uc7ac\ubb34\uc124\uacc4","permalink":"/blog/en/finance/tags/\uc7ac\ubb34\uc124\uacc4"}],"readingTime":2.15,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"goal-based-money-buckets","title":"\ubaa9\uc801\ubcc4 \ub3c8 \ub098\ub204\uae30: \ub2e8\uae30\xb7\uc911\uae30\xb7\uc7a5\uae30 \ubc84\ud0b7\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc7ac\ubb34 \uad6c\uc870","authors":["way"],"tags":["finance","\uac1c\uc778\uc7ac\ubb34","\uc790\uc0b0\ubc30\ubd84","\ube44\uc0c1\uae08","\uc7ac\ubb34\uc124\uacc4"]},"unlisted":false,"prevItem":{"title":"\uacf5\ub9e4\ub3c4 \uc81c\ub3c4\uc758 \uad6c\uc870\uc640 \ud655\uc778 \uc9c0\ud45c","permalink":"/blog/en/finance/short-selling-guide"},"nextItem":{"title":"\ub85c\ubd07 \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124: \ud558\ub4dc\uc6e8\uc5b4\ubd80\ud130 AI\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uac00\uce58\uc0ac\uc2ac","permalink":"/blog/en/finance/robot-industry-structure"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \ub3c8\uc744 \ud558\ub098\uc758 \ud1b5\uc7a5\uc5d0 \ubaa8\uc544\ub450\ub294 \ub300\uc2e0, \ubaa9\uc801\ubcc4\ub85c \ub098\ub204\uc5b4 \uad00\ub9ac\ud558\ub294 \ubc84\ud0b7 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc6d4\uae09\uc774 \ub4e4\uc5b4\uc624\uba74 \ub0a8\uc740 \ub3c8\uc744 \uc800\ucd95\ud558\ub294 \ubc29\uc2dd\uc740 \uc800\ucd95\uc561\uc774 \ub4e4\ucb49\ub0a0\ucb49\ud574\uc9c0\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa9\uc801\ubcc4 \ubc84\ud0b7\uc740 \ub3c8\uc744 \uc4f0\uae30 \uc804\uc5d0 \uc6a9\ub3c4\ubcc4\ub85c \uba3c\uc800 \ub098\ub204\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uac01 \ubc84\ud0b7\ub9c8\ub2e4 \ud544\uc694\ud55c \uc2dc\uae30\uc640 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \ubcc0\ub3d9\uc131\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0, \uc6b4\uc6a9 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ud2b9\uc815 \uae08\uc735\uc0c1\ud488\uc744 \uad8c\uc720\ud558\uc9c0 \uc54a\uace0, \uad6c\uc870\ub97c \uc124\uacc4\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExb3luOWx0eWYyem02ZnNxdmVhdDgybHJiaXkzOXB5czgzejh1YXIxZSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/GnCIHHO3V8Ls1lsQe7/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc138 \uac00\uc9c0 \ubc84\ud0b7\\n\\n#### \ub2e8\uae30 \ubc84\ud0b7: 1\ub144 \uc774\ub0b4\uc5d0 \uc4f8 \ub3c8\\n\\n\uc0dd\ud65c\ube44, \uc6d4\uc138, \ubcf4\ud5d8\ub8cc, \uc774\ubbf8 \uc608\uc815\ub41c \uc9c0\ucd9c\uc774 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.<br/>\\n\uac00\uc7a5 \uc911\uc694\ud55c \uc870\uac74\uc740 \uc5b8\uc81c\ub4e0 \uaebc\ub0bc \uc218 \uc788\ub294 \uc720\ub3d9\uc131\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uc775\ub960\ubcf4\ub2e4 \uc6d0\uae08 \ubcf4\uc804\uacfc \uc989\uc2dc \uc778\ucd9c \uac00\ub2a5\uc131\uc774 \uc6b0\uc120\ud569\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uae08\ub3c4 \ub2e8\uae30 \ubc84\ud0b7\uc5d0 \ud3ec\ud568\ub429\ub2c8\ub2e4.<br/>\\n\uac11\uc791\uc2a4\ub7ec\uc6b4 \uc2e4\uc9c1\uc774\ub098 \ubcd1\uc6d0\ube44\uc5d0 \ub300\ube44\ud574 \uc0dd\ud65c\ube44 3\uac1c\uc6d4\uc5d0\uc11c 6\uac1c\uc6d4\ubd84\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc911\uae30 \ubc84\ud0b7: 1\ub144\uc5d0\uc11c 5\ub144 \uc0ac\uc774\uc5d0 \uc4f8 \ub3c8\\n\\n\uc8fc\ud0dd \uacc4\uc57d\uae08, \uc790\ub3d9\ucc28 \uad50\uccb4, \uacb0\ud63c \uc790\uae08, \uc790\ub140 \uad50\uc721\ube44 \ub4f1\uc774 \ud574\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30 \ubc84\ud0b7\ubcf4\ub2e4\ub294 \uae34 \uc2dc\uac04\uc774 \uc788\uc9c0\ub9cc, \uc740\ud1f4 \uc790\uae08\ucc98\ub7fc \uc218\uc2ed \ub144\uc744 \ub458 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uac00\uaca9 \ubcc0\ub3d9\uc774 \ud06c\uba74 \ubaa9\ud45c \uc2dc\uc810\uc5d0 \uc6d0\uae08\uc774 \uc904\uc5b4\ub4e4 \uc704\ud5d8\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa9\ud45c \uc2dc\uc810\uc774 \uac00\uae4c\uc6cc\uc9c8\uc218\ub85d \ubcc0\ub3d9\uc131\uc774 \ub0ae\uc740 \uc790\uc0b0\uc73c\ub85c \ube44\uc911\uc744 \uc62e\uae30\ub294 \uac83\uc774 \uc6d0\uce59\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc7a5\uae30 \ubc84\ud0b7: 5\ub144 \uc774\ud6c4, \uc8fc\ub85c \uc740\ud1f4 \uc790\uae08\\n\\n\uc740\ud1f4 \uc774\ud6c4 \uc0dd\ud65c\ube44\uac00 \ub300\ud45c\uc801\uc778 \uc7a5\uae30 \ubc84\ud0b7\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uac04\uc774 \uae38\uae30 \ub54c\ubb38\uc5d0 \ub2e8\uae30 \ubcc0\ub3d9\uc5d0 \ud754\ub4e4\ub9ac\uae30\ubcf4\ub2e4, \uc7a5\uae30\uc801\uc778 \ubcf5\ub9ac \ud6a8\uacfc\ub97c \ub178\ub9ac\ub294 \uad6c\uc870\uac00 \uc801\ud569\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \ubc84\ud0b7\uc740 \uc2dc\uc7a5\uc774 \ub5a8\uc5b4\uc838\ub3c4 \ub2f9\uc7a5 \uaebc\ub0bc \ud544\uc694\uac00 \uc5c6\uc73c\ubbc0\ub85c, \ub2e8\uae30 \ubc84\ud0b7\ubcf4\ub2e4 \ubcc0\ub3d9\uc131\uc744 \uac10\ub2f9\ud560 \uc5ec\uc720\uac00 \ud07d\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc5ec\uc720\uac00 \ud06c\ub2e4\uace0 \ud574\uc11c \ubb34\uc791\uc815 \uc704\ud5d8\uc744 \ud0a4\uc6b0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ubcf8\uc778\uc758 \uac10\ub2f9 \ubc94\uc704\ub97c \uba3c\uc800 \uc815\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ubc84\ud0b7 \uc6b4\uc601\uc758 \uc2e4\uc81c\\n\\n#### \uc790\ub3d9 \uc774\uccb4\ub85c \uba3c\uc800 \ub098\ub204\uae30\\n\\n\uc6d4\uae09\uc77c \ub2e4\uc74c \ub0a0\uc5d0 \uac01 \ubc84\ud0b7\uc73c\ub85c \uc790\ub3d9 \uc774\uccb4\uac00 \ub418\ub3c4\ub85d \uc124\uc815\ud558\uba74, \ub0a8\uc740 \ub3c8\uc73c\ub85c \uc0dd\ud65c\ud558\ub294 \uad6c\uc870\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc758\uc9c0\uc5d0 \ub9e1\uae30\ub294 \uc800\ucd95\ubcf4\ub2e4 \uc790\ub3d9\ud654\ub41c \uad6c\uc870\uac00 \uc720\uc9c0\ub418\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubaa9\ud45c \uc2dc\uc810\uc774 \ubc14\ub00c\uba74 \ubc84\ud0b7\ub3c4 \uc62e\uae30\uae30\\n\\n\uacb0\ud63c \uc2dc\uae30\uac00 \ubbf8\ub904\uc9c0\uac70\ub098 \uc8fc\ud0dd \uad6c\uc785 \uacc4\ud68d\uc774 \ubc14\ub00c\uba74, \uc911\uae30 \ubc84\ud0b7\uc758 \ubaa9\ud45c \uc2dc\uc810\ub3c4 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n1\ub144\uc5d0 \ud55c \ubc88\uc740 \uac01 \ubc84\ud0b7\uc758 \ubaa9\ud45c\uc640 \uae08\uc561\uc744 \uc810\uac80\ud558\uace0, \ud544\uc694\ud558\uba74 \ubc84\ud0b7 \uac04 \uc774\ub3d9\uc744 \ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubc84\ud0b7\uc744 \uc11e\uc9c0 \uc54a\uae30\\n\\n\ube44\uc0c1\uae08\uc73c\ub85c \uc8fc\uc2dd \ud22c\uc790\ub97c \ud558\uac70\ub098, \uc740\ud1f4 \uc790\uae08\uc73c\ub85c \ub2e8\uae30 \uc9c0\ucd9c\uc744 \uba54\uc6b0\ub294 \uc77c\uc740 \ud53c\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubc84\ud0b7\uc774 \uc11e\uc774\uba74 \uc5b4\ub290 \ubaa9\uc801\uc758 \ub3c8\uc774 \ubd80\uc871\ud55c\uc9c0 \ud30c\uc545\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c0\uace0, \uae09\ud560 \ub54c \uc190\uc2e4\uc744 \ud655\uc815\ud558\ub294 \uc0c1\ud669\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubaa9\uc801\ubcc4 \ubc84\ud0b7\uc740 \ub3c8\uc744 \ub098\ub204\ub294 \uac83\ub9cc\uc73c\ub85c \uc7ac\ubb34 \uad6c\uc870\ub97c \ub610\ub837\ud558\uac8c \ub9cc\ub4ed\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30, \uc911\uae30, \uc7a5\uae30\uc758 \ubaa9\uc801\uc744 \uba3c\uc800 \uc815\ud558\uace0 \uadf8\uc5d0 \ub9de\ub294 \uc6b4\uc6a9 \ubc29\uc2dd\uc744 \uc801\uc6a9\ud574 \ubcf4\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExb3luOWx0eWYyem02ZnNxdmVhdDgybHJiaXkzOXB5czgzejh1YXIxZSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/dl9kKxlKlBXYJ8zHTZ/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"robot-industry-structure","metadata":{"permalink":"/blog/en/finance/robot-industry-structure","source":"@site/finance/2026-10-25-robot-industry-structure/index.mdx","title":"\ub85c\ubd07 \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124: \ud558\ub4dc\uc6e8\uc5b4\ubd80\ud130 AI\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uac00\uce58\uc0ac\uc2ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-25T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc139\ud130\ud574\uc124","permalink":"/blog/en/finance/tags/\uc139\ud130\ud574\uc124"},{"inline":true,"label":"\ub85c\ubd07","permalink":"/blog/en/finance/tags/\ub85c\ubd07"},{"inline":true,"label":"\uc0b0\uc5c5\uad6c\uc870","permalink":"/blog/en/finance/tags/\uc0b0\uc5c5\uad6c\uc870"}],"readingTime":2.27,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"robot-industry-structure","title":"\ub85c\ubd07 \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124: \ud558\ub4dc\uc6e8\uc5b4\ubd80\ud130 AI\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uac00\uce58\uc0ac\uc2ac","authors":["way"],"tags":["finance","\uc139\ud130\ud574\uc124","\ub85c\ubd07","\uc0b0\uc5c5\uad6c\uc870"]},"unlisted":false,"prevItem":{"title":"\ubaa9\uc801\ubcc4 \ub3c8 \ub098\ub204\uae30: \ub2e8\uae30\xb7\uc911\uae30\xb7\uc7a5\uae30 \ubc84\ud0b7\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc7ac\ubb34 \uad6c\uc870","permalink":"/blog/en/finance/goal-based-money-buckets"},"nextItem":{"title":"\ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c \uc77d\ub294 \ubc95: \ube44\ub18d\uc5c5 \uace0\uc6a9, \uc2e4\uc5c5\ub960, \uc784\uae08 \uc0c1\uc2b9\ub960","permalink":"/blog/en/finance/us-jobs-report-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \ub85c\ubd07 \uc0b0\uc5c5\uc774 \uc5b4\ub5a4 \uad6c\uc870\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\ub294\uc9c0, \uac00\uce58\uc0ac\uc2ac \ub2e8\uacc4\ubcc4\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ub85c\ubd07 \uc0b0\uc5c5\uc740 \uc81c\uc870 \ud604\uc7a5\uc758 \uc790\ub3d9\ud654 \uc218\uc694\uc640 \uc778\uad6c\uad6c\uc870 \ubcc0\ud654\ub77c\ub294 \ub450 \uac00\uc9c0 \ubc30\uacbd \uc704\uc5d0\uc11c \ub17c\uc758\ub429\ub2c8\ub2e4.<br/>\\n\uacf5\uc7a5\uc5d0\uc11c\ub294 \uc778\uac74\ube44 \uc0c1\uc2b9\uacfc \uc778\ub825 \ud655\ubcf4 \uc5b4\ub824\uc6c0\uc774 \uc790\ub3d9\ud654 \ud22c\uc790\uc758 \uc774\uc720\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc11c\ube44\uc2a4 \uc601\uc5ed\uc5d0\uc11c\ub294 \ubb3c\ub958, \uc758\ub8cc, \uac00\uc0ac \ub4f1 \uc0ac\ub78c\uc744 \ubcf4\uc870\ud558\ub294 \ub85c\ubd07\uc5d0 \ub300\ud55c \uad00\uc2ec\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ud2b9\uc815 \uae30\uc5c5\uc774\ub098 \uc81c\ud488\uc758 \uc804\ub9dd\uc744 \ub2e4\ub8e8\uc9c0 \uc54a\uace0, \uc0b0\uc5c5\uc758 \uad6c\uc870\ub97c \uc774\ud574\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucda5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMGxwcG5qZ2FraWRxdXdiNDZtYzU3MHdrb2ZzZDhnencxamxjdGF4ciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/H1eVHxFk781UxUNMul/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ub85c\ubd07\uc758 \uc885\ub958\\n\\n#### \uc0b0\uc5c5\uc6a9 \ub85c\ubd07\\n\\n\uc790\ub3d9\ucc28, \uc804\uc790 \uc81c\ud488 \uacf5\uc7a5\uc5d0\uc11c \uc6a9\uc811, \uc870\ub9bd, \ub3c4\uc7a5 \uac19\uc740 \ubc18\ubcf5 \uc791\uc5c5\uc744 \uc218\ud589\ud569\ub2c8\ub2e4.<br/>\\n\uc815\ud574\uc9c4 \ub3d9\uc791\uc744 \ube60\ub974\uace0 \uc815\ubc00\ud558\uac8c \ubc18\ubcf5\ud558\ub294 \uac83\uc774 \uac15\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc791\uc5c5 \ud658\uacbd\uc774 \uace0\uc815\ub3fc \uc788\uace0, \uc548\uc804 \ud39c\uc2a4 \uc548\uc5d0\uc11c \uc0ac\ub78c\uacfc \ubd84\ub9ac\ub3fc \uc6b4\uc6a9\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud611\ub3d9 \ub85c\ubd07\\n\\n\uc0ac\ub78c\uacfc \uac19\uc740 \uacf5\uac04\uc5d0\uc11c \ud568\uaed8 \uc791\uc5c5\ud558\ub3c4\ub85d \uc124\uacc4\ub41c \ub85c\ubd07\uc785\ub2c8\ub2e4.<br/>\\n\ucda9\ub3cc \uc2dc \ud798\uc744 \uc81c\ud55c\ud558\ub294 \uc13c\uc11c\uc640 \uc81c\uc5b4 \uae30\uc220\uc774 \ub4e4\uc5b4\uac00\uba70, \uc911\uc18c \uc81c\uc870 \ud604\uc7a5\uc5d0\uc11c \ud65c\uc6a9\uc774 \ub298\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ud488\uc885 \uc18c\ub7c9 \uc0dd\uc0b0\ucc98\ub7fc \uc791\uc5c5 \ubcc0\uacbd\uc774 \uc7a6\uc740 \ud658\uacbd\uc5d0 \uc801\ud569\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc11c\ube44\uc2a4 \ub85c\ubd07\uacfc \ud734\uba38\ub178\uc774\ub4dc\\n\\n\ubb3c\ub958 \ucc3d\uace0\uc758 \uc774\ub3d9 \ub85c\ubd07, \ubcd1\uc6d0 \uc548\ub0b4 \ub85c\ubd07, \uccad\uc18c \ub85c\ubd07 \ub4f1\uc774 \uc11c\ube44\uc2a4 \ub85c\ubd07\uc5d0 \uc18d\ud569\ub2c8\ub2e4.<br/>\\n\uc0ac\ub78c\uacfc \ube44\uc2b7\ud55c \ud615\ud0dc\uc758 \ud734\uba38\ub178\uc774\ub4dc\ub294 \uc544\uc9c1 \uc5f0\uad6c\uc640 \uc2dc\ubc94 \uc801\uc6a9 \ub2e8\uacc4\uc758 \ube44\uc911\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\ub450 \ub2e4\ub9ac\ub85c \uac77\uace0 \uc190\uc73c\ub85c \ubb3c\uac74\uc744 \ub2e4\ub8e8\ub294 \uae30\uc220\uc740 \ub09c\ub3c4\uac00 \ub192\uc544 \uc0c1\uc6a9\ud654\uae4c\uc9c0 \uc2dc\uac04\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n### \uac00\uce58\uc0ac\uc2ac\uc758 \ub2e8\uacc4\\n\\n#### \ud575\uc2ec \ubd80\ud488\\n\\n\ub85c\ubd07 \uc6d0\uac00\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc740 \uac10\uc18d\uae30, \uc11c\ubcf4\ubaa8\ud130, \uc81c\uc5b4\uae30, \uc13c\uc11c\uac00 \ucc28\uc9c0\ud569\ub2c8\ub2e4.<br/>\\n\uac10\uc18d\uae30\ub294 \ubaa8\ud130\uc758 \ud68c\uc804\uc744 \uc904\uc5ec \ud070 \ud798\uc744 \ub0b4\ub294 \uc7a5\uce58\uc774\uace0, \uc11c\ubcf4\ubaa8\ud130\ub294 \uc704\uce58\ub97c \uc815\ubc00\ud558\uac8c \uc81c\uc5b4\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \ubd80\ud488\ub4e4\uc758 \uc815\ubc00\ub3c4\uc640 \ub0b4\uad6c\uc131\uc774 \ub85c\ubd07 \uc804\uccb4\uc758 \uc131\ub2a5\uc744 \uc88c\uc6b0\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubcf8\uccb4\uc640 \uc2dc\uc2a4\ud15c \ud1b5\ud569\\n\\n\ubd80\ud488\uc744 \uc870\ub9bd\ud574 \ub85c\ubd07 \ubcf8\uccb4\ub97c \ub9cc\ub4e4\uace0, \uc2e4\uc81c \ud604\uc7a5\uc5d0 \ub9de\uac8c \uc124\uce58\ud558\ub294 \ub2e8\uacc4\ub97c \uc2dc\uc2a4\ud15c \ud1b5\ud569\uc774\ub77c \ud569\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub85c\ubd07\uc774\ub77c\ub3c4 \uc5b4\ub5a4 \uacf5\uc815\uc5d0 \ub4e4\uc5b4\uac00\ub290\ub0d0\uc5d0 \ub530\ub77c \uc124\uacc4\uc640 \ud504\ub85c\uadf8\ub798\ubc0d\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubcf8\uccb4 \uc81c\uc870\uc640 \uc2dc\uc2a4\ud15c \ud1b5\ud569\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ub7c9\uc744 \uc694\uad6c\ud558\ub294 \uc0ac\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 AI\\n\\n\ucd5c\uadfc \ub85c\ubd07 \uc0b0\uc5c5\uc5d0\uc11c \uac00\uc7a5 \ube60\ub974\uac8c \ubc14\ub00c\ub294 \ubd80\ubd84\uc740 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc785\ub2c8\ub2e4.<br/>\\n\uce74\uba54\ub77c\uc640 \uc13c\uc11c\ub85c \ud658\uacbd\uc744 \uc778\uc2dd\ud558\uace0, AI \ubaa8\ub378\uc774 \ub2e4\uc74c \ub3d9\uc791\uc744 \ud310\ub2e8\ud558\ub294 \ubc29\uc2dd\uc774 \ud655\uc0b0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc18c\ud504\ud2b8\uc6e8\uc5b4 \uc5ed\ub7c9\uc740 \ub85c\ubd07\uc774 \uc815\ud574\uc9c4 \ub3d9\uc791\ub9cc \ubc18\ubcf5\ud558\ub294 \uae30\uacc4\uc5d0\uc11c, \uc0c1\ud669\uc5d0 \uc801\uc751\ud558\ub294 \uae30\uacc4\ub85c \ubc14\ub00c\ub294 \uc5f4\uc1e0\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790 \uad00\uc810\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ub85c\ubd07 \uc0b0\uc5c5\uc744 \ubcfc \ub54c\ub294 \uc5b4\ub5a4 \ub2e8\uacc4\uc758 \uae30\uc5c5\uc778\uc9c0 \uba3c\uc800 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubd80\ud488, \ubcf8\uccb4, \uc2dc\uc2a4\ud15c \ud1b5\ud569, \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub294 \uc218\uc775 \uad6c\uc870\uc640 \uacbd\uae30 \ubbfc\uac10\ub3c4\uac00 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc218\uc8fc \uc794\uace0\uc640 \uace0\uac1d\uc0ac \ub2e4\ubcc0\ud654 \uc5ec\ubd80\ub3c4 \ud568\uaed8 \ud655\uc778\ud558\uba74, \ud55c\ub450 \uace0\uac1d\uc0ac\uc5d0 \uc758\uc874\ud558\ub294 \uad6c\uc870\uc778\uc9c0 \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub610\ud55c \uae30\uc220 \uacfc\uc7a5 \uc5ec\ubd80\ub97c \uac00\ub9ac\uae30 \uc704\ud574, \uc2dc\ubc94 \uc801\uc6a9 \ub2e8\uacc4\uc778\uc9c0 \uc2e4\uc81c \ub9e4\ucd9c\uc774 \ubc1c\uc0dd\ud558\ub294 \ub2e8\uacc4\uc778\uc9c0 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ub85c\ubd07 \uc0b0\uc5c5\uc740 \ubd80\ud488\ubd80\ud130 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uae4c\uc9c0 \uae34 \uac00\uce58\uc0ac\uc2ac\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac01 \ub2e8\uacc4\uc758 \uc5ed\ud560\uacfc \uc218\uc775 \uad6c\uc870\ub97c \uad6c\ubd84\ud574 \uc774\ud574\ud558\uba74, \uc0b0\uc5c5 \ub274\uc2a4\ub97c \uc77d\ub294 \ub208\uc774 \ud55c\uacb0 \ub610\ub837\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMGxwcG5qZ2FraWRxdXdiNDZtYzU3MHdrb2ZzZDhnencxamxjdGF4ciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/dsRgkyNuf7tWsgyTKa/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"us-jobs-report-guide","metadata":{"permalink":"/blog/en/finance/us-jobs-report-guide","source":"@site/finance/2026-10-25-us-jobs-report-guide/index.mdx","title":"\ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c \uc77d\ub294 \ubc95: \ube44\ub18d\uc5c5 \uace0\uc6a9, \uc2e4\uc5c5\ub960, \uc784\uae08 \uc0c1\uc2b9\ub960","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-25T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uacbd\uc81c\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uacbd\uc81c\uc9c0\ud45c"},{"inline":true,"label":"\uace0\uc6a9\ubcf4\uace0\uc11c","permalink":"/blog/en/finance/tags/\uace0\uc6a9\ubcf4\uace0\uc11c"},{"inline":true,"label":"\ubbf8\uad6d\uacbd\uc81c","permalink":"/blog/en/finance/tags/\ubbf8\uad6d\uacbd\uc81c"},{"inline":true,"label":"FOMC","permalink":"/blog/en/finance/tags/fomc"}],"readingTime":2.19,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"us-jobs-report-guide","title":"\ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c \uc77d\ub294 \ubc95: \ube44\ub18d\uc5c5 \uace0\uc6a9, \uc2e4\uc5c5\ub960, \uc784\uae08 \uc0c1\uc2b9\ub960","authors":["way"],"tags":["finance","\uacbd\uc81c\uc9c0\ud45c","\uace0\uc6a9\ubcf4\uace0\uc11c","\ubbf8\uad6d\uacbd\uc81c","FOMC"]},"unlisted":false,"prevItem":{"title":"\ub85c\ubd07 \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124: \ud558\ub4dc\uc6e8\uc5b4\ubd80\ud130 AI\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uac00\uce58\uc0ac\uc2ac","permalink":"/blog/en/finance/robot-industry-structure"},"nextItem":{"title":"\ud55c \uc8fc \uc2dc\uc7a5 \uc815\ub9ac: 5,550\uc120\uc5d0\uc11c \ub9c8\uac10\ud55c \ucf54\uc2a4\ud53c\uc640 \uc5c7\uac08\ub9b0 \ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/weekly-market-review"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \ub9e4\uc6d4 \uc804 \uc138\uacc4 \uae08\uc735\uc2dc\uc7a5\uc774 \uc8fc\ubaa9\ud558\ub294 \ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c\ub97c \uc5b4\ub5bb\uac8c \uc77d\uc5b4\uc57c \ud558\ub294\uc9c0 \uc124\uba85\ud558\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c\ub294 \ubbf8\uad6d \ub178\ub3d9\ud1b5\uacc4\uad6d(BLS)\uc774 \ub9e4\uc6d4 \uccab\uc9f8 \uae08\uc694\uc77c\uc5d0 \ubc1c\ud45c\ud558\ub294 \uacf5\uc2dd \ud1b5\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc740 \uacbd\uae30\uc758 \ud604\uc7ac \uc0c1\ud0dc\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub3d9\uc2dc\uc5d0, \uc18c\ube44 \uc5ec\ub825\uc744 \ud1b5\ud574 \ud5a5\ud6c4 \uacbd\uae30 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\uac8c \ud569\ub2c8\ub2e4.<br/>\\n\uc5f0\uc900\ub3c4 \ud1b5\ud654\uc815\ucc45\uc744 \uacb0\uc815\ud560 \ub54c \uace0\uc6a9 \uc0c1\ud669\uc744 \ud575\uc2ec \uadfc\uac70\ub85c \uc0bc\uae30 \ub54c\ubb38\uc5d0, \ubcf4\uace0\uc11c \ubc1c\ud45c \uc9c1\ud6c4 \uae08\ub9ac \uc804\ub9dd\uacfc \uc8fc\uac00\uac00 \ud06c\uac8c \uc6c0\uc9c1\uc774\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExbXhjM3dxMnBzeGg0dGZyZ2tsdGRtN3ZvczNld2dkNjBqZWk5OXozbSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/egSqD74685gzK/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc138 \uac00\uc9c0 \ud575\uc2ec \uc9c0\ud45c\\n\\n#### \ube44\ub18d\uc5c5 \ubd80\ubb38 \uace0\uc6a9\uc790 \uc218 \ubcc0\ud654\\n\\n\ub18d\uc5c5 \ubd80\ubb38\uc744 \uc81c\uc678\ud55c \uc804 \uc0b0\uc5c5\uc5d0\uc11c \ud55c \ub2ec \ub3d9\uc548 \uc77c\uc790\ub9ac\uac00 \uc5bc\ub9c8\ub098 \ub298\uc5c8\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uc608\uc0c1\uce58\uc640 \uc2e4\uc81c \ubc1c\ud45c\uce58\uc758 \ucc28\uc774\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc774 \ub298\uba74 \uacbd\uae30\uac00 \uac15\ud558\ub2e4\ub294 \ud574\uc11d\uc774 \ub098\uc624\uace0, \uc608\uc0c1\ubcf4\ub2e4 \uc801\uc73c\uba74 \ub454\ud654 \uc6b0\ub824\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc2e4\uc5c5\ub960\\n\\n\uc77c\ud560 \uc758\uc0ac\uc640 \ub2a5\ub825\uc774 \uc788\ub294 \uc0ac\ub78c \uc911 \uc77c\uc790\ub9ac\ub97c \uad6c\ud558\uc9c0 \ubabb\ud55c \uc0ac\ub78c\uc758 \ube44\uc728\uc785\ub2c8\ub2e4.<br/>\\n\uc2e4\uc5c5\ub960\uc774 \ub0ae\uc73c\uba74 \ub178\ub3d9\uc2dc\uc7a5\uc774 \ud0c0\uc774\ud2b8\ud558\ub2e4\ub294 \uc758\ubbf8\uc774\uace0, \ub192\uc73c\uba74 \uacbd\uae30 \ub454\ud654 \uc2e0\ud638\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc2e4\uc5c5\ub960\uc740 \uacbd\uae30\ubcf4\ub2e4 \ub2a6\uac8c \uc6c0\uc9c1\uc774\ub294 \ud6c4\ud589 \uc9c0\ud45c \uc131\uaca9\uc774 \uc788\uc5b4, \ub2e8\ub3c5\uc73c\ub85c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uace0\uc6a9\uc790 \uc218\uc640 \ud568\uaed8 \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc2dc\uac04\ub2f9 \ud3c9\uade0 \uc784\uae08 \uc0c1\uc2b9\ub960\\n\\n\uadfc\ub85c\uc790\uc758 \uc2dc\uac04\ub2f9 \uc784\uae08\uc774 \uc804\uc6d4\uacfc \uc804\ub144 \ub300\ube44 \uc5bc\ub9c8\ub098 \uc62c\ub790\ub294\uc9c0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc784\uae08\uc774 \ube60\ub974\uac8c \uc624\ub974\uba74 \uc18c\ube44 \uc5ec\ub825\uc740 \ucee4\uc9c0\uc9c0\ub9cc, \uae30\uc5c5\uc758 \ube44\uc6a9 \ubd80\ub2f4\uc774 \ucee4\uc838 \ubb3c\uac00 \uc0c1\uc2b9 \uc555\ub825\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uc900\uc774 \uc778\ud50c\ub808\uc774\uc158\uc744 \uacbd\uacc4\ud558\ub294 \uad6d\uba74\uc5d0\uc11c\ub294 \uc784\uae08 \uc0c1\uc2b9\ub960\uc774 \uae08\ub9ac \uacb0\uc815\uc5d0 \uc9c1\uc811\uc801\uc778 \uc601\ud5a5\uc744 \ubbf8\uce69\ub2c8\ub2e4.<br/>\\n\\n### \ud568\uaed8 \ubd10\uc57c \ud560 \uc138\ubd80 \ud56d\ubaa9\\n\\n#### \uc804\uc6d4 \uc218\uce58 \uc218\uc815\\n\\n\uace0\uc6a9\ubcf4\uace0\uc11c\uc5d0\uc11c\ub294 \uc9c1\uc804 \ub450 \ub2ec\uc758 \uace0\uc6a9\uc790 \uc218 \uc218\uc815\uce58\uac00 \ud568\uaed8 \ubc1c\ud45c\ub429\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \ub2ec \uc218\uce58\uac00 \uc88b\uc544 \ubcf4\uc5ec\ub3c4 \uc804\uc6d4 \uc218\uce58\uac00 \ud06c\uac8c \ud558\ud5a5 \uc218\uc815\ub418\uba74, \uc804\uccb4 \uadf8\ub9bc\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubc1c\ud45c\uce58\uc640 \uc218\uc815\uce58\ub97c \ud569\uc0b0\ud574\uc11c \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ub178\ub3d9\ucc38\uac00\uc728\uacfc \uc5c5\uc885\ubcc4 \ubd84\ud3ec\\n\\n\ub178\ub3d9\ucc38\uac00\uc728\uc740 \uc77c\ud560 \uc218 \uc788\ub294 \uc778\uad6c \uc911 \uc2e4\uc81c\ub85c \uc77c\ud558\uac70\ub098 \uad6c\uc9c1 \uc911\uc778 \uc0ac\ub78c\uc758 \ube44\uc728\uc785\ub2c8\ub2e4.<br/>\\n\ucc38\uac00\uc728\uc774 \uc624\ub974\uba74 \uad6c\uc9c1\uc790\uac00 \ub298\uc5b4\ub098 \uc2e4\uc5c5\ub960\uc774 \uc62c\ub77c\ub3c4 \ub178\ub3d9\uc2dc\uc7a5\uc774 \ubc18\ub4dc\uc2dc \ub098\ube60\uc9c4 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885\ubcc4\ub85c\ub294 \uc5b4\ub290 \uc0b0\uc5c5\uc5d0\uc11c \uc77c\uc790\ub9ac\uac00 \ub298\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\uba74, \uacbd\uae30 \ud68c\ubcf5\uc774 \ud2b9\uc815 \ubd84\uc57c\uc5d0 \uce58\uc6b0\ucce4\ub294\uc9c0 \uace0\ub974\uac8c \ub098\ud0c0\ub098\ub294\uc9c0 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud574\uc11d\uc758 \ud568\uc815\\n\\n\uace0\uc6a9\uc774 \uac15\ud55c \uac83\uc740 \uacbd\uae30\uc5d0\ub294 \uae0d\uc815\uc801\uc774\uc9c0\ub9cc, \uae08\ub9ac\uc5d0\ub294 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacfc\uc5f4\ub41c \uace0\uc6a9\uc740 \uc5f0\uc900\uc758 \uae08\ub9ac \uc778\ud558\ub97c \ub2a6\ucd94\ub294 \uadfc\uac70\uac00 \ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uace0\uc6a9\uc774 \uc57d\ud558\uba74 \uae08\ub9ac \uc778\ud558 \uae30\ub300\ub294 \ucee4\uc9c0\uc9c0\ub9cc, \uacbd\uae30 \uce68\uccb4 \uc6b0\ub824\ub3c4 \ud568\uaed8 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc989 \uac19\uc740 \uc9c0\ud45c\ub77c\ub3c4 \uae08\ub9ac \uad6d\uba74\uc5d0 \ub530\ub77c \uc2dc\uc7a5\uc758 \ubc18\uc751\uc774 \uc815\ubc18\ub300\ub85c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc5fc\ub450\uc5d0 \ub450\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c\ub294 \uc22b\uc790 \ud558\ub098\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc9c0\ud45c\uc758 \uc870\ud569\uc73c\ub85c \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ube44\ub18d\uc5c5 \uace0\uc6a9, \uc2e4\uc5c5\ub960, \uc784\uae08 \uc0c1\uc2b9\ub960\uacfc \uc218\uc815\uce58\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \uc2dc\uc7a5\uc758 \ubc18\uc751\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExYm9uNGY3dGFwMHd4cHBucWF1dHB5bGIxcjI2azF1djg4cXc2cW40YyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/13rQ7rrTrvZXlm/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"weekly-market-review","metadata":{"permalink":"/blog/en/finance/weekly-market-review","source":"@site/finance/2026-10-25-weekly-market-review/index.mdx","title":"\ud55c \uc8fc \uc2dc\uc7a5 \uc815\ub9ac: 5,550\uc120\uc5d0\uc11c \ub9c8\uac10\ud55c \ucf54\uc2a4\ud53c\uc640 \uc5c7\uac08\ub9b0 \ucf54\uc2a4\ub2e5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-25T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uc2dc\uc7a5\uc815\ub9ac","permalink":"/blog/en/finance/tags/\uc2dc\uc7a5\uc815\ub9ac"},{"inline":true,"label":"\ucf54\uc2a4\ud53c","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ud53c"},{"inline":true,"label":"\ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/tags/\ucf54\uc2a4\ub2e5"},{"inline":true,"label":"\ud658\uc728","permalink":"/blog/en/finance/tags/\ud658\uc728"}],"readingTime":1.89,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"weekly-market-review","title":"\ud55c \uc8fc \uc2dc\uc7a5 \uc815\ub9ac: 5,550\uc120\uc5d0\uc11c \ub9c8\uac10\ud55c \ucf54\uc2a4\ud53c\uc640 \uc5c7\uac08\ub9b0 \ucf54\uc2a4\ub2e5","authors":["way"],"tags":["finance","\uc2dc\uc7a5\uc815\ub9ac","\ucf54\uc2a4\ud53c","\ucf54\uc2a4\ub2e5","\ud658\uc728"]},"unlisted":false,"prevItem":{"title":"\ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c \uc77d\ub294 \ubc95: \ube44\ub18d\uc5c5 \uace0\uc6a9, \uc2e4\uc5c5\ub960, \uc784\uae08 \uc0c1\uc2b9\ub960","permalink":"/blog/en/finance/us-jobs-report-guide"},"nextItem":{"title":"\uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28 \ud574\uc124: \uc218\uc775\ub960 \uace1\uc120 \uc5ed\uc804\uc774 \ub9d0\ud574\uc8fc\ub294 \uac83","permalink":"/blog/en/finance/yield-curve-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uc8fc\ub9d0\uc744 \ub9de\uc544 \uae08\uc694\uc77c \ub9c8\uac10 \uae30\uc900\uc73c\ub85c \ud55c \uc8fc \uc99d\uc2dc\ub97c \uc815\ub9ac\ud558\uace0, \ub2e4\uc74c \uc8fc\uc5d0 \ud655\uc778\ud560 \uc9c0\ud45c\ub97c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc9c0\ub09c \uae08\uc694\uc77c(10\uc6d4 23\uc77c)\uc740 \uad6d\ub0b4 \uc99d\uc2dc\uac00 \uc5c7\uac08\ub9b0 \ud750\ub984\uc73c\ub85c \ud55c \uc8fc\ub97c \ub9c8\uce5c \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ucf54\uc2a4\ud53c\ub294 \uc0c1\uc2b9\ud588\uc9c0\ub9cc, \ucf54\uc2a4\ub2e5\uc740 \ud558\ub77d\ud558\uba70 \uc2dc\uc7a5 \ub0b4\ubd80\uc758 \uc628\ub3c4 \ucc28\uac00 \ub4dc\ub7ec\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ud574\uc678 \uc99d\uc2dc\ub3c4 \ubbf8\uad6d \uc8fc\uc694 \uc9c0\uc218\uac00 \uc18c\ud3ed \ud558\ub77d\ud558\ub294 \ub4f1 \ubc29\ud5a5\uc131\uc774 \ub69c\ub837\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExd3RwcjN5Znh6M2Nid3UxNHJjZHo5ZW5jYW9kMWg5a3l5aG5ubGs1eCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/JtBZm3Getg3dqxK0zP/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae08\uc694\uc77c \ub9c8\uac10 \uc218\uce58\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uc2dc\uc7a5 \ub370\uc774\ud130 \uae30\uc900\uc73c\ub85c 10\uc6d4 23\uc77c \ub9c8\uac10 \uc218\uce58\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 |\\n| --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,550.30 | +16.53 | +0.30% |\\n| \ucf54\uc2a4\ub2e5 | 751.69 | -12.41 | -1.62% |\\n| \ucf54\uc2a4\ud53c200 | 862.77 | +4.75 | +0.55% |\\n| \uc6d0/\ub2ec\ub7ec \ud658\uc728 | 1,326.20\uc6d0 | -0.30\uc6d0 | -0.02% |\\n| S&amp;P500 | 7,623.68 | -39.75 | -0.52% |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,955.34 | -53.52 | -0.21% |\\n\\n#### \ucf54\uc2a4\ud53c\ub294 \uc0c1\uc2b9, \ucf54\uc2a4\ub2e5\uc740 \ud558\ub77d\\n\\n\ucf54\uc2a4\ud53c\ub294 5,550\uc120\uc744 \uc9c0\ud0a4\uba70 \uc18c\ud3ed \uc62c\ub790\uace0, \ucf54\uc2a4\ud53c200\ub3c4 \ud568\uaed8 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ucf54\uc2a4\ub2e5\uc740 1.62% \ub0b4\ub9ac\uba70 \ub300\ud615\uc8fc\uc640 \uc911\uc18c\ud615\uc8fc \uc0ac\uc774\uc758 \uad34\ub9ac\uac00 \ud655\uc778\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc804\uccb4\uac00 \uc624\ub974\ub294 \uc7a5\uacfc \uc77c\ubd80\ub9cc \uc624\ub974\ub294 \uc7a5\uc740 \uccb4\uac10\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc774\ub7f4 \ub54c\ub294 \uc9c0\uc218 \uc218\uce58\ub9cc \ubcf4\uc9c0 \uc54a\uace0, \uc0c1\uc2b9 \uc885\ubaa9 \uc218\uc640 \uac70\ub798\ub300\uae08 \uac19\uc740 \uc2dc\uc7a5 breadth \uc9c0\ud45c\ub3c4 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\uacfc \ud574\uc678 \uc99d\uc2dc\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,326.20\uc6d0\uc73c\ub85c \uc804\uc77c\ubcf4\ub2e4 \uc18c\ud3ed \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d S&amp;P500\uacfc \ub098\uc2a4\ub2e5 \uc885\ud569\ub3c4 \uac01\uac01 0.52%, 0.21% \ud558\ub77d\ud558\uba70 \uc870\uc815 \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud574\uc678 \uc99d\uc2dc\uac00 \uc26c\uc5b4\uac00\ub294 \uad6c\uac04\uc5d0\uc11c\ub294 \uad6d\ub0b4 \uc99d\uc2dc\ub3c4 \ub3c5\uc790\uc801\uc778 \ubc29\ud5a5\uc744 \uc7a1\uae30\ubcf4\ub2e4 \uc678\ubd80 \ubcc0\uc218\uc5d0 \ubbfc\uac10\ud574\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub2e4\uc74c \uc8fc\uc5d0 \ud655\uc778\ud560 \uc810\\n\\n\ub2e4\uc74c \uc8fc\uc5d0\ub294 \ubbf8\uad6d \uc8fc\uc694 \uacbd\uc81c\uc9c0\ud45c \ubc1c\ud45c\uc640 \uad6d\ub0b4\uc678 \uae30\uc5c5 \uc2e4\uc801 \ubc1c\ud45c \uc77c\uc815\uc774 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc9c0\ud45c\uac00 \uc608\uc0c1\uc744 \ud06c\uac8c \ubc97\uc5b4\ub098\uba74 \uae08\ub9ac \uc804\ub9dd\uc774 \ubc14\ub00c\uace0, \uc774\ub294 \ub2e4\uc2dc \uc99d\uc2dc \ubc29\ud5a5\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \ubc1c\ud45c\uc5d0\uc11c\ub294 \ub9e4\ucd9c\uacfc \uc601\uc5c5\uc774\uc775\uc758 \uc808\ub300 \uc218\uce58\ubcf4\ub2e4, \uc2dc\uc7a5 \uc608\uc0c1 \ub300\ube44 \ubd80\ud569 \uc5ec\ubd80\uc640 \ud5a5\ud6c4 \uac00\uc774\ub358\uc2a4 \ubcc0\uacbd \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub610\ud55c \ucf54\uc2a4\ub2e5\uc758 \uc57d\uc138\uac00 \uc77c\uc2dc\uc801\uc778 \uc218\uae09 \uc694\uc778\uc778\uc9c0, \ucd94\uc138\uc801\uc778 \ubcc0\ud654\uc778\uc9c0\ub3c4 \uc9c0\ucf1c\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ud55c \uc8fc\ub294 \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ub9c8\uac10\ud558\uba70 \ub9c8\ubb34\ub9ac\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc\uc5d0\ub294 \uc9c0\ud45c\uc640 \uc2e4\uc801\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \uc7ac\ub8cc\ub97c \ucc28\ubd84\ud788 \ud655\uc778\ud558\uba70 \uc2dc\uc7a5\uc758 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud574 \ubcf4\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExZDhlM3RpMjR6NHQ0bm93aW5zaDczdzllb2V6dTFiZXFsOWl5NDE1byZlcD12MV9naWZzX3NlYXJjaCZjdD1n/RP0C2pxOil7dYuzgyi/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"yield-curve-guide","metadata":{"permalink":"/blog/en/finance/yield-curve-guide","source":"@site/finance/2026-10-25-yield-curve-guide/index.mdx","title":"\uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28 \ud574\uc124: \uc218\uc775\ub960 \uace1\uc120 \uc5ed\uc804\uc774 \ub9d0\ud574\uc8fc\ub294 \uac83","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-25T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"\uae08\ub9ac","permalink":"/blog/en/finance/tags/\uae08\ub9ac"},{"inline":true,"label":"\ucc44\uad8c","permalink":"/blog/en/finance/tags/\ucc44\uad8c"},{"inline":true,"label":"\uc218\uc775\ub960\uace1\uc120","permalink":"/blog/en/finance/tags/\uc218\uc775\ub960\uace1\uc120"},{"inline":true,"label":"\uacbd\uc81c\uc9c0\ud45c","permalink":"/blog/en/finance/tags/\uacbd\uc81c\uc9c0\ud45c"}],"readingTime":2.17,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"yield-curve-guide","title":"\uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28 \ud574\uc124: \uc218\uc775\ub960 \uace1\uc120 \uc5ed\uc804\uc774 \ub9d0\ud574\uc8fc\ub294 \uac83","authors":["way"],"tags":["finance","\uae08\ub9ac","\ucc44\uad8c","\uc218\uc775\ub960\uace1\uc120","\uacbd\uc81c\uc9c0\ud45c"]},"unlisted":false,"prevItem":{"title":"\ud55c \uc8fc \uc2dc\uc7a5 \uc815\ub9ac: 5,550\uc120\uc5d0\uc11c \ub9c8\uac10\ud55c \ucf54\uc2a4\ud53c\uc640 \uc5c7\uac08\ub9b0 \ucf54\uc2a4\ub2e5","permalink":"/blog/en/finance/weekly-market-review"},"nextItem":{"title":"\uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uc9c0\uc218\uc640 \ub3d9\uc77c\uac00\uc911 \uc9c0\uc218 \uc77d\uae30","permalink":"/blog/en/finance/cap-weighted-index-oct24"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28, \uc989 \uc218\uc775\ub960 \uace1\uc120\uc774 \ubb34\uc5c7\uc774\uace0 \uc65c \uc8fc\ubaa9\ubc1b\ub294\uc9c0 \uc124\uba85\ud558\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ucc44\uad8c\uc740 \ub9cc\uae30\uac00 \ub2e4\uc591\ud569\ub2c8\ub2e4.<br/>\\n2\ub144 \ub9cc\uae30 \uad6d\ucc44\uc640 10\ub144 \ub9cc\uae30 \uad6d\ucc44\ub294 \uac19\uc740 \ub098\ub77c\uac00 \ubc1c\ud589\ud574\ub3c4 \uae08\ub9ac\uac00 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\ub9cc\uae30\ubcc4 \uae08\ub9ac\ub97c \uc5f0\uacb0\ud55c \uace1\uc120\uc774 \uc218\uc775\ub960 \uace1\uc120\uc774\uace0, 10\ub144\ubb3c \uae08\ub9ac\uc5d0\uc11c 2\ub144\ubb3c \uae08\ub9ac\ub97c \ube80 \uac12\uc774 \uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc218\uce58\ub294 \uacbd\uae30\uc640 \ud1b5\ud654\uc815\ucc45\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \uae30\ub300\ub97c \uc555\ucd95\ud574 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\ub85c \uc790\uc8fc \uc778\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjExb2I0Z2Jqa2dncHQ3NjNzMmJuZjEzczA2d2JhdDJsNjJzMmt5aDh1OCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/OTq0Tin5Sk74c/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc218\uc775\ub960 \uace1\uc120\uc758 \uc138 \uac00\uc9c0 \ubaa8\uc591\\n\\n#### \uc815\uc0c1\ud615 \uace1\uc120\\n\\n\uc7a5\uae30 \uae08\ub9ac\uac00 \ub2e8\uae30 \uae08\ub9ac\ubcf4\ub2e4 \ub192\uc740 \uc77c\ubc18\uc801\uc778 \ud615\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\ub3c8\uc744 \uc624\ub798 \ube4c\ub824\uc904\uc218\ub85d \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc9c0\ubbc0\ub85c, \ud22c\uc790\uc790\ub294 \uadf8\ub9cc\ud07c \ub192\uc740 \uae08\ub9ac\ub97c \uc694\uad6c\ud569\ub2c8\ub2e4.<br/>\\n\uacbd\uae30 \ud655\uc7a5\uae30\uc5d0\ub294 \uc774\ub7f0 \ud615\ud0dc\uac00 \ud754\ud788 \ub098\ud0c0\ub0a9\ub2c8\ub2e4.<br/>\\n\\n#### \uc5ed\uc804\ud615 \uace1\uc120\\n\\n\ub2e8\uae30 \uae08\ub9ac\uac00 \uc7a5\uae30 \uae08\ub9ac\ubcf4\ub2e4 \ub192\uc544\uc9c0\ub294 \ud615\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\uacc4\uc0b0 \uc608\uc2dc\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n```text\\n10\ub144\ubb3c \uae08\ub9ac 4.0% - 2\ub144\ubb3c \uae08\ub9ac 4.5% = -0.5%p (\uc5ed\uc804)\\n```\\n\\n\uc911\uc559\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c \uc62c\ub824 \ub2e8\uae30 \uae08\ub9ac\uac00 \ub192\uc544\uc9c0\uac70\ub098, \uc2dc\uc7a5\uc774 \ubbf8\ub798 \uacbd\uae30 \ub454\ud654\ub97c \uc608\uc0c1\ud574 \uc7a5\uae30 \uae08\ub9ac\ub97c \ub0ae\uac8c \ud3c9\uac00\ud560 \ub54c \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\uacfc\uac70 \ubbf8\uad6d\uc5d0\uc11c\ub294 \uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28 \uc5ed\uc804 \uc774\ud6c4 \uacbd\uae30\uce68\uccb4\uac00 \ub4a4\ub530\ub978 \uc0ac\ub840\uac00 \uc5ec\ub7ec \ucc28\ub840 \uc788\uc5b4, \uce68\uccb4\uc758 \uc120\ud589 \uc2e0\ud638\ub85c \uac70\ub860\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ud3c9\ud0c4\ud615 \uace1\uc120\\n\\n\uc7a5\ub2e8\uae30 \uae08\ub9ac \ucc28\uc774\uac00 \uac70\uc758 \uc5c6\uc5b4 \uace1\uc120\uc774 \ub0a9\uc791\ud574\uc9c0\ub294 \ud615\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\ud1b5\ud654\uc815\ucc45 \uc804\ud658\uae30\ub098 \uacbd\uae30 \ubc29\ud5a5\uc774 \ubd88\ud655\uc2e4\ud560 \ub54c \ub098\ud0c0\ub098\uba70, \uc815\uc0c1\ud615\uacfc \uc5ed\uc804\ud615 \uc0ac\uc774\uc758 \uc911\uac04 \ub2e8\uacc4\ub85c \ud574\uc11d\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc65c \uc5ed\uc804\uc774 \uc8fc\ubaa9\ubc1b\ub294\uac00\\n\\n\uc740\ud589\uc740 \ub2e8\uae30\ub85c \ub3c8\uc744 \uc870\ub2ec\ud574 \uc7a5\uae30\ub85c \ube4c\ub824\uc8fc\ub294 \uad6c\uc870\uac00 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30 \uae08\ub9ac\uac00 \uc7a5\uae30 \uae08\ub9ac\ubcf4\ub2e4 \ub192\uc544\uc9c0\uba74 \uc774 \ub9c8\uc9c4\uc774 \uc904\uc5b4\ub4e4\uc5b4 \ub300\ucd9c \uc5ec\ub825\uc774 \ucd95\uc18c\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e0\uc6a9 \uacf5\uae09\uc774 \uc904\uc5b4\ub4e4\uba74 \ud22c\uc790\uc640 \uc18c\ube44\uac00 \uc704\ucd95\ub418\uace0, \uacbd\uae30 \ub454\ud654\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc5ed\uc804 \uc2e0\ud638\uac00 \uc8fc\ubaa9\ubc1b\ub294 \ub17c\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e0\ud638\uc758 \ud55c\uacc4\\n\\n\uc5ed\uc804\uc774 \uacbd\uae30\uce68\uccb4\ub97c \uc608\uace0\ud55c \uc0ac\ub840\uac00 \uc788\uc9c0\ub9cc, \uc2dc\ucc28\ub294 \uc77c\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc804 \uc774\ud6c4 \uc2e4\uc81c \uce68\uccb4\uae4c\uc9c0 \uc218\uac1c\uc6d4\uc5d0\uc11c 2\ub144 \uac00\uae4c\uc774 \uac78\ub9b0 \uacbd\uc6b0\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub610\ud55c \uc911\uc559\uc740\ud589\uc758 \ub300\uaddc\ubaa8 \ucc44\uad8c \ub9e4\uc785 \uac19\uc740 \uc815\ucc45 \uc694\uc778\uc774 \uc7a5\uae30 \uae08\ub9ac\ub97c \uc778\uc704\uc801\uc73c\ub85c \ub0ae\ucd94\uba74, \uace1\uc120 \ubaa8\uc591 \uc790\uccb4\uac00 \uc65c\uace1\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28 \ud558\ub098\ub9cc\uc73c\ub85c \uacbd\uae30 \ubc29\ud5a5\uc744 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4\ub294, \uace0\uc6a9, \uc18c\ube44, \uae30\uc5c5 \uc2e4\uc801 \uac19\uc740 \uc9c0\ud45c\uc640 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud569\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ubbf8\uad6d 10\ub144\ubb3c\uacfc 2\ub144\ubb3c \uae08\ub9ac, \ud55c\uad6d \uad6d\uace0\ucc44 10\ub144\ubb3c\uacfc 3\ub144\ubb3c \uae08\ub9ac\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \uad6d\ub0b4\uc678 \uace1\uc120 \ud750\ub984\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc804\uc774 \ud574\uc18c\ub418\ub294 \uacfc\uc815\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30 \uae08\ub9ac\uac00 \ub0b4\ub824\uac00\uba74\uc11c \ud574\uc18c\ub418\ub294 \uacbd\uc6b0\uc640, \uc7a5\uae30 \uae08\ub9ac\uac00 \uc62c\ub77c\uac00\uba74\uc11c \ud574\uc18c\ub418\ub294 \uacbd\uc6b0\ub294 \uacbd\uae30\uc5d0 \uc8fc\ub294 \uc758\ubbf8\uac00 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28\ub294 \uc2dc\uc7a5\uc758 \uacbd\uae30 \uae30\ub300\ub97c \ud55c\ub208\uc5d0 \ubcf4\uc5ec\uc8fc\ub294 \uc720\uc6a9\ud55c \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc120\ud589 \uc2e0\ud638\uc77c \ubfd0 \ud655\uc815\ub41c \uc608\uce21\uc774 \uc544\ub2c8\ubbc0\ub85c, \ub2e4\ub978 \uc9c0\ud45c\uc640 \ud568\uaed8 \uade0\ud615 \uc788\uac8c \ud574\uc11d\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media2.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ29oaXV3eGIyN2gyazdjaGM5dDZsbnlxbDQxaHBrc3hqcTN5Y2M5aSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/N2QQfEMAogAEQhJlkw/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"cap-weighted-index-oct24","metadata":{"permalink":"/blog/en/finance/cap-weighted-index-oct24","source":"@site/finance/2026-10-24-cap-weighted-index/index.mdx","title":"\uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uc9c0\uc218\uc640 \ub3d9\uc77c\uac00\uc911 \uc9c0\uc218 \uc77d\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-24T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"concept","permalink":"/blog/en/finance/tags/concept"},{"inline":true,"label":"index","permalink":"/blog/en/finance/tags/index"},{"inline":true,"label":"market-structure","permalink":"/blog/en/finance/tags/market-structure"}],"readingTime":2.19,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"cap-weighted-index-oct24","title":"\uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uc9c0\uc218\uc640 \ub3d9\uc77c\uac00\uc911 \uc9c0\uc218 \uc77d\uae30","authors":["way"],"tags":["finance","concept","index","market-structure"]},"unlisted":false,"prevItem":{"title":"\uc7a5\ub2e8\uae30 \uae08\ub9ac\ucc28 \ud574\uc124: \uc218\uc775\ub960 \uace1\uc120 \uc5ed\uc804\uc774 \ub9d0\ud574\uc8fc\ub294 \uac83","permalink":"/blog/en/finance/yield-curve-guide"},"nextItem":{"title":"\uc9c0\uc218\ub294 \uc62c\ub790\ub294\ub370 \ub0b4 \uc885\ubaa9\uc740 \ub0b4\ub838\ub2e4 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-breadth-divergence-oct24"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n10\uc6d4 23\uc77c\ucc98\ub7fc \uc9c0\uc218\uc640 \uccb4\uac10 \uc628\ub3c4\uac00 \uc5b4\uae0b\ub098\ub294 \ub0a0\uc774 \uc0dd\uae30\ub294 \uc774\uc720\ub97c, \uc9c0\uc218 \uacc4\uc0b0 \ubc29\uc2dd\uc5d0\uc11c \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uac19\uc740 \uc2dc\uc7a5, \ub2e4\ub978 \uc628\ub3c4\uacc4\\n\\n\uc9c0\uc218\ub294 \uc2dc\uc7a5 \uc804\uccb4\ub97c \ud558\ub098\uc758 \uc22b\uc790\ub85c \uc694\uc57d\ud55c \uc628\ub3c4\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uc628\ub3c4\uacc4\uc758 \uc124\uacc4 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uac19\uc740 \ub0a0\uc758 \uc22b\uc790\ub3c4 \ub2e4\ub974\uac8c \ub098\uc635\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uac00 \ub300\ud45c\uc801\uc73c\ub85c \uc4f0\ub294 \ubc29\uc2dd\uc740 \uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\uc774\uc640 \ub300\ube44\ub418\ub294 \ubc29\uc2dd\uc774 \ubaa8\ub4e0 \uc885\ubaa9\uc744 \uac19\uc740 \ube44\uc911\uc73c\ub85c \ub2e4\ub8e8\ub294 \ub3d9\uc77c\uac00\uc911 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ2VsYzc0a2tqbW1zcDF1amc3aXBxeTdlamcwb2ttNWh4dHJuaXdiOCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/SIB5Nv9q4LGULOaHZN/giphy.gif\\" alt=\\"Balance\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ub450 \uac00\uc9c0 \uac00\uc911 \ubc29\uc2dd\\n\\n#### \uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \ubc29\uc2dd\\n\\n\uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \ubc29\uc2dd\uc5d0\uc11c\ub294 \uc885\ubaa9\uc758 \uc2dc\uac00\ucd1d\uc561\uc774 \ud074\uc218\ub85d \uc9c0\uc218\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc2dc\uac00\ucd1d\uc561\uc774 `100\uc870 \uc6d0`\uc778 \uc885\ubaa9\uacfc `1\uc870 \uc6d0`\uc778 \uc885\ubaa9\uc774 \uac01\uac01 1% \uc62c\ub790\uc744 \ub54c, \uc9c0\uc218\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc740 100\ubc30 \ucc28\uc774\uac00 \ub0a9\ub2c8\ub2e4.<br/>\\n\uc774 \ubc29\uc2dd\uc740 \uc2dc\uc7a5 \uc804\uccb4\uc758 \uacbd\uc81c\uc801 \ubb34\uac8c\ub97c \ubc18\uc601\ud55c\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc18c\uc218 \ub300\ud615\uc8fc\uc758 \uc6c0\uc9c1\uc784\uc774 \uc9c0\uc218\ub97c \uc88c\uc6b0\ud558\uae30 \uc27d\ub2e4\ub294 \ub2e8\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 23\uc77c \ucf54\uc2a4\ud53c\uac00 \uc0c1\uc2b9 \uc885\ubaa9 173\uac1c, \ud558\ub77d \uc885\ubaa9 717\uac1c\ub77c\ub294 breadth \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9 \ub9c8\uac10\ud55c \ubc30\uacbd\uc774 \ubc14\ub85c \uc774 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ub3d9\uc77c\uac00\uc911 \ubc29\uc2dd\\n\\n\ub3d9\uc77c\uac00\uc911 \ubc29\uc2dd\uc5d0\uc11c\ub294 \ubaa8\ub4e0 \uc885\ubaa9\uc774 \uac19\uc740 \ube44\uc911\uc73c\ub85c \uc9c0\uc218\uc5d0 \ubc18\uc601\ub429\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \ud55c \uc885\ubaa9\uacfc \uc18c\ud615\uc8fc \ud55c \uc885\ubaa9\uc758 1% \uc0c1\uc2b9\uc774 \uc9c0\uc218\uc5d0 \ub611\uac19\uc774 \ubc18\uc601\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \ubc29\uc2dd\uc740 \uc2dc\uc7a5 \ucc38\uc5ec \uc885\ubaa9\ub4e4\uc758 \ud3c9\uade0\uc801\uc778 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ub370 \uc720\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc2e4\uc81c \ud22c\uc790 \uc790\uae08\uc774 \ub300\ud615\uc8fc\uc5d0 \ub354 \ub9ce\uc774 \ubab0\ub824 \uc788\ub2e4\ub294 \ud604\uc2e4\uacfc\ub294 \uac70\ub9ac\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0\uc758 \ub450 \uc9c0\uc218\ub97c \ube44\uad50\ud558\uba74, \uc0c1\uc2b9\uc774 \ub300\ud615\uc8fc \uc911\uc2ec\uc778\uc9c0 \uc885\ubaa9 \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub410\ub294\uc9c0\ub97c \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uacc4\uc0b0 \uc608\uc2dc\\n\\n\uc2dc\uac00\ucd1d\uc561 `100\uc870 \uc6d0` \uc885\ubaa9\uc774 2% \uc624\ub974\uace0, \uc2dc\uac00\ucd1d\uc561 `1\uc870 \uc6d0` \uc885\ubaa9 10\uac1c\uac00 \uac01\uac01 2% \ub0b4\ub838\ub2e4\uace0 \uac00\uc815\ud569\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uad00\uc810\uc5d0\uc11c\ub294 \ub300\ud615\uc8fc\uc758 \uc0c1\uc2b9 \uc601\ud5a5\uc774 \ub354 \ucee4\uc11c \uc804\uccb4 \uc9c0\uc218\ub294 \uc0c1\uc2b9 \ucabd\uc73c\ub85c \uae30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3d9\uc77c\uac00\uc911 \uad00\uc810\uc5d0\uc11c\ub294 \ud558\ub77d \uc885\ubaa9\uc774 10\uac1c\ub85c \ub354 \ub9ce\uc73c\ubbc0\ub85c \uc804\uccb4 \ud3c9\uade0\uc740 \ud558\ub77d \ucabd\uc73c\ub85c \uae30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc22b\uc790\ub294 \ub2e8\uc21c\ud654\ud55c \uc608\uc2dc\uc774\uc9c0\ub9cc, \ub450 \ubc29\uc2dd\uc774 \uc65c \ub2e4\ub978 \uc2e0\ud638\ub97c \ub0b4\ub294\uc9c0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc9c0\uc218\ub97c \ubcfc \ub54c\ub294 \uc5b4\ub5a4 \uac00\uc911 \ubc29\uc2dd\uc778\uc9c0 \uba3c\uc800 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uac19\uc740 \uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uc9c0\uc218\ub294 \ub300\ud615\uc8fc \ud750\ub984\uc744, \ub3d9\uc77c\uac00\uc911 \uc9c0\uc218\ub294 \uc885\ubaa9 \uc804\ubc18\uc758 \ud750\ub984\uc744 \ub354 \uc798 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\nETF\ub97c \uace0\ub97c \ub54c\ub3c4 \ucd94\uc885 \uc9c0\uc218\uc758 \uac00\uc911 \ubc29\uc2dd\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc5c5\uc885 ETF\ub77c\ub3c4 \uac00\uc911 \ubc29\uc2dd\uc5d0 \ub530\ub77c \ub300\ud615\uc8fc \ube44\uc911\uacfc \ubcc0\ub3d9\uc131\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uc624\ub974\ub294\ub370 \ubcf4\uc720 \uc885\ubaa9\uc774 \ub0b4\ub9b0\ub2e4\uba74, \uac00\uc911 \ubc29\uc2dd \ucc28\uc774\ubd80\ud130 \uc810\uac80\ud574\ubcf4\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc9c0\uc218\ub294 \ud558\ub098\uc758 \uc22b\uc790\uac00 \uc544\ub2c8\ub77c \uc124\uacc4 \ubc29\uc2dd\uc774 \ub2f4\uae34 \uc694\uc57d\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\uac00\uc911 \ubc29\uc2dd\uc744 \uc54c\uba74 \uc9c0\uc218\uc640 \uccb4\uac10 \uc0ac\uc774\uc758 \uac04\uaca9\uc774 \uc65c \uc0dd\uae30\ub294\uc9c0 \uc774\ud574\ud558\uae30\uac00 \uc26c\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ2VsYzc0a2tqbW1zcDF1amc3aXBxeTdlamcwb2ttNWh4dHJuaXdiOCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/pNTxdmv2IKs4OxdSGN/giphy.gif\\" alt=\\"Balance\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-breadth-divergence-oct24","metadata":{"permalink":"/blog/en/finance/kospi-breadth-divergence-oct24","source":"@site/finance/2026-10-24-kospi-breadth-divergence/index.mdx","title":"\uc9c0\uc218\ub294 \uc62c\ub790\ub294\ub370 \ub0b4 \uc885\ubaa9\uc740 \ub0b4\ub838\ub2e4 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-24T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"market-recap","permalink":"/blog/en/finance/tags/market-recap"},{"inline":true,"label":"kospi","permalink":"/blog/en/finance/tags/kospi"},{"inline":true,"label":"kosdaq","permalink":"/blog/en/finance/tags/kosdaq"}],"readingTime":2.25,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-breadth-divergence-oct24","title":"\uc9c0\uc218\ub294 \uc62c\ub790\ub294\ub370 \ub0b4 \uc885\ubaa9\uc740 \ub0b4\ub838\ub2e4 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","authors":["way"],"tags":["finance","market-recap","kospi","kosdaq"]},"unlisted":false,"prevItem":{"title":"\uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uc9c0\uc218\uc640 \ub3d9\uc77c\uac00\uc911 \uc9c0\uc218 \uc77d\uae30","permalink":"/blog/en/finance/cap-weighted-index-oct24"},"nextItem":{"title":"\uae09\uc5ec\uc77c\uc5d0 \uc790\ub3d9\uc774\uccb4\ub85c \ub9cc\ub4dc\ub294 \uc800\ucd95 \uc2dc\uc2a4\ud15c","permalink":"/blog/en/finance/paycheck-saving-system-oct24"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n10\uc6d4 23\uc77c \uae08\uc694\uc77c \uc7a5 \ub9c8\uac10 \ub3d9\ud5a5\uacfc, \uc9c0\uc218 \uc0c1\uc2b9\uacfc \uc885\ubaa9 \ud558\ub77d\uc774 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub09c \uc774\uc720\ub97c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 0.30% \uc0c1\uc2b9 \ub4a4\uc5d0 \uac00\ub824\uc9c4 \ud558\ub77d \uc885\ubaa9\\n\\n10\uc6d4 23\uc77c \ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 16.53\ud3ec\uc778\ud2b8(0.30%) \uc624\ub978 `5,550.30`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \ubc18\ub3c4\uccb4\uc8fc \uc57d\uc138 \uc5ec\ud30c\ub85c 2.36% \ud558\ub77d \ucd9c\ubc1c\ud55c \ub4a4 \uc7a5\uc911 \ud55c\ub54c 4% \ub118\uac8c \ubc00\ub838\uc9c0\ub9cc, \uc624\ud6c4 \ub4e4\uc5b4 \ub099\ud3ed\uc744 \uc904\uc774\uace0 \uc0c1\uc2b9 \uc804\ud658\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uac19\uc740 \ub0a0 12.41\ud3ec\uc778\ud2b8(1.62%) \ub0b4\ub9b0 `751.69`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc740 4.75\ud3ec\uc778\ud2b8(0.55%) \uc624\ub978 `862.77`\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 24\uc77c \ud1a0\uc694\uc77c\uc740 \ud734\uc7a5\uc77c\uc774\ubbc0\ub85c, \uc774\ubc88 \uc8fc\ub9d0\uc5d0 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac00\uc7a5 \ucd5c\uadfc \uc885\uac00\ub294 10\uc6d4 23\uc77c \uae08\uc694\uc77c \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY2tudHV2djhic25xZm5pN3EzNXA4ejlsazg0bG52c3R3YW0zdW1nayZlcD12MV9naWZzX3NlYXJjaCZjdD1n/JtBZm3Getg3dqxK0zP/giphy.gif\\" alt=\\"Market\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc9c0\uc218\ub294 \uc65c \uc62c\ub790\ub294\uac00\\n\\n#### \uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \ubc29\uc2dd\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00\ucd1d\uc561 \uac00\uc911 \uc9c0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00\ucd1d\uc561\uc774 \ud070 \uc885\ubaa9\uc758 \uc6c0\uc9c1\uc784\uc774 \uc9c0\uc218\uc5d0 \ub354 \ud06c\uac8c \ubc18\uc601\ub418\uace0, \uc791\uc740 \uc885\ubaa9\uc758 \uc6c0\uc9c1\uc784\uc740 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uac8c \ubc18\uc601\ub429\ub2c8\ub2e4.<br/>\\n10\uc6d4 23\uc77c\uc5d0\ub294 \uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4 \uac19\uc740 \ub300\ud615 \ubc18\ub3c4\uccb4\uc8fc\uac00 \uc0c1\uc2b9 \uc804\ud658\ud558\uba70 \uc9c0\uc218\ub97c \ub04c\uc5b4\uc62c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\ub294 0.47% \uc624\ub978 `215,500\uc6d0`, SK\ud558\uc774\ub2c9\uc2a4\ub294 4.42% \uc624\ub978 `1,277,000\uc6d0` \uc548\ud30e\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc0c1\uc2b9 \uc885\ubaa9\ubcf4\ub2e4 \ud558\ub77d \uc885\ubaa9\uc774 \ub9ce\uc558\ub2e4\\n\\n[\ud55c\uad6d\uac70\ub798\uc18c \uc9d1\uacc4](https://en.fnnews.com/news/202610241657373440)\uc5d0 \ub530\ub974\uba74, 10\uc6d4 23\uc77c \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0\uc11c \uc0c1\uc2b9 \uc885\ubaa9\uc740 173\uac1c, \ud558\ub77d \uc885\ubaa9\uc740 717\uac1c, \ubcf4\ud569 \uc885\ubaa9\uc740 23\uac1c\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uccb4 \uc885\ubaa9\uc758 \uc57d 78%\uac00 \ud558\ub77d\ud588\uc74c\uc5d0\ub3c4 \uc9c0\uc218\ub294 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc0c1\uc2b9\uc774 \uc2dc\uc7a5 \uc804\uccb4\uc758 \uc628\uae30\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\ub840\uc785\ub2c8\ub2e4.<br/>\\n[\uc5f0\ud569\ub274\uc2a4 \ubcf4\ub3c4](https://www.businesstoday.com.my/2026/10/24/kospi-closes-marginally-higher-on-bargain-hunting/)\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub0a0 \ucf54\uc2a4\ud53c\uac00 \uc800\uac00 \ub9e4\uc218\uc138\uc5d0 \ud798\uc785\uc5b4 \uc18c\ud3ed \uc0c1\uc2b9 \ub9c8\uac10\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ucf54\uc2a4\ub2e5\uc740 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\ub2e4\\n\\n\ucf54\uc2a4\ub2e5\uc740 \ucf54\uc2a4\ud53c\uc640 \ub2ec\ub9ac \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ucc28\uc804\uc9c0\uc640 \ubc18\ub3c4\uccb4 \uc7a5\ube44 \uad00\ub828 \uc885\ubaa9\ub4e4\uc774 \ud568\uaed8 \uc57d\uc138\ub97c \ubcf4\uc778 \uac83\uc774 \ucf54\uc2a4\ub2e5 \uc57d\uc138\uc758 \ubc30\uacbd\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0\uc5d0\ub3c4 \uc2dc\uc7a5\ubcc4, \uc5c5\uc885\ubcc4 \ud750\ub984\uc774 \ub2e4\ub974\uac8c \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc9c0\uc218 \ub4f1\ub77d\ub960\ub9cc \ubcf4\uace0 \uc2dc\uc7a5 \ubd84\uc704\uae30\ub97c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \uc885\ubaa9 \uc218\uc640 \ud558\ub77d \uc885\ubaa9 \uc218, \uc989 \uc2dc\uc7a5 breadth\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \uc9c0\uc218 \ub4a4\uc758 \uc628\ub3c4 \ucc28\uc774\ub97c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ubc18\ub4f1\uc778\uc9c0, \uc911\uc18c\ud615\uc8fc\uae4c\uc9c0 \ud655\uc0b0\ub418\ub294 \ubc18\ub4f1\uc778\uc9c0 \uad6c\ubd84\ud558\ub294 \uac83\ub3c4 \uac19\uc740 \ub9e5\ub77d\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc\uc5d0\ub294 10\uc6d4 27\uc77c\ubd80\ud130 28\uc77c\uae4c\uc9c0 \uc5f4\ub9ac\ub294 \ubbf8\uad6d FOMC \ud68c\uc758 \uacb0\uacfc\uc640 \uc8fc\uc694 \uae30\uc5c5 \uc2e4\uc801 \ubc1c\ud45c\uac00 \uc608\uc815\ub3fc \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacb0\uc815\uacfc \uc2e4\uc801 \uc22b\uc790\uac00 \ub098\uc628 \ub4a4\uc5d0\ub294, \uae08\uc694\uc77c \ubc18\ub4f1\uc758 \uadfc\uac70\uac00 \uc720\uc9c0\ub418\ub294\uc9c0 \ub2e4\uc2dc \uc810\uac80\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n10\uc6d4 23\uc77c\uc740 \uc9c0\uc218 \uc0c1\uc2b9\uacfc \uc885\ubaa9 \ud558\ub77d\uc774 \uacf5\uc874\ud55c \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc\uc5d0\ub294 FOMC \uacb0\uacfc\uc640 \ud568\uaed8 \uc2dc\uc7a5 breadth\uac00 \ud68c\ubcf5\ub418\ub294\uc9c0\ub97c \ud655\uc778\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY2tudHV2djhic25xZm5pN3EzNXA4ejlsazg0bG52c3R3YW0zdW1nayZlcD12MV9naWZzX3NlYXJjaCZjdD1n/l0HlDDyxBfSaPpU88/giphy.gif\\" alt=\\"Market\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"paycheck-saving-system-oct24","metadata":{"permalink":"/blog/en/finance/paycheck-saving-system-oct24","source":"@site/finance/2026-10-24-paycheck-saving-system/index.mdx","title":"\uae09\uc5ec\uc77c\uc5d0 \uc790\ub3d9\uc774\uccb4\ub85c \ub9cc\ub4dc\ub294 \uc800\ucd95 \uc2dc\uc2a4\ud15c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-24T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"personal-finance","permalink":"/blog/en/finance/tags/personal-finance"},{"inline":true,"label":"saving","permalink":"/blog/en/finance/tags/saving"},{"inline":true,"label":"budgeting","permalink":"/blog/en/finance/tags/budgeting"}],"readingTime":2.19,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"paycheck-saving-system-oct24","title":"\uae09\uc5ec\uc77c\uc5d0 \uc790\ub3d9\uc774\uccb4\ub85c \ub9cc\ub4dc\ub294 \uc800\ucd95 \uc2dc\uc2a4\ud15c","authors":["way"],"tags":["finance","personal-finance","saving","budgeting"]},"unlisted":false,"prevItem":{"title":"\uc9c0\uc218\ub294 \uc62c\ub790\ub294\ub370 \ub0b4 \uc885\ubaa9\uc740 \ub0b4\ub838\ub2e4 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-breadth-divergence-oct24"},"nextItem":{"title":"\uc870\uc120\uc5c5 \uc218\uc8fc \uc794\ub7c9\uacfc \uc120\ubcc4 \uc218\uc8fc \uad6c\uc870 \ud574\uc124","permalink":"/blog/en/finance/shipbuilding-order-structure-oct24"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc6d4\ub9d0\uc5d0 \ub0a8\uc740 \ub3c8\uc73c\ub85c \uc800\ucd95\ud558\ub824\ub2e4 \ub9e4\ubc88 \uc2e4\ud328\ud558\ub294 \uad6c\uc870\ub97c, \uae09\uc5ec\uc77c \uc790\ub3d9\uc774\uccb4\ub85c \ubc14\uafb8\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \ub0a8\ub294 \ub3c8\uc774 \uc544\ub2c8\ub77c \uba3c\uc800 \ub5bc\ub294 \ub3c8\\n\\n\uc800\ucd95\uc774 \uc798 \uc548 \ub418\ub294 \uac00\uc7a5 \ud754\ud55c \uc774\uc720\ub294 \uc21c\uc11c\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc4f0\uace0 \ub0a8\uc740 \ub3c8\uc744 \uc800\ucd95\ud558\uba74, \ub0a8\uc740 \ub3c8\uc740 \ub9e4\ub2ec \ub4e4\ucb49\ub0a0\ucb49\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uae09\uc5ec\uc77c\uc5d0 \uba3c\uc800 \uc800\ucd95\uc561\uc744 \ub5bc\uc5b4\ub450\uba74, \uc0dd\ud65c\ube44\ub294 \ub0a8\uc740 \uae08\uc561 \uc548\uc5d0\uc11c \uc870\uc815\ub429\ub2c8\ub2e4.<br/>\\n\uc758\uc9c0\ub825\uc774 \uc544\ub2c8\ub77c \uacc4\uc88c \uad6c\uc870\uac00 \uc800\ucd95\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ21lMWFwYWlyYmZxcHIwbmVyOTMwZXppOWR3cGVzMjRwbWVuMnpscyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1Sxi0VHTSfXNgjrLvt/giphy.gif\\" alt=\\"Saving\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae09\uc5ec\uc77c \uc790\ub3d9\uc774\uccb4 \uc124\uacc4\ubc95\\n\\n#### \uc138 \uac1c\uc758 \ud1b5\uc7a5\uc73c\ub85c \ub098\ub204\uae30\\n\\n\uae09\uc5ec \ud1b5\uc7a5, \uc0dd\ud65c\ube44 \ud1b5\uc7a5, \uc800\ucd95 \ud1b5\uc7a5\uc744 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uae09\uc5ec\uac00 \ub4e4\uc5b4\uc624\uba74 \ub2f9\uc77c\uc5d0 \uc800\ucd95 \ud1b5\uc7a5\uc73c\ub85c \uc815\ud574\uc9c4 \uae08\uc561\uc774 \uc790\ub3d9\uc774\uccb4\ub418\ub3c4\ub85d \uc124\uc815\ud569\ub2c8\ub2e4.<br/>\\n\uc0dd\ud65c\ube44\ub294 \uc0dd\ud65c\ube44 \ud1b5\uc7a5\uc5d0\uc11c\ub9cc \uc4f0\uace0, \uae09\uc5ec \ud1b5\uc7a5 \uc794\uc561\uc744 \uc0dd\ud65c\ube44\ub85c \uc4f0\uc9c0 \uc54a\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.<br/>\\n\ud1b5\uc7a5\uc774 \uc11e\uc774\uba74 \uc800\ucd95\uc561\uacfc \uc0dd\ud65c\ube44\uc758 \uacbd\uacc4\uac00 \ud750\ub824\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \ube44\uc0c1\uc790\uae08\ubd80\ud130 \ucc44\uc6b0\uae30\\n\\n\uc800\ucd95\uc758 \uccab \ubaa9\ud45c\ub294 \ud22c\uc790 \uc218\uc775\uc774 \uc544\ub2c8\ub77c \ube44\uc0c1\uc790\uae08\uc785\ub2c8\ub2e4.<br/>\\n\uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc774 \uc0dd\uacbc\uc744 \ub54c \ube44\uc0c1\uc790\uae08\uc774 \uc5c6\uc73c\uba74 \uc801\uae08\uc774\ub098 \ud22c\uc790\uae08\uc744 \uae68\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18\uc801\uc73c\ub85c\ub294 \uc6d4 \uc0dd\ud65c\ube44\uc758 3\uac1c\uc6d4\uc5d0\uc11c 6\uac1c\uc6d4 \uc218\uc900\uc744 \ube44\uc0c1\uc790\uae08 \ubaa9\ud45c\ub85c \uc0bc\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc0c1\uc790\uae08\uc740 \uc218\uc775\ub960\ubcf4\ub2e4 \uc989\uc2dc \uc778\ucd9c \uac00\ub2a5\uc131\uacfc \uc6d0\uae08 \uc548\uc815\uc131\uc774 \uc6b0\uc120\uc785\ub2c8\ub2e4.<br/>\\n\ubaa9\ud45c\uc561\uc5d0 \ub3c4\ub2ec\ud55c \ub4a4\uc5d0\uc57c \uc911\uc7a5\uae30 \uc800\ucd95\uacfc \ud22c\uc790 \ube44\uc911\uc744 \ub298\ub9ac\ub294 \uc21c\uc11c\uac00 \uc548\uc815\uc801\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\ub3d9\uc774\uccb4 \uae08\uc561 \uc815\ud558\ub294 \ubc95\\n\\n\ucc98\uc74c\ubd80\ud130 \ubb34\ub9ac\ud55c \uae08\uc561\uc744 \uc815\ud558\uba74 \ud55c\ub450 \ub2ec \ub9cc\uc5d0 \uc790\ub3d9\uc774\uccb4\ub97c \ud574\uc9c0\ud558\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\uccab \ub2ec\uc740 \uae09\uc5ec\uc758 10% \uc218\uc900\uc5d0\uc11c \uc2dc\uc791\ud574, 3\uac1c\uc6d4 \ub3d9\uc548 \uc0dd\ud65c\uc5d0 \ubb34\ub9ac\uac00 \uc5c6\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc815\uc9c0\ucd9c\uc774 \uc904\uc5b4\ub4dc\ub294 \ub2ec\uc5d0\ub294 \uadf8\ub9cc\ud07c \uc790\ub3d9\uc774\uccb4 \uae08\uc561\uc744 \uc62c\ub9ac\uace0, \uc9c0\ucd9c\uc774 \ub298\uc5b4\ub098\ub294 \ub2ec\uc5d0\ub294 \uc7a0\uc2dc \ub0ae\ucd94\ub294 \uc870\uc815\ub3c4 \uac00\ub2a5\ud569\ub2c8\ub2e4.<br/>\\n\uc911\uc694\ud55c \uac83\uc740 \uae08\uc561\uc758 \ud06c\uae30\uac00 \uc544\ub2c8\ub77c \uc790\ub3d9\uc774\uccb4\uac00 \ub04a\uae30\uc9c0 \uc54a\uace0 \uc774\uc5b4\uc9c0\ub294 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc5f0\ub9d0\uc815\uc0b0\uacfc \uc790\ub3d9\uc774\uccb4\ub97c \ud568\uaed8 \ubcf4\uae30\\n\\n\uc5f0\uae08\uc800\ucd95\uc774\ub098 \uac1c\uc778\ud615\ud1f4\uc9c1\uc5f0\uae08(IRP) \ub0a9\uc785\ub3c4 \uae09\uc5ec\uc77c \uc790\ub3d9\uc774\uccb4\ub85c \ubb36\uc5b4\ub450\uba74 \uc5f0\ub9d0 \uad00\ub9ac\uac00 \uc218\uc6d4\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\uc5f0\ub9d0\uc5d0 \ud55c\uaebc\ubc88\uc5d0 \ub0a9\uc785\ud558\ub824\ub2e4 \uc790\uae08\uc774 \ubd80\uc871\ud574\uc9c0\ub294 \uc77c\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138\uc561\uacf5\uc81c \ud55c\ub3c4\uc640 \ub0a9\uc785 \uc5ec\ub825\uc740 \uac1c\uc778 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2e4\ub974\ubbc0\ub85c, \uc5f0\ucd08\uc5d0 \uc5f0\uac04 \ub0a9\uc785 \uacc4\ud68d\uc744 \uba3c\uc800 \uc138\uc6b0\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc5d0\uc11c \ub2e4\ub8ec \uc5f0\uae08 \uc0c1\ud488\uc758 \uae30\ubcf8 \uad6c\uc870\ub294 10\uc6d4 22\uc77c \uc5f0\uae08 \uc138\uc561\uacf5\uc81c \uae00\uacfc 10\uc6d4 23\uc77c ISA \uae00\uc5d0\uc11c \uac01\uac01 \uc815\ub9ac\ud55c \ubc14 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc790\ub3d9\uc774\uccb4\uc77c\uc740 \uae09\uc5ec\uc77c \ub2f9\uc77c\uc774\ub098 \ub2e4\uc74c \ub0a0\ub85c \uc815\ud569\ub2c8\ub2e4.<br/>\\n\uba70\uce60 \ub2a6\ucd94\uba74 \uadf8 \uc0ac\uc774\uc5d0 \uc0dd\ud65c\ube44\ub85c \ud758\ub7ec\uac08 \uc5ec\uc9c0\uac00 \uc0dd\uae41\ub2c8\ub2e4.<br/>\\n\uce74\ub4dc \uacb0\uc81c\uc77c\uacfc \uc790\ub3d9\uc774\uccb4\uc77c\uc774 \uacb9\uccd0 \uc794\uc561\uc774 \ubd80\uc871\ud574\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \uacb0\uc81c \uce98\ub9b0\ub354\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc800\ucd95 \ud1b5\uc7a5\uc740 \uccb4\ud06c\uce74\ub4dc\uc640 \uc5f0\uacb0\ud558\uc9c0 \uc54a\uc544 \ubb34\uc2ec\ucf54 \uc778\ucd9c\ub418\uc9c0 \uc54a\ub3c4\ub85d \ubd84\ub9ac\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n3\uac1c\uc6d4\uc5d0 \ud55c \ubc88\uc740 \uc790\ub3d9\uc774\uccb4 \uae08\uc561\uacfc \uc0dd\ud65c\ube44 \ud1b5\uc7a5 \uc794\uc561\uc744 \ud568\uaed8 \uc810\uac80\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc800\ucd95\uc740 \uc758\uc9c0\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \ub3c8\uc774 \ud750\ub974\ub294 \uc21c\uc11c\uc758 \ubb38\uc81c\uc778 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uae09\uc5ec\uc77c\uc5d0 \uba3c\uc800 \ub5bc\uc5b4\ub450\ub294 \uad6c\uc870 \ud558\ub098\uac00 \uc6d4\ub9d0 \uc800\ucd95\uc758 \uc2e4\ud328\ub97c \uc904\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ21lMWFwYWlyYmZxcHIwbmVyOTMwZXppOWR3cGVzMjRwbWVuMnpscyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/cMJKDZqo32fQtoUvvf/giphy.gif\\" alt=\\"Saving\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"shipbuilding-order-structure-oct24","metadata":{"permalink":"/blog/en/finance/shipbuilding-order-structure-oct24","source":"@site/finance/2026-10-24-shipbuilding-order-structure/index.mdx","title":"\uc870\uc120\uc5c5 \uc218\uc8fc \uc794\ub7c9\uacfc \uc120\ubcc4 \uc218\uc8fc \uad6c\uc870 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-24T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"sector","permalink":"/blog/en/finance/tags/sector"},{"inline":true,"label":"shipbuilding","permalink":"/blog/en/finance/tags/shipbuilding"},{"inline":true,"label":"lng","permalink":"/blog/en/finance/tags/lng"}],"readingTime":2.32,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"shipbuilding-order-structure-oct24","title":"\uc870\uc120\uc5c5 \uc218\uc8fc \uc794\ub7c9\uacfc \uc120\ubcc4 \uc218\uc8fc \uad6c\uc870 \ud574\uc124","authors":["way"],"tags":["finance","sector","shipbuilding","lng"]},"unlisted":false,"prevItem":{"title":"\uae09\uc5ec\uc77c\uc5d0 \uc790\ub3d9\uc774\uccb4\ub85c \ub9cc\ub4dc\ub294 \uc800\ucd95 \uc2dc\uc2a4\ud15c","permalink":"/blog/en/finance/paycheck-saving-system-oct24"},"nextItem":{"title":"VIX \uacf5\ud3ec\uc9c0\uc218 \uc77d\ub294 \ubc95\uacfc \ud55c\uacc4","permalink":"/blog/en/finance/vix-volatility-guide-oct24"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc870\uc120\uc5c5\uc758 \uc218\uc8fc\uc640 \uc2e4\uc801\uc774 \uc5b4\ub5a4 \uad6c\uc870\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0, LNG\uc6b4\ubc18\uc120\uc744 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \ubc30 \ud55c \ucc99\uc758 \uc8fc\ubb38\uc5d0\uc11c \uc778\ub3c4\uae4c\uc9c0\\n\\n\uc870\uc120\uc5c5\uc740 \uc218\uc8fc, \uac74\uc870, \uc778\ub3c4\ub77c\ub294 \uae34 \uc8fc\uae30\ub85c \uc6c0\uc9c1\uc774\ub294 \uc0b0\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc120\uc8fc\uac00 \ubc1c\uc8fc\ud558\uba74 \uc870\uc120\uc0ac\ub294 \uc124\uacc4\uc640 \uc790\uc7ac \uc870\ub2ec\uc744 \uac70\uccd0 \uc218\ub144\uc5d0 \uac78\uccd0 \uac74\uc870\ud55c \ub4a4 \uc778\ub3c4\ud558\uace0 \ub300\uae08\uc744 \uc815\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ud2b9\uc815 \uc5f0\ub3c4\uc758 \uc218\uc8fc \uae08\uc561\uc774 \uace7\ubc14\ub85c \uadf8 \ud574\uc758 \ub9e4\ucd9c\uc774 \ub418\ub294 \uad6c\uc870\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc218\uc8fc\uc794\ub7c9\uc740 \uc55e\uc73c\ub85c \uac74\uc870\ud560 \uc77c\uac10\uc758 \uaddc\ubaa8\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHhxNnRwZ2J1bm01a2VhY3pyYWY5MDY1bXRoM254YzVscTU3ZGlzMiZlcD12MV9jaGFubmVsc19zZWFyY2gmY3Q9Zw/KyCHX1MA4EZU5H41oK/giphy.gif\\" alt=\\"Ship\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc870\uc120\uc5c5 \uad6c\uc870\ub97c \uc77d\ub294 \uc138 \uac00\uc9c0 \ucd95\\n\\n#### \uc120\uc885\ubcc4 \ubd80\uac00\uac00\uce58 \ucc28\uc774\\n\\n\uc870\uc120\uc5c5\uc758 \uc120\uc885\uc740 \ud06c\uac8c LNG\uc6b4\ubc18\uc120, \ucee8\ud14c\uc774\ub108\uc120, \ud0f1\ucee4, \ubc8c\ud06c\uc120 \ub4f1\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc774 \uac00\uc6b4\ub370 LNG\uc6b4\ubc18\uc120\uc740 \uc601\ud558 163\ub3c4 \uc218\uc900\uc758 \uc561\ud654\ucc9c\uc5f0\uac00\uc2a4\ub97c \uc6b4\ubc18\ud574\uc57c \ud558\ubbc0\ub85c \ud654\ubb3c\ucc3d\uacfc \ub2e8\uc5f4 \uae30\uc220\uc758 \ub09c\ub3c4\uac00 \ub192\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220 \ub09c\ub3c4\uac00 \ub192\uc740 \uc120\uc885\uc77c\uc218\ub85d \ucc99\ub2f9 \ub2e8\uac00\uac00 \ub192\uace0, \uac74\uc870 \uacbd\ud5d8\uc774 \uc788\ub294 \uc870\uc120\uc0ac\uc758 \ud611\uc0c1\ub825\uc774 \ucee4\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n[2026\ub144 \uc5c5\uc885 \uc804\ub9dd \ubcf4\ub3c4](https://en.infomaxai.com/news/articleView.html?idxno=96824)\uc5d0\uc11c\ub294 \ubbf8\uad6d LNG \uc218\ucd9c \ud130\ubbf8\ub110 \uac00\ub3d9 \uacc4\ud68d\uacfc \uce74\ud0c0\ub974 \uc120\ub300 \uad50\uccb4 \uc218\uc694\ub97c \ubc30\uacbd\uc73c\ub85c LNG\uc6b4\ubc18\uc120 \ubc1c\uc8fc\uac00 \ub2e4\uc2dc \ub298\uc5b4\ub0a0 \uac83\uc73c\ub85c \uc804\ub9dd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\uc8fc\uc794\ub7c9\uacfc \ub3c4\ud06c \ud68c\uc804\uc728\\n\\n\uc218\uc8fc\uc794\ub7c9\uc744 \uc5f0\uac04 \uac74\uc870 \ub2a5\ub825\uc73c\ub85c \ub098\ub204\uba74 \ub300\ub7b5 \uba87 \ub144\uce58 \uc77c\uac10\uc744 \ud655\ubcf4\ud588\ub294\uc9c0 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc794\ub7c9\uc774 \uae38\ub2e4\uace0 \ubb34\uc870\uac74 \uc88b\uc740 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc800\uac00 \uc218\uc8fc\uac00 \ub9ce\uc774 \uc313\uc774\uba74 \ub098\uc911\uc5d0 \uc6d0\uac00 \uc0c1\uc2b9\ubd84\uc744 \ub5a0\uc548\uac8c \ub418\uace0, \ub3c4\ud06c \uc77c\uc815\uc774 \uacfc\ub3c4\ud558\uac8c \ubc00\ub9ac\uba74 \uc778\ub3c4 \uc9c0\uc5f0 \ub9ac\uc2a4\ud06c\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uadf8\ub798\uc11c \uc870\uc120\uc0ac\ub4e4\uc740 \ubb3c\ub7c9\ubcf4\ub2e4 \uc120\uac00\uc640 \uc218\uc775\uc131\uc744 \ub530\uc9c0\ub294 \uc120\ubcc4 \uc218\uc8fc \uc804\ub7b5\uc744 \uc790\uc8fc \uc5b8\uae09\ud569\ub2c8\ub2e4.<br/>\\n[\uc544\uc8fc\uacbd\uc81c\uc758 2026\ub144 \uc804\ub9dd \ubcf4\ub3c4](https://www.ajupress.com/view/20251217152538088)\uc5d0\uc11c\ub3c4 \ub300\ud615 \uc870\uc120\uc0ac\ub4e4\uc774 LNG\uc6b4\ubc18\uc120 \uc911\uc2ec\uc73c\ub85c \uc120\ubcc4 \uc218\uc8fc\ub97c \uc774\uc5b4\uac08 \uac83\uc774\ub77c\ub294 \ubd84\uc11d\uc774 \uc18c\uac1c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ud6c4\ud310 \uac00\uaca9\uacfc \ud658\uc728\uc774\ub77c\ub294 \uc6d0\uac00 \ubcc0\uc218\\n\\n\uc870\uc120 \uc6d0\uac00\uc758 \ud070 \ucd95\uc740 \ud6c4\ud310 \ub4f1 \uac15\uc7ac \uac00\uaca9\uacfc \uc778\uac74\ube44, \uadf8\ub9ac\uace0 \ub2ec\ub7ec \uacb0\uc81c \ube44\uc911\uc774 \ub192\uc740 \ud658\uc728\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uc8fc \uc2dc\uc810\uc758 \uc120\uac00\uc640 \uac74\uc870 \uae30\uac04 \uc911 \uc6d0\uac00 \ubcc0\ub3d9 \uc0ac\uc774\uc758 \uac04\uaca9\uc774 \uae38\uc218\ub85d \uc218\uc775\uc131 \uc608\uce21\uc774 \uc5b4\ub824\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\uc77c\ubd80 \uacc4\uc57d\uc740 \uc6d0\uac00 \uc5f0\ub3d9 \uc870\ud56d\uc744 \ub450\uae30\ub3c4 \ud558\uc9c0\ub9cc, \ubaa8\ub4e0 \uacc4\uc57d\uc774 \uac19\uc740 \uc870\uac74\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc870\uc120\uc5c5 \uc2e4\uc801\uc744 \ubcfc \ub54c\ub294 \uc218\uc8fc \uae08\uc561\ubcf4\ub2e4 \ub9e4\ucd9c \uc778\uc2dd \uc2dc\uc810\uacfc \uc6d0\uac00 \ucd94\uc774\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc218\uc8fc \ub274\uc2a4\ub97c \ubcfc \ub54c\ub294 \ucc99\uc218\uc640 \uae08\uc561\ubfd0 \uc544\ub2c8\ub77c \uc120\uc885\uacfc \uc778\ub3c4 \uc2dc\uc810\uc744 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\nLNG\uc6b4\ubc18\uc120\uc778\uc9c0, \ucee8\ud14c\uc774\ub108\uc120\uc778\uc9c0\uc5d0 \ub530\ub77c \ucc99\ub2f9 \ub2e8\uac00\uc640 \uae30\uc220 \ub09c\ub3c4\uac00 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\ubd84\uae30 \uc2e4\uc801\uc744 \ubcfc \ub54c\ub294 \uc218\uc8fc\uc794\ub7c9 \ubcc0\ub3d9, \uac74\uc870 \uc9c4\ucc99\ub3c4, \ud6c4\ud310 \uac00\uaca9 \ucd94\uc774\ub97c \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ud574\uad70 \ud568\uc815 \uc815\ube44(MRO)\ub098 \ud574\uc678 \uc870\uc120\uc18c \ud611\ub825 \uac19\uc740 \ube44(\u975e)\uc0c1\uc120 \uc0ac\uc5c5\uc740 \ubcc4\ub3c4 \ucd95\uc73c\ub85c \uad6c\ubd84\ud574 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uae30 \ud504\ub85c\uc81d\ud2b8\uc77c\uc218\ub85d \uae30\ub300\uc640 \uc2e4\uc801 \uc0ac\uc774\uc758 \uc2dc\ucc28\ub97c \uc5fc\ub450\uc5d0 \ub450\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc870\uc120\uc5c5\uc740 \uc218\uc8fc\uac00 \uace7 \uc2e4\uc801\uc774 \uc544\ub2c8\ub77c, \uc218\uc8fc\uc794\ub7c9\uc774 \uc2dc\uac04\uc744 \ub450\uace0 \uc2e4\uc801\uc73c\ub85c \uc804\ud658\ub418\ub294 \uc0b0\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc120\uc885\uacfc \uc120\uac00, \uc6d0\uac00 \ubcc0\uc218\ub97c \ud568\uaed8 \ubcf4\uba74 \uc218\uc8fc \ub274\uc2a4\uc758 \ubb34\uac8c\ub97c \uac00\ub2a0\ud558\uae30\uac00 \uc218\uc6d4\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMHhxNnRwZ2J1bm01a2VhY3pyYWY5MDY1bXRoM254YzVscTU3ZGlzMiZlcD12MV9jaGFubmVsc19zZWFyY2gmY3Q9cw/TXDJlYYaBVp6vFACDC/giphy.gif\\" alt=\\"Ship\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"vix-volatility-guide-oct24","metadata":{"permalink":"/blog/en/finance/vix-volatility-guide-oct24","source":"@site/finance/2026-10-24-vix-volatility-guide/index.mdx","title":"VIX \uacf5\ud3ec\uc9c0\uc218 \uc77d\ub294 \ubc95\uacfc \ud55c\uacc4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-24T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"concept","permalink":"/blog/en/finance/tags/concept"},{"inline":true,"label":"vix","permalink":"/blog/en/finance/tags/vix"},{"inline":true,"label":"volatility","permalink":"/blog/en/finance/tags/volatility"}],"readingTime":2.4,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"vix-volatility-guide-oct24","title":"VIX \uacf5\ud3ec\uc9c0\uc218 \uc77d\ub294 \ubc95\uacfc \ud55c\uacc4","authors":["way"],"tags":["finance","concept","vix","volatility"]},"unlisted":false,"prevItem":{"title":"\uc870\uc120\uc5c5 \uc218\uc8fc \uc794\ub7c9\uacfc \uc120\ubcc4 \uc218\uc8fc \uad6c\uc870 \ud574\uc124","permalink":"/blog/en/finance/shipbuilding-order-structure-oct24"},"nextItem":{"title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","permalink":"/blog/en/finance/data-center-power-grid-structure"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc2dc\uc7a5\uc774 \ud754\ub4e4\ub9b4 \ub54c \uc790\uc8fc \uc5b8\uae09\ub418\ub294 VIX, \uc774\ub978\ubc14 \uacf5\ud3ec\uc9c0\uc218\ub97c \uc77d\ub294 \ubc95\uacfc \ud55c\uacc4\ub97c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \ud754\ub4e4\ub9bc\uc758 \ud06c\uae30\ub97c \uc7ac\ub294 \uc9c0\ud45c\\n\\n\uc8fc\uac00\ub294 \ubc29\ud5a5\ubfd0 \uc544\ub2c8\ub77c \ud754\ub4e4\ub9bc\uc758 \ud06c\uae30\ub85c\ub3c4 \uc124\uba85\ub429\ub2c8\ub2e4.<br/>\\nVIX\ub294 \ubbf8\uad6d S&amp;P500 \uc9c0\uc218 \uc635\uc158 \uac00\uaca9\uc5d0\uc11c \ub3c4\ucd9c\ub418\ub294 \ubcc0\ub3d9\uc131 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uce74\uace0\uc635\uc158\uac70\ub798\uc18c(Cboe)\uac00 \uc0b0\ucd9c\ud558\uba70, \ud5a5\ud6c4 30\uc77c \uc815\ub3c4\uc758 \uae30\ub300 \ubcc0\ub3d9\uc131\uc744 \uc5f0\uc728\ub85c \ud45c\uc2dc\ud569\ub2c8\ub2e4.<br/>\\n\uc22b\uc790\uac00 \ub192\uc744\uc218\ub85d \uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4\uc774 \uc55e\uc73c\ub85c \ub354 \ud070 \ubcc0\ub3d9\uc744 \uc608\uc0c1\ud558\uace0 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaXVxazNjOHp6cXZqM240YmltczR5MXJoNHk2bGo0YjI0Z2xod2g3OCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/V8PO3o4IIPgCiIMnme/giphy.gif\\" alt=\\"Volatility\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### VIX \uc22b\uc790 \uc77d\ub294 \ubc95\\n\\n#### 20 \ubbf8\ub9cc, 20\uc5d0\uc11c 30, 30 \ucd08\uacfc\\n\\n\uc2dc\uc7a5\uc5d0\uc11c \ud1b5\uc6a9\ub418\ub294 \ub300\ub7b5\uc801\uc778 \uad6c\ubd84\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\nVIX 20 \ubbf8\ub9cc\uc740 \uc0c1\ub300\uc801\uc73c\ub85c \uc548\uc815\uc801\uc778 \uad6c\uac04\uc73c\ub85c \ud574\uc11d\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n20\uc5d0\uc11c 30 \uad6c\uac04\uc740 \uacbd\uacc4\uc2ec\uc774 \ucee4\uc9c0\ub294 \uad6c\uac04\uc73c\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n30\uc744 \ub118\uc73c\uba74 \ubcc0\ub3d9\uc131\uc5d0 \ub300\ud55c \uacbd\uacc4\uac00 \ub192\uc544\uc9c4 \uc0c1\ud0dc\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\ubd84\uc740 \uc808\ub300\uc801\uc778 \uae30\uc900\uc774 \uc544\ub2c8\ub77c \uad00\ud589\uc801\uc778 \ucc38\uace0 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n[Thrivent\uc758 VIX \ud574\uc124](https://www.thrivent.com/insights/investing/understanding-the-vix-what-every-investor-should-know-about-the-volatility-index)\uc5d0\uc11c\ub3c4 20 \ubbf8\ub9cc\uc740 \uc548\uc815, 20\uc5d0\uc11c 30\uc740 \uc911\ub9bd, 30 \ucd08\uacfc\ub294 \uc2a4\ud2b8\ub808\uc2a4 \uad6c\uac04\uc73c\ub85c \uad6c\ubd84\ud574 \uc124\uba85\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc22b\uc790\ub97c \uae30\uac04 \ubcc0\ub3d9\uc73c\ub85c \ubc14\uafb8\ub294 \ubc95\\n\\nVIX 20\uc740 \ud5a5\ud6c4 30\uc77c \ub3d9\uc548 S&amp;P500\uc774 \uc5f0\uc728 \uae30\uc900 20% \uc218\uc900\uc73c\ub85c \uc6c0\uc9c1\uc77c \uac83\uc774\ub77c\ub294 \uae30\ub300\ub97c \ub73b\ud569\ub2c8\ub2e4.<br/>\\n\uc774\ub97c \ud55c \ub2ec\uce58 \ubcc0\ub3d9\uc73c\ub85c \ubc14\uafb8\ub824\uba74 12\uc758 \uc81c\uacf1\uadfc(\uc57d 3.46)\uc73c\ub85c \ub098\ub215\ub2c8\ub2e4.<br/>\\nVIX 20\uc774\uba74 \ud55c \ub2ec \uae30\ub300 \ubcc0\ub3d9\uc740 \uc57d 5.8%, VIX 30\uc774\uba74 \uc57d 8.7% \uc218\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc774 \ubcc0\ud658\uc740 [VIX \uc77d\uae30 \ud574\uc124](https://climbtheladder.com/how-to-read-the-vix-key-levels-and-what-they-mean/)\uc5d0\uc11c\ub3c4 \uc18c\uac1c\ub418\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\uc22b\uc790\ub97c \uc774\ub807\uac8c \ubc14\uafb8\uba74 \ucd94\uc0c1\uc801\uc778 \uc9c0\uc218\uac00 \uccb4\uac10 \uac00\ub2a5\ud55c \ubcc0\ub3d9 \ud3ed\uc73c\ub85c \ub2e4\uac00\uc635\ub2c8\ub2e4.<br/>\\n\\n#### \ubc29\ud5a5\uc744 \uc54c\ub824\uc8fc\uc9c0 \uc54a\ub294\ub2e4\\n\\nVIX\ub294 \ubcc0\ub3d9\uc131\uc758 \ud06c\uae30\ub97c \ubcf4\uc5ec\uc904 \ubfd0, \uc624\ub97c\uc9c0 \ub0b4\ub9b4\uc9c0 \ubc29\ud5a5\uc744 \uc54c\ub824\uc8fc\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uae09\ub4f1\ud558\uba74\uc11c VIX\uac00 \uc624\ub97c \uc218\ub3c4 \uc788\uace0, \uae09\ub77d\ud558\uba74\uc11c VIX\uac00 \uc624\ub97c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18\uc801\uc73c\ub85c\ub294 \uc8fc\uac00 \uae09\ub77d \uad6d\uba74\uc5d0\uc11c VIX\uac00 \ube60\ub974\uac8c \uc624\ub974\ub294 \uacbd\ud5a5\uc774 \uc788\uc5b4 \uacf5\ud3ec\uc9c0\uc218\ub77c\ub294 \ubcc4\uba85\uc774 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uacfc\uac70 \uae08\uc735\uc704\uae30\ub098 \ud32c\ub370\ubbf9 \uad6d\uba74\uc5d0\uc11c\ub294 VIX\uac00 80\uc744 \ub118\uae34 \uc0ac\ub840\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\nVIX\ub9cc \ubcf4\uace0 \ub9e4\ub9e4 \ubc29\ud5a5\uc744 \uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\nVIX\ub294 \ubbf8\uad6d \ub300\ud615\uc8fc \uc2dc\uc7a5\uc758 \uae30\ub300 \ubcc0\ub3d9\uc131\uc744 \uc7ac\ub294 \uc9c0\ud45c\uc774\ubbc0\ub85c, \uad6d\ub0b4 \uc911\uc18c\ud615\uc8fc\uc640\ub294 \uc628\ub3c4 \ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nVIX\uac00 \uae09\ub4f1\ud588\uc744 \ub54c\ub294 \ud3ec\uc9c0\uc158 \ud06c\uae30\uc640 \ud604\uae08 \ube44\uc911\uc744 \uc810\uac80\ud558\ub294 \uacc4\uae30\ub85c \uc0bc\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc785\ub2c8\ub2e4.<br/>\\nVIX \uc5f0\uacc4 \uc0c1\ud488\uc740 \uc120\ubb3c \uad6c\uc870\uc0c1 \uc7a5\uae30\uac04 \ubcf4\uc720 \uc2dc \ub864\uc624\ubc84 \ube44\uc6a9\uc774 \uc313\uc77c \uc218 \uc788\uc5b4, \uad6c\uc870\ub97c \uc774\ud574\ud558\uc9c0 \ubabb\ud55c \ucc44 \uc7a5\uae30 \ubcf4\uc720\ud558\ub294 \uac83\uc740 \ud53c\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcc0\ub3d9\uc131\uc774 \ub192\uc744 \ub54c\ub294 \uac70\ub798\ub7c9\uacfc \uc2a4\ud504\ub808\ub4dc \uac19\uc740 \uc2dc\uc7a5 \uc720\ub3d9\uc131 \uc9c0\ud45c\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nVIX\ub294 \ubc29\ud5a5\uc774 \uc544\ub2c8\ub77c \ud754\ub4e4\ub9bc\uc758 \ud06c\uae30\ub97c \uc54c\ub824\uc8fc\ub294 \uc628\ub3c4\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\uc22b\uc790\uc758 \uc758\ubbf8\uc640 \ud55c\uacc4\ub97c \ud568\uaed8 \uc54c\uba74 \uc2dc\uc7a5 \ub274\uc2a4\uc758 \uacf5\ud3ec \ud45c\ud604\uc5d0 \ub35c \ud754\ub4e4\ub9ac\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaXVxazNjOHp6cXZqM240YmltczR5MXJoNHk2bGo0YjI0Z2xod2g3OCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/WBEzTelr0GL0XfVywq/giphy.gif\\" alt=\\"Volatility\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"data-center-power-grid-structure","metadata":{"permalink":"/blog/en/finance/data-center-power-grid-structure","source":"@site/finance/2026-10-23-data-center-power-grid/index.mdx","title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"sector","permalink":"/blog/en/finance/tags/sector"},{"inline":true,"label":"power-infrastructure","permalink":"/blog/en/finance/tags/power-infrastructure"}],"readingTime":2.68,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"data-center-power-grid-structure","title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","authors":["way"],"tags":["finance","sector","power-infrastructure"]},"unlisted":false,"prevItem":{"title":"VIX \uacf5\ud3ec\uc9c0\uc218 \uc77d\ub294 \ubc95\uacfc \ud55c\uacc4","permalink":"/blog/en/finance/vix-volatility-guide-oct24"},"nextItem":{"title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","permalink":"/blog/en/finance/dividend-exdividend-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\nAI \ub370\uc774\ud130\uc13c\ud130\uac00 \uc65c \uc804\ub825 \uc124\ube44 \uc0b0\uc5c5\uc744 \ub04c\uc5b4\uc62c\ub9ac\ub294\uc9c0, \uadf8 \uad6c\uc870\ub97c \uad50\uc721 \ubaa9\uc801\uc73c\ub85c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc0b0\uc220\uc774 \uc544\ub2c8\ub77c \uc804\uae30\uac00 \ubc1c\ubaa9\uc744 \uc7a1\ub294\ub2e4\\n\\nAI \ub370\uc774\ud130\uc13c\ud130\uac00 \ub298\uc5b4\ub098\uba74\uc11c \ud76c\uc18c \uc790\uc6d0\uc774 \ubc18\ub3c4\uccb4 \uce69\uc5d0\uc11c \uc804\ub825\ub9dd\uc73c\ub85c \uc62e\uaca8\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\ub9dd \uc5f0\uacb0 \uc9c0\uc5f0\uc774 3\ub144\uc5d0\uc11c \uae38\uac8c\ub294 5\ub144\uae4c\uc9c0 \uae38\uc5b4\uc9c0\uc790, \uc720\ud2f8\ub9ac\ud2f0 \ud68c\uc0ac\uc758 \uc1a1\uc804\uc120 \uad6c\ucd95\uc744 \uae30\ub2e4\ub9b4 \uc218 \uc5c6\ub294 \uc0c1\ud669\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\nHD\ud604\ub300\uc77c\ub809\ud2b8\ub9ad\uc740 10\uc6d4 28~30\uc77c \ucf54\uc5d1\uc2a4\uc5d0\uc11c \uc5f4\ub9ac\ub294 [SEP 2026](https://www.mt.co.kr/industry/2026/10/08/2026100714420243542) \ubc1c\ud45c\ub97c \uc55e\ub450\uace0 \\"\ud604\uc7ac\uc758 \ubcc0\uc555\uae30 \uc218\uc694\ub294 \uc288\ud37c\uc0ac\uc774\ud074\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \ub274\ub178\uba40\ub85c \uc790\ub9ac \uc7a1\uc744 \uac83\\"\uc774\ub77c\uace0 \ubc1d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc804\ub825\uc774 \ub2e8\uc21c\ud55c \ubd80\ud488\uc774 \uc544\ub2c8\ub77c \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc758 \uc120\uacb0 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdXg5dzR0MTUyeXB1aWFlYWo4a2wxM2phaGszbW96a2FxZDdheDh3biZlcD12MV9naWZzX3NlYXJjaCZjdD1n/AXLv8xVMmASjtr9xeD/giphy.gif\\" alt=\\"Electricity\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc804\ub825\uc774 \ub370\uc774\ud130\uc13c\ud130\uc5d0 \ub3c4\ucc29\ud558\ub294 \uacbd\ub85c\\n\\n#### \uc1a1\uc804 \u2014 \ubc1c\uc804\uc18c\uc5d0\uc11c \ub370\uc774\ud130\uc13c\ud130\uae4c\uc9c0\\n\\n\ubc1c\uc804\uc18c\uc5d0\uc11c \uc0dd\uc0b0\ub41c \uc804\uae30\ub294 \uc1a1\uc804\uc120\uc744 \ud0c0\uace0 \uc7a5\uac70\ub9ac\ub97c \uc774\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uac70\ub9ac \uc1a1\uc804\uc5d0\ub294 `154kV`, `345kV`, `765kV` \uac19\uc740 \ucd08\uace0\uc555\uc774 \uc4f0\uc774\uba70, \uc804\uc555\uc774 \ub192\uc744\uc218\ub85d \uc190\uc2e4\uc774 \uc801\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3c4\ucc29\ud55c \uc804\uae30\ub294 \ubcc0\uc804\uc18c\uc758 \ubcc0\uc555\uae30\ub97c \uac70\uccd0 \ub2e8\uacc4\uc801\uc73c\ub85c \uc804\uc555\uc774 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885\uc801\uc73c\ub85c \ub370\uc774\ud130\uc13c\ud130 \ub0b4\ubd80\uc5d0\uc11c\ub294 \uc11c\ubc84 \ub799\uc774 \uc4f0\ub294 \uc804\uc555\uc73c\ub85c \ubcc0\ud658\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ubcc0\uc555\uae30 \ub0a9\uae30\uac00 2~3\ub144\uc778 \uc774\uc720\\n\\n\ub300\ud615 \ubcc0\uc555\uae30\ub294 \uc8fc\ubb38 \uc81c\uc791 \ubc29\uc2dd\uc774\ub77c \uc0dd\uc0b0 \ub9ac\ub4dc\ud0c0\uc784\uc774 2~3\ub144\uc5d0 \uc774\ub985\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc5d0\ub108\uc9c0\uc815\ubcf4\uccad(EIA)\uc740 2026\ub144 \ubbf8\uad6d \uc5f0\uac04 \uc804\ub825 \ud310\ub9e4\ub7c9\uc744 4.135\uc870 kWh, 2027\ub144\uc744 4.211\uc870 kWh\ub85c \uc804\ub9dd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615 \ub370\uc774\ud130\uc13c\ud130\uac00 \uc694\uad6c\ud558\ub294 \ubcc0\uc555\uae30 \uc6a9\ub7c9\uc740 `150~200 MVA`\uae09\uae4c\uc9c0 \uc62c\ub77c\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uc694\uac00 \ub298\uc5b4\ub3c4 \uacf5\uc7a5\uc774 \ub2f9\uc7a5 \ub530\ub77c\uac00\uc9c0 \ubabb\ud558\ubbc0\ub85c, \uc218\uc8fc\uc794\uace0\uac00 \uc2e4\uc801\uc758 \uc120\ud589\uc9c0\ud45c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\uc804\ub9dd \u2014 \uac74\ubb3c \ub0b4\ubd80\ub85c \uc804\uae30\ub97c \ucabc\uac1c\ub294 \uc77c\\n\\n\uc1a1\uc804\uc774 \'\ubc1c\uc804\uc18c\uc5d0\uc11c \ub370\uc774\ud130\uc13c\ud130\uae4c\uc9c0\'\ub77c\uba74, \ubc30\uc804\uc740 \'\ub370\uc774\ud130\uc13c\ud130 \uac74\ubb3c \uc548\uc5d0\uc11c \uc11c\ubc84 \ub799\uae4c\uc9c0\' \uc804\uae30\ub97c \ub098\ub204\ub294 \ub2e8\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\ubc84\uc2a4\ub355\ud2b8(\uc804\uae30 \ud1b5\ub85c)\uc640 \uc911\uc804\uc555 \ucf00\uc774\ube14\uc774 \uc774 \uad6c\uac04\uc744 \ub2f4\ub2f9\ud569\ub2c8\ub2e4.<br/>\\n\uc1a1\uc804 \ubcd1\ubaa9\uc774 \uae38\uc5b4\uc9c0\uba74\uc11c \uc2dc\uc7a5\uc758 \uad00\uc2ec\uc774 \ubc30\uc804 \uad6c\uac04\uc73c\ub85c\uae4c\uc9c0 \ud655\uc0b0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### BTM(Behind The Meter) \u2014 \uc804\ub825\ub9dd\uc744 \uac70\uce58\uc9c0 \uc54a\ub294 \uc804\uc6d0\\n\\nBTM\uc740 \uc720\ud2f8\ub9ac\ud2f0 \uc804\ub825\ub9dd\uc744 \uac70\uce58\uc9c0 \uc54a\uace0 \ud604\uc7a5\uc5d0\uc11c \uc9c1\uc811 \uc804\ub825\uc744 \uacf5\uae09\ud558\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uc18c \uc5f0\ub8cc\uc804\uc9c0, \uac00\uc2a4\ud130\ube48, \ubc30\ud130\ub9ac \uc5d0\ub108\uc9c0\uc800\uc7a5\uc7a5\uce58(BESS)\ub97c \ub370\uc774\ud130\uc13c\ud130 \uc606\uc5d0 \uc124\uce58\ud574 \uc790\uae09\uc790\uc871\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uc804\ub825\uc744 \uc81c\uc5b4\ud558\ub294 \ud2b9\uc218\ubcc0\uc555\uae30\uac00 \ubcc4\ub3c4 \uc2dc\uc7a5\uc744 \ud615\uc131\ud558\uace0 \uc788\uc73c\uba70, \uae30\uc874 \ubc94\uc6a9 \ubcc0\uc555\uae30\ubcf4\ub2e4 \ub09c\ub3c4\uac00 \ub192\uc544 \ub9c8\uc9c4\uc774 \ub450\ud130\uc6b4 \ud3b8\uc785\ub2c8\ub2e4.<br/>\\n\uc804\ub825\ub9dd \uc5f0\uacc4\uac00 3~5\ub144\uc529 \uc9c0\uc5f0\ub418\ub294 \ud658\uacbd\uc5d0\uc11c BTM\uc740 \uc6b0\ud68c\ub85c\uc774\uc790 \ud544\uc218 \uacbd\ub85c\uac00 \ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc5c5\uacc4\uc758 \ub300\uc751 \u2014 \uc0dd\uc0b0\ub2a5\ub825 \ud655\ucda9\\n\\nHD\ud604\ub300\uc77c\ub809\ud2b8\ub9ad\uc740 \uc62c\ud574 4\ubd84\uae30 \uc6b8\uc0b0 \uacf5\uc7a5 \uc99d\uc124\uc744 \uc644\ub8cc\ud558\uace0, \ub0b4\ub144 \uc0c1\ubc18\uae30 \ubbf8\uad6d \uc568\ub77c\ubc30\ub9c8 \ubc95\uc778 \uc81c2\uacf5\uc7a5\uc744 \uac00\ub3d9\ud560 \uacc4\ud68d\uc785\ub2c8\ub2e4.<br/>\\n\uc568\ub77c\ubc30\ub9c8 \uc99d\uc124\uc774 \ub05d\ub098\uba74 \ud604\uc9c0 \ubcc0\uc555\uae30 \uc0dd\uc0b0\ub2a5\ub825\uc740 \uae30\uc874\ubcf4\ub2e4 50% \ub298\uc5b4\ub0a0 \uc804\ub9dd\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \ud68c\uc0ac\uc758 \ubd81\ubbf8 \ub9e4\ucd9c\uc740 2024\ub144 1\uc870 \uc6d0\uc5d0\uc11c \uc9c0\ub09c\ud574 1\uc870 6\ucc9c\uc5b5 \uc6d0\uc73c\ub85c \uc99d\uac00\ud588\uace0, \uc62c\ud574 \uc0c1\ubc18\uae30\uc5d0\ub3c4 1\uc870 \uc6d0\uc744 \ub118\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\uae30\uae30 \uc5c5\uccb4\ub4e4\uc758 \uacf5\ud1b5 \uc804\ub7b5\uc740 \uc0dd\uc0b0\ub2a5\ub825 \ud655\ucda9\uacfc \ubd81\ubbf8 \ud604\uc9c0\ud654\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5\uc744 \ubcfc \ub54c\ub294 \uc218\uc8fc\uc794\uace0, \ub9ac\ub4dc\ud0c0\uc784, \ub0a9\uae30 \ub2e8\ucd95 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc8fc\ubb38\uc774 \ubab0\ub824\ub3c4 \ub0a9\uae30\uac00 2~3\ub144\uc774\ubbc0\ub85c, \uc2e0\uaddc \uacf5\uc7a5\uc758 \uac00\ub3d9 \uc2dc\uc810\uc774 \uc2e4\uc801 \ubc18\uc601 \uc2dc\uc810\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\nBTM \uad6c\uc870\uac00 \ud655\uc0b0\ub418\ub294\uc9c0, \ud574\uc678 \ud604\uc9c0 \uc0dd\uc0b0 \ube44\uc911\uc774 \ub298\uc5b4\ub098\ub294\uc9c0\ub3c4 \uad6c\uc870\uc801 \ubcc0\ud654\uc758 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc0b0\uc5c5 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nAI \uc2dc\ub300\uc758 \uc9c4\uc9dc \ubcd1\ubaa9\uc740 \uce69\uc774 \uc544\ub2c8\ub77c \uc804\ub825\uc774 \ub420 \uac00\ub2a5\uc131\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc1a1\uc804\uc5d0\uc11c \ubc30\uc804, BTM\uae4c\uc9c0 \uc804\ub825 \ud750\ub984\uc744 \uc774\ud574\ud558\uba74 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 \ub274\uc2a4\uac00 \ub2ec\ub9ac \ubcf4\uc774\uae30 \uc2dc\uc791\ud569\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExdXg5dzR0MTUyeXB1aWFlYWo4a2wxM2phaGszbW96a2FxZDdheDh3biZlcD12MV9naWZzX3NlYXJjaCZjdD1n/Yd9BNyMoC6d6NFZ1iW/giphy.gif\\" alt=\\"Power\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"dividend-exdividend-guide","metadata":{"permalink":"/blog/en/finance/dividend-exdividend-guide","source":"@site/finance/2026-10-23-dividend-exdividend/index.mdx","title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"dividend","permalink":"/blog/en/finance/tags/dividend"},{"inline":true,"label":"basics","permalink":"/blog/en/finance/tags/basics"}],"readingTime":2.58,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"dividend-exdividend-guide","title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","authors":["way"],"tags":["finance","dividend","basics"]},"unlisted":false,"prevItem":{"title":"AI \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc778\ud504\ub77c \uc0b0\uc5c5 \uad6c\uc870 \ud574\uc124","permalink":"/blog/en/finance/data-center-power-grid-structure"},"nextItem":{"title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/fomc-bok-rate-decision-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc5f0\ub9d0 \ubc30\ub2f9 \uc2dc\uc98c\uc744 \uc55e\ub450\uace0 \ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960\uc758 \uac1c\ub150\uc744 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \ubc30\ub2f9\uc740 \'\uacf5\uc9dc \ub3c8\'\uc774 \uc544\ub2c8\ub2e4\\n\\n\uc8fc\uc2dd\uc744 \uac00\uc9c4 \uc8fc\uc8fc\ub294 \ud68c\uc0ac\uc758 \uc774\uc775\uc744 \ubc30\ub2f9\uc73c\ub85c \ub098\ub220 \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \ubc30\ub2f9\uc744 \ubc1b\ub294 \ub0a0 \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c0\ub294 \uac83\uc744 \ubcf4\uace0 \ub2f9\ud669\ud558\ub294 \ud22c\uc790\uc790\uac00 \uc801\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c\uc758 \uc6d0\ub9ac\ub97c \uc54c\uba74, \ubc30\ub2f9\uc774 \uacf5\uc9dc\ub85c \uc0dd\uae30\ub294 \ub3c8\uc774 \uc544\ub2c8\ub77c \uad6c\uc870\uc801\uc73c\ub85c \uc815\uc0b0\ub418\ub294 \uae08\uc561\uc784\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzc2dXR3YTRrY2R2dXJuMXU1aTFzMnF6MWk3YTBmb3B1dzA1NTRhMiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/RGXhikrzGUUyh8vrsH/giphy.gif\\" alt=\\"Money\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubc30\ub2f9\uc758 \uc885\ub958\\n\\n#### \uc911\uac04\ubc30\ub2f9\uacfc \uae30\ub9d0\ubc30\ub2f9\\n\\n\ubc30\ub2f9\uc740 \uc9c0\uae09 \uc2dc\uae30\uc5d0 \ub530\ub77c \uc911\uac04\ubc30\ub2f9\uacfc \uae30\ub9d0\ubc30\ub2f9\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc911\uac04\ubc30\ub2f9\uc740 \ud68c\uacc4\uc5f0\ub3c4 \uc911\uac04\uc5d0 \uc9c0\uae09\ud558\ub294 \ubc30\ub2f9\uc774\uace0, \uae30\ub9d0\ubc30\ub2f9\uc740 \uacb0\uc0b0 \ud6c4 \uc9c0\uae09\ud558\ub294 \ubc30\ub2f9\uc785\ub2c8\ub2e4.<br/>\\n12\uc6d4 \uacb0\uc0b0\ubc95\uc778\uc758 \uae30\ub9d0\ubc30\ub2f9\uc740 \ubcf4\ud1b5 \ub2e4\uc74c \ud574 3~4\uc6d4 \uc8fc\uc8fc\ucd1d\ud68c \ub4a4\uc5d0 \uc9c0\uae09\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \ubc16\uc5d0 \ud2b9\ubcc4\ud55c \uc0ac\uc720\ub85c \ud55c \ubc88\ub9cc \uc9c0\uae09\ud558\ub294 \ud2b9\ubcc4\ubc30\ub2f9\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ub2f9\ubc1b\uc744 \uad8c\ub9ac\ub294 \uae30\uc900\uc77c\ub85c \uc815\ud574\uc9c4\ub2e4\\n\\n\ubc30\ub2f9\uc744 \ubc1b\uc744 \uc8fc\uc8fc\ub294 \'\ubc30\ub2f9\uae30\uc900\uc77c\' \ud604\uc7ac \uc8fc\uc8fc\uba85\ubd80\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc785\ub2c8\ub2e4.<br/>\\n12\uc6d4 \uacb0\uc0b0\ubc95\uc778\uc758 \uae30\ub9d0\ubc30\ub2f9 \uae30\uc900\uc77c\uc740 \ud1b5\uc0c1 12\uc6d4 \ub9d0\uc77c\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc900\uc77c\uc5d0 \uc8fc\uc8fc\uc5ec\uc57c \ud558\ubbc0\ub85c, \uadf8 \uc804\uc5d0 \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\ub2f9\ub77d\uc77c\uc758 \uc6d0\ub9ac\\n\\n#### \ubc30\ub2f9\ubc1b\uc744 \uad8c\ub9ac\uac00 \ub5a8\uc5b4\uc9c0\ub294 \ub0a0\\n\\n\ubc30\ub2f9\ub77d\uc77c(ex-dividend date)\uc740 \ubc30\ub2f9\ubc1b\uc744 \uad8c\ub9ac\uac00 \uc0c8\ub85c \ub5a8\uc5b4\uc9c0\ub294 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \ubc30\ub2f9\uae30\uc900\uc77c 2\uc601\uc5c5\uc77c \uc804\ubd80\ud130 \uac70\ub798\ud55c \uc8fc\uc2dd\uc774 \ubc30\ub2f9 \uad8c\ub9ac\ub97c \uac16\uc2b5\ub2c8\ub2e4.<br/>\\n\uc989 \ubc30\ub2f9\ub77d\uc77c\uc5d0 \uc8fc\uc2dd\uc744 \uc0ac\uba74 \ud574\ub2f9 \ubc30\ub2f9\uc740 \ubc1b\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c \uc774\uc804\uc5d0 \ub9e4\uc218\ud55c \uc8fc\uc8fc\ub9cc\uc774 \ubc30\ub2f9 \ub300\uc0c1\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc65c \ubc30\ub2f9\ub77d\uc77c\uc5d0 \uc8fc\uac00\uac00 \uc870\uc815\ub418\ub294\uac00\\n\\n\ubc30\ub2f9\ub77d\uc77c\uc5d0\ub294 \uc8fc\uac00\uac00 \ubc30\ub2f9\uae08\ub9cc\ud07c \uae30\uc900\uac00\uaca9\uc5d0\uc11c \uc870\uc815\ub429\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc8fc\uac00\uac00 `50,000\uc6d0`\uc774\uace0 \ubc30\ub2f9\uae08\uc774 `1,000\uc6d0`\uc778 \uc885\ubaa9\uc740 \ubc30\ub2f9\ub77d\uc77c \uae30\uc900\uac00\uac00 `49,000\uc6d0`\uc5d0\uc11c \ucd9c\ubc1c\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c\uc758 \uc8fc\uac00 \ud558\ub77d\uc740 \uc545\uc7ac\uac00 \uc544\ub2c8\ub77c \ubc30\ub2f9\uae08\uc744 \ubc18\uc601\ud55c \uc815\uc0b0\uc785\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uae08\uc744 \ud604\uae08\uc73c\ub85c \ubc1b\uc740 \uc8fc\uc8fc \uc785\uc7a5\uc5d0\uc11c\ub294 \uc804\uccb4 \uc7ac\uc0b0\uc774 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c\uc5d0 \\"\uc8fc\uac00\uac00 \ub5a8\uc5b4\uc84c\ub2e4\\"\uba70 \ub2f9\ud669\ud560 \ud544\uc694\uac00 \uc5c6\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\\n\\n#### \ubc30\ub2f9\uc218\uc775\ub960 \uacf5\uc2dd\\n\\n\ubc30\ub2f9\uc218\uc775\ub960\uc740 \uc8fc\ub2f9\ubc30\ub2f9\uae08\uc744 \uc8fc\uac00\ub85c \ub098\ub208 \ube44\uc728\uc785\ub2c8\ub2e4.<br/>\\n\\n`\ubc30\ub2f9\uc218\uc775\ub960(%) = \uc8fc\ub2f9\ubc30\ub2f9\uae08 \xf7 \uc8fc\uac00 \xd7 100`\\n\\n\uc8fc\ub2f9\ubc30\ub2f9\uae08\uc774 `1,000\uc6d0`\uc774\uace0 \uc8fc\uac00\uac00 `50,000\uc6d0`\uc774\uba74 \ubc30\ub2f9\uc218\uc775\ub960\uc740 2%\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ubc30\ub2f9\uae08\uc774\ub77c\ub3c4 \uc8fc\uac00\uac00 \uc624\ub974\uba74 \uc218\uc775\ub960\uc740 \ub0ae\uc544\uc9c0\uace0, \uc8fc\uac00\uac00 \ub0b4\ub9ac\uba74 \uc218\uc775\ub960\uc740 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ub2f9\uc218\uc775\ub960\uc758 \ud568\uc815\\n\\n\ubc30\ub2f9\uc218\uc775\ub960\uc774 \ub192\ub2e4\uace0 \ubb34\uc870\uac74 \uc88b\uc740 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\uac00 \uc2e4\uc801 \uc545\ud654\ub85c \uae09\ub77d\ud558\uba74 \ubc30\ub2f9\uc218\uc775\ub960\uc740 \uc218\uce58\uc0c1 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uae08\uc740 \ud68c\uc0ac\uc758 \uc774\uc775\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc774\ubbc0\ub85c, \uc774\uc775\uc774 \uc904\uc5b4\ub4e4\uba74 \ubc30\ub2f9\ub3c4 \uc904\uc5b4\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc218\uc775\ub960\uc744 \ubcfc \ub54c\ub294 \ubc30\ub2f9\uc131\ud5a5(\uc21c\uc774\uc775 \uc911 \ubc30\ub2f9 \ube44\uc728)\uacfc \uc774\uc775 \ucd94\uc774\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\\n#### \ubc30\ub2f9\uc18c\ub4dd\uc5d0\ub294 \uc138\uae08\uc774 \ubd99\ub294\ub2e4\\n\\n\ubc1b\uc740 \ubc30\ub2f9\uc740 \ubc30\ub2f9\uc18c\ub4dd\uc73c\ub85c \ubd84\ub958\ub418\uc5b4 `15.4%`\uc758 \uc138\uc728\ub85c \uc6d0\ucc9c\uc9d5\uc218\ub429\ub2c8\ub2e4.<br/>\\n\uc8fc\ub2f9 `1,000\uc6d0` \ubc30\ub2f9\uc744 \ubc1b\uc73c\uba74 \uc2e4\uc81c \uc218\ub839\uc561\uc740 `846\uc6d0`\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\uac04 \uae08\uc735\uc18c\ub4dd\uc774 \uc77c\uc815 \uae30\uc900\uc744 \ub118\uc73c\uba74 \uae08\uc735\uc18c\ub4dd\uc885\ud569\uacfc\uc138 \ub300\uc0c1\uc774 \ub418\ubbc0\ub85c, \ubc30\ub2f9\uc774 \ud070 \ud22c\uc790\uc790\ub294 \uc5f0\ub9d0\uc5d0 \ud569\uc0b0\uc744 \ud568\uaed8 \uacc4\uc0b0\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ubc30\ub2f9\uae30\uc900\uc77c\uacfc \ubc30\ub2f9\ub77d\uc77c \uc77c\uc815\uc744 \ubbf8\ub9ac \ud655\uc778\ud558\uba74 \ub9e4\uc218 \uc2dc\uc810\uc744 \uacc4\ud68d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\ub77d\uc77c \uc804\ud6c4\uc758 \uc8fc\uac00 \uc6c0\uc9c1\uc784\uc744 \'\ub77d \ud6a8\uacfc\'\uc640 \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubc30\ub2f9\uc218\uc775\ub960\uc740 \ud604\uc7ac \uc8fc\uac00 \uae30\uc900\uc774\ubbc0\ub85c, \uacfc\uac70 \ub192\uc740 \uc218\uc775\ub960\uc5d0 \uae30\ub300\uc5b4 \ub9e4\uc218 \uacb0\uc815\uc744 \ub0b4\ub9ac\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ubc30\ub2f9 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubc30\ub2f9\uc740 \uad6c\uc870\ub97c \uc54c\uba74 \ub2e8\uc21c\ud55c \ud604\uae08 \uc9c0\uae09\uc774 \uc544\ub2c8\ub77c \uad8c\ub9ac\uc640 \uac00\uaca9\uc758 \uc815\uc0b0 \uacfc\uc815\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\ub9d0 \ubc30\ub2f9 \uc2dc\uc98c\uc5d0 \ubc30\ub2f9\ub77d\uc77c \uc77c\uc815\uc744 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc758\uc678\ub85c \uc2e4\uc218\ub97c \ub9ce\uc774 \ub9c9\uc544\uc90d\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzc2dXR3YTRrY2R2dXJuMXU1aTFzMnF6MWk3YTBmb3B1dzA1NTRhMiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/XfDqt93JwrfwgoHkrq/giphy.gif\\" alt=\\"Dividend\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"fomc-bok-rate-decision-guide","metadata":{"permalink":"/blog/en/finance/fomc-bok-rate-decision-guide","source":"@site/finance/2026-10-23-fomc-bok-rate-decision/index.mdx","title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"interest-rate","permalink":"/blog/en/finance/tags/interest-rate"},{"inline":true,"label":"fomc","permalink":"/blog/en/finance/tags/fomc"}],"readingTime":2.99,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"fomc-bok-rate-decision-guide","title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","authors":["way"],"tags":["finance","interest-rate","fomc"]},"unlisted":false,"prevItem":{"title":"\ubc30\ub2f9\uacfc \ubc30\ub2f9\ub77d\uc77c, \ubc30\ub2f9\uc218\uc775\ub960 \uacc4\uc0b0\ubc95","permalink":"/blog/en/finance/dividend-exdividend-guide"},"nextItem":{"title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","permalink":"/blog/en/finance/isa-basics-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\ub2e4\uc74c \uc8fc FOMC\ub97c \uc55e\ub450\uace0, \ubbf8\uad6d \uc5f0\uc900\uacfc \ud55c\uad6d\uc740\ud589\uc758 \uae08\ub9ac \uacb0\uc815\uc744 \uc5b4\ub5bb\uac8c \uc77d\uc5b4\uc57c \ud558\ub294\uc9c0 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uae08\ub9ac \uacb0\uc815 \uc8fc\uac04\uc774 \uc628\ub2e4\\n\\n2026\ub144 10\uc6d4 22\uc77c, \ud55c\uad6d\uc740\ud589 \uae08\uc735\ud1b5\ud654\uc704\uc6d0\ud68c\ub294 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00 \uc555\ubc15\uc774 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\ub3c4 \uac70\ub860\ub418\ub294 \'\ub9e4\ud30c\uc801 \ub3d9\uacb0\'\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\uc5b4\uc11c 10\uc6d4 27~28\uc77c\uc5d0\ub294 \ubbf8\uad6d \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c(FOMC)\uac00 \uc5f4\ub9ac\uace0, \uacb0\uacfc\ub294 \ud55c\uad6d \uc2dc\uac01 10\uc6d4 29\uc77c \uc0c8\ubcbd 3\uc2dc\uc5d0 \ubc1c\ud45c\ub429\ub2c8\ub2e4.<br/>\\n\ub450 \uae08\ub9ac \uacb0\uc815\uc758 \uc77d\ub294 \ubc95\uc740 \ube44\uc2b7\ud558\uc9c0\ub9cc, \ud655\uc778\ud574\uc57c \ud560 \ud3ec\uc778\ud2b8\uac00 \uc870\uae08\uc529 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExMnl5OGQ1djMwMWx2eDZtODI5OXB1OWk4YmF6dTR2eDV5ZTA5d2NtZCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/GFIpUu2yP0C5UEN10L/giphy.gif\\" alt=\\"Interest rate\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae30\uc900\uae08\ub9ac\uac00 \ubb34\uc5c7\uc778\uac00\\n\\n#### \uc5f0\uc900\uc758 \uc5f0\ubc29\uae30\uae08\uae08\ub9ac\\n\\n\ubbf8\uad6d \uc5f0\uc900\uc774 \uc815\ud558\ub294 \uae30\uc900\uae08\ub9ac\ub294 \uc5f0\ubc29\uae30\uae08\uae08\ub9ac \ubaa9\ud45c \ubc94\uc704\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 9\uc6d4 15~16\uc77c \ud68c\uc758\uc5d0\uc11c 0.25%\ud3ec\uc778\ud2b8 \uc778\uc0c1\ub41c \ub4a4, \ud604\uc7ac \ubaa9\ud45c \ubc94\uc704\ub294 `3.75~4.00%`\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc740\ud589 \uac04 \ucd08\ub2e8\uae30 \ub300\ucd9c \uae08\ub9ac\ub97c \uaca8\ub0e5\ud55c \uac83\uc73c\ub85c, \ubbf8\uad6d \ub2ec\ub7ec \uc790\uae08\uc758 \uae30\uc900 \uac00\uaca9 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud55c\uad6d\uc740\ud589\uc758 \uae30\uc900\uae08\ub9ac\\n\\n\ud55c\uad6d\uc740\ud589 \uae30\uc900\uae08\ub9ac\ub294 \ud604\uc7ac \uc5f0 3.00%\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 7\uc6d4\uacfc 8\uc6d4 \ub450 \ucc28\ub840\uc5d0 \uac78\uccd0 0.25%\ud3ec\uc778\ud2b8\uc529 \uc62c\ub790\uace0, 10\uc6d4 22\uc77c\uc5d0\ub294 \ub3d9\uacb0\ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc900\uae08\ub9ac\ub294 \uc608\uae08\uacfc \ub300\ucd9c \uae08\ub9ac\uc758 \ucd9c\ubc1c\uc810\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc740\ud589 \ub300\ucd9c\uae08\ub9ac\ub294 \uae30\uc900\uae08\ub9ac\ubcf4\ub2e4 \ucf54\ud53d\uc2a4(COFIX) \uac19\uc740 \uc2dc\uc7a5 \uc9c0\ud45c\uc758 \uc601\ud5a5\uc744 \ub354 \ud06c\uac8c \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n9\uc6d4 \uc2e0\uaddc\ucde8\uae09\uc561 \uae30\uc900 \ucf54\ud53d\uc2a4\ub294 `3.43%`\ub85c, \uc774\ubbf8 \uae30\uc900\uae08\ub9ac\ub97c \uc6c3\ub3cc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### FOMC \ubc1c\ud45c \uc77d\ub294 \ubc95\\n\\n#### \uc5b8\uc81c, \ubb34\uc5c7\uc744 \ud655\uc778\ud558\ub294\uac00\\n\\nFOMC\ub294 10\uc6d4 27~28\uc77c \uc774\ud2c0\uac04 \ud68c\uc758\ub97c \ud558\uace0, \ubbf8\uad6d \ub3d9\ubd80 \uc2dc\uac01 28\uc77c \uc624\ud6c4 2\uc2dc\uc5d0 \uc131\uba85\uc11c\ub97c \ubc1c\ud45c\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \uc2dc\uac01\uc73c\ub85c\ub294 10\uc6d4 29\uc77c \uc0c8\ubcbd 3\uc2dc\uc785\ub2c8\ub2e4.<br/>\\n30\ubd84 \ub4a4\uc5d0\ub294 \uc758\uc7a5 \uae30\uc790\ud68c\uacac\uc774 \uc774\uc5b4\uc9c0\ubbc0\ub85c, \uc0c8\ubcbd 3\uc2dc 30\ubd84\ubd80\ud130 \ucd94\uac00 \ubc1c\uc5b8\uc774 \ub098\uc635\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc740 11\uc6d4 1\uc77c\uc5d0 \uc11c\uba38\ud0c0\uc784\uc774 \ub05d\ub098\ubbc0\ub85c, 12\uc6d4 \ud68c\uc758\ubd80\ud130\ub294 \uac19\uc740 \uc624\ud6c4 2\uc2dc \ubc1c\ud45c\uac00 \ud55c\uad6d \uc2dc\uac01 \uc0c8\ubcbd 4\uc2dc\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### 10\uc6d4 \ud68c\uc758\uc5d0\ub294 \uc810\ub3c4\ud45c\uac00 \uc5c6\ub2e4\\n\\n\uc5f0\uc900 \uc704\uc6d0\ub4e4\uc758 \uae08\ub9ac \uc804\ub9dd\uc744 \uc810\uc73c\ub85c \ucc0d\uc740 \uc810\ub3c4\ud45c(dot plot)\ub294 3\uc6d4, 6\uc6d4, 9\uc6d4, 12\uc6d4 \ud68c\uc758\uc5d0\ub9cc \ub098\uc635\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ud68c\uc758\ub294 \uc810\ub3c4\ud45c\uac00 \uc5c6\ub294 \ud68c\uc758\uc774\ubbc0\ub85c, \uc131\uba85\uc11c \ubb38\uad6c\uc640 \uc758\uc7a5 \ubc1c\uc5b8\uc774 \ub354 \uc911\uc694\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\'\uc778\ub0b4\uc2ec\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4\', \'\ub370\uc774\ud130\uc5d0 \uc758\uc874\ud558\uaca0\ub2e4\' \uac19\uc740 \ubb38\uad6c\uc758 \ubbf8\ubb18\ud55c \ubcc0\ud654\uac00 \uc2dc\uc7a5\uc758 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub3d9\uacb0\xb7\uc778\uc0c1\xb7\uc778\ud558\ubcf4\ub2e4 \ubc29\ud5a5\uc758 \ub2e8\uc11c\\n\\n\uae08\ub9ac\ub97c \uc62c\ub838\ub294\uc9c0 \ub0b4\ub838\ub294\uc9c0\ubcf4\ub2e4, \uc55e\uc73c\ub85c \uc5b4\ub514\ub85c \uac08\uc9c0\uac00 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n10\uc6d4 22\uc77c \ud55c\uad6d\uc740\ud589 \uacb0\uc815\ub3c4 \ub3d9\uacb0\uc774\uc5c8\uc9c0\ub9cc \'\ub9e4\ud30c\uc801 \ub3d9\uacb0\'\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c\ubb38\uacfc \ucd1d\uc7ac \uae30\uc790\uac04\ub2f4\ud68c, FOMC\uc5d0\uc11c\ub294 \uc758\uc7a5 \uae30\uc790\ud68c\uacac\uc758 \ud45c\ud604\uc774 \ud5a5\ud6c4 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \uba3c\uc800 \uc6c0\uc9c1\uc774\ub294 \uac83\uc740 \uae08\ub9ac \uacb0\uc815 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8 \ud574\uc11d\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uae08\ub9ac\uac00 \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ub418\ub294 \uacbd\ub85c\\n\\n#### \ucc44\uad8c\uacfc \ub300\ucd9c\\n\\n\uae30\uc900\uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc2dc\uc7a5\uae08\ub9ac\ub3c4 \ub530\ub77c \uc624\ub974\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucc44\uad8c \uac00\uaca9\uc740 \uae08\ub9ac\uc640 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc774\ubbc0\ub85c, \uae08\ub9ac \uc0c1\uc2b9\uae30\uc5d0\ub294 \uae30\uc874 \ucc44\uad8c \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc740\ud589 \ubcc0\ub3d9\uae08\ub9ac \ub300\ucd9c\uc740 \ucf54\ud53d\uc2a4 \uc0c1\uc2b9\ubd84\ub9cc\ud07c \uc7ac\uc0b0\uc815\uc77c\uc5d0 \uae08\ub9ac\uac00 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\\n\\n\ubbf8\uad6d \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ub2ec\ub7ec\uac00 \uac15\uc138\ub97c \ubcf4\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ubbf8 \uae08\ub9ac \ucc28\uc774\uc640 \ub2ec\ub7ec \ubc29\ud5a5\uc740 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uc678\uad6d\uc778 \uc218\uae09\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 10\uc6d4 23\uc77c `1,324.6\uc6d0`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uae08\ub9ac \ubc1c\ud45c \ub2f9\uc77c\uc5d0\ub294 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c, \ubc1c\ud45c \uc804\ud6c4\uc758 \ub274\uc2a4 \ud574\uc11d\uc744 \uc11c\ub450\ub974\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub3d9\uacb0\xb7\uc778\uc0c1\xb7\uc778\ud558\uc758 \uc5ec\ubd80\ubcf4\ub2e4 \uc131\uba85\uc11c \ubb38\uad6c \ubcc0\ud654\uc640 \uc758\uc7a5 \ubc1c\uc5b8\uc744 \ud568\uaed8 \uc77d\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub0b4 \ub300\ucd9c \uae08\ub9ac\ub294 \uae30\uc900\uae08\ub9ac\ubcf4\ub2e4 \ucf54\ud53d\uc2a4\uc640 \uc7ac\uc0b0\uc815\uc77c\uc758 \uc601\ud5a5\uc744 \uba3c\uc800 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uae08\ub9ac \uacb0\uc815 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, \uae08\ub9ac \ubc29\ud5a5\uc744 \uc608\uce21\ud558\uac70\ub098 \ud22c\uc790\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uae08\ub9ac \uacb0\uc815\uc740 \uc22b\uc790\ub97c \uc77d\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubb38\uad6c\ub97c \uc77d\ub294 \uc77c\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 29\uc77c \uc0c8\ubcbd \ubc1c\ud45c \ub4a4\uc5d0\ub294 \uc131\uba85\uc11c \uc6d0\ubb38\uc758 \ubb38\uad6c \ubcc0\ud654\ubd80\ud130 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \uad8c\ud574\ub4dc\ub9bd\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjExMnl5OGQ1djMwMWx2eDZtODI5OXB1OWk4YmF6dTR2eDV5ZTA5d2NtZCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/M8doLiB9p18QFo8XIM/giphy.gif\\" alt=\\"Fed\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"isa-basics-guide","metadata":{"permalink":"/blog/en/finance/isa-basics-guide","source":"@site/finance/2026-10-23-isa-basics/index.mdx","title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"personal-finance","permalink":"/blog/en/finance/tags/personal-finance"},{"inline":true,"label":"isa","permalink":"/blog/en/finance/tags/isa"},{"inline":true,"label":"tax","permalink":"/blog/en/finance/tags/tax"}],"readingTime":2.99,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"isa-basics-guide","title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","authors":["way"],"tags":["finance","personal-finance","isa","tax"]},"unlisted":false,"prevItem":{"title":"FOMC\uc640 \uae08\ud1b5\uc704 \uae08\ub9ac \uacb0\uc815 \uc77d\ub294 \ubc95","permalink":"/blog/en/finance/fomc-bok-rate-decision-guide"},"nextItem":{"title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-4percent-rebound-oct23"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\ud558\ub098\uc758 \uacc4\uc88c\ub85c \uc5ec\ub7ec \uae08\uc735\uc0c1\ud488\uc744 \uad74\ub9ac\uba74\uc11c \uc138\uae08 \ud61c\ud0dd\uc744 \ubc1b\ub294 ISA\uc758 \uae30\ubcf8 \uad6c\uc870\ub97c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uacc4\uc88c \ud558\ub098\uc5d0 \ub2f4\ub294 \uc808\uc138 \uad6c\uc870\\n\\nISA\ub294 Individual Savings Account\uc758 \uc57d\uc790\ub85c, \uc6b0\ub9ac\ub9d0\ub85c\ub294 \uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c\uc785\ub2c8\ub2e4.<br/>\\n\uc608\uae08, \ud380\ub4dc, ETF, \uad6d\ub0b4 \uc0c1\uc7a5\uc8fc\uc2dd \ub4f1\uc744 \ud558\ub098\uc758 \uacc4\uc88c\uc5d0 \ub2f4\uc544 \uc6b4\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud575\uc2ec\uc740 \uac01 \uc0c1\ud488\uc758 \uc218\uc775\uc744 \ub530\ub85c\ub530\ub85c \uacfc\uc138\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uacc4\uc88c \uc804\uccb4\uc758 \uc21c\uc774\uc775\uc744 \uae30\uc900\uc73c\ub85c \uc138\uae08 \ud61c\ud0dd\uc744 \uc8fc\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc190\uc2e4\uacfc \uc774\uc775\uc744 \ud569\uc0b0\ud558\ub294 \'\uc190\uc775\ud1b5\uc0b0\' \uad6c\uc870 \ub355\ubd84\uc5d0 \uc2e4\ud6a8\uc138\uc728\uc774 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaW50YW51MXp0dGFrbHI4MnBhbjdxd2ZvMWFhbGwxNnFwcHN4bjVuayZlcD12MV9naWZzX3NlYXJjaCZjdD1n/7JMFaaqRtn6K2jUd2O/giphy.gif\\" alt=\\"Savings\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uac00\uc785\uacfc \ub0a9\uc785\uc758 \uaddc\uce59\\n\\n#### \ub204\uac00 \uac00\uc785\ud560 \uc218 \uc788\ub294\uac00\\n\\n\uac00\uc785\uc77c \uae30\uc900\uc73c\ub85c 19\uc138 \uc774\uc0c1\uc778 \uac70\uc8fc\uc790\uac00 \uac00\uc785 \ub300\uc0c1\uc785\ub2c8\ub2e4.<br/>\\n15\uc138 \uc774\uc0c1\uc774\ub77c\ub3c4 \uac00\uc785\uc77c\uc774 \uc18d\ud55c \ud574\uc758 \uc9c1\uc804 \uacfc\uc138\uae30\uac04\uc5d0 \uadfc\ub85c\uc18c\ub4dd\uc774 \uc788\uc73c\uba74 \uac00\uc785\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n1\uc778\ub2f9 1\uac1c\uc758 \uacc4\uc88c\ub9cc \ubcf4\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc9c1\uc804 3\uac1c \uacfc\uc138\uae30\uac04 \uc911 \ud55c \ubc88\uc774\ub77c\ub3c4 \uae08\uc735\uc18c\ub4dd\uc885\ud569\uacfc\uc138 \ub300\uc0c1\uc774\uc5c8\ub358 \uacbd\uc6b0\uc5d0\ub294 \uacfc\uc138\ud2b9\ub840\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub0a9\uc785\ud55c\ub3c4\uc640 \uc758\ubb34\uae30\uac04\\n\\n\uc5f0\uac04 \ub0a9\uc785\ud55c\ub3c4\ub294 `2,000\ub9cc \uc6d0`, \ucd1d \ub0a9\uc785\ud55c\ub3c4\ub294 `1\uc5b5 \uc6d0`\uc785\ub2c8\ub2e4.<br/>\\n\ubabb \ucc44\uc6b4 \uc5f0\uac04 \ud55c\ub3c4\ub294 \ub2e4\uc74c \ud574\ub85c \uc774\uc6d4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacc4\uc57d\uae30\uac04\uc740 3\ub144 \uc774\uc0c1\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n3\ub144 \uc804\uc5d0 \ud574\uc9c0\ud558\uba74 \uac10\uba74\ubc1b\uc740 \uc138\uae08\uc744 \ucd94\uc9d5\ub2f9\ud558\ubbc0\ub85c, 3\ub144\uac04 \ubb36\uc77c \uc218 \uc788\ub294 \uc5ec\uc720 \uc790\uae08\uc73c\ub85c \ub0a9\uc785\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc138 \uac00\uc9c0 \uc720\ud615\\n\\nISA\ub294 \uc6b4\uc6a9 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc911\uac1c\ud615, \uc2e0\ud0c1\ud615, \uc77c\uc784\ud615\uc73c\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uc911\uac1c\ud615\uc740 \ud22c\uc790\uc790\uac00 \uc9c1\uc811 \uc8fc\uc2dd\uacfc ETF\ub97c \uc0ac\uace0\ud314 \uc218 \uc788\ub294 \uc720\ud615\uc73c\ub85c, \uc99d\uad8c\uc0ac\uc5d0\uc11c\ub9cc \uac1c\uc124\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e0\ud0c1\ud615\uc740 \uae08\uc735\ud68c\uc0ac\uac00 \ud22c\uc790\uc790\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \uc6b4\uc6a9\ud558\uba70 \uc608\uae08 \uc704\uc8fc\uc758 \ubcf4\uc218\uc801 \uc6b4\uc6a9\uc5d0 \uc801\ud569\ud569\ub2c8\ub2e4.<br/>\\n\uc77c\uc784\ud615\uc740 \uc6b4\uc6a9\uc0ac\uc5d0 \uc790\uc0b0 \uc6b4\uc6a9\uc744 \ub9e1\uae30\ub294 \ubc29\uc2dd\uc73c\ub85c, \uc218\uc218\ub8cc\uac00 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\\n### \uc138\uc81c \ud61c\ud0dd\uc758 \uad6c\uc870\\n\\n#### \ube44\uacfc\uc138 \ud55c\ub3c4\\n\\n\uacc4\uc88c\uc5d0\uc11c \ubc1c\uc0dd\ud55c \uc774\uc790\xb7\ubc30\ub2f9 \uc18c\ub4dd\uc740 \uc77c\ubc18\ud615 \uae30\uc900 `200\ub9cc \uc6d0`\uae4c\uc9c0 \ube44\uacfc\uc138\uc785\ub2c8\ub2e4.<br/>\\n\uc11c\ubbfc\ud615(\ucd1d\uae09\uc5ec 5,000\ub9cc \uc6d0 \uc774\ud558 \ub4f1)\uacfc \ub18d\uc5b4\ubbfc\ud615\uc740 `400\ub9cc \uc6d0`\uae4c\uc9c0 \ube44\uacfc\uc138\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\ubc18 \uacc4\uc88c\uc5d0\uc11c ETF\ub85c \ubc88 \uc218\uc775\uc5d0 \ubd99\ub294 \uc138\uc728\uc774 `15.4%`\uc778 \uac83\uacfc \ube44\uad50\ud558\uba74 \ucc28\uc774\uac00 \ud07d\ub2c8\ub2e4.<br/>\\n\\n#### \ucd08\uacfc\ubd84\uc740 9% \ubd84\ub9ac\uacfc\uc138\\n\\n\ube44\uacfc\uc138 \ud55c\ub3c4\ub97c \ucd08\uacfc\ud558\ub294 \uc21c\uc774\uc775\uc5d0\ub294 `9%`\uc758 \uc138\uc728\ub85c \ubd84\ub9ac\uacfc\uc138\uac00 \uc801\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\ub18d\uc5b4\ucd0c\ud2b9\ubcc4\uc138\ub97c \ud3ec\ud568\ud558\uba74 \uc2e4\ud6a8\uc138\uc728\uc740 `9.9%`\uc785\ub2c8\ub2e4.<br/>\\n\ubd84\ub9ac\uacfc\uc138\uc774\ubbc0\ub85c \uae08\uc735\uc18c\ub4dd\uc885\ud569\uacfc\uc138\uc5d0 \ud569\uc0b0\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\ub3c4 \uc7a5\uc810\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc30\ub2f9\uc18c\ub4dd \uc790\uccb4\ub294 ISA \uc548\uc5d0\uc11c\ub3c4 \uc6d0\ucc9c\uc9d5\uc218 \uac1c\ub150\uc774 \uc801\uc6a9\ub418\ubbc0\ub85c, \uc21c\uc774\uc775 \uae30\uc900\uc73c\ub85c \uc815\uc0b0\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc190\uc775\ud1b5\uc0b0\uc758 \ud6a8\uacfc\\n\\n\ud55c \uc0c1\ud488\uc5d0\uc11c \uc190\uc2e4\uc774 \ub098\ub3c4 \ub2e4\ub978 \uc0c1\ud488\uc758 \uc774\uc775\uacfc \uc0c1\uc1c4\ud55c \ub4a4 \uc21c\uc774\uc775\uc5d0\ub9cc \uacfc\uc138\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\ubcc4 \uc0c1\ud488\ub9c8\ub2e4 \uc138\uae08\uc744 \uacc4\uc0b0\ud558\ub294 \uc77c\ubc18 \uacc4\uc88c\ubcf4\ub2e4 \uc2e4\ud6a8\uc138\uc728\uc774 \ub0ae\uc544\uc9c0\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 ISA\ub294 \ub2e8\uc77c \uc0c1\ud488\ubcf4\ub2e4\ub294 \uc5ec\ub7ec \uc0c1\ud488\uc744 \ud568\uaed8 \ub2f4\uc744 \ub54c \ud6a8\uacfc\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n### 2026\ub144 \ub17c\uc758 \uc911\uc778 \uac1c\ud3b8\\n\\n#### \ubb34\uc5c7\uc774 \ubc14\ub00c\ub824 \ud558\ub294\uac00\\n\\n2026\ub144 \uc138\uc81c\uac1c\ud3b8\uc548\uc5d0\ub294 ISA \uad00\ub828 \uac1c\ud3b8\uc774 \ud3ec\ud568\ub418\uc5b4 \ub17c\uc758 \uc911\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\uac04 \ub0a9\uc785\ud55c\ub3c4 \ud655\ub300, \ubbf8\uc0ac\uc6a9 \uc5f0\uac04 \ud55c\ub3c4\uc758 \ub2e4\uc74c \ud574 \uc774\uc6d4 \uc81c\ub3c4 \ud3d0\uc9c0(2027\ub144 \uc2dc\ud589 \uc608\uc815), \uc0dd\uc0b0\uc801\uae08\uc735 ISA \uc2e0\uc124 \ub4f1\uc774 \uac70\ub860\ub429\ub2c8\ub2e4.<br/>\\n\uc0dd\uc0b0\uc801\uae08\uc735 ISA\ub294 \uad6d\ub0b4 \uc8fc\uc2dd\xb7\ud380\ub4dc \uc804\uc6a9 \uacc4\uc88c\ub85c \uc774\uc790\xb7\ubc30\ub2f9\uc18c\ub4dd \uc804\uc561 \ube44\uacfc\uc138\ub97c \ud2b9\uc9d5\uc73c\ub85c \ud558\ub294 \ubc29\uc548\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc544\uc9c1 \uc2dc\ud589 \uc804\uc774\ub2e4\\n\\n\uc704 \ub0b4\uc6a9\uc740 \ubaa8\ub450 \ub17c\uc758\xb7\uc608\uace0 \ub2e8\uacc4\uc774\uba70, \uc785\ubc95 \uacfc\uc815\uc744 \uac70\uccd0 \ud655\uc815\ub429\ub2c8\ub2e4.<br/>\\n\uc2dc\ud589 \uc804\uc5d0\ub294 \uae30\uc874 \uaddc\uce59\uc774 \uc801\uc6a9\ub418\ubbc0\ub85c, \ud604\uc7ac \ub0a9\uc785 \uacc4\ud68d\uc740 \ud604\ud589 \uae30\uc900\uc73c\ub85c \uc138\uc6c1\ub2c8\ub2e4.<br/>\\n\uac1c\ud3b8\uc774 \ud655\uc815\ub418\uba74 \ub0a9\uc785 \uc804\ub7b5\ub3c4 \uadf8\ub54c \ub2e4\uc2dc \uc810\uac80\ud558\uba74 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\nISA\ub294 3\ub144 \uc758\ubb34\uae30\uac04\uc774 \uc788\uc73c\ubbc0\ub85c \ub2e8\uae30 \uc790\uae08\uc774 \uc544\ub2cc \uc911\uc7a5\uae30 \uc5ec\uc720 \uc790\uae08\uc73c\ub85c \uc6b4\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc5f0\uae08\uc800\ucd95\xb7IRP\ub294 \ub178\ud6c4 \uc790\uae08\uc758 \uc138\uc561\uacf5\uc81c\uac00 \ubaa9\uc801\uc774\uace0, ISA\ub294 \uc6b4\uc6a9 \uc911 \uc138\uae08 \uc808\uac10\uc774 \ubaa9\uc801\uc774\ub77c\ub294 \uc810\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc911\ub3c4\ud574\uc9c0 \uc2dc \uc138\uae08 \ucd94\uc9d5\uc774 \ubc1c\uc0dd\ud558\ubbc0\ub85c, \ud574\uc9c0 \uc2dc\uc810\ub3c4 3\ub144 \uc774\ud6c4\ub85c \uacc4\ud68d\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 ISA \uc81c\ub3c4\ub97c \uc124\uba85\ud558\ub294 \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc774\uba70, ISA \uac00\uc785 \uc790\uccb4\ub97c \uad8c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nISA\ub294 \uc190\uc775\ud1b5\uc0b0\uacfc \ube44\uacfc\uc138 \ud55c\ub3c4\uac00 \ub9cc\ub4dc\ub294 \uc808\uc138 \uad6c\uc870\ub97c \uc774\ud574\ud558\uba74 \ud65c\uc6a9\ub3c4\uac00 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n3\ub144 \uc758\ubb34\uae30\uac04\uc744 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uc790\uae08\uc778\uc9c0 \uba3c\uc800 \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExaW50YW51MXp0dGFrbHI4MnBhbjdxd2ZvMWFhbGwxNnFwcHN4bjVuayZlcD12MV9naWZzX3NlYXJjaCZjdD1n/zbsMLe0hKqS2nNJ7LT/giphy.gif\\" alt=\\"ISA\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-4percent-rebound-oct23","metadata":{"permalink":"/blog/en/finance/kospi-4percent-rebound-oct23","source":"@site/finance/2026-10-23-kospi-4percent-rebound/index.mdx","title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"market-recap","permalink":"/blog/en/finance/tags/market-recap"},{"inline":true,"label":"kospi","permalink":"/blog/en/finance/tags/kospi"}],"readingTime":2.66,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-4percent-rebound-oct23","title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","authors":["way"],"tags":["finance","market-recap","kospi"]},"unlisted":false,"prevItem":{"title":"ISA(\uac1c\uc778\uc885\ud569\uc790\uc0b0\uad00\ub9ac\uacc4\uc88c) \uae30\ucd08 \ud574\uc124","permalink":"/blog/en/finance/isa-basics-guide"},"nextItem":{"title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","permalink":"/blog/en/finance/bond-price-yield"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n10\uc6d4 23\uc77c \uae08\uc694\uc77c \uc7a5 \ub9c8\uac10 \ub3d9\ud5a5\uacfc \ub2e4\uc74c \uc8fc\uc5d0 \ud655\uc778\ud560 \uc77c\uc815\uc744 \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 4% \ub118\uac8c \ud754\ub4e4\ub9b0 \ud558\ub8e8\\n\\n\uac04\ubc24 \ub274\uc695\uc99d\uc2dc\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc8fc\uac00 \uc57d\uc138\ub97c \ubcf4\uc778 \uc5ec\ud30c\ub85c, 10\uc6d4 23\uc77c \ucf54\uc2a4\ud53c\ub294 2.36% \ud558\ub77d\ud55c `5,403.17`\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc774\ud6c4 \uc678\uad6d\uc778\uc758 \ub9e4\ub3c4\uc138\uac00 \ud655\ub300\ub418\uba70 \uc7a5\uc911 \ud55c\ub54c `5,305.98`\uae4c\uc9c0 \ubc00\ub838\uace0, \uc804\uc77c \ub300\ube44 \ub099\ud3ed\uc740 4%\ub97c \ub118\uc5b4\uc130\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc624\ud6c4 \ub4e4\uc5b4 \uae30\uad00\uc758 \ub9e4\uc218\uc138\uac00 \uc720\uc785\ub418\uba70 \ub099\ud3ed\uc744 \ube60\ub974\uac8c \uc904\uc600\uace0, \uc7a5\uc911 \ucd5c\uace0\uc810\uc5d0\uc11c `5,550.30`(+0.30%, +16.53\ud3ec\uc778\ud2b8)\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub8e8 \ub4f1\ub77d\ub960\uc740 0.30%\uc5d0 \ubd88\uacfc\ud588\uc9c0\ub9cc, \uc7a5\uc911 \uc9c4\ud3ed\uc774 4%\ud3ec\uc778\ud2b8\ub97c \ub118\uc740 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZmR1MzltcWFlZmFzcDNnMWJjZWl1ZDNxYnZ0a3gzN3U4Y2JvZ2d1MSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1AjFk7MzJBT2UPYKLB/giphy.gif\\" alt=\\"Market\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc678\uad6d\uc778\uc774 \ud310 \ub9cc\ud07c \uae30\uad00\uc774 \ubc1b\uc544 \uc0c0\ub2e4\\n\\n#### \uc218\uae09 \uad6c\uc870\\n\\n\uc678\uad6d\uc778\uc774 \uc57d 1\uc870 \uc6d0 \uac00\uae4c\uc774 \uc21c\ub9e4\ub3c4\ud558\uba70 \ub9e4\ub3c4 \uc6b0\uc704\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uae30\uad00\uc740 8\ucc9c\uc5b5 \uc6d0\ub300 \uc21c\ub9e4\uc218, \uac1c\uc778\ub3c4 \uc21c\ub9e4\uc218\uc5d0 \ub3d9\ucc38\ud558\uba70 \uc9c0\uc218 \ubc18\ub4f1\uc744 \ub4b7\ubc1b\uce68\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \ubb3c\ub7c9\uc758 \ubc18\ub300\ud3b8\uc5d0 \uad6d\ub0b4 \uae30\uad00\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc624\ub298 \uc2dc\uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ubc18\ub4f1\uc758 \uc911\uc2ec \u2014 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\\n\\n\uc7a5 \ucd08\ubc18 5% \ub118\uac8c \ubc00\ub838\ub358 SK\ud558\uc774\ub2c9\uc2a4\ub294 \uc190\uc790\ud68c\uc0ac \uc194\ub9ac\ub2e4\uc784\uc758 \ubbf8\uad6d \uc99d\uc2dc \uc0c1\uc7a5 \uc808\ucc28 \uc911\ub2e8 \uc18c\uc2dd\uc774 \uc804\ud574\uc9c4 \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 4.42% \uc624\ub978 `1,277,000\uc6d0`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\ub294 \uc7a5\uc911 5% \ub118\uac8c \ud558\ub77d\ud588\ub2e4\uac00 \uc624\ud6c4\uc5d0 \uc0c1\uc2b9 \uc804\ud658\ud574 0.47% \uc624\ub978 `215,500\uc6d0`\uc5d0 \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc885\ubaa9\uc744 \ubb36\uc5b4 \ubd80\ub974\ub294 \'\uc0bc\uc804\ub2c9\uc2a4\'\uac00 \uc9c0\uc218 \ud68c\ubcf5\uc744 \uacac\uc778\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc0c1\uc2b9 \uc885\ubaa9\uacfc \ud558\ub77d \uc885\ubaa9\\n\\n\uc0bc\uc131\ubc14\uc774\uc624\ub85c\uc9c1\uc2a4\ub294 7.71% \uae09\ub4f1\ud55c `1,466,000\uc6d0`\uc5d0 \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\uc6b0(+0.48%), SK\uc2a4\ud018\uc5b4(+3.20%), \uc0bc\uc131\uc0dd\uba85(+1.45%)\ub3c4 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 LG\uc5d0\ub108\uc9c0\uc194\ub8e8\uc158(-1.79%), \uc0bc\uc131SDI(-4.20%), \ud604\ub300\ucc28(-1.99%), KB\uae08\uc735(-3.29%)\uc740 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc \uc548\uc5d0\uc11c\ub3c4 \uc5c7\uac08\ub9b0 \ud750\ub984\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ucf54\uc2a4\ub2e5\uc740 \ubc18\ub4f1\uc5d0 \uc2e4\ud328\ud588\ub2e4\\n\\n\ucf54\uc2a4\ub2e5\uc740 12.41\ud3ec\uc778\ud2b8(-1.62%) \ub0b4\ub9b0 `751.69`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uac01\uac01 \uc218\ubc31\uc5b5 \uc6d0\uc529 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc740 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9 \ub300\ubd80\ubd84\uc774 \uc57d\uc138\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d0\ucf54\ud504\ub85c(-5.83%, 72,700\uc6d0), \uc5d0\ucf54\ud504\ub85c\ube44\uc5e0(-5.50%), \uc54c\ud14c\uc624\uc820(-2.81%), \ub9ac\ub178\uacf5\uc5c5(-4.05%), \ub808\uc778\ubcf4\uc6b0\ub85c\ubcf4\ud2f1\uc2a4(-3.42%) \ub4f1\uc774 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ucc28\uc804\uc9c0\uc8fc\uc640 \ubc18\ub3c4\uccb4 \uc7a5\ube44\uc8fc\uac00 \ud568\uaed8 \ub20c\ub9b0 \uac83\uc774 \ucf54\uc2a4\ub2e5 \uc57d\uc138\uc758 \ubc30\uacbd\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\uacfc \ud574\uc678 \ubcc0\uc218\\n\\n\uc11c\uc6b8 \uc678\ud658\uc2dc\uc7a5\uc5d0\uc11c \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \uc804\uc77c \uc8fc\uac04 \uc885\uac00\ubcf4\ub2e4 0.4\uc6d0 \uc624\ub978 `1,324.6\uc6d0`\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d\uc5d0\uc11c\ub294 \ub098\uc2a4\ub2e5\uc885\ud569\uc9c0\uc218\uac00 2.60%, S&P500\uc774 1.21% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nAI \ud22c\uc790 \uc9c0\uc18d\uc131\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uad6d\ub0b4 \ubc18\ub3c4\uccb4\uc8fc\ub85c \uc804\uc774\ub41c \ub4a4 \uc624\ud6c4\uc5d0 \uc9c4\uc815\ub41c \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ub9c8\uac10 \uc2dc\ud669\uc740 [\ub354\ud329\ud2b8](https://news.tf.co.kr/read/economy/2380152.htm)\uc640 [\ub274\uc2a4\ud54c](https://m.newspim.com/news/view/20261023001023) \uae30\uc0ac\ub85c \uad50\ucc28 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud22c\uc790\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\uc7a5\uc911 4% \uae09\ub77d\uacfc \uc885\uac00 \ubc18\ub4f1\uc740 \uc131\uaca9\uc774 \ub2e4\ub978 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\uc885\uac00\ub9cc \ubcf4\uba74 0.30% \uc0c1\uc2b9\uc774\uc9c0\ub9cc, \uc7a5\uc911 \ud754\ub4e4\ub9bc\uc758 \ud3ed\uc744 \ud568\uaed8 \ubd10\uc57c \ub2e4\uc74c \uc8fc \ubcc0\ub3d9\uc131\uc744 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \ubc18\ub4f1\uc774 \uad6d\ub0b4 \uc218\uae09\uc5d0 \uc758\uc874\ud588\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc \uc77c\uc815\uc740 10\uc6d4 27~28\uc77c \ubbf8\uad6d FOMC \ud68c\uc758(\ud55c\uad6d \uc2dc\uac01 10\uc6d4 29\uc77c \uc0c8\ubcbd 3\uc2dc \uacb0\uacfc \ubc1c\ud45c)\uc640 \uc8fc\uc694 \uae30\uc5c5 \uc2e4\uc801 \ubc1c\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacb0\uc815\uacfc \uc2e4\uc801 \uc22b\uc790\uac00 \ub098\uc628 \ub4a4\uc5d0\ub294, \uc624\ub298 \ubc18\ub4f1\uc758 \uadfc\uac70\uac00 \uc720\uc9c0\ub418\ub294\uc9c0 \ub2e4\uc2dc \uc810\uac80\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc7a5\uc911 4% \uae09\ub77d\uc744 \ub51b\uace0 \uc624\ub978 0.30%\ub294 \uc885\uac00\ubcf4\ub2e4 \uc9c4\ud3ed\uc5d0 \uc8fc\ubaa9\ud574\uc57c \ud558\ub294 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uc8fc FOMC \uacb0\uacfc\uae4c\uc9c0 \ud655\uc778\ud55c \ub4a4\uc5d0 \uc774\ubc88 \ubc18\ub4f1\uc758 \uc131\uaca9\uc744 \ub2e4\uc2dc \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNWJ1ZHMwM2FvbHFvZXQ4NjBhdjFpcjR3d2VuYyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/4xpB3eE00FfBm/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"bond-price-yield","metadata":{"permalink":"/blog/en/finance/bond-price-yield","source":"@site/finance/2026-10-22-bond-price-yield/index.mdx","title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"bond","permalink":"/blog/en/finance/tags/bond"},{"inline":true,"label":"interest-rate","permalink":"/blog/en/finance/tags/interest-rate"}],"readingTime":2.87,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"bond-price-yield","title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","authors":["way"],"tags":["finance","bond","interest-rate"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c, \uc7a5\uc911 4% \uae09\ub77d \ub51b\uace0 \ubc18\ub4f1 \u2014 10\uc6d4 23\uc77c \uc2dc\uc7a5 \uc815\ub9ac","permalink":"/blog/en/finance/kospi-4percent-rebound-oct23"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","permalink":"/blog/en/finance/kospi-plunge-oct22"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \ud55c\uad6d\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud55c \ub0a0\uc5d0 \ub9de\ucdb0, \ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4\ub97c \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc624\ub298\uc758 \uae08\ub9ac \uacb0\uc815\\n\\n2026\ub144 10\uc6d4 22\uc77c, \ud55c\uad6d\uc740\ud589 \uae08\uc735\ud1b5\ud654\uc704\uc6d0\ud68c\ub294 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubb3c\uac00 \uc555\ubc15\uc774 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 11\uc6d4 \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\ub3c4 \uac70\ub860\ub418\ub294 \uc0c1\ud669\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc900\uae08\ub9ac\ub294 \uc2dc\uc911 \uae08\ub9ac\uc758 \uae30\uc900\uc810\uc774 \ub418\uace0, \uc2dc\uc911 \uae08\ub9ac\ub294 \ucc44\uad8c \uac00\uaca9\uc744 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ub274\uc2a4\uac00 \ucc44\uad8c \ud22c\uc790\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0 \uc774\ud574\ud558\ub824\uba74, \uba3c\uc800 \ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4\ub97c \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHc0MjBibDZvZDY0dzFib2g0YzNmbzFkZTVwb3N3MDV1c2loZm04MiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/1BPvv1QvbKV156jyul/giphy.gif\\" alt=\\"Money\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\ub294 \uc65c \ubc18\ub300\ub85c \uc6c0\uc9c1\uc774\ub294\uac00\\n\\n#### \ucc44\uad8c\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n\ucc44\uad8c\uc740 \ubc1c\ud589\uc790\uac00 \ud22c\uc790\uc790\uc5d0\uac8c \uc6d0\uae08\uacfc \uc774\uc790\ub97c \uc57d\uc18d\ud558\ub294 \uc99d\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc561\uba74\uae08\uc561, \ud45c\uba74\uae08\ub9ac(\ucfe0\ud3f0\uae08\ub9ac), \ub9cc\uae30\uac00 \ubc1c\ud589 \uc2dc\uc810\uc5d0 \uc815\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4 \uc561\uba74 10,000\uc6d0, \ud45c\uba74\uae08\ub9ac \uc5f0 3%, \ub9cc\uae30 3\ub144\uc778 \ucc44\uad8c\uc740 \ub9e4\ub144 300\uc6d0\uc758 \uc774\uc790\ub97c \uc9c0\uae09\ud558\uace0 \ub9cc\uae30\uc5d0 10,000\uc6d0\uc744 \ub3cc\ub824\uc90d\ub2c8\ub2e4.<br/>\\n\uc774 \uc870\uac74\uc740 \ubc1c\ud589 \uc774\ud6c4\uc5d0\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc2dc\uc7a5\uae08\ub9ac\uac00 \uc624\ub974\uba74 \uae30\uc874 \ucc44\uad8c\uc758 \ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c4\ub2e4\\n\\n\ucc44\uad8c\uc740 \ubc1c\ud589 \ud6c4\uc5d0\ub3c4 \uc2dc\uc7a5\uc5d0\uc11c \uc0ac\uace0\ud314 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub54c \ucc44\uad8c \uac00\uaca9\uc740 \uc2dc\uc7a5\uae08\ub9ac\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 3%\uc77c \ub54c \uc5f0 3% \uc774\uc790\ub97c \uc8fc\ub294 \ucc44\uad8c\uc740 \uc561\uba74\uac00\uc778 10,000\uc6d0\uc5d0 \uac70\ub798\ub429\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uc2dc\uc7a5\uae08\ub9ac\uac00 4%\ub85c \uc624\ub974\uba74, \uc0c8\ub85c \ubc1c\ud589\ub418\ub294 \ucc44\uad8c\uc740 \uc5f0 4%\uc758 \uc774\uc790\ub97c \uc90d\ub2c8\ub2e4.<br/>\\n\uae30\uc874\uc758 \uc5f0 3% \ucc44\uad8c\uc740 \uc0c8 \ucc44\uad8c\ubcf4\ub2e4 \ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c0\ubbc0\ub85c, \ub204\uad70\uac00 \uc0ac\ub824\uba74 \uac00\uaca9\uc774 10,000\uc6d0\ubcf4\ub2e4 \ub0ae\uc544\uc838\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c0\uba74 \uadf8 \ucc44\uad8c\uc744 \uc0b0 \ud22c\uc790\uc790\uc758 \uc2e4\uc9c8 \uc218\uc775\ub960(\ub9cc\uae30\uc218\uc775\ub960)\uc740 4%\uc5d0 \uac00\uae4c\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\uc989, \uc2dc\uc7a5\uae08\ub9ac \uc0c1\uc2b9\uc740 \uae30\uc874 \ucc44\uad8c \uac00\uaca9 \ud558\ub77d\uc73c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc2dc\uc7a5\uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778\ub2e4\\n\\n\ubc18\ub300\ub85c \uc2dc\uc7a5\uae08\ub9ac\uac00 2%\ub85c \ub0b4\ub9ac\uba74, \uc5f0 3% \uc774\uc790\ub97c \uc8fc\ub294 \uae30\uc874 \ucc44\uad8c\uc740 \uadc0\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\uc0c8 \ucc44\uad8c\ubcf4\ub2e4 \uc774\uc790\ub97c \ub9ce\uc774 \uc8fc\ubbc0\ub85c, \uac00\uaca9\uc774 10,000\uc6d0\ubcf4\ub2e4 \ub192\uac8c \ud615\uc131\ub429\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc774 \uc624\ub974\uba74 \uc2e4\uc9c8 \uc218\uc775\ub960\uc740 2%\uc5d0 \uac00\uae4c\uc6cc\uc9d1\ub2c8\ub2e4.<br/>\\n\uc815\ub9ac\ud558\uba74 \ucc44\uad8c \uac00\uaca9\uacfc \uc2dc\uc7a5\uae08\ub9ac\ub294 \ud56d\uc0c1 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uacc4\uc0b0 \uc608\uc2dc\ub85c \ud655\uc778\ud558\uae30\\n\\n#### \ub2e8\uc21c\ud654\ub41c \ud604\uc7ac\uac00\uce58 \uacc4\uc0b0\\n\\n\ucc44\uad8c \uac00\uaca9\uc740 \ubbf8\ub798\uc5d0 \ubc1b\uc744 \ud604\uae08\ud750\ub984\uc744 \ud604\uc7ac \uac00\uce58\ub85c \ud560\uc778\ud55c \ud569\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc561\uba74 10,000\uc6d0, \ud45c\uba74\uae08\ub9ac 3%, \ub9cc\uae30 3\ub144, \ub9e4\ub144 \uc774\uc790 \uc9c0\uae09 \ucc44\uad8c\uc73c\ub85c \uacc4\uc0b0\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n\ub9e4\ub144 \ubc1b\ub294 \uae08\uc561\uc740 `300\uc6d0`, `300\uc6d0`, `10,300\uc6d0`\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 3%\uc77c \ub54c \uac00\uaca9\uc740 `10,000\uc6d0`\uc73c\ub85c \uc561\uba74\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 4%\ub85c \uc624\ub974\uba74 \uac00\uaca9\uc740 \uc57d `9,723\uc6d0`\uc73c\ub85c \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uae08\ub9ac\uac00 2%\ub85c \ub0b4\ub9ac\uba74 \uac00\uaca9\uc740 \uc57d `10,288\uc6d0`\uc73c\ub85c \uc624\ub985\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ucc44\uad8c\uc778\ub370 \uc2dc\uc7a5\uae08\ub9ac\uc5d0 \ub530\ub77c \uac00\uaca9\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc744 \uc218\uce58\ub85c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub4c0\ub808\uc774\uc158 \u2014 \uac00\uaca9\uc774 \uc5bc\ub9c8\ub098 \ubbfc\uac10\ud55c\uac00\\n\\n\uae08\ub9ac\uac00 1%\ud3ec\uc778\ud2b8 \uc6c0\uc9c1\uc77c \ub54c \ucc44\uad8c \uac00\uaca9\uc774 \uba87 % \uc6c0\uc9c1\uc774\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \uc9c0\ud45c\uac00 \ub4c0\ub808\uc774\uc158\uc785\ub2c8\ub2e4.<br/>\\n\ub9cc\uae30\uac00 \uae38\uace0 \ud45c\uba74\uae08\ub9ac\uac00 \ub0ae\uc744\uc218\ub85d \ub4c0\ub808\uc774\uc158\uc774 \ucee4\uc11c \uac00\uaca9 \ubcc0\ub3d9\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\uc7a5\uae30\ucc44\uac00 \ub2e8\uae30\ucc44\ubcf4\ub2e4 \uae08\ub9ac \ubcc0\ud654\uc5d0 \ubbfc\uac10\ud55c \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc0c1\uc2b9\uc774 \uc608\uc0c1\ub418\ub294 \uad6d\uba74\uc5d0\uc11c\ub294 \ub4c0\ub808\uc774\uc158\uc774 \uc9e7\uc740 \ucc44\uad8c\uc774 \uac00\uaca9 \ud558\ub77d \ud3ed\uc774 \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\uae30\uc900\uae08\ub9ac \uacb0\uc815\ubb38\uc744 \uc77d\uc744 \ub54c\ub294 \ub3d9\uacb0\xb7\uc778\uc0c1\xb7\uc778\ud558 \uc5ec\ubd80\ubcf4\ub2e4 \ud5a5\ud6c4 \ubc29\ud5a5\uc5d0 \ub300\ud55c \ubb38\uad6c\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uc624\ub298\ucc98\ub7fc \ub3d9\uacb0\uc774\uba74\uc11c\ub3c4 \ubb3c\uac00 \uc555\ubc15\uacfc \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\uc774 \uac70\ub860\ub418\ub294 \uacbd\uc6b0, \uc2dc\uc7a5\uae08\ub9ac\ub294 \ub3d9\uacb0\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc624\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucc44\uad8c \uae08\ub9ac\ub294 \uad6d\uace0\ucc44 \uc218\uc775\ub960 \uace1\uc120\uc73c\ub85c \ud655\uc778\ud558\uace0, \uae30\uc900\uae08\ub9ac\uc640\uc758 \ucc28\uc774\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\ubcf4\uc720 \uc911\uc778 \ucc44\uad8c\uc758 \ub4c0\ub808\uc774\uc158\uc744 \uc54c\uba74, \uae08\ub9ac \ubcc0\ud654 \uc2dc \ud3c9\uac00\uae08\uc561\uc774 \uc5b4\ub290 \uc815\ub3c4 \uc6c0\uc9c1\uc77c\uc9c0 \uac00\ub2a0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc608\uae08\uacfc \ub2ec\ub9ac \ucc44\uad8c\uc740 \uc911\ub3c4 \ub9e4\ub3c4 \uc2dc \uac00\uaca9 \ubcc0\ub3d9\uc774 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uc5ed\uad00\uacc4\ub294 \ud55c \ubc88 \uc774\ud574\ud558\uba74 \ud3c9\uc0dd \uc4f0\ub294 \uae30\ubcf8\uae30\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ub274\uc2a4\ub97c \ubcfc \ub54c\ub9c8\ub2e4 \\"\uadf8\ub798\uc11c \ucc44\uad8c \uac00\uaca9\uc740 \uc5b4\ub290 \ubc29\ud5a5\uc778\uac00\\"\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHc0MjBibDZvZDY0dzFib2g0YzNmbzFkZTVwb3N3MDV1c2loZm04MiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/67ThRZlYBvibtdF9JH/giphy.gif\\" alt=\\"Finance\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-plunge-oct22","metadata":{"permalink":"/blog/en/finance/kospi-plunge-oct22","source":"@site/finance/2026-10-22-kospi-plunge-oct22/index.mdx","title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"market","permalink":"/blog/en/finance/tags/market"},{"inline":true,"label":"kospi","permalink":"/blog/en/finance/tags/kospi"}],"readingTime":3.71,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-plunge-oct22","title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","authors":["way"],"tags":["finance","market","kospi"]},"unlisted":false,"prevItem":{"title":"\ucc44\uad8c \uac00\uaca9\uacfc \uae08\ub9ac\uc758 \uad00\uacc4 \u2014 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c\uac12\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc774\uc720","permalink":"/blog/en/finance/bond-price-yield"},"nextItem":{"title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","permalink":"/blog/en/finance/pension-tax-credit-2026"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uc5b4\uc81c\uc758 \uc0c1\uc2b9\ubd84\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ubc18\ub0a9\ud55c \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uae09\ub77d\uacfc, \uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c4 \ub0a0\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uc9c0\ud45c\ub4e4\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc624\ub298\uc758 \uc2dc\uc7a5\\n\\n2026\ub144 10\uc6d4 22\uc77c, \ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 201.89\ud3ec\uc778\ud2b8, 3.52% \ud558\ub77d\ud55c 5,533.77\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\uc81c 5,700\uc120\uc744 \ub118\uc5c8\ub358 \uc0c1\uc2b9\ubd84\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \uace0\uc2a4\ub780\ud788 \ubc18\ub0a9\ud55c \uc148\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\ub294 5,670.11\uc5d0 \ucd9c\ubc1c\ud574 \uc7a5\uc911 5,740.28\uae4c\uc9c0 \ubc18\ub4f1\uc744 \uc2dc\ub3c4\ud588\uc9c0\ub9cc, \uc774\ud6c4 \ub099\ud3ed\uc744 \ud0a4\uc6cc \uc7a5\uc911 \ud55c\ub54c 5,485.98\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uc804\uc77c \ub300\ube44 28.66\ud3ec\uc778\ud2b8, 3.62% \ud558\ub77d\ud55c 764.10\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub294 3.71% \ud558\ub77d\ud55c 858.02\ub85c, \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \ub099\ud3ed\uc774 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.6\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.11% \ud558\ub77d\ud574 \uc6d0\ud654\uac00 \uc18c\ud3ed \uac15\uc138\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc740 \ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\uac00 1.05%, S&P500\uc774 0.58% \uc624\ub974\ub294 \ub4f1 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc989, \uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uae09\ub77d\uc740 \ud574\uc678 \uc2dc\uc7a5\uc758 \ud750\ub984\uacfc \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778, \uad6d\ub0b4 \uc694\uc778\uc774 \uac15\ud558\uac8c \uc791\uc6a9\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExanZuZzl0cmFhanF3Z290c3F3YjdrYjJsa2hvODVmejAzMm45aHZiaiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/JtBZm3Getg3dqxK0zP/giphy.gif\\" alt=\\"Falling chart\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae09\ub77d\uc758 \ubc30\uacbd\\n\\n\uc624\ub298\uc758 \ud558\ub77d\uc740 \ud558\ub098\uc758 \uc6d0\uc778\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \uc545\uc7ac\uac00 \uacb9\uce58\uba70 \ud22c\uc790\uc2ec\ub9ac\uac00 \ud55c \ubc88\uc5d0 \uc5bc\uc5b4\ubd99\uc740 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### AI \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824\uc640 \ubc18\ub3c4\uccb4 \ucc28\uc775 \uc2e4\ud604\\n\\n\ud558\ub77d\uc744 \uc8fc\ub3c4\ud55c \uac83\uc740 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\ub294 \uac01\uac01 4.03%, 5.49% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n([\uc544\uc8fc\uacbd\uc81c \ubcf4\ub3c4](https://www.ajunews.com/view/20261022154721705)\ub97c \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.)<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c \uba54\ud0c0\uac00 3\ubd84\uae30 \ud638\uc2e4\uc801\uc744 \ubc1c\ud45c\ud588\uc74c\uc5d0\ub3c4, \ub0b4\ub144 \uc124\ube44\ud22c\uc790 \uac00\uc774\ub358\uc2a4\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc558\uace0 3\ubd84\uae30 \uc789\uc5ec\ud604\uae08\ud750\ub984\uc774 21\uc5b52\ucc9c\ub9cc \ub2ec\ub7ec \uc801\uc790\ub85c \uc804\ud658\ud55c \uc810\uc774 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nAI \uc0ac\uc5c5\uc758 \uc131\uc7a5\uc138\uc640 \ubcc4\uac1c\ub85c, \ub300\uaddc\ubaa8 \ud22c\uc790 \ube44\uc6a9\uc744 \uac10\ub2f9\ud560 \ud604\uae08\ud750\ub984\uacfc \uc218\uc775\uc131\uc744 \ud655\ubcf4\ud560 \uc218 \uc788\uc744\uc9c0\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \ud574\uc18c\ub418\uc9c0 \uc54a\uc740 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc5d0 \uc804\ub0a0 \uae09\ub4f1\uc5d0 \ub530\ub978 \ucc28\uc775 \uc2e4\ud604 \ub9e4\ubb3c\uc774 \uacb9\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc885\ub8cc\uc5d0 \ub530\ub978 \uc218\uae09 \uacf5\ubc31\\n\\n\uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc774 \uc787\ub2ec\uc544 \uc885\ub8cc\ub418\uba70 \ub9e4\uc218 \uae30\ubc18\uc774 \uc57d\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\ub294 15\uc870\uc6d0 \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc744 \uc9c0\ub09c 6\uc77c \ub9c8\ucce4\uace0, SK\ud558\uc774\ub2c9\uc2a4\ub294 40\uc870\uc6d0 \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc744 \uc9c0\ub09c 21\uc77c \uc644\ub8cc\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\uc2e0\uc99d\uad8c \uc774\uacbd\ubbfc \uc5f0\uad6c\uc6d0\uc740 SK\ud558\uc774\ub2c9\uc2a4\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc885\ub8cc\ub85c \\"\uc218\uae09 \uc644\ucda9\ub825\uc774 \ucd94\uac00\ub85c \uc57d\ud654\ub410\ub2e4\\"\uace0 \uc9c4\ub2e8\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nSK\ud558\uc774\ub2c9\uc2a4\uc758 \ubbf8\uad6d \uc790\ud68c\uc0ac \uc194\ub9ac\ub2e4\uc784 \uc0c1\uc7a5 \ucd94\uc9c4\uc744 \ub458\ub7ec\uc2fc \uc911\ubcf5\uc0c1\uc7a5 \ub17c\ub780\ub3c4 \ud22c\uc790\uc2ec\ub9ac\uc5d0 \ubd80\ub2f4\uc744 \ub354\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc9c0\uc815\ud559\uc801 \uae34\uc7a5\uacfc \ud1b5\ud654\uc815\ucc45 \uacbd\uacc4\uac10\\n\\n\uc911\ub3d9\uc758 \uc9c0\uc815\ud559\uc801 \uae34\uc7a5\ub3c4 \ud22c\uc790\uc2ec\ub9ac\ub97c \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc774 \uc0ac\uc6b0\ub514\uc544\ub77c\ube44\uc544 \uc8fc\uc7ac \ube44\ud544\uc218 \uc678\uad50 \uc778\ub825\uc5d0 \ucd9c\uad6d\uc744 \uba85\ub839\ud558\uba74\uc11c \uad6d\uc9c0\uc801 \uad70\uc0ac \ucda9\ub3cc\uc5d0 \ub300\ud55c \uacbd\uacc4\uac10\uc774 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc740\ud589 \uae08\uc735\ud1b5\ud654\uc704\uc6d0\ud68c\ub294 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.00%\ub85c \ub3d9\uacb0\ud588\uc9c0\ub9cc, \ubb3c\uac00 \ubd80\ub2f4\uacfc \ud1b5\ud654\uc815\ucc45\uc744 \ub458\ub7ec\uc2fc \uacbd\uacc4\uac10 \uc18d\uc5d0 \uc99d\uc2dc \ubc18\ub4f1\uc744 \uc774\ub04c \ub9cc\ud55c \uc7ac\ub8cc\uac00 \ub418\uc9c0\ub294 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c4 \ub0a0 \ud655\uc778\ud560 \uac83\ub4e4\\n\\n\uc5b4\uc81c \uc0c1\uc2b9\uc7a5\uc5d0\uc11c \ud655\uc778\ud55c \uc9c0\ud45c\ub4e4\uc740 \ud558\ub77d\uc7a5\uc5d0\uc11c\ub3c4 \ub611\uac19\uc774 \uc720\ud6a8\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud574\uc11d\uc758 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\uae09 \u2014 \ub204\uac00 \ud314\uc558\ub294\uac00\\n\\n\uc624\ub298 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 5,748\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uc678\uad6d\uc778\uc740 619\uc5b5\uc6d0, \uae30\uad00\uc740 5,556\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n(\ub124\uc774\ubc84 \uc99d\uad8c \ud22c\uc790\uc790\ubcc4 \ub9e4\ub9e4\ub3d9\ud5a5 \uc9d1\uacc4, 2026\ub144 10\uc6d4 22\uc77c \uae30\uc900\uc785\ub2c8\ub2e4.)<br/>\\n\uae30\uad00 \uc911\uc5d0\uc11c\ub294 \uae08\uc735\ud22c\uc790(-3,771\uc5b5\uc6d0)\uc640 \ud22c\uc2e0(-3,073\uc5b5\uc6d0)\uc758 \ub9e4\ub3c4\uac00 \ucef8\uace0, \uc5f0\uae30\uae08\uc740 1,161\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\uc81c\uc640 \ubc18\ub300\ub85c \uc624\ub298\uc740 \uae30\uad00\uc758 \ub9e4\ub3c4\uac00 \uc9c0\uc218\ub97c \ub04c\uc5b4\ub0b4\ub838\uace0, \uac1c\uc778\uc774 \ub9e4\ubb3c\uc744 \ubc1b\uc544\ub0b8 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub099\ud3ed\uc758 \ubd84\ud3ec \u2014 \uc77c\ubd80 \uc885\ubaa9\uc778\uac00, \uc2dc\uc7a5 \uc804\uccb4\uc778\uac00\\n\\n\uc624\ub298 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc0c1\uc2b9 \uc885\ubaa9\uc774 174\uac1c\uc5d0 \uadf8\uce5c \ubc18\uba74 \ud558\ub77d \uc885\ubaa9\uc740 709\uac1c\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n([\uc11c\uc6b8\uc2e0\ubb38 \ubcf4\ub3c4](https://www.seoul.co.kr/news/economy/securities/2026/10/22/20261022500246)\ub97c \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.)<br/>\\n\uc2dc\uac00\ucd1d\uc561 \uc0c1\uc704 \uc885\ubaa9 \ub300\ubd80\ubd84\uc774 \uc57d\uc138\uc600\uace0, LG\uc5d0\ub108\uc9c0\uc194\ub8e8\uc158(-5.22%), \uc0bc\uc131\ubc14\uc774\uc624\ub85c\uc9c1\uc2a4(-3.95%), \ud604\ub300\ucc28(-2.58%) \ub4f1 \uc5c5\uc885\uc744 \uac00\ub9ac\uc9c0 \uc54a\uace0 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc5c5\uc885\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uc2dc\uc7a5 \uc804\ubc18\uc758 \ud22c\uc790\uc2ec\ub9ac\uac00 \uc704\ucd95\ub41c \ub0a0\uc774\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uac70\ub798\ub300\uae08\\n\\n\uc624\ub298 \ucf54\uc2a4\ud53c \uac70\ub798\ub300\uae08\uc740 13\uc8707002\uc5b5\uc6d0 \uc218\uc900\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c0\uba74\uc11c \uac70\ub798\ub300\uae08\ub3c4 \ud568\uaed8 \ub298\uc5c8\ub2e4\uba74, \ub9e4\ub3c4 \ubb3c\ub7c9\uc774 \uc2e4\uc81c\ub85c \uc3df\uc544\uc838 \ub098\uc654\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc744 \uc2dc\ub3c4\ud558\ub294 \uad6c\uac04\uc5d0\uc11c \uac70\ub798\ub300\uae08\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.6\uc6d0\uc73c\ub85c 5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d\uacfc \ud658\uc728 \ud558\ub77d(\uc6d0\ud654 \uac15\uc138)\uc774 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub09c \uac83\uc740, \uc624\ub298\uc758 \ud558\ub77d\uc774 \uc678\uad6d\uc778 \uc790\uae08 \uc774\ud0c8\ubcf4\ub2e4\ub294 \uad6d\ub0b4 \uc218\uae09\uacfc \uc2ec\ub9ac\uc5d0 \uae30\uc778\ud588\ub2e4\ub294 \ud574\uc11d\uc5d0 \ud798\uc744 \uc2e3\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\uc9c0\uc218\uac00 \ud06c\uac8c \ub5a8\uc5b4\uc9c4 \ub0a0\uc77c\uc218\ub85d \ub9c8\uac10 \uc218\uce58 \ud558\ub098\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc6d0\uc778\uc744 \ubd84\ud574\ud574 \ubcf4\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc624\ub298\ucc98\ub7fc \ud574\uc678 \uc2dc\uc7a5\uacfc \uad6d\ub0b4 \uc2dc\uc7a5\uc774 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778 \ub0a0\uc740, \uad6d\ub0b4 \uace0\uc720\uc758 \uc694\uc778\uc774 \ubb34\uc5c7\uc778\uc9c0 \ub274\uc2a4\uc640 \uc218\uae09\uc744 \ub300\uc870\ud574 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \ud654\uba74\uc5d0\uc11c\ub294 \uae30\uad00 \uc138\ubd80 \uc8fc\uccb4(\uae08\uc735\ud22c\uc790\xb7\ud22c\uc2e0\xb7\uc5f0\uae30\uae08 \ub4f1)\ubcc4\ub85c \ub9e4\ub9e4 \ubc29\ud5a5\uc774 \uc5c7\uac08\ub9ac\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc758 \uc6d0\uc778\uc774 \ub2e8\ubc1c\uc131 \uc218\uae09 \uacf5\ubc31\uc778\uc9c0, \uc2e4\uc801\xb7\uc815\ucc45 \ub4f1 \ud380\ub354\uba58\ud138 \uc694\uc778\uc778\uc9c0\ub97c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc774\ud6c4\uc758 \ud750\ub984\uc744 \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc5b4\uc81c\uc758 \uc0c1\uc2b9\uacfc \uc624\ub298\uc758 \ud558\ub77d\uc740 \uac19\uc740 \uc2dc\uc7a5\uc758 \ub2e4\ub978 \uc5bc\uad74\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ub4f1\ub77d \uc790\uccb4\ubcf4\ub2e4 \uc218\uae09, \ub099\ud3ed\uc758 \ubd84\ud3ec, \uac70\ub798\ub300\uae08, \ud658\uc728\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\ub294 \uc2b5\uad00\uc774 \ubcc0\ub3d9\uc131 \uc7a5\uc138\uc5d0\uc11c \uc2dc\uc7a5\uc758 \ud750\ub984\uc744 \uc77d\ub294 \uae30\ubcf8\uae30\uac00 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExanZuZzl0cmFhanF3Z290c3F3YjdrYjJsa2hvODVmejAzMm45aHZiaiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/MEq4za8poCEOfdY5Pr/giphy.gif\\" alt=\\"Market data\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"pension-tax-credit-2026","metadata":{"permalink":"/blog/en/finance/pension-tax-credit-2026","source":"@site/finance/2026-10-22-pension-tax-credit-2026/index.mdx","title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"pension","permalink":"/blog/en/finance/tags/pension"},{"inline":true,"label":"tax","permalink":"/blog/en/finance/tags/tax"}],"readingTime":2.73,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"pension-tax-credit-2026","title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","authors":["way"],"tags":["finance","pension","tax"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 3.52% \uae09\ub77d \u2014 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc2dc\uc7a5, \ud558\ub77d\uc7a5\uc5d0\uc11c \ud655\uc778\ud560 \uac83\ub4e4","permalink":"/blog/en/finance/kospi-plunge-oct22"},"nextItem":{"title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","permalink":"/blog/en/finance/semiconductor-industry-structure"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uc5f0\ub9d0\uc774 \ub2e4\uac00\uc624\ub294 \uc2dc\uc810\uc5d0 \ub9de\ucdb0, \uc5f0\uae08\uc800\ucd95\uacfc IRP\uc758 \uc138\uc561\uacf5\uc81c \uad6c\uc870\ub97c 2026\ub144 \uae30\uc900\uc73c\ub85c \uc815\ub9ac\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc808\uc138\ub97c \uad8c\uc720\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c, \uc81c\ub3c4\ub97c \uc774\ud574\ud558\uae30 \uc704\ud55c \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc65c \uc5f0\ub9d0\uc5d0 \uc5f0\uae08 \uc774\uc57c\uae30\uac00 \ub098\uc624\ub294\uac00\\n\\n\uc5f0\uae08\uc800\ucd95\uacfc IRP(\uac1c\uc778\ud615 \ud1f4\uc9c1\uc5f0\uae08)\uc5d0 \ub123\uc740 \ub3c8\uc740 \uc77c\uc815 \ud55c\ub3c4 \uc548\uc5d0\uc11c \uc138\uc561\uacf5\uc81c\ub97c \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138\uc561\uacf5\uc81c\ub294 1\uc6d4\ubd80\ud130 12\uc6d4\uae4c\uc9c0 \ub0a9\uc785\ud55c \uae08\uc561\uc744 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ub418\ubbc0\ub85c, \uc5f0\ub9d0\uc774 \ub418\uba74 \uc62c\ud574 \ub0a9\uc785\uc561\uc744 \uc810\uac80\ud558\ub294 \uc2dc\uae30\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\ud55c\ub3c4\uc640 \uacf5\uc81c\uc728\uc744 \uc815\ud655\ud788 \uc54c\uc544\uc57c \\"\uc5bc\ub9c8\ub97c \ub354 \ub123\uc5b4\uc57c \ud558\ub294\uc9c0\\"\uac00 \uc544\ub2c8\ub77c \\"\uc5bc\ub9c8\uae4c\uc9c0\uac00 \uc758\ubbf8 \uc788\ub294\uc9c0\\"\ub97c \ud310\ub2e8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3Y4N3MweGZ4djhmZmRkbTg5cjhyNWI3Y3d2bWJnNWp2bnU4d3lsbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3oriO2rfuppV6GkC5O/giphy.gif\\" alt=\\"Savings\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc138\uc561\uacf5\uc81c\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n#### \ud55c\ub3c4 \u2014 600\ub9cc\uc6d0\uacfc 900\ub9cc\uc6d0\\n\\n\uc5f0\uae08\uc800\ucd95\uc758 \uc138\uc561\uacf5\uc81c \ub300\uc0c1 \ub0a9\uc785\ud55c\ub3c4\ub294 \uc5f0 600\ub9cc\uc6d0\uc785\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc5d0 IRP \ub4f1 \ud1f4\uc9c1\uc5f0\uae08\uacc4\uc88c\uc758 \ubcf8\uc778 \ucd94\uac00 \ub0a9\uc785\uc561\uc744 \ud569\uce58\uba74 \uc5f0 900\ub9cc\uc6d0\uae4c\uc9c0 \uc138\uc561\uacf5\uc81c \ub300\uc0c1\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc989, \uc5f0\uae08\uc800\ucd95\uc5d0 600\ub9cc\uc6d0, IRP\uc5d0 300\ub9cc\uc6d0\uc744 \ub123\uc73c\uba74 \ud569\uc0b0 900\ub9cc\uc6d0 \uc804\uc561\uc774 \uacf5\uc81c \ub300\uc0c1\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc5f0\uae08\uc800\ucd95\uc5d0\ub9cc 900\ub9cc\uc6d0\uc744 \ub123\uc73c\uba74 600\ub9cc\uc6d0\uae4c\uc9c0\ub9cc \uacf5\uc81c \ub300\uc0c1\uc774 \ub418\ubbc0\ub85c, \uad6c\uc870\ub97c \uc54c\uace0 \ub098\ub204\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ucc38\uace0\ub85c \uc5f0\uae08\uacc4\uc88c\uc5d0 \ub123\uc744 \uc218 \uc788\ub294 \uae08\uc561 \uc790\uccb4\uc758 \ud55c\ub3c4(\ub0a9\uc785\ud55c\ub3c4)\ub294 \uc5f0 1,800\ub9cc\uc6d0\uc73c\ub85c \ubcc4\ub3c4\uc774\uba70, \uc804\uc561\uc774 \uacf5\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n#### \uacf5\uc81c\uc728 \u2014 16.5%\uc640 13.2%\\n\\n\uc138\uc561\uacf5\uc81c\uc728\uc740 \uc18c\ub4dd \uad6c\uac04\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uadfc\ub85c\uc18c\ub4dd\ub9cc \uc788\ub294 \uacbd\uc6b0 \ucd1d\uae09\uc5ec 5,500\ub9cc\uc6d0 \uc774\ud558\uc774\uba74 16.5%, \ucd08\uacfc\uc774\uba74 13.2%\uc785\ub2c8\ub2e4.<br/>\\n(\uc885\ud569\uc18c\ub4dd\uae08\uc561 \uae30\uc900\uc73c\ub85c\ub294 4,500\ub9cc\uc6d0\uc774 \uae30\uc900\uc120\uc774\uba70, \uc9c0\ubc29\uc18c\ub4dd\uc138\ub97c \ud3ec\ud568\ud55c \uc218\uce58\uc785\ub2c8\ub2e4.)<br/>\\n\uacc4\uc0b0\uc0c1 \ucd5c\ub300 \uc808\uc138\uc561\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \uacf5\uc81c \ub300\uc0c1 \ub0a9\uc785\uc561 | \ucd1d\uae09\uc5ec 5,500\ub9cc\uc6d0 \uc774\ud558 (16.5%) | \ucd1d\uae09\uc5ec 5,500\ub9cc\uc6d0 \ucd08\uacfc (13.2%) |\\n|---|---|---|\\n| 600\ub9cc\uc6d0 | 99\ub9cc\uc6d0 | 79\ub9cc2\ucc9c\uc6d0 |\\n| 900\ub9cc\uc6d0 | 148\ub9cc5\ucc9c\uc6d0 | 118\ub9cc8\ucc9c\uc6d0 |\\n\\n### \uacc4\uc0b0 \uc804\uc5d0 \ud655\uc778\ud560 \uac83\ub4e4\\n\\n#### \uacb0\uc815\uc138\uc561\uc758 \ud55c\ub3c4\\n\\n\uc704 \ud45c\uc758 \uae08\uc561\uc740 \\"\uacc4\uc0b0\uc0c1 \ucd5c\ub300\\"\uc785\ub2c8\ub2e4.<br/>\\n\uc138\uc561\uacf5\uc81c\ub294 \ub0bc \uc138\uae08(\uacb0\uc815\uc138\uc561)\uc774 \uc788\uc5b4\uc57c \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uc815\uc138\uc561\uc774 \uc801\uc73c\uba74 \ud55c\ub3c4\ub9cc\ud07c \ub123\uc5b4\ub3c4 \uacc4\uc0b0\ub41c \uae08\uc561\uc744 \uc804\ubd80 \ub3cc\ub824\ubc1b\uc9c0 \ubabb\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\uc138\uccad \uc5f0\ub9d0\uc815\uc0b0 \ubbf8\ub9ac\ubcf4\uae30\ub85c \uc608\uc0c1 \uc138\uc561\uc744 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc911\ub3c4\ud574\uc9c0\uc758 \uc138\uae08\\n\\n\uc138\uc561\uacf5\uc81c\ub97c \ubc1b\uc740 \ub3c8\uc744 \uc5f0\uae08\uc774 \uc544\ub2cc \ubc29\uc2dd\uc73c\ub85c \uc911\ub3c4\uc5d0 \ucc3e\uc73c\uba74, \uacf5\uc81c\ubc1b\uc740 \uc6d0\uae08\uacfc \uc218\uc775\uc5d0 16.5%\uc758 \uae30\ud0c0\uc18c\ub4dd\uc138\uac00 \ubd80\uacfc\ub429\ub2c8\ub2e4.<br/>\\n\uacf5\uc81c\uc728\uc774 13.2%\uc778 \uad6c\uac04\uc5d0 \ud574\ub2f9\ud558\ub294 \ubd84\uc740 \uc624\ud788\ub824 \uc190\ud574\uac00 \ub420 \uc218 \uc788\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n3\ub144 \uc548\uc5d0 \uc4f8 \uac00\ub2a5\uc131\uc774 \uc788\ub294 \ub3c8\uc740 \uc5f0\uae08\uc800\ucd95\ubcf4\ub2e4 \uc608\uae08\uc774\ub098 \ud30c\ud0b9\ud1b5\uc7a5 \ub4f1 \ubcc4\ub3c4 \uc790\uae08\uc73c\ub85c \ubd84\ub9ac\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uc218\ub839 \ub2e8\uacc4\uc758 \uae30\uc900\\n\\n\uc5f0\uae08\uc73c\ub85c \ubc1b\uc744 \ub54c\ub294 \uc5f0\uae08\uc18c\ub4dd\uc138\uac00 \uc801\uc6a9\ub418\uba70, \uc5f0\uac04 \uc0ac\uc801\uc5f0\uae08 \uc218\ub839\uc561 1,500\ub9cc\uc6d0\uc774\ub77c\ub294 \uae30\uc900\ub3c4 \ud568\uaed8 \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub0a9\uc785 \ub2e8\uacc4\uc758 \uc808\uc138\ub9cc \ubcf4\uace0 \uc218\ub839 \ub2e8\uacc4\uc758 \uc138\uae08\uc744 \ub193\uce58\uba74 \uc804\uccb4 \uadf8\ub9bc\uc774 \uc5b4\uae0b\ub0a9\ub2c8\ub2e4.<br/>\\n\ub9cc\uae30\uac00 \ub41c ISA \uc794\uc561\uc744 \uc5f0\uae08\uacc4\uc88c\ub85c \uc62e\uae30\uba74 \uc62e\uae34 \uae08\uc561\uc758 10%, \ucd5c\ub300 300\ub9cc\uc6d0\uae4c\uc9c0 \uacf5\uc81c \ud55c\ub3c4\uac00 \ucd94\uac00\ub85c \ub298\uc5b4\ub098\ub294 \ud2b9\ub840\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\uc5f0\ub9d0\uc815\uc0b0 \uc2dc\uc98c\uc774 \uc624\uae30 \uc804\uc5d0 \uc62c\ud574 \uc5f0\uae08\uc800\ucd95\uacfc IRP\uc5d0 \uc2e4\uc81c\ub85c \ub0a9\uc785\ud55c \uae08\uc561\uc744 \ud569\uc0b0\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n600\ub9cc\uc6d0\uacfc 900\ub9cc\uc6d0\uc774\ub77c\ub294 \ub450 \uac1c\uc758 \ud55c\ub3c4\uc120\uc5d0\uc11c \ud604\uc7ac \uc704\uce58\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ubcf8\uc778\uc758 \ucd1d\uae09\uc5ec \uad6c\uac04\uc5d0 \ub9de\ub294 \uacf5\uc81c\uc728\ub85c \uacc4\uc0b0\uc0c1 \uc808\uc138\uc561\uc744 \uad6c\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n\uacb0\uc815\uc138\uc561\uc774 \ucda9\ubd84\ud55c\uc9c0, \uc911\ub3c4\uc5d0 \ucc3e\uc744 \uac00\ub2a5\uc131\uc740 \uc5c6\ub294\uc9c0\ub97c \ud568\uaed8 \uc810\uac80\ud569\ub2c8\ub2e4.<br/>\\n\uc138\uc81c \ud61c\ud0dd\uc740 \ub9e4\ub144 \uc870\uae08\uc529 \ubc14\ub014 \uc218 \uc788\uc73c\ubbc0\ub85c, \ucd5c\uc885 \ud310\ub2e8 \uc804\uc5d0\ub294 \uad6d\uc138\uccad \uc548\ub0b4\ub098 \uae08\uc735\ud68c\uc0ac \uacf5\uc9c0\ub97c \uc6d0\ubb38\uc73c\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc5f0\uae08 \uc138\uc561\uacf5\uc81c\ub294 \\"\ub9ce\uc774 \ub123\uc744\uc218\ub85d \uc88b\uc740 \uc81c\ub3c4\\"\uac00 \uc544\ub2c8\ub77c \\"\ud55c\ub3c4\uc640 \uc870\uac74\uc744 \uc54c\uace0 \uc4f0\ub294 \uc81c\ub3c4\\"\uc785\ub2c8\ub2e4.<br/>\\n600\ub9cc\uc6d0\uacfc 900\ub9cc\uc6d0, 16.5%\uc640 13.2%\ub77c\ub294 \uc22b\uc790 \ub124 \uac1c\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc5f0\ub9d0 \uc810\uac80\uc758 \uae30\uc900\uc774 \uc12d\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3Y4N3MweGZ4djhmZmRkbTg5cjhyNWI3Y3d2bWJnNWp2bnU4d3lsbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/KoWFceykJC0NNjucLC/giphy.gif\\" alt=\\"Piggy bank\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"semiconductor-industry-structure","metadata":{"permalink":"/blog/en/finance/semiconductor-industry-structure","source":"@site/finance/2026-10-22-semiconductor-industry-structure/index.mdx","title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"sector","permalink":"/blog/en/finance/tags/sector"},{"inline":true,"label":"semiconductor","permalink":"/blog/en/finance/tags/semiconductor"}],"readingTime":3.16,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"semiconductor-industry-structure","title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","authors":["way"],"tags":["finance","sector","semiconductor"]},"unlisted":false,"prevItem":{"title":"\uc5f0\uae08\uc800\ucd95\uacfc IRP \uc138\uc561\uacf5\uc81c \u2014 2026\ub144 \uae30\uc900 \ud55c\ub3c4\uc640 \uacc4\uc0b0\ubc95","permalink":"/blog/en/finance/pension-tax-credit-2026"},"nextItem":{"title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","permalink":"/blog/en/finance/usd-krw-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uc624\ub298 \uc2dc\uc7a5\uc758 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud55c \ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870\uc640, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \uc774 \uc5c5\uc885\uc744 \ubcfc \ub54c \ud655\uc778\ud558\ub294 \uc9c0\ud45c\ub4e4\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\xb7\ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c, \uc0b0\uc5c5\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uad50\uc721 \ubaa9\uc801\uc758 \ud574\uc124\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc65c \ubc18\ub3c4\uccb4\uac00 \uc9c0\uc218\ub97c \uc6c0\uc9c1\uc774\ub294\uac00\\n\\n\uad6d\ub0b4 \uc99d\uc2dc\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc758 \ube44\uc911\uc740 \ub9e4\uc6b0 \ud07d\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ucf54\uc2a4\ud53c\uac00 3.52% \ud558\ub77d\ud55c \ub0a0\uc5d0\ub3c4 \uc0bc\uc131\uc804\uc790(-4.03%)\uc640 SK\ud558\uc774\ub2c9\uc2a4(-5.49%) \ub450 \uc885\ubaa9\uc758 \ud558\ub77d\uc774 \uc9c0\uc218 \ub099\ud3ed\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.<br/>\\n([\uc544\uc8fc\uacbd\uc81c \ubcf4\ub3c4](https://www.ajunews.com/view/20261022154721705)\ub97c \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4.)<br/>\\n\uc9c0\uc218\ub97c \uc6c0\uc9c1\uc774\ub294 \uc5c5\uc885\uc744 \uc774\ud574\ud558\ub824\uba74, \uadf8 \uc5c5\uc885\uc774 \uc5b4\ub5a4 \uad6c\uc870\ub85c \ub3c8\uc744 \ubc84\ub294\uc9c0\ub97c \uba3c\uc800 \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY3U4NWZjMDIwN3BldXQ1c3hiM2V3Z2ExZHdhbmt3Z2s3ano5OWFsMSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/R2eoW62p8mcKGWUKSk/giphy.gif\\" alt=\\"Chip\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \ud070 \uadf8\ub9bc\\n\\n#### \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4\\n\\n\ubc18\ub3c4\uccb4\ub294 \ud06c\uac8c \uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4(\ube44\uba54\ubaa8\ub9ac)\ub85c \ub098\ub269\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4\ub294 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \uce69\uc73c\ub85c, D\ub7a8\uacfc \ub0b8\ub4dc\ud50c\ub798\uc2dc\uac00 \ub300\ud45c\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4\ub294 \uc5f0\uc0b0\xb7\uc81c\uc5b4\ub97c \ub2f4\ub2f9\ud558\ub294 \uce69\uc73c\ub85c, CPU, GPU, \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ud504\ub85c\uc138\uc11c \ub4f1\uc774 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \uae30\uc5c5\uc774 \uac15\ud55c \ubd84\uc57c\ub294 \uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4\uc774\uba70, \uc138\uacc4 \uc2dc\uc7a5 \uc810\uc720\uc728 \uae30\uc900\uc73c\ub85c D\ub7a8\uacfc \ub0b8\ub4dc \ubaa8\ub450 \uc0c1\uc704\uad8c\uc744 \ucc28\uc9c0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc\uc5d0\ub294 AI \uc11c\ubc84\uc6a9 \uace0\ub300\uc5ed\ud3ed \uba54\ubaa8\ub9ac(HBM)\ucc98\ub7fc \uba54\ubaa8\ub9ac \uc548\uc5d0\uc11c\ub3c4 \uace0\ubd80\uac00 \uc81c\ud488\uc758 \ube44\uc911\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ubc38\ub958\uccb4\uc778 \u2014 \uc124\uacc4, \uc0dd\uc0b0, \uc7a5\ube44, \uc18c\uc7ac\\n\\n\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc740 \uc124\uacc4, \uc0dd\uc0b0, \uc7a5\ube44, \uc18c\uc7ac\ub85c \uc774\uc5b4\uc9c0\ub294 \uae34 \ubc38\ub958\uccb4\uc778\uc744 \uac00\uc9d1\ub2c8\ub2e4.<br/>\\n\uc124\uacc4\ub9cc \ud558\ub294 \ud68c\uc0ac\ub97c \ud339\ub9ac\uc2a4, \uc0dd\uc0b0\ub9cc \uc704\ud0c1\ubc1b\uc544 \ud558\ub294 \ud68c\uc0ac\ub97c \ud30c\uc6b4\ub4dc\ub9ac\ub77c\uace0 \ud569\ub2c8\ub2e4.<br/>\\n\uc124\uacc4\ubd80\ud130 \uc0dd\uc0b0\uae4c\uc9c0 \ubaa8\ub450 \ud558\ub294 \ud68c\uc0ac\ub294 \uc885\ud569\ubc18\ub3c4\uccb4\uae30\uc5c5(IDM)\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.<br/>\\n\uc5ec\uae30\uc5d0 \ub178\uad11\xb7\uc2dd\uac01 \uc7a5\ube44\ub97c \ub9cc\ub4dc\ub294 \uc7a5\ube44 \uae30\uc5c5\uacfc, \uc6e8\uc774\ud37c\xb7\ud2b9\uc218\uac00\uc2a4\ub97c \uacf5\uae09\ud558\ub294 \uc18c\uc7ac \uae30\uc5c5\uc774 \uc0dd\ud0dc\uacc4\ub97c \uc774\ub8f9\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4\uc5d0\uc11c\ub294 \uc18c\ubd80\uc7a5(\uc18c\uc7ac\xb7\ubd80\ud488\xb7\uc7a5\ube44) \uae30\uc5c5\ub4e4\uc774 \ucf54\uc2a4\ub2e5\uc744 \uc911\uc2ec\uc73c\ub85c \ud3ec\uc9c4\ud574 \uc788\uc5b4, \uba54\ubaa8\ub9ac \uc5c5\ud669\uc774 \uc6c0\uc9c1\uc774\uba74 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc0ac\uc774\ud074 \uc0b0\uc5c5\uc758 \ud2b9\uc131\\n\\n\ubc18\ub3c4\uccb4\ub294 \ub300\ud45c\uc801\uc778 \uc0ac\uc774\ud074 \uc0b0\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc218\uc694\uac00 \ub298\uba74 \uac00\uaca9\uc774 \uc624\ub974\uace0(\uc5c5\uc0ac\uc774\ud074), \uacf5\uae09\uc774 \uacfc\uc789\ub418\uba74 \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c0\ub294(\ub2e4\uc6b4\uc0ac\uc774\ud074) \ud328\ud134\uc744 \ubc18\ubcf5\ud569\ub2c8\ub2e4.<br/>\\n\uac00\uaca9\uc744 \uc6c0\uc9c1\uc774\ub294 \ud575\uc2ec \ubcc0\uc218\ub294 \uc7ac\uace0\uc640 \uc218\uc694, \uadf8\ub9ac\uace0 \uacf5\uae09 \uc5c5\uccb4\ub4e4\uc758 \uc124\ube44\ud22c\uc790(CAPEX)\uc785\ub2c8\ub2e4.<br/>\\n\uc5c5\uc0ac\uc774\ud074\uc5d0\uc11c\ub294 \uc99d\uc124 \ud22c\uc790\uac00 \ub298\uace0, \ub2e4\uc6b4\uc0ac\uc774\ud074\uc5d0\uc11c\ub294 \uac10\uc0b0\uacfc \ud22c\uc790 \ucd95\uc18c\uac00 \ub098\ud0c0\ub0a9\ub2c8\ub2e4.<br/>\\n\uc774\ub7f0 \uc0ac\uc774\ud074 \ub54c\ubb38\uc5d0 \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 \uc2e4\uc801\uc740 \ubd84\uae30\ub9c8\ub2e4 \ud06c\uac8c \ucd9c\ub801\uc774\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4\\n\\n#### \uc7ac\uace0\uc640 \uac00\uaca9(ASP)\\n\\n\uba54\ubaa8\ub9ac \uc2e4\uc801\uc744 \ubcfc \ub54c \uac00\uc7a5 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uac83\uc740 \uc7ac\uace0 \uc218\uc900\uacfc \ud3c9\uade0\ud310\ub9e4\ub2e8\uac00(ASP)\uc785\ub2c8\ub2e4.<br/>\\n\uc7ac\uace0\uac00 \uc904\uace0 ASP\uac00 \uc624\ub974\uba74 \uc5c5\ud669 \uac1c\uc120\uc758 \uc2e0\ud638\ub85c \ud574\uc11d\ud558\uace0, \ubc18\ub300\uba74 \uc218\uc694 \ub454\ud654\ub97c \uc758\uc2ec\ud569\ub2c8\ub2e4.<br/>\\n\ubd84\uae30 \uc2e4\uc801 \ubc1c\ud45c \ub54c \uacf5\uac1c\ub418\ub294 \uc7ac\uace0\uc790\uc0b0\uc758 \uc99d\uac10\uc740 \ub2e4\uc74c \ubd84\uae30 \uac00\uaca9 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n#### \uc124\ube44\ud22c\uc790(CAPEX) \uac00\uc774\ub358\uc2a4\\n\\n\uae30\uc5c5\uc774 \uc81c\uc2dc\ud558\ub294 \ub0b4\ub144 \uc124\ube44\ud22c\uc790 \uacc4\ud68d\ub3c4 \uc911\uc694\ud55c \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\nCAPEX\uac00 \ub298\uba74 \uacf5\uae09 \uc99d\uac00\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5b4 \uac00\uaca9\uc5d0 \ubd80\ub2f4\uc774 \ub418\uace0, \uc904\uba74 \uacf5\uae09 \uc870\uc808\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc5b4\uc81c \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c \uba54\ud0c0\uac00 \ud638\uc2e4\uc801\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ub0b4\ub144 \uc124\ube44\ud22c\uc790 \uac00\uc774\ub358\uc2a4\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc544 \ud22c\uc790\uc2ec\ub9ac\uac00 \uc704\ucd95\ub41c \uac83\ub3c4 \uac19\uc740 \ub9e5\ub77d\uc785\ub2c8\ub2e4.<br/>\\n\ube45\ud14c\ud06c\uc758 CAPEX\ub294 AI \uc11c\ubc84 \uc218\uc694, \uc989 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4 \uc218\uc694\ub85c \uc9c1\uacb0\ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \uc790\ud68c\uc0ac \uc774\uc288\uc640 \uc8fc\uc8fc \uac00\uce58\\n\\n\uc624\ub298 SK\ud558\uc774\ub2c9\uc2a4\uc5d0\ub294 \ubbf8\uad6d \uc790\ud68c\uc0ac \uc194\ub9ac\ub2e4\uc784\uc758 \uc0c1\uc7a5 \ucd94\uc9c4\uc744 \ub458\ub7ec\uc2fc \uc911\ubcf5\uc0c1\uc7a5 \ub17c\ub780\uc774 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\ud68c\uc0ac \uc0c1\uc7a5\uc774 \uc65c \ubaa8\ud68c\uc0ac\uc5d0 \ubd80\ub2f4\uc774 \ub418\ub294\uc9c0 \uc774\ud574\ud558\ub824\uba74 \uc8fc\uc8fc \uac00\uce58\uc758 \uad00\uc810\uc5d0\uc11c \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc790\ud68c\uc0ac\uc758 \uac00\uce58\uac00 \ubcc4\ub3c4\ub85c \uc0c1\uc7a5\ub418\uba70 \uc2dc\uc7a5\uc5d0\uc11c \uc7ac\ud3c9\uac00\ub418\uba74, \uae30\uc874 \ubaa8\ud68c\uc0ac \uc8fc\uc8fc\uac00 \ubcf4\uc720\ud55c \uc9c0\ubd84 \uac00\uce58\uc5d0 \ub300\ud55c \ud560\uc778 \uc6b0\ub824\uac00 \uc0dd\uae30\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub7f0 \uc774\uc288\uac00 \ub098\uc62c \ub54c\ub294 \uacf5\uc2dc\ub41c \uc0c1\uc7a5 \uad6c\uc870\uc640 \uc9c0\ubd84 \uad00\uacc4\ub97c \uc6d0\ubb38\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc774 \uae30\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\ubc18\ub3c4\uccb4 \ub274\uc2a4\ub97c \ubcfc \ub54c\ub294 \ud5e4\ub4dc\ub77c\uc778\ubcf4\ub2e4 \uc218\uce58\uc758 \ucd9c\ucc98\ub97c \uba3c\uc800 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\nASP, \uc7ac\uace0, \uac00\ub3d9\ub960 \uac19\uc740 \uc9c0\ud45c\ub294 \ubd84\uae30 \ubcf4\uace0\uc11c\uc640 \uc2e4\uc801 \ubc1c\ud45c \uc790\ub8cc\uc5d0 \uc6d0\ubb38\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nCAPEX \uac00\uc774\ub358\uc2a4\ub294 \uae30\uc5c5 IR \uc790\ub8cc\ub098 \ucee8\ud37c\ub7f0\uc2a4\ucf5c \uae30\ub85d\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\ud68c\uc0ac \uc0c1\uc7a5 \uac19\uc740 \uc9c0\ubc30\uad6c\uc870 \uc774\uc288\ub294 \uc804\uc790\uacf5\uc2dc(DART)\uc758 \uacf5\uc2dc \uc6d0\ubb38\uc744 \uc77d\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885 \uc804\uccb4\uc758 \ud750\ub984\uc744 \ubcfc \ub54c\ub294 \uac1c\ubcc4 \uae30\uc5c5 \ub274\uc2a4\uc640 \ud568\uaed8 \uba54\ubaa8\ub9ac \uac00\uaca9 \ub3d9\ud5a5, \ube45\ud14c\ud06c\uc758 \uc124\ube44\ud22c\uc790 \uacc4\ud68d\uc744 \uacb9\uccd0\uc11c \ubd05\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubc18\ub3c4\uccb4\ub294 \uad6c\uc870\ub97c \uc54c\uba74 \ub274\uc2a4\uac00 \uc77d\ud788\uace0, \uad6c\uc870\ub97c \ubaa8\ub974\uba74 \ub4f1\ub77d\ub9cc \ubcf4\uc774\ub294 \uc5c5\uc885\uc785\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4\uc758 \uad6c\ubd84, \ubc38\ub958\uccb4\uc778, \uc0ac\uc774\ud074\uc758 \uad00\uc810\uc744 \uac16\ucdb0 \ub450\uba74 \uc2e4\uc801 \uc2dc\uc98c\uc758 \uc22b\uc790\ub4e4\uc744 \ucc28\ubd84\ud788 \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY3U4NWZjMDIwN3BldXQ1c3hiM2V3Z2ExZHdhbmt3Z2s3ano5OWFsMSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/ihM636Z71DgV3ZKZiP/giphy.gif\\" alt=\\"Technology\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"usd-krw-guide","metadata":{"permalink":"/blog/en/finance/usd-krw-guide","source":"@site/finance/2026-10-22-usd-krw-guide/index.mdx","title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"fx","permalink":"/blog/en/finance/tags/fx"},{"inline":true,"label":"exchange-rate","permalink":"/blog/en/finance/tags/exchange-rate"}],"readingTime":3.03,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"usd-krw-guide","title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","authors":["way"],"tags":["finance","fx","exchange-rate"]},"unlisted":false,"prevItem":{"title":"\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc758 \uad6c\uc870 \u2014 \uba54\ubaa8\ub9ac\uc640 \uc2dc\uc2a4\ud15c\ubc18\ub3c4\uccb4, \uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ud558\ub294 \uac83\ub4e4","permalink":"/blog/en/finance/semiconductor-industry-structure"},"nextItem":{"title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","permalink":"/blog/en/finance/diversification-rebalancing"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud55c \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc758 \uc6c0\uc9c1\uc784\uc744 \uacc4\uae30\ub85c, \ud658\uc728\uc744 \uc77d\ub294 \uae30\ubcf8\uc801\uc778 \ubc29\ubc95\uc744 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd \u2014 \uc624\ub298\uc758 \ud658\uc728\\n\\n2026\ub144 10\uc6d4 22\uc77c, \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.6\uc6d0\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 1.4\uc6d0, 0.11% \ud558\ub77d\ud55c \uc218\uce58\ub85c, 5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\uc138\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n(KIS MTS \uc2dc\uc7a5 \ub370\uc774\ud130 \uae30\uc900\uc785\ub2c8\ub2e4.)<br/>\\n\ud658\uc728\uc740 \uc8fc\uc2dd\ub9cc\ud07c \uc790\uc8fc \uc5b8\uae09\ub418\uc9c0\ub9cc, \uc22b\uc790\uc758 \ubc29\ud5a5\uc744 \ubc18\ub300\ub85c \uc77d\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc744 \uacc4\uae30\ub85c \ud658\uc728 \ud45c\uc2dc\ubc95\uacfc \ud574\uc11d\uc758 \uae30\ubcf8\uc744 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExd3l1ZjhyMnd4Nmd4eTF0OGhycndudWNjajM4bWJlcnYydGpib2M3ciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/h0MTqLyvgG0Ss/giphy.gif\\" alt=\\"Dollar\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ud658\uc728 \uc22b\uc790\uc758 \uc77d\ub294 \ubc95\\n\\n#### \uc6d0/\ub2ec\ub7ec 1,324.6\uc6d0\uc758 \ub73b\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728 1,324.6\uc6d0\uc740 1\ub2ec\ub7ec\ub97c \uc0ac\ub294 \ub370 1,324.6\uc6d0\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc989, \ub2ec\ub7ec\uc758 \uc6d0\ud654 \uac00\uaca9\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc22b\uc790\uac00 \uc624\ub974\uba74 \ub2ec\ub7ec\uac00 \ube44\uc2f8\uc9c4 \uac83\uc774\uace0, \uc6d0\ud654\uc758 \uac00\uce58\ub294 \ub5a8\uc5b4\uc9c4 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc22b\uc790\uac00 \ub0b4\ub9ac\uba74 \ub2ec\ub7ec\uac00 \uc2f8\uc9c4 \uac83\uc774\uace0, \uc6d0\ud654\uc758 \uac00\uce58\ub294 \uc62c\ub77c\uac04 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\ucc98\ub7fc \ud658\uc728\uc774 \ud558\ub77d\ud588\ub2e4\ub294 \uac83\uc740 \uc6d0\ud654\uac00 \uac15\uc138\ub97c \ubcf4\uc600\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n#### \ud658\uc728 \uc0c1\uc2b9\uacfc \ud558\ub77d\uc758 \ud45c\ud604\\n\\n\ud658\uc728\uc774 \uc624\ub97c \ub54c\ub294 \\"\ud658\uc728 \uc0c1\uc2b9\\" \ub610\ub294 \\"\uc6d0\ud654 \uc57d\uc138(\uc6d0\ud654 \uac00\uce58 \ud558\ub77d)\\"\ub77c\uace0 \ud45c\ud604\ud569\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uc774 \ub0b4\ub9b4 \ub54c\ub294 \\"\ud658\uc728 \ud558\ub77d\\" \ub610\ub294 \\"\uc6d0\ud654 \uac15\uc138(\uc6d0\ud654 \uac00\uce58 \uc0c1\uc2b9)\\"\ub77c\uace0 \ud45c\ud604\ud569\ub2c8\ub2e4.<br/>\\n\ub274\uc2a4\uc5d0\uc11c \\"\ud658\uc728\uc774 \uc62c\ub790\ub2e4\\"\uc640 \\"\uc6d0\ud654\uac00 \uac15\uc138\ub2e4\\"\ub294 \ubc18\ub300 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a4\ubbc0\ub85c, \uc8fc\uc5b4\uac00 \ubb34\uc5c7\uc778\uc9c0 \ud655\uc778\ud558\uace0 \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \ud658\uc728\uc744 \uc6c0\uc9c1\uc774\ub294 \uc694\uc778\ub4e4\\n\\n#### \uae08\ub9ac \ucc28\uc774\\n\\n\ub450 \ub098\ub77c\uc758 \uae08\ub9ac \ucc28\uc774\uac00 \ud658\uc728\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uae08\ub9ac\uac00 \ud55c\uad6d\ubcf4\ub2e4 \ub192\uc73c\uba74 \ub2ec\ub7ec \uc790\uc0b0\uc758 \uc774\uc790 \ub9e4\ub825\uc774 \ucee4\uc838 \ub2ec\ub7ec \uc218\uc694\uac00 \ub298\uc5b4\ub0a9\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ud55c\uad6d\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c 3.00%\ub85c \ub3d9\uacb0\ud55c \uac00\uc6b4\ub370, \ubbf8\uad6d\uc758 \uae08\ub9ac \ubc29\ud5a5\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \ubc14\ub00c\uba74 \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacb0\uc815\ubb38\uc744 \ubcfc \ub54c\ub294 \uad6d\ub0b4 \uae08\ub9ac\ubfd0 \uc544\ub2c8\ub77c \ubbf8\uad6d \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uc815\ucc45 \ubc29\ud5a5\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n#### \ubb34\uc5ed\uc218\uc9c0\uc640 \uc678\uad6d\uc778 \uc790\uae08\\n\\n\uc218\ucd9c\uc774 \ub298\uba74 \ub2ec\ub7ec\uac00 \uad6d\ub0b4\ub85c \ub4e4\uc5b4\uc640 \uc6d0\ud654 \uac15\uc138 \uc694\uc778\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc218\uc785\uc774 \ub298\uac70\ub098 \ud574\uc678\ud22c\uc790\uac00 \ub298\uba74 \ub2ec\ub7ec \uc218\uc694\uac00 \ub298\uc5b4 \uc6d0\ud654 \uc57d\uc138 \uc694\uc778\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc678\uad6d\uc778 \ub9e4\ub9e4\ub3c4 \ud658\uc728\uacfc \uc5f0\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \uad6d\ub0b4 \uc8fc\uc2dd\uc744 \uc0ac\ub824\uba74 \uc6d0\ud654\ub97c \uc0ac\uc57c \ud558\ubbc0\ub85c, \uc678\uad6d\uc778 \uc21c\ub9e4\uc218\ub294 \uc6d0\ud654 \uac15\uc138\uc640 \ud568\uaed8 \ub098\ud0c0\ub098\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc9c0\uc218\uac00 3.52% \ud558\ub77d\ud588\ub294\ub370\ub3c4 \ud658\uc728\uc774 \ud558\ub77d(\uc6d0\ud654 \uac15\uc138)\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ucf54\uc2a4\ud53c\uc5d0\uc11c 619\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud55c \ub0a0\uc774\uc5c8\uc73c\ubbc0\ub85c, \uc624\ub298\uc758 \uc6d0\ud654 \uac15\uc138\ub294 \uc678\uad6d\uc778 \uc790\uae08 \uc720\uc785\ubcf4\ub2e4\ub294 \ub2e4\ub978 \uc694\uc778\uc5d0 \uae30\uc778\ud55c \uac83\uc73c\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\\n#### \ub2ec\ub7ec \uc790\uccb4\uc758 \uc6c0\uc9c1\uc784\\n\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ub2ec\ub7ec \uc790\uccb4\uc758 \uc6c0\uc9c1\uc784\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uc778\ub371\uc2a4\uac00 \uc624\ub974\uba74 \ub2ec\ub7ec\uac00 \uc8fc\uc694 \ud1b5\ud654 \ub300\ube44 \uac15\uc138\ub97c \ubcf4\uc774\ub294 \uac83\uc774\ubbc0\ub85c, \uc6d0/\ub2ec\ub7ec \ud658\uc728\ub3c4 \uc624\ub974\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\ud654\uc758 \uac15\uc138\uc778\uc9c0 \ub2ec\ub7ec\uc758 \uc57d\uc138\uc778\uc9c0\ub97c \uad6c\ubd84\ud558\ub824\uba74, \uc5d4\ud654\xb7\uc720\ub85c\ud654 \ub300\ube44 \ub2ec\ub7ec\uc758 \uc6c0\uc9c1\uc784\ub3c4 \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\\n### \uc6d0\ud654 \uac15\uc138\uc640 \uc57d\uc138\uc758 \uc591\uba74\uc131\\n\\n#### \uc6d0\ud654 \uac15\uc138\uac00 \ubc18\uac00\uc6b4 \uacbd\uc6b0\uc640 \ubd80\ub2f4\uc2a4\ub7ec\uc6b4 \uacbd\uc6b0\\n\\n\uc6d0\ud654 \uac15\uc138\ub294 \uc218\uc785 \ubb3c\uac00\ub97c \ub0ae\ucdb0 \ubb3c\uac00 \uc548\uc815\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ud574\uc678\uc5ec\ud589\uc774\ub098 \ud574\uc678\uc9c1\uad6c, \uc678\ud654 \uc790\uc0b0 \ub9e4\uc218 \uc785\uc7a5\uc5d0\uc11c\ub294 \uc720\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc218\ucd9c \uae30\uc5c5 \uc785\uc7a5\uc5d0\uc11c\ub294 \uac00\uaca9 \uacbd\uc7c1\ub825\uc774 \ub5a8\uc5b4\uc838 \ubd80\ub2f4\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ud658\uc728 \uc6c0\uc9c1\uc784\ub3c4 \uc785\uc7a5\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ubc29\ud5a5 \ud558\ub098\ub9cc\uc73c\ub85c \uc88b\uace0 \ub098\uc068\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc99d\uc2dc\uc640\uc758 \uad00\uacc4\\n\\n\uc77c\ubc18\uc801\uc73c\ub85c \uc6d0\ud654 \uac15\uc138\ub294 \uc678\uad6d\uc778 \uc790\uae08 \uc720\uc785\uacfc \ub9de\ubb3c\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc6b0\ud638\uc801\uc73c\ub85c \ud574\uc11d\ub418\uace4 \ud569\ub2c8\ub2e4.<br/>\\n\ud558\uc9c0\ub9cc \uc624\ub298\ucc98\ub7fc \uc9c0\uc218 \ud558\ub77d\uacfc \uc6d0\ud654 \uac15\uc138\uac00 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub098\uba74, \uc218\uae09\uc758 \uc8fc\uccb4\uac00 \ub2e4\ub974\ub2e4\ub294 \uc2e0\ud638\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uacfc \uc9c0\uc218\ub97c \ub530\ub85c \ubcf4\uc9c0 \uc54a\uace0 \ud568\uaed8 \ubcf4\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud55c \uc774\uc720\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\n\ud658\uc728\uc744 \ubcfc \ub54c\ub294 \uc885\uac00 \uc22b\uc790 \ud558\ub098\ubcf4\ub2e4 \ubc29\ud5a5\uacfc \uc18d\ub3c4\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n5\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ucc98\ub7fc \uac19\uc740 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\uba74, \uadf8 \ubc30\uacbd\uc774 \ubb34\uc5c7\uc778\uc9c0 \uae08\ub9ac\xb7\ubb34\uc5ed\xb7\ub2ec\ub7ec \uc778\ub371\uc2a4\uc5d0\uc11c \uc6d0\uc778\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.<br/>\\nMTS\uc758 \ud658\uc728 \ud654\uba74\uc5d0\uc11c\ub294 \uc804\uc77c \ub300\ube44 \ub4f1\ub77d\uacfc \ud568\uaed8 \uc7a5\uc911 \uace0\uc810\xb7\uc800\uc810\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc218\ucd9c\uc785 \uae30\uc5c5\uc5d0 \ud22c\uc790\ud55c\ub2e4\uba74 \uc2e4\uc801 \ubc1c\ud45c \ub54c \ud658\uc728 \ubcc0\ub3d9\uc774 \ub9e4\ucd9c\uacfc \uc774\uc775\uc5d0 \ubbf8\uce5c \uc601\ud5a5\uc744 \uc124\uba85\ud558\ub294 \ubd80\ubd84\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ud658\uc728\uc740 \uc22b\uc790\uc758 \ubc29\ud5a5\ub9cc \uc815\ud655\ud788 \uc77d\uc5b4\ub3c4 \ub274\uc2a4\uc758 \uc808\ubc18\uc740 \uc774\ud574\ub429\ub2c8\ub2e4.<br/>\\n\\"\ub204\uad6c\uc758 \uac00\uaca9\uc774 \uc62c\ub790\ub294\uac00\\"\ub97c \uba3c\uc800 \ubb3b\ub294 \uc2b5\uad00\uc774 \ud658\uc728\uc744 \uc77d\ub294 \uccab\uac78\uc74c\uc785\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjExd3l1ZjhyMnd4Nmd4eTF0OGhycndudWNjajM4bWJlcnYydGpib2M3ciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/11IXPaNTDdw2Eo/giphy.gif\\" alt=\\"Currency\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"diversification-rebalancing","metadata":{"permalink":"/blog/en/finance/diversification-rebalancing","source":"@site/finance/2026-10-21-diversification-rebalancing/index.mdx","title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"portfolio","permalink":"/blog/en/finance/tags/portfolio"},{"inline":true,"label":"basics","permalink":"/blog/en/finance/tags/basics"}],"readingTime":2.62,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"diversification-rebalancing","title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","authors":["way"],"tags":["finance","portfolio","basics"]},"unlisted":false,"prevItem":{"title":"\uc6d0/\ub2ec\ub7ec \ud658\uc728 \uc77d\ub294 \ubc95 \u2014 1,300\uc6d0\ub300 \ud658\uc728\uc774 \uc758\ubbf8\ud558\ub294 \uac83","permalink":"/blog/en/finance/usd-krw-guide"},"nextItem":{"title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","permalink":"/blog/en/finance/etf-basics"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \ud22c\uc790\uc758 \uac00\uc7a5 \uae30\ubcf8 \uc6d0\uce59\uc73c\ub85c \uaf3d\ud788\ub294 \ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ud22c\uc790\ub97c \uc2dc\uc791\ud558\uba74 \uc5b4\ub5a4 \uc885\ubaa9\uc744 \uace0\ub97c\uc9c0\uc5d0 \uba3c\uc800 \uad00\uc2ec\uc774 \uac00\uae30 \ub9c8\ub828\uc785\ub2c8\ub2e4.<br/>\\n\ud558\uc9c0\ub9cc \uc7a5\uae30\uc801\uc778 \uc131\uacfc\ub294 \uc885\ubaa9 \uc120\ud0dd\ub9cc\ud07c\uc774\ub098 \uc790\uc0b0\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\uc5b4 \ub2f4\uace0, \uadf8 \ube44\uc911\uc744 \uc5b4\ub5bb\uac8c \uc720\uc9c0\ud558\ub290\ub0d0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\uc0b0\ud22c\uc790\ub294 \ube44\uc911\uc744 \uc124\uacc4\ud558\ub294 \ubc29\ubc95\uc774\uace0, \ub9ac\ubc38\ub7f0\uc2f1\uc740 \uadf8 \ube44\uc911\uc744 \uc2dc\uac04\uc774 \uc9c0\ub098\ub3c4 \uc720\uc9c0\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \uac00\uc9c0\ub97c \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExY2l4eWJoZXp6enNmdnJyeGlibzdjNzJiaGhnaTltMzl0aHVnZ2dpdyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/PxZqQHKP3VFbkZ0EDI/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \ubd84\uc0b0\ud22c\uc790\ub780\\n\\n#### \uc790\uc0b0\uad70\uc73c\ub85c \ub098\ub204\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud569\ub2c8\ub2e4\\n\\n\ubd84\uc0b0\ud22c\uc790\ub294 \uc5ec\ub7ec \uc885\ubaa9\uc5d0 \ub098\ub204\uc5b4 \ub2f4\ub294 \uac83\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd, \ucc44\uad8c, \ud604\uae08\uc131 \uc790\uc0b0\ucc98\ub7fc \uc131\uaca9\uc774 \ub2e4\ub978 \uc790\uc0b0\uad70\uc5d0 \ub098\ub204\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uc2dd \uc548\uc5d0\uc11c\ub3c4 \uad6d\ub0b4\uc640 \ud574\uc678, \uc2dc\uac00\ucd1d\uc561 \uaddc\ubaa8\uac00 \ub2e4\ub978 \uc790\uc0b0\uc744 \uc11e\uc73c\uba74 \ud2b9\uc815 \uc2dc\uc7a5\uc774 \ud754\ub4e4\ub9b4 \ub54c \ubc1b\ub294 \ucda9\uaca9\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc0c1\uad00\uad00\uacc4\uac00 \ud575\uc2ec\uc785\ub2c8\ub2e4\\n\\n\uc0c1\uad00\uad00\uacc4\ub294 \ub450 \uc790\uc0b0\uc774 \uc5bc\ub9c8\ub098 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\ud568\uaed8 \uc624\ub974\uace0 \ud568\uaed8 \ub0b4\ub9ac\ub294 \uc790\uc0b0\ub9cc \ubaa8\uc544\ub450\uba74 \uac1c\uc218\ub294 \ub9ce\uc544\ub3c4 \ubd84\uc0b0 \ud6a8\uacfc\ub294 \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc6c0\uc9c1\uc784\uc774 \uc11c\ub85c \ub2e4\ub978 \uc790\uc0b0\uc744 \uc870\ud569\ud558\uba74, \ud55c\ucabd\uc774 \ud754\ub4e4\ub9b4 \ub54c \uc804\uccb4 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uc758 \ucd9c\ub801\uc784\uc774 \uc904\uc5b4\ub4dc\ub294 \ud6a8\uacfc\ub97c \uae30\ub300\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n```text\\n\uc608\uc2dc) \uc8fc\uac00\uac00 \ud558\ub77d\ud558\ub294 \uad6d\uba74\uc5d0\uc11c\ub3c4 \ucc44\uad8c \uac00\uaca9\uc774 \uc548\uc815\uc801\uc774\ub77c\uba74\\n     \uc804\uccb4 \uc790\uc0b0\uc758 \ud558\ub77d \ud3ed\uc740 \uc8fc\uc2dd\ub9cc \ubcf4\uc720\ud588\uc744 \ub54c\ubcf4\ub2e4 \uc791\uc544\uc9d1\ub2c8\ub2e4.\\n```\\n\\n\ubd84\uc0b0\uc758 \ubaa9\uc801\uc740 \uc218\uc775\uc744 \uadf9\ub300\ud654\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uc0c1\ud669\uc5d0\uc11c \ubc1b\ub294 \ucda9\uaca9\uc744 \uc904\uc774\ub294 \ub370 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9ac\ubc38\ub7f0\uc2f1\uc774\ub780\\n\\n#### \ud2c0\uc5b4\uc9c4 \ube44\uc911\uc744 \uc6d0\ub798\ub300\ub85c \ub418\ub3cc\ub9bd\ub2c8\ub2e4\\n\\n\uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uc624\ub978 \uc790\uc0b0\uc758 \ube44\uc911\uc740 \ucee4\uc9c0\uace0, \ub0b4\ub9b0 \uc790\uc0b0\uc758 \ube44\uc911\uc740 \uc791\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \uc774\ub807\uac8c \ud2c0\uc5b4\uc9c4 \ube44\uc911\uc744 \ucc98\uc74c \uc815\ud55c \ubaa9\ud45c \ube44\uc911\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294 \uc791\uc5c5\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub978 \uc790\uc0b0\uc744 \uc77c\ubd80 \ud314\uace0 \ub0b4\ub9b0 \uc790\uc0b0\uc744 \uc0ac\ub294 \ud615\ud0dc\uac00 \ub418\ubbc0\ub85c, \uacb0\uacfc\uc801\uc73c\ub85c \ube44\uc2f8\uc9c4 \uac83\uc744 \uc904\uc774\uace0 \uc2f8\uc9c4 \uac83\uc744 \ub298\ub9ac\ub294 \uc6d0\uce59\uc774 \uc790\ub3d9\uc73c\ub85c \uc801\uc6a9\ub429\ub2c8\ub2e4.<br/>\\n\\n```text\\n\uc608\uc2dc) \ubaa9\ud45c \ube44\uc911\uc774 \uc8fc\uc2dd 60 : \ucc44\uad8c 40\uc778\ub370\\n     \uc8fc\uc2dd \uc0c1\uc2b9\uc73c\ub85c 70 : 30\uc774 \ub418\uc5c8\ub2e4\uba74\\n     \uc8fc\uc2dd\uc758 10\ub9cc\ud07c\uc744 \ud314\uc544 \ucc44\uad8c\uc744 \uc0ac\uc11c 60 : 40\uc73c\ub85c \ub418\ub3cc\ub9bd\ub2c8\ub2e4.\\n```\\n\\n#### \uc8fc\uae30\ub97c \uc815\ud558\ub294 \ub450 \uac00\uc9c0 \ubc29\ubc95\\n\\n\ub0a0\uc9dc \uae30\uc900\uc73c\ub85c \uc815\ud558\ub294 \ubc29\ubc95\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\uae30\ub098 \ubc18\uae30\ucc98\ub7fc \uc815\ud574\uc9c4 \uc2dc\uc810\uc5d0 \ube44\uc911\uc744 \uc810\uac80\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c, \uaddc\uce59\uc774 \ub2e8\uc21c\ud574 \uafb8\uc900\ud788 \uc2e4\ucc9c\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\ube44\uc911 \uae30\uc900\uc73c\ub85c \uc815\ud558\ub294 \ubc29\ubc95\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa9\ud45c\uc5d0\uc11c \uc77c\uc815 \ud3ed \uc774\uc0c1 \ubc97\uc5b4\ub0ac\uc744 \ub54c\ub9cc \uc870\uc815\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c, \uc7a6\uc740 \uac70\ub798\ub97c \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ucabd\uc744 \ud0dd\ud558\ub4e0 \ub9e4\ub9e4\uc5d0\ub294 \uc218\uc218\ub8cc\uc640 \uc138\uae08 \uac19\uc740 \ube44\uc6a9\uc774 \ub530\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c, \ub108\ubb34 \uc7a6\uc740 \uc870\uc815\uc740 \uc624\ud788\ub824 \uc190\ud574\uac00 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucd08\ubcf4\uc790\uac00 \ud754\ud788 \ud558\ub294 \uc2e4\uc218\\n\\n\uc885\ubaa9 \uc218\ub9cc \ub298\ub9ac\uace0 \ubd84\uc0b0\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uacbd\uc6b0\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc131\uaca9\uc758 \uc790\uc0b0\ub9cc \ub9ce\uc544\uc9c0\uba74 \ubd84\uc0b0 \ud6a8\uacfc\ub294 \uc81c\ud55c\uc801\uc77c \uc218\ubc16\uc5d0 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub978 \uc790\uc0b0\ub9cc \uacc4\uc18d \uc0ac\uc11c \ube44\uc911\uc774 \ud55c\ucabd\uc73c\ub85c \uc3e0\ub9ac\ub294 \uacbd\uc6b0\ub3c4 \ud754\ud569\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1 \uc5c6\uc774 \uadf8\ub300\ub85c \ub450\uba74 \ucc98\uc74c \uc758\ub3c4\uc640 \uc804\ud600 \ub2e4\ub978 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uac00 \ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \ud754\ub4e4\ub9b4 \ub54c\ub9c8\ub2e4 \ube44\uc911\uc744 \ubc14\uafb8\ub294 \uac83\ub3c4 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub9ac\ubc38\ub7f0\uc2f1\uc740 \uc2dc\uc7a5\uc744 \ub9de\ud788\uae30 \uc704\ud55c \ub3c4\uad6c\uac00 \uc544\ub2c8\ub77c, \uc815\ud574\ub454 \uc6d0\uce59\uc744 \uc9c0\ud0a4\uae30 \uc704\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\n\ubaa9\ud45c \ube44\uc911\uc740 \uc790\uc2e0\uc758 \ud22c\uc790 \uae30\uac04\uacfc \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \ud558\ub77d \ud3ed\uc744 \uba3c\uc800 \uc815\ud55c \ub4a4\uc5d0 \uc815\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc801\ub9bd\uc2dd\uc73c\ub85c \uafb8\uc900\ud788 \ud22c\uc790\ud558\uace0 \uc788\ub2e4\uba74, \uc0c8\ub85c \ub123\ub294 \ub3c8\uc73c\ub85c \ubd80\uc871\ud574\uc9c4 \uc790\uc0b0\uad70\uc744 \ucc44\uc6b0\ub294 \ubc29\uc2dd\uc73c\ub85c\ub3c4 \ube44\uc911\uc744 \ub9de\ucd9c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub807\uac8c \ud558\uba74 \ud30c\ub294 \uac70\ub798\ub97c \uc904\uc774\uba74\uc11c \ubaa9\ud45c \ube44\uc911\uc5d0 \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\ubd84\uc0b0\ud22c\uc790\uac00 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uc124\uacc4\ub77c\uba74, \ub9ac\ubc38\ub7f0\uc2f1\uc740 \uadf8 \uc124\uacc4\uac00 \uc2dc\uac04\uc774 \uc9c0\ub098\ub3c4 \uc720\uc9c0\ub418\ub3c4\ub85d \ud558\ub294 \uad00\ub9ac \ubc29\ubc95\uc785\ub2c8\ub2e4.<br/>\\n\uc885\ubaa9\uc744 \uace0\ub974\ub294 \uc77c\ub9cc\ud07c, \ube44\uc911\uc744 \uc815\ud558\uace0 \uc9c0\ud0a4\ub294 \uc77c\uc744 \ud22c\uc790 \uacfc\uc815\uc758 \uc77c\ubd80\ub85c \ub450\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZzljbTkxanZmajYwZXF6ZWtvbmtlbGhvNjBtdW80NnliYm84dmxsNCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/5bcVz12UJLRvyLlx21/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"etf-basics","metadata":{"permalink":"/blog/en/finance/etf-basics","source":"@site/finance/2026-10-21-etf-basics/index.mdx","title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"etf","permalink":"/blog/en/finance/tags/etf"},{"inline":true,"label":"basics","permalink":"/blog/en/finance/tags/basics"}],"readingTime":3.07,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"etf-basics","title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","authors":["way"],"tags":["finance","etf","basics"]},"unlisted":false,"prevItem":{"title":"\ubd84\uc0b0\ud22c\uc790\uc640 \ub9ac\ubc38\ub7f0\uc2f1 \u2014 \uc815\ud574\ub454 \ube44\uc911\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95","permalink":"/blog/en/finance/diversification-rebalancing"},"nextItem":{"title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","permalink":"/blog/en/finance/interest-rate-and-stocks"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \ud380\ub4dc\uc640 \uc8fc\uc2dd\uc758 \uc911\uac04 \ud615\ud0dc\ub85c \ubd88\ub9ac\ub294 ETF\uac00 \ubb34\uc5c7\uc778\uc9c0, \uc5b4\ub5a4 \uc810\uc744 \ud655\uc778\ud558\uace0 \uace8\ub77c\uc57c \ud558\ub294\uc9c0\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uac1c\ubcc4 \uc885\ubaa9\uc744 \uace0\ub974\ub294 \uac83\uc774 \ubd80\ub2f4\uc2a4\ub7fd\uc9c0\ub9cc \uc608\uae08\ub9cc\uc73c\ub85c\ub294 \uc544\uc26c\uc6b4 \ubd84\ub4e4\uc774 \ucc98\uc74c \uc811\ud558\ub294 \uc0c1\ud488\uc774 ETF\uc778 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\nETF\ub294 \uc774\ub984 \uadf8\ub300\ub85c \uac70\ub798\uc18c\uc5d0 \uc0c1\uc7a5\ub41c \ud380\ub4dc(Exchange Traded Fund)\uc785\ub2c8\ub2e4.<br/>\\n\uc5ec\ub7ec \uc885\ubaa9\uc744 \ud55c \ubc14\uad6c\ub2c8\uc5d0 \ub2f4\uc544 \uc6b4\uc6a9\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ud380\ub4dc\uc640 \uac19\uace0, \uadf8 \ubc14\uad6c\ub2c8\ub97c \uc8fc\uc2dd\ucc98\ub7fc \uc2e4\uc2dc\uac04\uc73c\ub85c \uc0ac\uace0\ud314 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \uc8fc\uc2dd\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uc870 \ub355\ubd84\uc5d0 \ud558\ub098\uc758 \uc0c1\ud488\uc744 \uc0ac\ub294 \uac83\ub9cc\uc73c\ub85c \uc5ec\ub7ec \uc885\ubaa9\uc5d0 \ub098\ub204\uc5b4 \ud22c\uc790\ud558\ub294 \ud6a8\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExODg5anViMzF1aG5vcHo3MG4zcjYxaWFyMmszNTlqNDBrcW8xb2s4dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/7oIn6Khh0sF3r4qQdW/giphy.gif\\" alt=\\"Investment\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### ETF\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n#### \uc9c0\uc218 \ucd94\uc885\\n- \ub300\ubd80\ubd84\uc758 ETF\ub294 \ud2b9\uc815 \uc9c0\uc218\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c\uac00\ub3c4\ub85d \uc124\uacc4\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc608\ub97c \ub4e4\uc5b4 \ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 ETF\ub294 \uc9c0\uc218\ub97c \uad6c\uc131\ud558\ub294 \ub300\ud615\uc8fc\ub4e4\uc744 \ube44\uc2b7\ud55c \ube44\uc911\uc73c\ub85c \ub2f4\uc2b5\ub2c8\ub2e4.\\n- \uc9c0\uc218\uac00 \uc624\ub974\uba74 ETF \uac00\uaca9\ub3c4 \ube44\uc2b7\ud55c \ube44\uc728\ub85c \uc624\ub974\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \uc6b4\uc6a9\ub429\ub2c8\ub2e4.\\n- \uc6b4\uc6a9\uc0ac\uac00 \uc885\ubaa9\uc744 \uc9c1\uc811 \uace0\ub974\ub294 \uc561\ud2f0\ube0c ETF\ub3c4 \uc788\uc9c0\ub9cc, \uc9c0\uc218 \ucd94\uc885\ud615\uc774 \uae30\ubcf8 \ud615\ud0dc\uc785\ub2c8\ub2e4.\\n\\n#### \uc8fc\uc2dd\uacfc\uc758 \ucc28\uc774\\n- \uc8fc\uc2dd\uc740 \ud55c \uae30\uc5c5\uc758 \uc9c0\ubd84\uc744 \uc0ac\ub294 \uac83\uc774\uace0, ETF\ub294 \uc5ec\ub7ec \uc790\uc0b0\uc744 \ub2f4\uc740 \ubc14\uad6c\ub2c8\uc758 \uc9c0\ubd84\uc744 \uc0ac\ub294 \uac83\uc785\ub2c8\ub2e4.\\n- \uc8fc\uc2dd\ucc98\ub7fc \uc7a5\uc911\uc5d0 \uc2e4\uc2dc\uac04\uc73c\ub85c \ub9e4\ub9e4\ud560 \uc218 \uc788\uace0, \ud638\uac00\ub97c \ubcf4\uba74\uc11c \uac00\uaca9\uc744 \uc9c0\uc815\ud574 \uc8fc\ubb38\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc77c\ubc18 \ud380\ub4dc\ucc98\ub7fc \ud658\ub9e4\uc5d0 \uba70\uce60\uc774 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ud070 \ucc28\uc774\uc785\ub2c8\ub2e4.\\n\\n#### \ud380\ub4dc\uc640\uc758 \ucc28\uc774\\n- \uc77c\ubc18 \ud380\ub4dc\ub294 \ud558\ub8e8\uc5d0 \ud55c \ubc88 \uc815\ud574\uc9c0\ub294 \uae30\uc900\uac00\uaca9\uc73c\ub85c \uac70\ub798\ub418\uc9c0\ub9cc, ETF\ub294 \uc7a5\uc911 \uac00\uaca9\uc774 \uacc4\uc18d \ubc14\ub01d\ub2c8\ub2e4.\\n- \uc77c\ubc18 \ud380\ub4dc\uc5d0 \ubd80\uacfc\ub418\ub294 \ud310\ub9e4 \uc218\uc218\ub8cc\uac00 \uc5c6\ub294 \uacbd\uc6b0\uac00 \ub9ce\uace0, MTS\uc5d0\uc11c \uc8fc\uc2dd\uacfc \uac19\uc740 \ud654\uba74\uc73c\ub85c \uac70\ub798\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc0ac\uae30 \uc804\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4\\n\\n#### \ubcf4\uc218(TER)\\n- ETF\ub97c \ubcf4\uc720\ud558\ub294 \ub3d9\uc548 \uc6b4\uc6a9 \ube44\uc6a9\uc73c\ub85c \ucc28\uac10\ub418\ub294 \ube44\uc728\uc744 \ucd1d\ubcf4\uc218(TER)\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n- \ubcf4\uc218\ub294 \uc218\uc775\ub960\uc5d0\uc11c \ub9e4\uc77c \uc870\uae08\uc529 \ubc18\uc601\ub418\uc5b4 \ube60\uc9c0\uae30 \ub54c\ubb38\uc5d0, \uac19\uc740 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uc0c1\ud488\ub07c\ub9ac\ub294 \ubcf4\uc218\uac00 \ub0ae\uc744\uc218\ub85d \uc7a5\uae30 \uc131\uacfc\uc5d0 \uc720\ub9ac\ud569\ub2c8\ub2e4.\\n- \uc0c1\ud488 \uc774\ub984\uc774 \ube44\uc2b7\ud574\ub3c4 \uc6b4\uc6a9\uc0ac\ub9c8\ub2e4 \ubcf4\uc218\uac00 \ub2e4\ub97c \uc218 \uc788\uc5b4 \ube44\uad50\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n#### \uad34\ub9ac\uc728\\n- ETF\uc758 \uc2dc\uc7a5\uac00\uaca9\uacfc \uc2e4\uc81c \ubc14\uad6c\ub2c8\uc758 \uac00\uce58(\uc21c\uc790\uc0b0\uac00\uce58, NAV)\uac00 \ubc8c\uc5b4\uc9c4 \uc815\ub3c4\ub97c \uad34\ub9ac\uc728\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n- \uac70\ub798\uac00 \ud65c\ubc1c\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud488\uc740 \uc2dc\uc7a5\uac00\uaca9\uc774 \uc790\uc0b0 \uac00\uce58\ubcf4\ub2e4 \ube44\uc2f8\uac70\ub098 \uc2f8\uac8c \ud615\uc131\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ub9e4\uc218\ud558\uae30 \uc804\uc5d0 \uad34\ub9ac\uc728\uc774 \uc9c0\ub098\uce58\uac8c \ud06c\uc9c0 \uc54a\uc740\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\\n- \uc7a5\uc911\uc5d0\ub294 \ucd94\uc815 \uc21c\uc790\uc0b0\uac00\uce58\uc778 iNAV\ub97c \ud1b5\ud574 \ub300\ub7b5\uc801\uc778 \uac00\uce58\ub97c \ucc38\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n#### \ubd84\ubc30\uae08\\n- ETF\uac00 \ub2f4\uace0 \uc788\ub294 \uc8fc\uc2dd\uc758 \ubc30\ub2f9\uc774\ub098 \ucc44\uad8c\uc758 \uc774\uc790\ub97c \ubaa8\uc544 \ud22c\uc790\uc790\uc5d0\uac8c \ub098\ub220\uc8fc\ub294 \ub3c8\uc744 \ubd84\ubc30\uae08\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n- \uc9c0\uae09 \uc5ec\ubd80\uc640 \uc8fc\uae30\ub294 \uc0c1\ud488\ub9c8\ub2e4 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0, \ubd84\ubc30\uae08\uc744 \uae30\ub300\ud558\uace0 \ub9e4\uc218\ud55c\ub2e4\uba74 \uc9c0\uae09 \uc815\ucc45\uc744 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\\n- \ubd84\ubc30\uae08\uc744 \uc9c0\uae09\ud558\uba74 \uadf8\ub9cc\ud07c ETF\uc758 \uc790\uc0b0\uc774 \uc904\uc5b4 \uac00\uaca9\uc774 \uc870\uc815\ub41c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uc774\ud574\ud574 \ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n#### \uac70\ub798\ub7c9\uacfc \uc6b4\uc6a9 \uaddc\ubaa8\\n- \uac70\ub798\ub7c9\uc774 \uc801\uc740 \uc0c1\ud488\uc740 \uc6d0\ud558\ub294 \uac00\uaca9\uc5d0 \uc0ac\uace0\ud314\uae30 \uc5b4\ub835\uace0, \ub9e4\uc218\xb7\ub9e4\ub3c4 \ud638\uac00\uc758 \uac04\uaca9\uc774 \ubc8c\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc6b4\uc6a9 \uaddc\ubaa8\uac00 \ub108\ubb34 \uc791\uc740 \uc0c1\ud488\uc740 \uc0c1\uc7a5\ud3d0\uc9c0\uac00 \ub420 \uac00\ub2a5\uc131\ub3c4 \uc788\uc5b4 \uaddc\ubaa8\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n### ETF\uc758 \uc720\ud615\\n\\n#### \uc2dc\uc7a5\ub300\ud45c\uc9c0\uc218\ud615\\n- \ucf54\uc2a4\ud53c200\ucc98\ub7fc \ud55c \ub098\ub77c \uc2dc\uc7a5 \uc804\uccb4\ub97c \ub300\ud45c\ud558\ub294 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \ud574\uc678 \uc2dc\uc7a5\uc744 \ub300\uc0c1\uc73c\ub85c S&P500, \ub098\uc2a4\ub2e5100 \uac19\uc740 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uc0c1\ud488\ub3c4 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.\\n\\n#### \uc139\ud130\xb7\ud14c\ub9c8\ud615\\n- \ubc18\ub3c4\uccb4, 2\ucc28\uc804\uc9c0\ucc98\ub7fc \ud2b9\uc815 \uc0b0\uc5c5\uc774\ub098 \uc8fc\uc81c\ub97c \ubaa8\uc544 \ub2f4\uc740 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \uc2dc\uc7a5 \uc804\uccb4\uac00 \uc544\ub2cc \uc77c\ubd80 \uc601\uc5ed\uc5d0 \uc9d1\uc911\ud558\uae30 \ub54c\ubb38\uc5d0 \ubcc0\ub3d9\uc131\uc774 \ub354 \ud074 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n#### \ucc44\uad8c\ud615\\n- \uad6d\ucc44\ub098 \ud68c\uc0ac\ucc44 \uac19\uc740 \ucc44\uad8c\uc744 \ub2f4\ub294 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \uc8fc\uc2dd\ud615\uc5d0 \ube44\ud574 \uac00\uaca9 \ubcc0\ub3d9\uc774 \uc791\uc740 \ud3b8\uc774\ub77c \uc790\uae08\uc744 \uc548\uc815\uc801\uc73c\ub85c \ub450\ub294 \uc6a9\ub3c4\ub85c \uc4f0\uc785\ub2c8\ub2e4.\\n\\n#### \uc6d0\uc790\uc7ac\xb7\ub300\uccb4\uc790\uc0b0\ud615\\n- \uae08\uacfc \uac19\uc740 \uc6d0\uc790\uc7ac\ub098 \ub9ac\uce20 \ub4f1\uc744 \ub2f4\ub294 \uc720\ud615\uc785\ub2c8\ub2e4.\\n- \uc8fc\uc2dd\uacfc \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc774\ub294 \uc790\uc0b0\uc744 \uc11e\uc5b4 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\uc758 \ubcc0\ub3d9\uc744 \ub098\ub204\ub294 \ub370 \ud65c\uc6a9\ub429\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\nMTS\uc758 ETF \uac80\uc0c9\uc5d0\uc11c\ub294 \uc9c0\uc218 \uc774\ub984\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \ucd1d\ubcf4\uc218, \uad34\ub9ac\uc728, \uac70\ub798\ub7c9\uc744 \ud568\uaed8 \uc815\ub82c\ud574 \ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc9c0\uc218\ub97c \ucd94\uc885\ud558\ub294 \uc0c1\ud488\uc774 \uc5ec\ub7ec \uac1c\ub77c\uba74 \ubcf4\uc218\uc640 \uac70\ub798\ub7c9, \uc6b4\uc6a9 \uaddc\ubaa8\ub97c \ube44\uad50\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc120\ud0dd\uc758 \uae30\uc900\uc774 \uba85\ud655\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\ucc98\uc74c\uc5d0\ub294 \uc2dc\uc7a5\ub300\ud45c\uc9c0\uc218\ud615\ucc98\ub7fc \uad6c\uc870\uac00 \ub2e8\uc21c\ud55c \uc0c1\ud488\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uba74\uc11c, \uad34\ub9ac\uc728\uacfc iNAV\ub97c \ud655\uc778\ud558\ub294 \ud750\ub984\uc5d0 \uc775\uc219\ud574\uc9c0\ub294 \uac83\uc744 \uad8c\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nETF\ub294 \ud380\ub4dc\uc758 \ubd84\uc0b0 \ud22c\uc790\ub97c \uc8fc\uc2dd\uc758 \uac70\ub798 \ud3b8\uc758\uc131\uc73c\ub85c \uc62e\uaca8 \uc628 \uc0c1\ud488\uc785\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\ub97c \uc774\ud574\ud558\uace0 \ubcf4\uc218\uc640 \uad34\ub9ac\uc728\ub9cc \ud655\uc778\ud574\ub3c4, \uc0c1\ud488\uc744 \uace0\ub97c \ub54c \ud754\ub4e4\ub9ac\ub294 \uc77c\uc774 \ud6e8\uc52c \uc904\uc5b4\ub4ed\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZjRnd3J3azg3M3dobWZoem45azJzZXZ6bGFjNzJ2bDJvc3JsZGc0MCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/2SxYjYV9vP9NDSc2r4/giphy.gif\\" alt=\\"Piggy bank\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"interest-rate-and-stocks","metadata":{"permalink":"/blog/en/finance/interest-rate-and-stocks","source":"@site/finance/2026-10-21-interest-rate-and-stocks/index.mdx","title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"interest-rate","permalink":"/blog/en/finance/tags/interest-rate"},{"inline":true,"label":"basics","permalink":"/blog/en/finance/tags/basics"}],"readingTime":2.47,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"interest-rate-and-stocks","title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","authors":["way"],"tags":["finance","interest-rate","basics"]},"unlisted":false,"prevItem":{"title":"ETF\ub780 \ubb34\uc5c7\uc778\uac00 \u2014 \uc8fc\uc2dd\ucc98\ub7fc \uc0ac\uace0\ud30c\ub294 \ud380\ub4dc","permalink":"/blog/en/finance/etf-basics"},"nextItem":{"title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","permalink":"/blog/en/finance/kospi-5700-rally"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \uae30\uc900\uae08\ub9ac\uac00 \uc624\ub974\ub0b4\ub9b4 \ub54c \uc8fc\uac00\uc640 \ucc44\uad8c\uac00\uaca9\uc774 \uc65c \uc6c0\uc9c1\uc774\ub294\uc9c0, \uadf8 \uc6d0\ub9ac\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\ub274\uc2a4\uc5d0\uc11c\ub294 \uc911\uc559\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c \uc62c\ub9ac\uba74 \uc8fc\uac00\uac00 \ud754\ub4e4\ub9ac\uace0, \ub0b4\ub9ac\uba74 \ubc18\ub4f1\ud55c\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc790\uc8fc \uc811\ud569\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uae08\ub9ac\ub294 \ub300\ucd9c \uc774\uc790\uc5d0 \ubd99\ub294 \uc22b\uc790\uc774\uace0, \uc8fc\uac00\ub294 \uae30\uc5c5\uc758 \uac00\uce58\ub97c \ub098\ud0c0\ub0b4\ub294 \uc22b\uc790\uc778\ub370 \ub458 \uc0ac\uc774\uc5d0 \uc5b4\ub5a4 \uc5f0\uacb0\uace0\ub9ac\uac00 \uc788\ub294 \uac83\uc77c\uae4c\uc694.<br/>\\n\uc774 \uc5f0\uacb0\uace0\ub9ac\ub97c \uc774\ud574\ud558\ub824\uba74 \uba3c\uc800 \uae30\uc900\uae08\ub9ac\uac00 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 \ud560\uc778\uc728\uc774\ub77c\ub294 \uac1c\ub150\uc744 \uc54c\uc544\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n#### \uae30\uc900\uae08\ub9ac\\n- \uc911\uc559\uc740\ud589\uc774 \uc2dc\uc911 \uc740\ud589\uacfc\uc758 \uac70\ub798\uc5d0 \uc801\uc6a9\ud558\ub294 \uc815\ucc45 \uae08\ub9ac\uc785\ub2c8\ub2e4.\\n- \uc774 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc608\uae08\xb7\ub300\ucd9c \uae08\ub9ac\uac00 \ub530\ub77c \uc6c0\uc9c1\uc774\uba70, \ub3c8\uc758 \uac00\uaca9\uc774 \uc804\ubc18\uc801\uc73c\ub85c \ube44\uc2f8\uc9d1\ub2c8\ub2e4.\\n- \ubc18\ub300\ub85c \ub0b4\ub9ac\uba74 \ub3c8\uc744 \ube4c\ub9ac\ub294 \ube44\uc6a9\uc774 \uc904\uc5b4\ub4e4\uc5b4 \uc2dc\uc911\uc5d0 \uc790\uae08\uc774 \ud480\ub9ac\uae30 \uc26c\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExeTJzZzkwdnFoOHp2OWd2OGV1eXFyOG5jejJiM2dhNzJoZWh1eGtrbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/IvYx0wz4V9ivnvpVGV/giphy.gif\\" alt=\\"Interest rate\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uae08\ub9ac\uac00 \uc8fc\uac00\uc5d0 \ub2ff\ub294 \uae38\\n\\n#### \ud560\uc778\uc728\uacfc \ud604\uc7ac\uac00\uce58\\n- \uc8fc\uc2dd\uc758 \uac00\uaca9\uc740 \uadf8 \uae30\uc5c5\uc774 \uc55e\uc73c\ub85c \ubc8c\uc5b4\ub4e4\uc77c \uc774\uc775\uc744 \ud604\uc7ac\uc758 \uac00\uce58\ub85c \ud658\uc0b0\ud55c \uac12\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.\\n- \ubbf8\ub798\uc758 \ub3c8\uc744 \ud604\uc7ac \uac00\uce58\ub85c \ubc14\uafc0 \ub54c \uc801\uc6a9\ud558\ub294 \ube44\uc728\uc774 \ud560\uc778\uc728\uc774\uba70, \ud560\uc778\uc728\uc740 \uae08\ub9ac\ub97c \ub530\ub77c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.\\n- \uc608\ub97c \ub4e4\uc5b4 1\ub144 \ub4a4\uc5d0 \ubc1b\uc744 110\ub9cc \uc6d0\uc740 \ud560\uc778\uc728\uc774 10%\uc774\uba74 \uc624\ub298\uc758 100\ub9cc \uc6d0\uacfc \uac19\uc740 \uac00\uce58\uc785\ub2c8\ub2e4.\\n- \uac19\uc740 \ub3c8\uc774\ub77c\ub3c4 \ud560\uc778\uc728\uc774 5%\ub85c \ub0ae\uc544\uc9c0\uba74 \ud604\uc7ac\uac00\uce58\ub294 \uc57d 104.8\ub9cc \uc6d0\uc73c\ub85c \ucee4\uc9d1\ub2c8\ub2e4.\\n- \uc989, \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \ubbf8\ub798 \uc774\uc775\uc758 \ud604\uc7ac\uac00\uce58\uac00 \ucee4\uc838 \uc8fc\uac00\uc5d0 \uc6b0\ud638\uc801\uc73c\ub85c \uc791\uc6a9\ud558\uace0, \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uadf8 \ubc18\ub300\uac00 \ub429\ub2c8\ub2e4.\\n\\n#### \ucc44\uad8c\uac00\uaca9\uacfc\uc758 \uc5ed\uad00\uacc4\\n- \ucc44\uad8c\uc740 \uc815\ud574\uc9c4 \uc774\uc790(\ud45c\uba74\uae08\ub9ac)\ub97c \uc9c0\uae09\ud558\uae30\ub85c \uc57d\uc18d\ud55c \uc99d\uad8c\uc785\ub2c8\ub2e4.\\n- \uc2dc\uc7a5 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc0c8\ub85c \ubc1c\ud589\ub418\ub294 \ucc44\uad8c\uc774 \ub354 \ub192\uc740 \uc774\uc790\ub97c \uc8fc\uae30 \ub54c\ubb38\uc5d0, \uc774\uc790\uac00 \ub0ae\uc740 \uae30\uc874 \ucc44\uad8c\uc758 \ub9e4\ub825\uc740 \ub5a8\uc5b4\uc9c0\uace0 \uac00\uaca9\uc740 \ud558\ub77d\ud569\ub2c8\ub2e4.\\n- \ubc18\ub300\ub85c \uc2dc\uc7a5 \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \uae30\uc874 \ucc44\uad8c\uc758 \uc0c1\ub300\uc801 \ub9e4\ub825\uc774 \ucee4\uc838 \uac00\uaca9\uc774 \uc624\ub985\ub2c8\ub2e4.\\n- \uadf8\ub798\uc11c \ucc44\uad8c\uac00\uaca9\uacfc \uae08\ub9ac\ub294 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778\ub2e4\uace0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n#### \uae30\uc5c5\uc758 \ube44\uc6a9\uacfc \uc2e4\uc801\\n- \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uae30\uc5c5\uc774 \ub3c8\uc744 \ube4c\ub9ac\ub294 \ube44\uc6a9\uc774 \ub298\uc5b4 \uc774\uc775\uc774 \uc904\uc5b4\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ube5a\uc774 \ub9ce\uc740 \uae30\uc5c5\uc77c\uc218\ub85d \uc774\uc790 \ubd80\ub2f4\uc758 \uc601\ud5a5\uc744 \ud06c\uac8c \ubc1b\uc2b5\ub2c8\ub2e4.\\n- \uae08\ub9ac\uac00 \ub0b4\ub9ac\uba74 \uc774\uc790 \ubd80\ub2f4\uc774 \uc904\uace0, \uc18c\ube44\uc640 \ud22c\uc790\ub3c4 \ub298\uc5b4\ub098\uae30 \uc26c\uc6cc \uae30\uc5c5 \uc2e4\uc801\uc5d0 \uc6b0\ud638\uc801\uc778 \ud658\uacbd\uc774 \ub429\ub2c8\ub2e4.\\n\\n### \uc131\uc7a5\uc8fc\uc640 \uac00\uce58\uc8fc\uac00 \ub2e4\ub974\uac8c \ubc1b\ub294 \uc601\ud5a5\\n\\n#### \uc131\uc7a5\uc8fc\\n- \uc9c0\uae08\uc758 \uc774\uc775\ubcf4\ub2e4 \uba3c \ubbf8\ub798\uc758 \ud070 \uc774\uc775\uc744 \uae30\ub300\ud558\uace0 \uac00\uaca9\uc774 \ud615\uc131\ub418\ub294 \uc8fc\uc2dd\uc785\ub2c8\ub2e4.\\n- \uc774\uc775\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc774 \uba3c \ubbf8\ub798\uc5d0 \uc788\uae30 \ub54c\ubb38\uc5d0, \ud560\uc778\uc728\uc774 \uc624\ub974\uba74 \ud604\uc7ac\uac00\uce58\uac00 \ud06c\uac8c \uae4e\uc785\ub2c8\ub2e4.\\n- \uadf8\ub798\uc11c \uae08\ub9ac \uc0c1\uc2b9\uae30\uc5d0 \uc0c1\ub300\uc801\uc73c\ub85c \ub354 \ud070 \uc870\uc815\uc744 \ubc1b\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n#### \uac00\uce58\uc8fc\\n- \ud604\uc7ac\uc758 \uc774\uc775\uacfc \uc790\uc0b0\uc5d0 \ube44\ud574 \uac00\uaca9\uc774 \ub0ae\uac8c \ud3c9\uac00\ub41c \uc8fc\uc2dd\uc785\ub2c8\ub2e4.\\n- \uc774\uc775\uc774 \uac00\uae4c\uc6b4 \uc2dc\uae30\uc5d0 \ubc1c\uc0dd\ud558\ubbc0\ub85c \ud560\uc778\uc728 \ubcc0\ud654\uc758 \uc601\ud5a5\uc744 \ube44\uad50\uc801 \ub35c \ubc1b\uc2b5\ub2c8\ub2e4.\\n- \uae08\ub9ac \uc0c1\uc2b9\uae30\uc5d0\ub294 \uc131\uc7a5\uc8fc\ubcf4\ub2e4 \ubc29\uc5b4\uc801\uc778 \ubaa8\uc2b5\uc744 \ubcf4\uc774\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ubd05\ub2c8\ub2e4\\n\\n\uae08\ub9ac \ub274\uc2a4\ub97c \uc811\ud560 \ub54c\ub294 \uc778\uc0c1\xb7\uc778\ud558 \uc5ec\ubd80 \uc790\uccb4\ubcf4\ub2e4 \uc2dc\uc7a5\uc758 \uc608\uc0c1\uacfc \uc5bc\ub9c8\ub098 \ub2e4\ub978\uc9c0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.<br/>\\n\uc774\ubbf8 \uc608\uc0c1\ub41c \uae08\ub9ac \uacb0\uc815\uc740 \uc8fc\uac00\uc5d0 \ubbf8\ub9ac \ubc18\uc601\ub41c \uacbd\uc6b0\uac00 \ub9ce\uc544, \ubc1c\ud45c \ud6c4\uc5d0\ub3c4 \uc2dc\uc7a5\uc774 \ud06c\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc608\uc0c1\uacfc \ub2e4\ub978 \uacb0\uc815\uc774\ub098 \uc911\uc559\uc740\ud589 \ucd1d\uc7ac\uc758 \ubc1c\uc5b8\uc740 \ud560\uc778\uc728\uc5d0 \ub300\ud55c \uae30\ub300 \uc790\uccb4\ub97c \ubc14\uafb8\uae30 \ub54c\ubb38\uc5d0 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\uc720\ud55c \uc8fc\uc2dd\uc774 \uba3c \ubbf8\ub798\uc758 \uc131\uc7a5\uc5d0 \uae30\ub300\ub294 \uc720\ud615\uc778\uc9c0, \ud604\uc7ac \uc774\uc775 \uc911\uc2ec\uc758 \uc720\ud615\uc778\uc9c0 \uad6c\ubd84\ud574 \ub450\uba74 \uae08\ub9ac \ud658\uacbd \ubcc0\ud654\uc5d0 \ub530\ub978 \uc601\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4\ub294 \uacb0\uad6d \ubbf8\ub798\uc758 \ub3c8\uc744 \uc624\ub298\uc758 \uac00\uce58\ub85c \ubc14\uafb8\ub294 \ud560\uc778\uc728\uc5d0\uc11c \ucd9c\ubc1c\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uc6d0\ub9ac\ub97c \uc54c\uc544\ub450\uba74 \uae08\ub9ac \uad00\ub828 \ub274\uc2a4\uac00 \ub098\uc62c \ub54c\ub9c8\ub2e4 \uc2dc\uc7a5\uc774 \uc65c \uadf8\ub807\uac8c \ubc18\uc751\ud558\ub294\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZjZnNzNwamZvb2kxNTVyNG9tNW5ycG9manhwZHg2cHU1czQ2cHI3eiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/12Eo7WogCAoj84/giphy.gif\\" alt=\\"Money\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"kospi-5700-rally","metadata":{"permalink":"/blog/en/finance/kospi-5700-rally","source":"@site/finance/2026-10-21-kospi-5700-rally/index.mdx","title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"market","permalink":"/blog/en/finance/tags/market"},{"inline":true,"label":"kospi","permalink":"/blog/en/finance/tags/kospi"}],"readingTime":2.44,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kospi-5700-rally","title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","authors":["way"],"tags":["finance","market","kospi"]},"unlisted":false,"prevItem":{"title":"\uae08\ub9ac\uc640 \uc8fc\uac00\uc758 \uad00\uacc4 \u2014 \uae30\uc900\uae08\ub9ac\uac00 \uc6c0\uc9c1\uc774\uba74 \uc8fc\uac00\ub294 \uc65c \uc6c0\uc9c1\uc77c\uae4c","permalink":"/blog/en/finance/interest-rate-and-stocks"},"nextItem":{"title":"PER\uacfc PBR \uc77d\ub294 \ubc95 \u2014 \uc774\uc775\uacfc \uc790\uc0b0\uc73c\ub85c \uc8fc\uac00\ub97c \uac00\ub2a0\ud558\ub294 \ub450 \uac00\uc9c0 \uc9c0\ud45c","permalink":"/blog/en/finance/per-pbr-guide"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc624\ub298\uc740 \ucf54\uc2a4\ud53c\uac00 5,700\uc120\uc744 \ub118\uc740 \uc2dc\uc7a5 \ub3d9\ud5a5\uacfc, \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud560 \uc9c0\ud45c\ub4e4\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc624\ub298\uc758 \uc2dc\uc7a5\\n\\n2026\ub144 10\uc6d4 21\uc77c, \ucf54\uc2a4\ud53c\ub294 \uc624\ud6c4 2\uc2dc \ubb34\ub835 5,712.46\uc744 \uae30\ub85d\ud558\uba70 5,700\uc120\uc744 \ub118\uc5b4\uc130\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 159.72\ud3ec\uc778\ud2b8, 2.88% \uc624\ub978 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 792.38\ub85c \uc804\uc77c \ub300\ube44 10.41\ud3ec\uc778\ud2b8, 1.33% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub294 886.28\ub85c 3.20% \uc624\ub974\uba70 \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \ud070 \uc0c1\uc2b9\ud3ed\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,324.0\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.15% \ud558\ub77d\ud574 \uc6d0\ud654\uac00 \uc18c\ud3ed \uac15\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc740 \ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\uac00 0.02% \ud558\ub77d\ud558\uace0 S&P500\uc774 0.28% \uc624\ub974\ub294 \ub4f1 \ubc29\ud5a5\uc131\uc774 \uc5c7\uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc989, \uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uc0c1\uc2b9\uc740 \ud574\uc678 \uc2dc\uc7a5\uc758 \ud750\ub984\ub9cc\uc73c\ub85c\ub294 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4, \uad6d\ub0b4 \uc694\uc778\uc774 \uac15\ud558\uac8c \uc791\uc6a9\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExZnN6MWxzOGNpMmF2N3BtaXFsYzZyYWFmMXVjbWdqdTY2bXV0NHduaiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/5RNNQvq3fhYlOYDIQ2/giphy.gif\\" alt=\\"Stock market\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4\\n\\n\uc9c0\uc218 \uc0c1\uc2b9\ub960\ub9cc \ubcf4\uace0 \uc2dc\uc7a5\uc744 \ud310\ub2e8\ud558\uba74 \ud750\ub984\uc744 \uc798\ubabb \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc0c1\uc2b9\uc774\ub77c\ub3c4 \uc5b4\ub5a4 \ub3c8\uc774, \uc5b4\ub5a4 \uc885\ubaa9\uc744 \uc0ac\uc11c \uc62c\ub790\ub294\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c0\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ub300\ud45c\uc801\uc73c\ub85c \ub2e4\uc74c \ub124 \uac00\uc9c0\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n#### \uac70\ub798\ub300\uae08\\n- \uc9c0\uc218\uac00 \uc624\ub974\uba74\uc11c \uac70\ub798\ub300\uae08\ub3c4 \ud568\uaed8 \ub298\uc5c8\ub294\uc9c0\ub97c \ubd05\ub2c8\ub2e4.\\n- \uac70\ub798\ub300\uae08\uc774 \ub4b7\ubc1b\uce68\ub418\ub294 \uc0c1\uc2b9\uc740 \uc2dc\uc7a5\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc790\uae08 \uc790\uccb4\uac00 \ub298\uc5c8\ub2e4\ub294 \uc2e0\ud638\ub85c \ud574\uc11d\ud569\ub2c8\ub2e4.\\n- \ubc18\ub300\ub85c \uac70\ub798\uac00 \ud55c\uc0b0\ud55c\ub370 \uc9c0\uc218\ub9cc \uc624\ub974\uba74, \uc801\uc740 \ub9e4\uc218\uc138\uc5d0\ub3c4 \uac00\uaca9\uc774 \uc6c0\uc9c1\uc778 \uac83\uc77c \uc218 \uc788\uc5b4 \uc0c1\uc2b9\uc758 \uc9c0\uc18d\uc131\uc744 \ubcf4\uc218\uc801\uc73c\ub85c \ubcf4\uac8c \ub429\ub2c8\ub2e4.\\n\\n#### \uc678\uad6d\uc778\xb7\uae30\uad00 \uc218\uae09\\n- \uc678\uad6d\uc778\uacfc \uae30\uad00, \uac1c\uc778 \uc911 \ub204\uac00 \uc21c\ub9e4\uc218\ub97c \uc8fc\ub3c4\ud588\ub294\uc9c0\ub97c \ud655\uc778\ud569\ub2c8\ub2e4.\\n- \ud2b9\ud788 \uc678\uad6d\uc778\uc758 \ub9e4\ub9e4\ub294 \ud658\uc728\uacfc \uae00\ub85c\ubc8c \uc790\uae08 \ud750\ub984\uc758 \uc601\ud5a5\uc744 \ud06c\uac8c \ubc1b\uae30 \ub54c\ubb38\uc5d0, \uad6d\ub0b4 \uc99d\uc2dc\uc758 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub370 \uc790\uc8fc \ucc38\uace0\ud569\ub2c8\ub2e4.\\n- \uae30\uad00 \uc911\uc5d0\uc11c\ub3c4 \uc5f0\uae30\uae08, \ud22c\uc2e0, \uae08\uc735\ud22c\uc790 \ub4f1 \uc8fc\uccb4\ubcc4\ub85c \uc131\uaca9\uc774 \ub2ec\ub77c, \uc5b4\ub290 \uc8fc\uccb4\uac00 \uc0c0\ub294\uc9c0\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n#### \uc8fc\ub3c4 \uc5c5\uc885\\n- \uc5b4\ub5a4 \uc5c5\uc885\uc774 \uc0c1\uc2b9\uc744 \uc774\ub04c\uc5c8\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.\\n- \uc2dc\uac00\ucd1d\uc561\uc774 \ud070 \uc5c5\uc885\uc774 \uc8fc\ub3c4\ud558\uba74 \uc9c0\uc218 \uc0c1\uc2b9\ud3ed\uc774 \ucee4\uc9c0\uae30 \uc27d\uace0, \ud2b9\uc815 \uc5c5\uc885\uc5d0 \uc0c1\uc2b9\uc774 \uc9d1\uc911\ub410\ub294\uc9c0 \uc2dc\uc7a5 \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub410\ub294\uc9c0\uc5d0 \ub530\ub77c \uccb4\uac10 \uac15\ub3c4\uac00 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.\\n- \uc624\ub298\ucc98\ub7fc \ucf54\uc2a4\ud53c200\uc758 \uc0c1\uc2b9\ub960\uc774 \ucf54\uc2a4\ud53c\ub97c \uc6c3\ub3c4\ub294 \ub0a0\uc740 \ub300\ud615\uc8fc \uc911\uc2ec\uc758 \uc0c1\uc2b9\uc774\uc5c8\uc74c\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n#### \ud658\uc728\\n- \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc758 \ubc29\ud5a5\uc744 \uc9c0\uc218\uc640 \ud568\uaed8 \ubd05\ub2c8\ub2e4.\\n- \uc77c\ubc18\uc801\uc73c\ub85c \uc6d0\ud654 \uac15\uc138(\ud658\uc728 \ud558\ub77d)\ub294 \uc678\uad6d\uc778 \uc790\uae08 \uc720\uc785\uacfc \ub9de\ubb3c\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544, \uc9c0\uc218 \uc0c1\uc2b9\uacfc \ud658\uc728 \ud558\ub77d\uc774 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub098\uba74 \uc218\uae09 \ud658\uacbd\uc744 \uc6b0\ud638\uc801\uc73c\ub85c \ud574\uc11d\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\\n- \ub2e4\ub9cc \ud658\uc728\uc740 \uc218\ucd9c \uae30\uc5c5\uc758 \uc2e4\uc801\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uae30 \ub54c\ubb38\uc5d0, \ubc29\ud5a5 \ud558\ub098\ub9cc\uc73c\ub85c \uc88b\uace0 \ub098\uc068\uc744 \ub2e8\uc815\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ud655\uc778\ud569\ub2c8\ub2e4\\n\\nMTS\uc5d0\uc11c\ub294 \uc9c0\uc218 \ud654\uba74\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc218\uae09 \ud654\uba74\uacfc \uc5c5\uc885\ubcc4 \uc9c0\uc218\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uc624\ub978 \ub0a0\uc77c\uc218\ub85d \uc0c1\uc2b9\ub960\ubcf4\ub2e4 \uba3c\uc800 \uac70\ub798\ub300\uae08 \ucd94\uc774\uc640 \uc678\uad6d\uc778\xb7\uae30\uad00\uc758 \ub9e4\ub9e4 \ub3d9\ud5a5\uc744 \ub300\uc870\ud574 \ubd05\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc5c5\uc885\uc774 \uae09\ub4f1\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc5c5\uc885 \uc548\uc5d0\uc11c \ub300\uc7a5\uc8fc\uac00 \uc6c0\uc9c1\uc600\ub294\uc9c0, \uc5c5\uc885 \uc804\ubc18\uc774 \ub530\ub77c \uc62c\ub790\ub294\uc9c0\ub3c4 \uad6c\ubd84\ud574\uc11c \ubd05\ub2c8\ub2e4.<br/>\\n\uc774\ub807\uac8c \uc9c0\ud45c\ub97c \uacb9\uccd0\uc11c \ubcf4\uba74 \ud558\ub8e8\uc758 \uc0c1\uc2b9\uc774 \uc790\uae08 \uc720\uc785\uc5d0 \uae30\ubc18\ud55c \uac83\uc778\uc9c0, \ub2e8\uae30\uc801\uc778 \uc218\uae09 \uc3e0\ub9bc\uc778\uc9c0 \ud310\ub2e8\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc9c0\uc218\uac00 \ud070 \ud3ed\uc73c\ub85c \uc624\ub978 \ub0a0\uc5d0\ub294 \uc0c1\uc2b9\ub960 \uc790\uccb4\ubcf4\ub2e4 \uadf8 \uc548\uc758 \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub300\uae08, \uc218\uae09, \uc8fc\ub3c4 \uc5c5\uc885, \ud658\uc728\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\ub294 \uc2b5\uad00\uc774 \uc2dc\uc7a5\uc758 \ud750\ub984\uc744 \uc77d\ub294 \uae30\ubcf8\uae30\uac00 \ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExcG1ocTFtbTk0aWY0d2hzZGJpNnhtN3J3dmUwaGRxNXNtbGFsb20zYSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/U7gTVK2ch30xsUskCL/giphy.gif\\" alt=\\"Chart\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"per-pbr-guide","metadata":{"permalink":"/blog/en/finance/per-pbr-guide","source":"@site/finance/2026-10-21-per-pbr-guide/index.mdx","title":"PER\uacfc PBR \uc77d\ub294 \ubc95 \u2014 \uc774\uc775\uacfc \uc790\uc0b0\uc73c\ub85c \uc8fc\uac00\ub97c \uac00\ub2a0\ud558\ub294 \ub450 \uac00\uc9c0 \uc9c0\ud45c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"finance","permalink":"/blog/en/finance/tags/finance"},{"inline":true,"label":"valuation","permalink":"/blog/en/finance/tags/valuation"},{"inline":true,"label":"basics","permalink":"/blog/en/finance/tags/basics"}],"readingTime":3.27,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/finance/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"per-pbr-guide","title":"PER\uacfc PBR \uc77d\ub294 \ubc95 \u2014 \uc774\uc775\uacfc \uc790\uc0b0\uc73c\ub85c \uc8fc\uac00\ub97c \uac00\ub2a0\ud558\ub294 \ub450 \uac00\uc9c0 \uc9c0\ud45c","authors":["way"],"tags":["finance","valuation","basics"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 5,700\uc120 \ub3cc\ud30c \u2014 \uc9c0\uc218\uac00 \uc624\ub97c \ub54c \ud655\uc778\ud574\uc57c \ud560 \uac83\ub4e4","permalink":"/blog/en/finance/kospi-5700-rally"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298\uc740 \uc8fc\uc2dd\uc758 \uac00\uaca9 \uc218\uc900\uc744 \ud310\ub2e8\ud560 \ub54c \uac00\uc7a5 \uba3c\uc800 \ud655\uc778\ud558\uac8c \ub418\ub294 \uc9c0\ud45c\uc778 PER\uacfc PBR\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\n\\n\uc885\ubaa9\uc744 \uac80\uc0c9\ud558\uba74 \ud604\uc7ac\uac00\uc640 \ud568\uaed8 PER, PBR \uac19\uc740 \uc22b\uc790\uac00 \ub098\ub780\ud788 \ud45c\uc2dc\ub429\ub2c8\ub2e4.<br/>\\n\uc22b\uc790\uac00 \ub0ae\uc73c\uba74 \uc2f8\uace0 \ub192\uc73c\uba74 \ube44\uc2f8\ub2e4\uace0 \ub2e8\uc21c\ud558\uac8c \uc774\ud574\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\uc9c0\ub9cc \uc774 \uc9c0\ud45c\ub4e4\uc740 \uc5b4\ub5a4 \uc22b\uc790\ub97c \ub098\ub204\uc5b4 \ub9cc\ub4e0 \uac83\uc778\uc9c0, \uadf8\ub9ac\uace0 \uc5c5\uc885\uc758 \ud2b9\uc131\uc774 \ubb34\uc5c7\uc778\uc9c0\uc640 \ud568\uaed8 \ubd10\uc57c \uc81c\ub300\ub85c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac01 \uc9c0\ud45c\uc758 \uacc4\uc0b0 \ubc29\uc2dd\ubd80\ud130 \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExa2dvNTI5bTQ2dzUyMTQ2MjN5N3h1dXVsdnJzczMxaXNsOGtpemw3dCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3tEFVAbfzzcwo/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### PER \u2014 \uc774\uc775\uacfc \ube44\uad50\ud55c \uac00\uaca9\\n\\n#### \uc815\uc758\uc640 \uacc4\uc0b0\uc2dd\\n\\nPER(\uc8fc\uac00\uc218\uc775\ube44\uc728, Price Earnings Ratio)\uc740 \uc8fc\uac00\ub97c \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc5c5\uc774 \ubc8c\uc5b4\ub4e4\uc774\ub294 \uc774\uc775\uc5d0 \ube44\ud574 \uc8fc\uac00\uac00 \uba87 \ubc30\ub85c \uac70\ub798\ub418\uace0 \uc788\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\\n```text\\nPER = \uc8fc\uac00 \xf7 EPS(\uc8fc\ub2f9\uc21c\uc774\uc775)\\nEPS = \ub2f9\uae30\uc21c\uc774\uc775 \xf7 \ubc1c\ud589\uc8fc\uc2dd\uc218\\n\\n\uc608\uc2dc) \uc8fc\uac00 50,000\uc6d0, EPS 5,000\uc6d0\uc778 \uacbd\uc6b0\\n     PER = 50,000 \xf7 5,000 = 10\ubc30\\n```\\n\\nPER\uc774 10\ubc30\ub77c\ub294 \uac83\uc740 \ud604\uc7ac\uc758 \uc774\uc775 \uc218\uc900\uc774 \uadf8\ub300\ub85c \uc720\uc9c0\ub41c\ub2e4\uace0 \uac00\uc815\ud558\uba74, \ud22c\uc790\ud55c \uae08\uc561\uacfc \uac19\uc740 \ud06c\uae30\uc758 \uc774\uc775\uc774 \uc313\uc774\uae30\uae4c\uc9c0 10\ub144\uc774 \uac78\ub9b0\ub2e4\ub294 \uc758\ubbf8\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### PER\uc744 \uc77d\uc744 \ub54c \uc8fc\uc758\ud560 \uc810\\n\\n\uc774\uc775\uc774 \uc77c\uc2dc\uc801\uc73c\ub85c \ud754\ub4e4\ub9ac\uba74 PER\ub3c4 \ud568\uaed8 \ud06c\uac8c \ud754\ub4e4\ub9bd\ub2c8\ub2e4.<br/>\\n\uc77c\ud68c\uc131 \uc774\uc775\uc774 \ubc1c\uc0dd\ud55c \ud574\uc5d0\ub294 \uc774\uc775\uc774 \ubd80\ud480\ub824\uc838 PER\uc774 \uc2e4\uc81c\ubcf4\ub2e4 \ub0ae\uc544 \ubcf4\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc801\uc790 \uae30\uc5c5\uc740 EPS\uac00 \uc74c\uc218\uac00 \ub418\uc5b4 PER\uc744 \uacc4\uc0b0\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uacbd\uc6b0 PER\uc774 \ud45c\uc2dc\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ud574\uc11c \uc774\uc0c1\ud55c \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n### PBR \u2014 \uc790\uc0b0\uacfc \ube44\uad50\ud55c \uac00\uaca9\\n\\n#### \uc815\uc758\uc640 \uacc4\uc0b0\uc2dd\\n\\nPBR(\uc8fc\uac00\uc21c\uc790\uc0b0\ube44\uc728, Price Book-value Ratio)\uc740 \uc8fc\uac00\ub97c \uc8fc\ub2f9\uc21c\uc790\uc0b0(BPS)\uc73c\ub85c \ub098\ub208 \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ud68c\uc0ac\uac00 \uac00\uc9c4 \uc21c\uc790\uc0b0\uc5d0 \ube44\ud574 \uc8fc\uac00\uac00 \uc5b4\ub290 \uc218\uc900\uc778\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\\n```text\\nPBR = \uc8fc\uac00 \xf7 BPS(\uc8fc\ub2f9\uc21c\uc790\uc0b0)\\nBPS = \uc790\ubcf8\ucd1d\uacc4 \xf7 \ubc1c\ud589\uc8fc\uc2dd\uc218\\n\\n\uc608\uc2dc) \uc8fc\uac00 50,000\uc6d0, BPS 100,000\uc6d0\uc778 \uacbd\uc6b0\\n     PBR = 50,000 \xf7 100,000 = 0.5\ubc30\\n```\\n\\nPBR\uc774 1\ubc30\ubcf4\ub2e4 \ub0ae\uc73c\uba74 \uc7a5\ubd80\uc0c1 \uc21c\uc790\uc0b0\ubcf4\ub2e4 \uc8fc\uac00\uac00 \ub0ae\uac8c \ud615\uc131\ub418\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5\ubd80\uc5d0 \uae30\ub85d\ub41c \uc790\uc0b0 \uac00\uce58\uc640 \uc2e4\uc81c \uac00\uce58\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### \uc5c5\uc885\ub9c8\ub2e4 \uae30\uc900\uc774 \ub2e4\ub978 \uc774\uc720\\n\\n\uc131\uc7a5 \uc0b0\uc5c5\uc740 \ubbf8\ub798 \uc774\uc775\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uac00\uaca9\uc5d0 \uba3c\uc800 \ubc18\uc601\ub418\uc5b4 PER\uc774 \ub192\uac8c \ud615\uc131\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc740\ud589\xb7\ubcf4\ud5d8 \uac19\uc740 \uae08\uc735 \uc5c5\uc885\uc740 \uc790\uc0b0 \uaddc\ubaa8\uac00 \ud06c\uace0 \uc774\uc775\uc758 \ubcc0\ub3d9\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc544, PER\uacfc \ud568\uaed8 PBR\uc744 \ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ud50c\ub7ab\ud3fc\xb7\uc18c\ud504\ud2b8\uc6e8\uc5b4 \uae30\uc5c5\uc740 \uc7a5\ubd80\uc5d0 \uc7a1\ud788\uc9c0 \uc54a\ub294 \ubb34\ud615\uc790\uc0b0\uc758 \ube44\uc911\uc774 \ucee4\uc11c PBR\uc774 \ub192\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc808\ub300\uc801\uc778 \uc22b\uc790 \ud558\ub098\ub9cc\uc73c\ub85c \ube44\uad50\ud558\uae30\ubcf4\ub2e4, \uac19\uc740 \uc5c5\uc885 \uc548\uc5d0\uc11c \ube44\uad50\ud558\uace0 \uadf8 \uae30\uc5c5\uc758 \uacfc\uac70 \ud750\ub984\uacfc \ube44\uad50\ud558\ub294 \uac83\uc774 \uba3c\uc800\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub0ae\ub2e4\uace0 \ubb34\uc870\uac74 \uc2fc \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4\\n\\nPER\uacfc PBR\uc774 \ub0ae\uac8c \uba38\ubb34\ub294 \ub370\uc5d0\ub294 \uadf8\ub9cc\ud55c \uc774\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub807\uac8c \uc2f8 \ubcf4\uc774\ub294 \uc0c1\ud0dc\uac00 \uc624\ub798 \uc9c0\uc18d\ub418\ub294 \uc0c1\ud669\uc744 \uac00\uce58 \ud568\uc815\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.<br/>\\n\uc774\uc775\uc774 \uc904\uc5b4\ub4dc\ub294 \ucd94\uc138\uc774\uac70\ub098, \uc0b0\uc5c5 \uc790\uccb4\uac00 \uc1e0\ud1f4\ud558\uace0 \uc788\uac70\ub098, \uc7ac\ubb34 \uad6c\uc870\uc5d0 \ubb38\uc81c\uac00 \uc788\uc73c\uba74 \ub0ae\uc740 \uc9c0\ud45c\uac00 \uc624\ud788\ub824 \uc704\ud5d8 \uc2e0\ud638\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ud45c\uac00 \ub0ae\uc740 \uc774\uc720\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uc22b\uc790\ub9cc \ubcf4\uace0 \uc811\uadfc\ud558\uba74, \uc2f8 \ubcf4\uc774\ub294 \uac00\uaca9\uc774 \uacc4\uc18d \uc2f8\uac8c \uba38\ubb34\ub294 \uc0c1\ud669\uc744 \uacaa\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### ROE\uc640 \ud568\uaed8 \ubcf4\ub294 \ubc95\\n\\nROE(\uc790\uae30\uc790\ubcf8\uc774\uc775\ub960)\ub294 \ud68c\uc0ac\uac00 \uc790\ubcf8\uc744 \uc5bc\ub9c8\ub098 \ud6a8\uc728\uc801\uc73c\ub85c \uc774\uc775\uc73c\ub85c \ubc14\uafb8\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\ud45c \uc0ac\uc774\uc5d0\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uad00\uacc4\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4.<br/>\\n\\n```text\\nROE = \ub2f9\uae30\uc21c\uc774\uc775 \xf7 \uc790\ubcf8\ucd1d\uacc4 \xd7 100\\n\\n\uad00\uacc4\uc2dd) PBR = PER \xd7 ROE\\n```\\n\\nROE\uac00 \ub192\uc740 \uae30\uc5c5\uc740 \uac19\uc740 \uc790\ubcf8\uc73c\ub85c \ub354 \ub9ce\uc740 \uc774\uc775\uc744 \ub0b4\ubbc0\ub85c, \uc2dc\uc7a5\uc774 \ub354 \ub192\uc740 PBR\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c PBR\uc774 \ub0ae\uc740\ub370 ROE\uae4c\uc9c0 \ub0ae\ub2e4\uba74, \uc790\uc0b0\uc740 \uc788\uc9c0\ub9cc \uc774\uc775\uc744 \uc798 \ub0b4\uc9c0 \ubabb\ud558\ub294 \uae30\uc5c5\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nPER, PBR, ROE \uc138 \uac00\uc9c0\ub97c \ud568\uaed8 \ubcf4\uba74 \uac00\uaca9 \uc218\uc900\uacfc \uc218\uc775\uc131\uc744 \uac19\uc774 \ub193\uace0 \ud310\ub2e8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc2e4\ubb34\uc5d0\uc11c \ud655\uc778\ud560 \uc810\\n\\nMTS\ub098 \ud3ec\ud138\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 PER\xb7PBR\uc740 \uc5b4\ub5a4 \ub0a0\uc9dc\uc758 \uc7ac\ubb34\uc81c\ud45c\ub97c \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud588\ub294\uc9c0\uc5d0 \ub530\ub77c \uc22b\uc790\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uadfc \ud655\uc815 \uc2e4\uc801 \uae30\uc900\uc778\uc9c0, \uc608\uc0c1 \uc2e4\uc801 \uae30\uc900\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc9c0\ud45c\ub97c \ube44\uad50\ud560 \ub54c\ub294 \uac19\uc740 \uae30\uc900, \uac19\uc740 \uc5c5\uc885, \uac19\uc740 \uc2dc\uc810\uc73c\ub85c \ub9de\ucd94\ub294 \uac83\uc774 \uae30\ubcf8\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub9c8\uce58\uba70\\n\\nPER\uacfc PBR\uc740 \uc8fc\uac00\uac00 \uc774\uc775\uacfc \uc790\uc0b0\uc5d0 \ube44\ud574 \uc5b4\ub290 \uc218\uc900\uc778\uc9c0 \uc54c\ub824\uc8fc\ub294 \ucd9c\ubc1c\uc810\uc77c \ubfd0, \uadf8 \uc790\uccb4\ub85c \uacb0\ub860\uc774 \ub418\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5c5\uc885\uc758 \ud2b9\uc131\uacfc ROE\ub97c \ud568\uaed8 \ub193\uace0, \uc9c0\ud45c\uac00 \ub0ae\uc740 \uc774\uc720\uae4c\uc9c0 \ud655\uc778\ud558\ub294 \uc21c\uc11c\ub85c \uc77d\uc5b4\ubcf4\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExeG9rczN5dWlqdWtlNWM2N3pkcWxsa25seDk5a285b3hscmUzd3FhbiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/U7gTVK2ch30xsUskCL/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"}]}}')}}]);